CREATE FUNCTION calendar.color_key_ok(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    select p in ('teal', 'rust', 'indigo', 'plum', 'green', 'amber', 'rose', 'sky', 'slate', 'olive', 'coral', 'violet')
  $$;

CREATE FUNCTION calendar.detail_number_ok(p numeric) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    select p is null or (p = round(p, 3) and abs(p) < 1000000000)
  $$;

CREATE FUNCTION calendar.details_ok(d jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    select d is not null and jsonb_typeof(d) = 'object'
       and not exists (
         select 1 from jsonb_each(d) kv
          where jsonb_typeof(kv.value) = 'object'
             or (jsonb_typeof(kv.value) = 'array'
                 and exists (select 1 from jsonb_array_elements(kv.value) el where jsonb_typeof(el) in ('object', 'array'))))
  $$;

CREATE FUNCTION calendar.event_activity_links_before_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_event record;
  v_activity record;
begin
  if tg_op = 'UPDATE' then
    if new.event_id is distinct from old.event_id or new.activity_id is distinct from old.activity_id
       or new.link_method is distinct from old.link_method
       or new.linked_by_user_id is distinct from old.linked_by_user_id or new.linked_at is distinct from old.linked_at then
      raise exception 'calendar.event_activity_links: a link is ended, never changed' using errcode = '23514';
    end if;
    if old.ended_at is not null then
      raise exception 'calendar.event_activity_links: an ended link is final' using errcode = '23514';
    end if;
    return new;
  end if;
  if new.ended_at is not null then
    raise exception 'calendar.event_activity_links: a new link is live' using errcode = '23514';
  end if;
  select e.status, e.day, e.end_day into v_event from calendar.events e where e.id = new.event_id;
  if not found or v_event.status <> 'planned' then
    raise exception 'calendar.event_activity_links: only a planned event takes a link' using errcode = '23514';
  end if;
  select a.lifecycle_state, a.occurred_local_date into v_activity from training.activities a where a.id = new.activity_id;
  if not found or v_activity.lifecycle_state = 'superseded' then
    raise exception 'calendar.event_activity_links: only a canonical activity can be linked' using errcode = '23514';
  end if;
  if v_activity.occurred_local_date < v_event.day or v_activity.occurred_local_date > coalesce(v_event.end_day, v_event.day) then
    raise exception 'calendar.event_activity_links: the activity''s day is outside the event''s days' using errcode = '23514';
  end if;
  return new;
end $$;

CREATE FUNCTION calendar.event_changes_before_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_request record;
  v_revision integer;
begin
  select r.event_id, r.operation, r.performed_by_user_id into v_request from calendar.event_requests r where r.id = new.request_id;
  if not found then
    raise exception 'calendar.event_changes: request_id names no request' using errcode = '23514';
  end if;
  if v_request.event_id <> new.event_id or v_request.operation <> new.kind or v_request.performed_by_user_id <> new.performed_by_user_id then
    raise exception 'calendar.event_changes: the change does not match its request' using errcode = '23514';
  end if;
  select e.revision into v_revision from calendar.events e where e.id = new.event_id;
  if v_revision is distinct from new.revision then
    raise exception 'calendar.event_changes: revision must be the event''s current revision' using errcode = '23514';
  end if;
  return new;
end $$;

CREATE FUNCTION calendar.event_field_options_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_field record;
begin
  -- The detail's row FOR UPDATE: options and the values of one detail
  -- serialize on it (the freeze, the count).
  select f.owner_scope, f.value_kind, f.archived_at into v_field
    from calendar.event_fields f where f.id = new.field_id for update;
  if not found then
    raise exception 'calendar.event_field_options: field_id names no detail' using errcode = '23514';
  end if;
  if v_field.value_kind <> 'choice' then
    raise exception 'calendar.event_field_options: only a choice detail has options' using errcode = '23514';
  end if;
  if tg_op = 'INSERT' then
    if v_field.owner_scope = 'system' and new.seed_key is null then
      raise exception 'calendar.event_field_options: the system set is final' using errcode = '23514';
    end if;
    if new.archived_at is not null then
      raise exception 'calendar.event_field_options: a new option is live' using errcode = '23514';
    end if;
    if (select count(*) from calendar.event_field_options o where o.field_id = new.field_id and o.archived_at is null) >= 20 then
      raise exception 'calendar.event_field_options: at most 20 live options' using errcode = '23514', constraint = 'event_field_options_max';
    end if;
    return new;
  end if;
  if v_field.owner_scope = 'system' then
    raise exception 'calendar.event_field_options: the system set is final' using errcode = '23514';
  end if;
  if new.field_id is distinct from old.field_id or new.seed_key is distinct from old.seed_key or new.created_at is distinct from old.created_at then
    raise exception 'calendar.event_field_options: field_id, seed_key and created_at are write-once' using errcode = '23514';
  end if;
  if new.label is distinct from old.label and calendar.field_has_values(old.field_id) then
    raise exception 'calendar.event_field_options: an option of a detail with values keeps its label' using errcode = '23514', constraint = 'event_fields_answered_frozen';
  end if;
  if old.archived_at is not null and new.archived_at is null
     and (select count(*) from calendar.event_field_options o where o.field_id = new.field_id and o.archived_at is null) >= 20 then
    raise exception 'calendar.event_field_options: at most 20 live options' using errcode = '23514', constraint = 'event_field_options_max';
  end if;
  new.updated_at := now();
  return new;
end $$;

