CREATE FUNCTION calendar.event_type_fields_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_type record;
  v_field record;
begin
  if tg_op = 'DELETE' then
    select t.owner_scope into v_type from calendar.event_types t where t.id = old.event_type_id;
    if found and v_type.owner_scope = 'system' then
      raise exception 'calendar.event_type_fields: the system set is final' using errcode = '23514';
    end if;
    return old;
  end if;
  if tg_op = 'UPDATE' then
    -- Only an entry's place in the list moves (an edit keeps the entries it
    -- keeps, so an archived detail already listed stays, plan 2.6).
    if new.event_type_id is distinct from old.event_type_id or new.field_id is distinct from old.field_id then
      raise exception 'calendar.event_type_fields: an entry only moves' using errcode = '23514';
    end if;
    select t.owner_scope into v_type from calendar.event_types t where t.id = new.event_type_id;
    if v_type.owner_scope = 'system' then
      raise exception 'calendar.event_type_fields: the system set is final' using errcode = '23514';
    end if;
    return new;
  end if;
  select t.owner_scope, t.owner_club_id into v_type from calendar.event_types t where t.id = new.event_type_id for update;
  if not found or v_type.owner_scope = 'system' then
    raise exception 'calendar.event_type_fields: the system set is final' using errcode = '23514';
  end if;
  select f.owner_scope, f.owner_club_id, f.archived_at into v_field from calendar.event_fields f where f.id = new.field_id for share;
  if not found or v_field.owner_scope <> v_type.owner_scope or v_field.owner_club_id is distinct from v_type.owner_club_id then
    raise exception 'calendar.event_type_fields: a type lists its own owner''s details only' using errcode = '23514';
  end if;
  if v_field.archived_at is not null then
    raise exception 'calendar.event_type_fields: an archived detail is not added' using errcode = '23514';
  end if;
  if (select count(*) from calendar.event_type_fields l where l.event_type_id = new.event_type_id) >= 20 then
    raise exception 'calendar.event_type_fields: at most 20 details per type' using errcode = '23514', constraint = 'event_type_fields_max';
  end if;
  return new;
end $$;

CREATE FUNCTION calendar.event_type_fields_need_parent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_type_id uuid;
begin
  if tg_op = 'DELETE' then
    v_type_id := old.event_type_id;
  else
    v_type_id := new.event_type_id;
  end if;
  if exists (select 1 from calendar.event_types t where t.id = v_type_id)
     and not exists (select 1 from calendar.event_types t
                      where t.id = v_type_id
                        and (calendar.written_in_this_transaction(t.xmin)
                             or (t.revision = 1 and t.seed_key is not null and t.created_by_user_id is null))) then
    raise exception 'calendar.event_type_fields: a list is written with its type' using errcode = '23514';
  end if;
  return null;
end $$;

CREATE FUNCTION calendar.event_types_before_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.kind is distinct from old.kind then
      raise exception 'calendar.event_types: kind is write-once' using errcode = '23514';
    end if;
    if new.owner_scope is distinct from old.owner_scope or new.owner_club_id is distinct from old.owner_club_id then
      raise exception 'calendar.event_types: the owner is write-once' using errcode = '23514';
    end if;
    if new.seed_key is distinct from old.seed_key then
      raise exception 'calendar.event_types: seed_key is write-once' using errcode = '23514';
    end if;
    new.updated_at := now();
  end if;
  return new;
end $$;

CREATE FUNCTION calendar.event_types_club_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.owner_scope = 'club' and exists (select 1 from public.clubs c where c.id = old.owner_club_id) then
    raise exception 'calendar.event_types: a type is archived, never deleted' using errcode = '23514';
  end if;
  return old;
end $$;

CREATE FUNCTION calendar.event_types_k2b_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.revision <> 1 or new.archived_at is not null then
      raise exception 'calendar.event_types: a new type has revision 1 and is live' using errcode = '23514';
    end if;
    -- D35: the system set changes by migration only, in the seed's shape.
    if new.owner_scope = 'system' and not (new.seed_key is not null and new.created_by_user_id is null) then
      raise exception 'calendar.event_types: the system set is final' using errcode = '23514';
    end if;
    return new;
  end if;
  if old.owner_scope = 'system' then
    raise exception 'calendar.event_types: the system set is final' using errcode = '23514';
  end if;
  if new.key is distinct from old.key or new.created_by_user_id is distinct from old.created_by_user_id
     or new.created_at is distinct from old.created_at then
    raise exception 'calendar.event_types: key and the creation facts are write-once' using errcode = '23514';
  end if;
  if new.revision <> old.revision + 1 then
    raise exception 'calendar.event_types: revision must increase by exactly one on every write' using errcode = '23514';
  end if;
  -- A club keeps at least one live type (plan 2.6). Archives of one owner are
  -- serialized on a transaction-scoped advisory lock, so two concurrent
  -- archives of the last two types cannot both pass.
  if old.archived_at is null and new.archived_at is not null then
    perform pg_advisory_xact_lock(hashtextextended('calendar.event_types.live:' || coalesce(new.owner_club_id::text, 'system'), 0));
    if not exists (select 1 from calendar.event_types x
                    where x.owner_scope = new.owner_scope and x.owner_club_id is not distinct from new.owner_club_id
                      and x.archived_at is null and x.id <> new.id) then
      raise exception 'calendar.event_types: an owner keeps at least one live type' using errcode = '23514', constraint = 'event_types_last_live';
    end if;
  end if;
  return new;
end $$;

CREATE FUNCTION calendar.event_types_need_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' and new.seed_key is not null and new.created_by_user_id is null then
    return null;
  end if;
  if not exists (select 1 from calendar.settings_changes c where c.event_type_id = new.id and c.revision = new.revision) then
    raise exception 'calendar.event_types: a write needs its change row (type, revision) in the same transaction' using errcode = '23514';
  end if;
  return null;
end $$;

CREATE FUNCTION calendar.event_types_system_final() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.owner_scope = 'system' then
    raise exception 'calendar.event_types: a system type is never deleted' using errcode = '23514';
  end if;
  return old;
end $$;

CREATE FUNCTION calendar.events_before_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_type record;
  v_owner_club uuid;
begin
  if tg_op = 'UPDATE' then
    if old.status = 'cancelled' then
      raise exception 'calendar.events: a cancelled event is final' using errcode = '23514';
    end if;
    if new.owner_scope is distinct from old.owner_scope or new.owner_user_id is distinct from old.owner_user_id
       or new.owner_club_id is distinct from old.owner_club_id or new.owner_team_id is distinct from old.owner_team_id then
      raise exception 'calendar.events: the owner is write-once' using errcode = '23514';
    end if;
    if new.created_by_user_id is distinct from old.created_by_user_id or new.created_at is distinct from old.created_at then
      raise exception 'calendar.events: the creation facts are write-once' using errcode = '23514';
    end if;
    if new.revision <> old.revision + 1 then
      raise exception 'calendar.events: revision must increase by exactly one on every write' using errcode = '23514';
    end if;
    new.updated_at := now();
  elsif new.revision <> 1 then
    raise exception 'calendar.events: a new event has revision 1' using errcode = '23514';
  end if;

  -- The references are validated when they are SET or CHANGED, never again
  -- on every later write: a test schedule the Tests module deleted, or a
  -- team moved to another club, must never make the event uncancellable.
  if tg_op = 'INSERT' or new.timezone is distinct from old.timezone then
    if not exists (select 1 from pg_timezone_names where name = new.timezone) then
      raise exception 'calendar.events: timezone is not a recognized IANA name' using errcode = '23514', constraint = 'events_timezone_iana';
    end if;
  end if;

  select t.owner_scope, t.owner_club_id, t.kind, t.archived_at
    into v_type
    from calendar.event_types t where t.id = new.event_type_id;
  if not found then
    raise exception 'calendar.events: event_type_id names no event type' using errcode = '23514';
  end if;
  if tg_op = 'INSERT' or new.event_type_id is distinct from old.event_type_id then
    if v_type.archived_at is not null then
      raise exception 'calendar.events: an archived event type takes no new event' using errcode = '23514';
    end if;
    v_owner_club := case new.owner_scope
                      when 'club' then new.owner_club_id
                      when 'team' then (select t.club_id from public.teams t where t.id = new.owner_team_id)
                      else null end;
    if not (v_type.owner_scope = 'system'
            or (v_type.owner_scope = 'club' and v_owner_club is not null and v_type.owner_club_id = v_owner_club)) then
      raise exception 'calendar.events: the event type belongs to another owner' using errcode = '23514';
    end if;
  end if;

  if new.test_schedule_id is not null
     and (tg_op = 'INSERT' or new.test_schedule_id is distinct from old.test_schedule_id or new.event_type_id is distinct from old.event_type_id) then
    if v_type.kind <> 'test' then
      raise exception 'calendar.events: a test schedule can be referenced only by an event of kind test' using errcode = '23514';
    end if;
    if (tg_op = 'INSERT' or new.test_schedule_id is distinct from old.test_schedule_id)
       and not exists (select 1 from tests.test_schedules s where s.id = new.test_schedule_id) then
      raise exception 'calendar.events: test_schedule_id names no test schedule' using errcode = '23514';
    end if;
  end if;
  return new;
end $$;

CREATE FUNCTION calendar.events_location_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_club uuid;
begin
  if new.location_id is not null and (tg_op = 'INSERT' or new.location_id is distinct from old.location_id) then
    v_club := case new.owner_scope
                when 'club' then new.owner_club_id
                when 'team' then (select t.club_id from public.teams t where t.id = new.owner_team_id)
                else null end;
    if not calendar.location_usable(new.location_id, v_club) then
      raise exception 'calendar.events: the place is a live place of the event owner''s club' using errcode = '23514', constraint = 'events_location_usable';
    end if;
  end if;
  return new;
end $$;

CREATE FUNCTION calendar.events_need_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from calendar.event_changes c where c.event_id = new.id and c.revision = new.revision) then
    raise exception 'calendar.events: a write needs its change row (event, revision) in the same transaction' using errcode = '23514';
  end if;
  return null;
end $$;

CREATE FUNCTION calendar.events_need_target_after_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not calendar.event_has_target(new.id) then
    raise exception 'calendar.events: an event needs at least one target' using errcode = '23514';
  end if;
  return null;
end $$;

CREATE FUNCTION calendar.expects_ok(p text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    select p is not null
       and not exists (select 1 from unnest(p) e where e is null or e not in ('rpe', 'device_data', 'test_result'))
       and (select count(*) from unnest(p) e) = (select count(distinct e) from unnest(p) e)
  $$;

CREATE FUNCTION calendar.field_has_values(p_field_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select exists (select 1 from calendar.event_field_values v where v.field_id = p_field_id)
$$;

CREATE FUNCTION calendar.location_usable(p_location_id uuid, p_club_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
  v record;
begin
  select l.owner_club_id, l.archived_at into v from calendar.locations l where l.id = p_location_id for share;
  return found and p_club_id is not null and v.owner_club_id = p_club_id and v.archived_at is null;
end $$;

CREATE FUNCTION calendar.locations_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.revision <> 1 or new.archived_at is not null then
      raise exception 'calendar.locations: a new place has revision 1 and is live' using errcode = '23514';
    end if;
    return new;
  end if;
  if new.owner_club_id is distinct from old.owner_club_id or new.created_by_user_id is distinct from old.created_by_user_id
     or new.created_at is distinct from old.created_at then
    raise exception 'calendar.locations: the owner and the creation facts are write-once' using errcode = '23514';
  end if;
  if new.revision <> old.revision + 1 then
    raise exception 'calendar.locations: revision must increase by exactly one on every write' using errcode = '23514';
  end if;
  new.updated_at := now();
  return new;
end $$;

CREATE FUNCTION calendar.locations_need_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from calendar.settings_changes c where c.location_id = new.id and c.revision = new.revision) then
    raise exception 'calendar.locations: a write needs its change row (place, revision) in the same transaction' using errcode = '23514';
  end if;
  return null;
end $$;

CREATE FUNCTION calendar.lock_event_writer(p_user_id uuid, p_owner_scope character varying, p_owner_id uuid, p_basis character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare
  v_club_id uuid;
  v_team_active boolean;
  v_club_active boolean;
  v_user_ok boolean;
begin
  if p_basis is null or p_basis not in ('platform_admin', 'club_admin', 'team_coach', 'private_coach') then
    raise exception 'lock_event_writer: unknown basis %', p_basis using errcode = 'invalid_parameter_value';
  end if;
  if p_owner_scope is null or p_owner_scope not in ('club', 'team', 'user') or p_owner_id is null then
    raise exception 'lock_event_writer: unknown owner' using errcode = 'invalid_parameter_value';
  end if;

  -- 1. The owner: the team, then its club; a club; a user. An archived owner
  --    takes writes from the next level up only (plan section 4.1, so its
  --    events can still be cancelled): an archived team never through its
  --    team_coach (its club's admin or the platform admin instead); an
  --    archived club — an archived team's club included — through
  --    platform_admin only.
  if p_owner_scope = 'team' then
    select t.club_id, coalesce(t.is_active, true) into v_club_id, v_team_active from public.teams t where t.id = p_owner_id for share;
    if not found then
      raise exception 'user % may not write the events of an unknown team', p_user_id using errcode = 'insufficient_privilege';
    end if;
    if not v_team_active and p_basis = 'team_coach' then
      raise exception 'user % may not write the events of an archived team as team_coach', p_user_id using errcode = 'insufficient_privilege';
    end if;
  elsif p_owner_scope = 'club' then
    v_club_id := p_owner_id;
  end if;
  if v_club_id is not null then
    select coalesce(c.is_active, true) into v_club_active from public.clubs c where c.id = v_club_id for share;
    if not found then
      raise exception 'user % may not write the events of an unknown club', p_user_id using errcode = 'insufficient_privilege';
    end if;
    if not v_club_active and p_basis <> 'platform_admin' then
      raise exception 'user % may not write the events of an archived club as %', p_user_id, p_basis using errcode = 'insufficient_privilege';
    end if;
  end if;
  if p_owner_scope = 'user' and p_basis <> 'platform_admin' and p_owner_id <> p_user_id then
    raise exception 'user % may not write another coach''s events', p_user_id using errcode = 'insufficient_privilege';
  end if;

  -- 2. The acting user (LO-2: before the role row, the order of the revocations;
  --    an inactive or unknown user is refused after the role row, as before),
  --    then the role row of the basis.
  perform 1 from public.users u where u.id = p_user_id and u.is_active = true for share;
  v_user_ok := found;
  if p_basis = 'platform_admin' then
    perform 1 from public.user_global_roles r
     where r.user_id = p_user_id and r.role = 'platform_admin' and r.is_active = true
       for share;
  elsif p_basis = 'club_admin' then
    if v_club_id is null then
      raise exception 'user % may not write these events as club_admin', p_user_id using errcode = 'insufficient_privilege';
    end if;
    perform 1 from public.user_club_roles r
     where r.user_id = p_user_id and r.club_id = v_club_id and r.role = 'club_admin' and r.is_active = true
       for share;
  elsif p_basis = 'team_coach' then
    if p_owner_scope <> 'team' then
      raise exception 'user % may not write these events as team_coach', p_user_id using errcode = 'insufficient_privilege';
    end if;
    perform 1 from public.user_team_roles r
     where r.user_id = p_user_id and r.team_id = p_owner_id and r.role = 'team_coach' and r.is_active = true
       for share;
  else
    if p_owner_scope <> 'user' then
      raise exception 'user % may not write these events as private_coach', p_user_id using errcode = 'insufficient_privilege';
    end if;
    perform 1 from public.user_global_roles r
     where r.user_id = p_user_id and r.role = 'independent_coach' and r.is_active = true
       for share;
  end if;
  if not found then
    raise exception 'user % may not write the events of this % as %', p_user_id, p_owner_scope, p_basis using errcode = 'insufficient_privilege';
  end if;

  -- 3. The acting user was locked in step 2.
  if not v_user_ok then
    raise exception 'user % may not write calendar events', p_user_id using errcode = 'insufficient_privilege';
  end if;
  return p_basis;
end $$;

CREATE FUNCTION calendar.multiline_text_ok(v text, max_len integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    select v is not null and training_load.source_metric_text_ok(replace(v, E'\n', ' '), max_len)
  $$;

CREATE FUNCTION calendar.refuse_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'calendar.%: % is refused, the table is append-only', tg_table_name, tg_op using errcode = '23514';
end $$;

CREATE FUNCTION calendar.refuse_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'calendar.%: rows are never deleted (an event is cancelled, a link is ended)', tg_table_name using errcode = '23514';
end $$;

CREATE FUNCTION calendar.refuse_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'calendar.%: TRUNCATE is refused', tg_table_name using errcode = '23514';
end $$;

CREATE FUNCTION calendar.seed_club_event_types(p_club_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  v_count integer;
begin
  insert into calendar.event_types (owner_scope, owner_club_id, kind, key, label, default_expects, icon_key, color_key, sort_order, seed_key)
  select 'club', p_club_id, s.kind, s.key, s.label, s.default_expects, s.icon_key, s.color_key, s.sort_order, s.seed_key
    from calendar.event_types s
   where s.owner_scope = 'system' and s.seed_key is not null and s.archived_at is null
     and not exists (select 1 from calendar.event_types x
                      where x.owner_scope = 'club' and x.owner_club_id = p_club_id and x.seed_key = s.seed_key)
   order by s.sort_order;
  get diagnostics v_count = row_count;

  insert into calendar.event_fields (owner_scope, owner_club_id, key, label, description, value_kind, unit, min_value, max_value, required, sort_order, seed_key)
  select 'club', p_club_id, s.key, s.label, s.description, s.value_kind, s.unit, s.min_value, s.max_value, s.required, s.sort_order, s.seed_key
    from calendar.event_fields s
   where s.owner_scope = 'system' and s.seed_key is not null and s.archived_at is null
     and not exists (select 1 from calendar.event_fields x
                      where x.owner_scope = 'club' and x.owner_club_id = p_club_id and x.seed_key = s.seed_key)
   order by s.sort_order;

  insert into calendar.event_field_options (field_id, label, sort_order, seed_key)
  select c.id, o.label, o.sort_order, o.seed_key
    from calendar.event_fields s
    join calendar.event_field_options o on o.field_id = s.id and o.seed_key is not null and o.archived_at is null
    join calendar.event_fields c on c.owner_scope = 'club' and c.owner_club_id = p_club_id and c.seed_key = s.seed_key
   where s.owner_scope = 'system' and c.revision = 1
     and not exists (select 1 from calendar.event_field_options x where x.field_id = c.id)
   order by c.id, o.sort_order;

  insert into calendar.event_type_fields (event_type_id, field_id, position)
  select ct.id, cf.id, l.position
    from calendar.event_type_fields l
    join calendar.event_types st on st.id = l.event_type_id and st.owner_scope = 'system'
    join calendar.event_fields sf on sf.id = l.field_id and sf.owner_scope = 'system'
    join calendar.event_types ct on ct.owner_scope = 'club' and ct.owner_club_id = p_club_id and ct.seed_key = st.seed_key
    join calendar.event_fields cf on cf.owner_scope = 'club' and cf.owner_club_id = p_club_id and cf.seed_key = sf.seed_key
   where ct.revision = 1 and cf.archived_at is null
     and not exists (select 1 from calendar.event_type_fields x where x.event_type_id = ct.id)
   order by ct.id, l.position;
  return v_count;
end $$;

CREATE FUNCTION calendar.settings_changes_before_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_request record;
  v_club uuid;
  v_revision integer;
begin
  select r.operation, r.performed_by_user_id, r.club_id into v_request from calendar.settings_requests r where r.id = new.request_id;
  if not found then
    raise exception 'calendar.settings_changes: request_id names no request' using errcode = '23514';
  end if;
  if v_request.operation <> new.kind or v_request.performed_by_user_id <> new.performed_by_user_id then
    raise exception 'calendar.settings_changes: the change does not match its request' using errcode = '23514';
  end if;
  if new.subject_kind = 'type' then
    select t.owner_club_id, t.revision into v_club, v_revision from calendar.event_types t where t.id = new.event_type_id and t.owner_scope = 'club';
  elsif new.subject_kind = 'field' then
    select f.owner_club_id, f.revision into v_club, v_revision from calendar.event_fields f where f.id = new.field_id and f.owner_scope = 'club';
  elsif new.subject_kind = 'location' then
    select l.owner_club_id, l.revision into v_club, v_revision from calendar.locations l where l.id = new.location_id;
  else
    select t.club_id, s.revision into v_club, v_revision
      from public.teams t join calendar.team_settings s on s.team_id = t.id where t.id = new.team_id;
  end if;
  if v_club is null or v_club <> v_request.club_id then
    raise exception 'calendar.settings_changes: the subject belongs to the request''s club only' using errcode = '23514';
  end if;
  if v_revision is distinct from new.revision then
    raise exception 'calendar.settings_changes: revision must be the subject''s current revision' using errcode = '23514';
  end if;
  return new;
end $$;

CREATE FUNCTION calendar.settings_requests_need_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from calendar.settings_changes c where c.request_id = new.id) then
    raise exception 'calendar.settings_requests: a request must have its change row in the same transaction' using errcode = '23514';
  end if;
  return null;
end $$;

CREATE FUNCTION calendar.team_settings_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_club uuid;
begin
  if tg_op = 'INSERT' then
    if new.revision <> 1 then
      raise exception 'calendar.team_settings: a new row has revision 1' using errcode = '23514';
    end if;
  else
    if new.team_id is distinct from old.team_id then
      raise exception 'calendar.team_settings: team_id is write-once' using errcode = '23514';
    end if;
    if new.revision <> old.revision + 1 then
      raise exception 'calendar.team_settings: revision must increase by exactly one on every write' using errcode = '23514';
    end if;
    new.updated_at := now();
  end if;
  if new.default_location_id is not null
     and (tg_op = 'INSERT' or new.default_location_id is distinct from old.default_location_id) then
    select t.club_id into v_club from public.teams t where t.id = new.team_id;
    if not calendar.location_usable(new.default_location_id, v_club) then
      raise exception 'calendar.team_settings: the default place is a live place of the team''s club' using errcode = '23514', constraint = 'team_settings_location';
    end if;
  end if;
  return new;
end $$;

CREATE FUNCTION calendar.team_settings_need_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from calendar.settings_changes c where c.team_id = new.team_id and c.revision = new.revision) then
    raise exception 'calendar.team_settings: a write needs its change row (team, revision) in the same transaction' using errcode = '23514';
  end if;
  return null;
end $$;

CREATE FUNCTION calendar.written_in_this_transaction(p_xmin xid) RETURNS boolean
    LANGUAGE sql
    AS $$
    select p_xmin = pg_current_xact_id()::xid
  $$;

CREATE FUNCTION library.guard_exercise_block_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.deleted_at is not null then
      raise exception 'an exercise block is not created deleted' using errcode = '23514';
    end if;
    return new;
  end if;
  if old.deleted_at is not null then
    raise exception 'a deleted exercise block is final' using errcode = '23514';
  end if;
  if new.deleted_at is not null and current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'an exercise block is deleted only under READ COMMITTED' using errcode = '23514';
  end if;
  if new.deleted_at is not null and (
       exists (select 1 from library.exercise_collection_items where collection_id = old.id)
       or exists (select 1 from library.exercise_collection_users where collection_id = old.id)) then
    raise exception 'an exercise block is deleted only without exercises and users' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION library.guard_exercise_block_membership() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  block_deleted_at timestamptz;
begin
  select c.deleted_at into block_deleted_at
    from library.exercise_collections c where c.id = new.collection_id for share;
  if block_deleted_at is not null then
    raise exception 'exercise block is deleted' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION library.guard_exercise_copy_parent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'library'
    AS $$
begin
  if tg_op='UPDATE' and old.copy_parent_id is not null and
    (new.copy_parent_id is distinct from old.copy_parent_id or new.owner_user_id is distinct from old.owner_user_id or new.owner_scope is distinct from old.owner_scope) then
    raise exception using errcode='23514',message='Exercise copy provenance cannot be changed.';
  end if;
  if new.copy_parent_id is not null then
    perform id from library.exercises where id=new.copy_parent_id for share;
    if exists (
      with recursive ancestry as (
        select id,coalesce(source_exercise_id,copy_parent_id) as parent,array[id] as path from library.exercises where id=new.copy_parent_id
        union all
        select source.id,coalesce(source.source_exercise_id,source.copy_parent_id),ancestry.path||source.id
        from library.exercises source join ancestry on source.id=ancestry.parent
        where not source.id=any(ancestry.path)
      ) select 1 from ancestry where id=new.id or parent=any(path)
    ) then
      raise exception using errcode='23514',message='Exercise copy source cycle is not allowed.';
    end if;
  end if;
  return new;
end $$;

CREATE FUNCTION library.guard_exercise_copy_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'library'
    AS $$
begin
  if tg_op = 'UPDATE' then
    if old.source_exercise_id is not null
       and (new.source_exercise_id is distinct from old.source_exercise_id
         or new.owner_scope is distinct from old.owner_scope
         or new.owner_user_id is distinct from old.owner_user_id) then
      raise exception using errcode = '23514',
        message = 'Exercise copy provenance cannot be changed.';
    end if;
    if old.owner_scope = 'system'
       and (new.owner_scope is distinct from 'system' or new.source_exercise_id is not null) then
      if current_setting('transaction_isolation') <> 'read committed' then
        raise exception using errcode = '23514',
          message = 'Exercise source ownership changes require READ COMMITTED.';
      end if;
      if exists (select 1 from library.exercises personal where personal.source_exercise_id = old.id) then
        raise exception using errcode = '23514',
          message = 'A referenced exercise source must remain system-owned.';
      end if;
    end if;
  end if;
  if new.source_exercise_id is not null then
    perform source.id from library.exercises source
      where source.id = new.source_exercise_id and source.owner_scope = 'system'
        and source.source_exercise_id is null
      for share of source;
    if not found then
      raise exception using errcode = '23514',
        message = 'Exercise copies require a canonical system source.';
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION media.l1_asset_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if NEW.source_video_asset_id is not null and NEW.source_video_asset_id is distinct from OLD.source_video_asset_id then
    if NEW.source_video_asset_id=NEW.id then raise exception 'media_reference_unavailable' using errcode='P7501'; end if;
    perform media.l1_require_ready(NEW.source_video_asset_id,'video');
  end if;
  if OLD.status='ready' and (NEW.status<>'ready' or NEW.object_key is distinct from OLD.object_key or NEW.kind is distinct from OLD.kind)
    and current_setting('transaction_isolation')<>'read committed' then raise exception 'media_retention_isolation_required' using errcode='P7503'; end if;
  if OLD.status='ready' and (NEW.status<>'ready' or NEW.object_key is distinct from OLD.object_key or NEW.kind is distinct from OLD.kind)
    and exists(select 1 from media.asset_reference_matrix where asset_id=OLD.id and protects_retention) then
    raise exception 'media_retention_protected' using errcode='P7502';
  end if;
  return NEW;
end; $$;

CREATE FUNCTION media.l1_asset_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if NEW.source_video_asset_id=NEW.id then raise exception 'media_reference_unavailable' using errcode='P7501'; end if;
  perform media.l1_require_ready(NEW.source_video_asset_id,'video');return NEW;
end; $$;

CREATE FUNCTION media.l1_capture_members(p_hold uuid, p_item uuid, p_video uuid, p_image uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare inserted record;
begin
  for inserted in
    insert into media.hold_assets(hold_id,asset_id,plan_item_id,slot)
      select p_hold,v.asset,p_item,v.slot from (values(p_video,'video'),(p_image,'image')) v(asset,slot)
      where v.asset is not null and not exists(select 1 from media.hold_assets h
        where h.hold_id=p_hold and h.asset_id=v.asset and h.slot=v.slot)
      order by v.asset,v.slot on conflict(hold_id,asset_id,slot) do nothing returning asset_id,slot
  loop
    insert into media.retention_events(asset_id,hold_id,event,source_table,source_id,reason,details)
      values(inserted.asset_id,p_hold,'manifest_asset_captured','plans.plan_items',p_item,
        'Preserve acquired-use evidence; not playback authorization',jsonb_build_object('slot',inserted.slot));
  end loop;
end; $$;

CREATE FUNCTION media.l1_capture_plan(p_plan uuid, p_item uuid DEFAULT NULL::uuid, p_grant uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare p plans.plans%rowtype; basis record; hold_uuid uuid; new_hold boolean; member record; delta record;
begin
  if p_item is not null then
    select i.* into delta from media.l1_item_assets i join plans.plan_sessions ps on ps.id=i.plan_session_id
      join plans.plan_days d on d.id=ps.plan_day_id where i.id=p_item and d.plan_id=p_plan;
    if not found or (delta.video_asset_id is null and delta.image_asset_id is null) then return; end if;
  end if;
  select * into p from plans.plans where id=p_plan for no key update;
  if not found then return; end if;
  if p_item is null and not exists(select 1 from media.l1_item_assets i join plans.plan_sessions ps on ps.id=i.plan_session_id
    join plans.plan_days d on d.id=ps.plan_day_id where d.plan_id=p_plan and (i.video_asset_id is not null or i.image_asset_id is not null)) then return; end if;
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'media_retention_isolation_required' using errcode='P7503'; end if;
  for basis in
    select 'assigned:'||p.id||':'||p.athlete_id as basis_key,'assigned_plan'::text as kind,null::uuid as grant_id,null::uuid as beneficiary,
      p.athlete_id as athlete,false as needs_review,jsonb_build_object('planStatus',p.status,'athleteId',p.athlete_id) as snapshot
      where p_grant is null and p.athlete_id is not null and not coalesce(p.is_template,false) and p.status='active' and coalesce(p.is_active,true)
    union all
    select 'grant:'||g.id||':'||p.id||':'||coalesce(g.user_id::text,'unknown'),case when g.access_type='purchased' then 'unverified_commercial'
      when g.access_type in ('assigned','coach_assigned','downloaded') then 'program_grant' else 'ambiguous_grant' end,
      g.id,g.user_id,null,coalesce(g.access_type not in ('assigned','coach_assigned','downloaded'),true),
      jsonb_build_object('accessType',g.access_type,'status',g.status,'startsAt',g.starts_at,'expiresAt',g.expires_at,'source',g.source,'license',g.license_snapshot)
      from library.program_access g where g.plan_id=p_plan and g.status in ('accessed','used','completed')
        and (g.expires_at is null or g.expires_at>now()) and (p_grant is null or g.id=p_grant)
        and not (g.access_type is not distinct from 'copied' and g.user_id is not distinct from p.created_by_user_id)
  loop
    insert into media.retention_holds(basis_key,basis_type,source_plan_id,source_program_access_id,beneficiary_user_id,
      source_owner_user_id,assigned_athlete_id,review_required,reason,basis_snapshot)
      values(basis.basis_key,basis.kind,p_plan,basis.grant_id,basis.beneficiary,p.created_by_user_id,basis.athlete,basis.needs_review,
        case when basis.needs_review then 'Existing grant requires review; no payment proof inferred' else 'Existing application grant or assigned plan; preserve snapshot media' end,basis.snapshot)
      on conflict(basis_key) do nothing returning id into hold_uuid;
    new_hold:=found;
    if not new_hold then select id into hold_uuid from media.retention_holds where basis_key=basis.basis_key; end if;
    if new_hold then insert into media.retention_events(hold_id,event,source_table,source_id,reason,details)
      values(hold_uuid,'hold_created','plans.plans',p_plan,'Acquired-use retention captured; not playback authorization',basis.snapshot); end if;
    if p_item is not null then
      perform media.l1_capture_members(hold_uuid,delta.id,delta.video_asset_id,delta.image_asset_id);
    else
      for member in select i.id,i.video_asset_id,i.image_asset_id from media.l1_item_assets i
        join plans.plan_sessions ps on ps.id=i.plan_session_id join plans.plan_days d on d.id=ps.plan_day_id
        where d.plan_id=p_plan and (i.video_asset_id is not null or i.image_asset_id is not null) order by i.id
      loop perform media.l1_capture_members(hold_uuid,member.id,member.video_asset_id,member.image_asset_id); end loop;
    end if;
  end loop;
end; $$;

CREATE FUNCTION media.l1_derivation_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare old_source uuid;
begin
  if TG_OP='UPDATE' then old_source:=OLD.source_video_asset_id; end if;
  if NEW.source_video_asset_id is distinct from old_source then
    insert into media.retention_events(asset_id,event,source_table,source_id,reason,details)
      select v.id,v.event,'media.assets',NEW.id,'Derived media ancestry changed; no hold release',
        jsonb_build_object('slot','source_video')
      from (values(old_source,'reference_removed'),(NEW.source_video_asset_id,'reference_added')) v(id,event)
      where v.id is not null;
  end if;
  return null;
end; $$;

CREATE FUNCTION media.l1_drive_copy_capture() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare plan_uuid uuid;
begin
  for plan_uuid in select plan_id from media.l1_drive_plan_ids(NEW.drive_file_id,NEW.kind) order by plan_id loop
    perform media.l1_capture_plan(plan_uuid);
  end loop;
  return null;
end; $$;

CREATE FUNCTION media.l1_drive_copy_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare plan_uuid uuid;
begin
  perform media.l1_lock_drive_import(NEW.drive_file_id,NEW.kind);
  perform media.l1_require_ready(NEW.asset_id,NEW.kind);
  return NEW;
end; $$;

CREATE FUNCTION media.l1_drive_file_id(p_url text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare raw text:=btrim(p_url); file_id text;
begin
  file_id:=(regexp_match(raw,'drive\.google\.com/file/d/([^/?#]+)'))[1];
  if file_id is null and raw ~ 'drive\.google\.com' then file_id:=(regexp_match(raw,'[?&]id=([^&#]+)'))[1]; end if;
  if file_id is null then file_id:=(regexp_match(raw,'lh3\.googleusercontent\.com/d/([^/?#=]+)'))[1]; end if;
  if file_id ~ '^[A-Za-z0-9_-]{10,200}$' then return file_id; end if;
  return null;
end; $_$;

CREATE FUNCTION media.l1_drive_item_capture() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare plan_uuid uuid;
begin
  select d.plan_id into plan_uuid from plans.plan_sessions s join plans.plan_days d on d.id=s.plan_day_id where s.id=NEW.plan_session_id;
  perform media.l1_capture_plan(plan_uuid,NEW.id);
  return null;
end; $$;

CREATE FUNCTION media.l1_drive_item_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare plan_uuid uuid; reference record;
begin
  for plan_uuid in select distinct d.plan_id from plans.plan_sessions s join plans.plan_days d on d.id=s.plan_day_id
    where s.id=NEW.plan_session_id order by d.plan_id loop
    perform 1 from plans.plans where id=plan_uuid for no key update;
  end loop;
  for reference in select v.file_id,v.kind from (values
    (case when NEW.video_source='legacy' then media.l1_drive_file_id(NEW.video_url) end,'video'),
    (case when NEW.image_source='legacy' then media.l1_drive_file_id(NEW.image_url) end,'image')) v(file_id,kind)
    where v.file_id is not null order by v.file_id,v.kind loop
    if current_setting('transaction_isolation')<>'read committed' then raise exception 'media_retention_isolation_required' using errcode='P7503'; end if;
    perform pg_advisory_xact_lock(hashtextextended('drive-copy:'||reference.file_id||':'||reference.kind,0));
    perform media.l1_require_ready(c.asset_id,reference.kind) from media.drive_copies c
      where c.drive_file_id=reference.file_id and c.kind=reference.kind;
  end loop;
  return NEW;
end; $$;

CREATE FUNCTION media.l1_drive_plan_ids(p_file text, p_kind text) RETURNS TABLE(plan_id uuid)
    LANGUAGE sql STABLE
    AS $$
  select distinct d.plan_id from plans.plan_items i join plans.plan_sessions s on s.id=i.plan_session_id join plans.plan_days d on d.id=s.plan_day_id
  where (p_kind='video' and i.video_source='legacy' and media.l1_drive_file_id(i.video_url)=p_file)
     or (p_kind='image' and i.image_source='legacy' and media.l1_drive_file_id(i.image_url)=p_file)
$$;

CREATE FUNCTION media.l1_grant_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- Evidence already exists from grant creation/activation and item deltas.
  -- A revoke/delete must never take grant -> plan locks against plan DELETE's cascade.
  if TG_WHEN='BEFORE' and TG_OP='UPDATE' then return NEW; end if;
  insert into media.retention_events(event,source_table,source_id,reason,details)
    values('grant_'||lower(TG_OP),'library.program_access',coalesce(NEW.id,OLD.id),
      'Grant transition recorded; historical event alone is not an entitlement',
      jsonb_build_object('before',case when TG_OP<>'INSERT' then to_jsonb(OLD) else null end,'after',case when TG_OP<>'DELETE' then to_jsonb(NEW) else null end));
  if TG_WHEN='AFTER' and NEW.status in ('accessed','used','completed') and (NEW.expires_at is null or NEW.expires_at>now()) then
    perform media.l1_capture_plan(NEW.plan_id,null,NEW.id);
  end if;
  if TG_OP='DELETE' then return OLD; end if;return NEW;
end; $$;

CREATE FUNCTION media.l1_hold_asset_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform media.l1_require_ready(NEW.asset_id,NEW.slot);
  return NEW;
end; $$;

CREATE FUNCTION media.l1_lock_drive_import(p_file text, p_kind text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare plan_uuid uuid; locked_plans uuid[]:='{}'; saved jsonb; lock_key text:=p_file||':'||p_kind;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'media_retention_isolation_required' using errcode='P7503'; end if;
  saved:=coalesce(nullif(current_setting('media.drive_import_plans',true),''),'{}')::jsonb;
  if saved ? lock_key then
    select coalesce(array_agg(value::uuid),'{}') into locked_plans from jsonb_array_elements_text(saved->lock_key);
    if exists(select 1 from media.l1_drive_plan_ids(p_file,p_kind) where not(plan_id=any(locked_plans))) then
      raise exception 'drive_reference_set_changed' using errcode='40001';
    end if;
    return;
  end if;
  for plan_uuid in select plan_id from media.l1_drive_plan_ids(p_file,p_kind) order by plan_id loop
    perform 1 from plans.plans where id=plan_uuid for no key update nowait;
    locked_plans:=array_append(locked_plans,plan_uuid);
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('drive-copy:'||p_file||':'||p_kind,0));
  if exists(select 1 from media.l1_drive_plan_ids(p_file,p_kind) where not(plan_id=any(locked_plans))) then
    raise exception 'drive_reference_set_changed' using errcode='40001';
  end if;
  perform set_config('media.drive_import_plans',jsonb_set(saved,array[lock_key],to_jsonb(locked_plans))::text,true);
end; $$;

CREATE FUNCTION media.l1_parent_move_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare plan_uuid uuid;
begin
  if TG_TABLE_NAME='plan_days' then
    for plan_uuid in select distinct id from unnest(array[OLD.plan_id,NEW.plan_id]) id order by id loop perform media.l1_capture_plan(plan_uuid); end loop;
  else
    for plan_uuid in select distinct d.plan_id from plans.plan_days d where d.id in (OLD.plan_day_id,NEW.plan_day_id) order by d.plan_id loop perform media.l1_capture_plan(plan_uuid); end loop;
  end if;
  insert into media.retention_events(event,source_table,source_id,reason)
    values('reference_parent_moved',TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME,NEW.id,'Re-evaluate retention for moved snapshot hierarchy');
  return null;
end; $$;

CREATE FUNCTION media.l1_plan_delete_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  insert into media.retention_events(hold_id,event,source_table,source_id,reason,details)
    select h.id,'source_plan_deleted','plans.plans',OLD.id,
      'Business row deleted; historical evidence retained without playback rights',
      jsonb_build_object('athleteId',OLD.athlete_id,'ownerUserId',OLD.created_by_user_id)
    from media.retention_holds h where h.source_plan_id=OLD.id;
  return OLD;
end; $$;

CREATE FUNCTION media.l1_plan_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform media.l1_capture_plan(NEW.id);return null;
end; $$;

CREATE FUNCTION media.l1_reference_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare before_row jsonb; after_row jsonb; slot_name text; old_id uuid; new_id uuid; plan_uuid uuid;
begin
  before_row:=case when TG_OP<>'INSERT' then to_jsonb(OLD) else '{}'::jsonb end;
  after_row:=case when TG_OP<>'DELETE' then to_jsonb(NEW) else '{}'::jsonb end;
  foreach slot_name in array array['video','image'] loop
    old_id:=(before_row->>(slot_name||'_asset_id'))::uuid;new_id:=(after_row->>(slot_name||'_asset_id'))::uuid;
    if old_id is distinct from new_id then
      if old_id is not null then insert into media.retention_events(asset_id,event,source_table,source_id,reason,details)
        values(old_id,'reference_removed',TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME,coalesce(NEW.id,OLD.id),'Source selection removed; no automatic hold release',jsonb_build_object('slot',slot_name)); end if;
      if new_id is not null then insert into media.retention_events(asset_id,event,source_table,source_id,reason,details)
        values(new_id,'reference_added',TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME,NEW.id,'New source selection',jsonb_build_object('slot',slot_name)); end if;
    end if;
  end loop;
  if TG_TABLE_SCHEMA='plans' and TG_OP='UPDATE' and after_row->>'plan_session_id' is distinct from before_row->>'plan_session_id' then
    insert into media.retention_events(event,source_table,source_id,reason,details)
      values('reference_context_changed','plans.plan_items',NEW.id,'Moved snapshot; prior manifests remain retained',jsonb_build_object('oldSessionId',OLD.plan_session_id,'newSessionId',NEW.plan_session_id));
  end if;
  if TG_TABLE_SCHEMA='plans' and TG_OP<>'DELETE' then
    select d.plan_id into plan_uuid from plans.plan_sessions s join plans.plan_days d on d.id=s.plan_day_id where s.id=NEW.plan_session_id;
    perform media.l1_capture_plan(plan_uuid,NEW.id);
  end if;
  return null;
end; $$;

CREATE FUNCTION media.l1_reference_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare previous jsonb; value uuid; old_value uuid; slot_name text; plan_uuid uuid;
begin
  previous:=case when TG_OP='UPDATE' then to_jsonb(OLD) else '{}'::jsonb end;
  -- The grant path locks plan -> assets. Item writes must follow the same order.
  if TG_TABLE_SCHEMA='plans' then
    for plan_uuid in select distinct d.plan_id from plans.plan_sessions ps join plans.plan_days d on d.id=ps.plan_day_id
      where ps.id in (NEW.plan_session_id,(previous->>'plan_session_id')::uuid) order by d.plan_id
    loop perform 1 from plans.plans where id=plan_uuid for no key update; end loop;
  end if;
  -- Sorted IDs avoid the common two-slot reverse-lock deadlock.
  for slot_name,value in select x.slot,x.asset from (values
    ('video',NEW.video_asset_id),('image',NEW.image_asset_id)) x(slot,asset) order by x.asset nulls last loop
    old_value:=(previous->>(slot_name||'_asset_id'))::uuid;
    if value is not null and value is distinct from old_value then perform media.l1_require_ready(value,slot_name); end if;
  end loop;
  return NEW;
end; $$;

CREATE FUNCTION media.l1_require_ready(p_asset uuid, p_kind text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare a media.assets%rowtype;
begin
  if p_asset is null then return; end if;
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'media_retention_isolation_required' using errcode='P7503'; end if;
  select * into a from media.assets where id=p_asset for share;
  if not found or a.status<>'ready' or a.kind<>p_kind then
    raise exception 'media_reference_unavailable' using errcode='P7501';
  end if;
end; $$;

CREATE FUNCTION media.reject_audit_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'Media storage audit is append-only' using errcode = '42501';
end;
$$;

CREATE FUNCTION media.reject_drive_copy_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'A Drive copy is added or removed, never changed' using errcode = '42501';
end;
$$;

CREATE FUNCTION public.protect_athlete_membership_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.athlete_id is distinct from old.athlete_id or new.club_id is distinct from old.club_id
     or new.team_id is distinct from old.team_id or new.membership_type is distinct from old.membership_type then
    raise exception 'athlete_memberships (id=%): athlete, club, team and membership type never change — archive it and add a new membership', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.protect_athlete_membership_period() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  m record;
begin
  if tg_op = 'DELETE' then
    if exists (select 1 from public.athlete_memberships where id = old.membership_id) then
      raise exception 'athlete_membership_periods: a period is removed only with its membership (period %)', old.id;
    end if;
    return old;
  end if;
  if current_setting('optimove.membership_period_write', true) is distinct from 'on' then
    raise exception 'athlete_membership_periods: written only by the membership trigger (% refused)', tg_op;
  end if;
  if tg_op = 'INSERT' then
    select athlete_id, club_id, team_id, membership_type into m from public.athlete_memberships where id = new.membership_id;
    if not found
       or m.athlete_id is distinct from new.athlete_id or m.club_id is distinct from new.club_id
       or m.team_id is distinct from new.team_id or m.membership_type is distinct from new.membership_type then
      raise exception 'athlete_membership_periods: the period does not copy membership %', new.membership_id;
    end if;
    return new;
  end if;
  -- UPDATE: only closing an open period, once.
  if old.valid_to is not null or new.valid_to is null
     or new.id is distinct from old.id or new.membership_id is distinct from old.membership_id
     or new.athlete_id is distinct from old.athlete_id or new.club_id is distinct from old.club_id
     or new.team_id is distinct from old.team_id or new.membership_type is distinct from old.membership_type
     or new.valid_from is distinct from old.valid_from or new.created_at is distinct from old.created_at then
    raise exception 'athlete_membership_periods: a period only gets its end once (period %)', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.record_athlete_membership_period() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  previous text := current_setting('optimove.membership_period_write', true);
  member_before boolean;
  member_after boolean := new.status in ('active', 'paused');
begin
  perform set_config('optimove.membership_period_write', 'on', true);
  if tg_op = 'INSERT' then
    if member_after then
      insert into public.athlete_membership_periods (membership_id, athlete_id, club_id, team_id, membership_type, valid_from)
      values (new.id, new.athlete_id, new.club_id, new.team_id, new.membership_type, new.starts_at);
    else
      insert into public.athlete_membership_periods (membership_id, athlete_id, club_id, team_id, membership_type, valid_from, valid_to)
      values (new.id, new.athlete_id, new.club_id, new.team_id, new.membership_type, new.starts_at,
              greatest(new.starts_at, coalesce(new.archived_at, now())));
    end if;
  elsif new.status is distinct from old.status then
    member_before := old.status in ('active', 'paused');
    if member_before and not member_after then
      update public.athlete_membership_periods
         set valid_to = greatest(valid_from, coalesce(new.archived_at, now()))
       where membership_id = new.id and valid_to is null;
    elsif member_after and not member_before then
      -- now() is the transaction's START: a restore that waited on the row
      -- lock behind an archive may have started before that archive's end.
      -- The new period never starts before the previous one ended, so the
      -- periods of one membership never overlap.
      insert into public.athlete_membership_periods (membership_id, athlete_id, club_id, team_id, membership_type, valid_from)
      select new.id, new.athlete_id, new.club_id, new.team_id, new.membership_type,
             greatest(now(), coalesce((select max(p.valid_to) from public.athlete_membership_periods p where p.membership_id = new.id), now()))
       where not exists (select 1 from public.athlete_membership_periods where membership_id = new.id and valid_to is null);
    end if;
  end if;
  perform set_config('optimove.membership_period_write', coalesce(previous, ''), true);
  return null;
end;
$$;

CREATE FUNCTION public.validate_athlete_device_timezone() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if NEW.device_timezone is not null and not exists (select 1 from pg_timezone_names where name = NEW.device_timezone) then
    raise exception 'device_timezone % is not a recognized IANA timezone name', NEW.device_timezone;
  end if;
  return NEW;
end $$;

CREATE FUNCTION tests.enforce_approval_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if TG_OP = 'DELETE' then
    raise exception 'Approval audit rows cannot be deleted';
  end if;

  if NEW.decided_at is not null and NEW.decided_at < NEW.requested_at then
    raise exception 'decided_at cannot be before requested_at';
  end if;
  if NEW.revoked_at is not null and NEW.decided_at is not null and NEW.revoked_at < NEW.decided_at then
    raise exception 'revoked_at cannot be before decided_at';
  end if;
  if NEW.cancelled_at is not null and NEW.cancelled_at < NEW.requested_at then
    raise exception 'cancelled_at cannot be before requested_at';
  end if;

  if TG_OP = 'INSERT' then
    return NEW;
  end if;

  if NEW.id is distinct from OLD.id
     or NEW.test_battery_version_id is distinct from OLD.test_battery_version_id
     or NEW.club_id is distinct from OLD.club_id
     or NEW.team_id is distinct from OLD.team_id
     or NEW.requested_by_user_id is distinct from OLD.requested_by_user_id
     or NEW.requested_at is distinct from OLD.requested_at
  then
    raise exception 'test_battery_version_id, club/team scope, requester and requested_at are immutable after insert';
  end if;

  if OLD.status = 'pending' and NEW.status = 'pending' then
    return NEW;

  elsif OLD.status = 'pending' and NEW.status in ('approved','rejected') then
    if NEW.revoked_by_user_id is not null or NEW.revoked_at is not null
       or NEW.cancelled_by_user_id is not null or NEW.cancelled_at is not null then
      raise exception 'Only decision fields may be set when moving pending -> %', NEW.status;
    end if;
    return NEW;

  elsif OLD.status = 'pending' and NEW.status = 'cancelled' then
    if NEW.decided_by_user_id is not null or NEW.decided_at is not null
       or NEW.revoked_by_user_id is not null or NEW.revoked_at is not null then
      raise exception 'Only cancellation fields may be set when moving pending -> cancelled';
    end if;
    return NEW;

  elsif OLD.status = 'approved' and NEW.status = 'revoked' then
    if NEW.decided_by_user_id is distinct from OLD.decided_by_user_id
       or NEW.decided_at is distinct from OLD.decided_at
       or NEW.cancelled_by_user_id is not null or NEW.cancelled_at is not null then
      raise exception 'Only revocation fields may change when moving approved -> revoked';
    end if;
    return NEW;

  elsif OLD.status in ('approved','rejected','revoked','cancelled') then
    raise exception 'Approval rows in % status cannot be modified (approved may only move to revoked)', OLD.status;

  else
    raise exception 'Invalid approval status transition: % -> %', OLD.status, NEW.status;
  end if;
end $$;

CREATE FUNCTION tests.enforce_condition_battery_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_set_battery_version_id uuid;
begin
  select battery_version_id into v_set_battery_version_id
  from tests.test_criteria_set_versions where id = NEW.set_version_id;

  if NEW.battery_version_id is distinct from v_set_battery_version_id then
    raise exception 'test_criteria_conditions.battery_version_id (%) must match its set version''s battery_version_id (%)',
      NEW.battery_version_id, v_set_battery_version_id;
  end if;
  return NEW;
end $$;

CREATE FUNCTION tests.enforce_criteria_condition_value_types() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_resolved_type text;
  v_sel_source_kind text;
  v_sel_native_id uuid;
  v_sel_derived_id uuid;
  v_decl_source_kind text;
  v_decl_native_id uuid;
  v_decl_derived_id uuid;
begin
  v_resolved_type := null;

  if NEW.parameter_source_kind = 'battery_item_parameter_selection' then
    select source_kind, test_parameter_id, test_version_derived_parameter_id
      into v_sel_source_kind, v_sel_native_id, v_sel_derived_id
    from tests.test_battery_item_parameter_selections
    where id = NEW.source_battery_item_parameter_selection_id;

    if v_sel_source_kind = 'native' then
      select value_type into v_resolved_type from tests.test_parameters where id = v_sel_native_id;
    else
      select result_type into v_resolved_type from tests.test_version_derived_parameters where id = v_sel_derived_id;
    end if;

  elsif NEW.parameter_source_kind = 'battery_derived' then
    select result_type into v_resolved_type
    from tests.test_battery_derived_parameters where id = NEW.source_battery_derived_parameter_id;

  elsif NEW.parameter_source_kind = 'declared_source' then
    select source_kind, test_parameter_id, test_derived_parameter_id
      into v_decl_source_kind, v_decl_native_id, v_decl_derived_id
    from tests.test_criteria_set_version_sources
    where id = NEW.source_declaration_id;

    if v_decl_source_kind = 'native' then
      select value_type into v_resolved_type from tests.test_parameters where id = v_decl_native_id;
    else
      select result_type into v_resolved_type from tests.test_version_derived_parameters where id = v_decl_derived_id;
    end if;
  end if;

  if v_resolved_type is null then
    raise exception 'could not resolve source type for criteria condition';
  end if;

  if v_resolved_type = 'text' then
    raise exception 'text-typed sources are not supported in criteria conditions (v4.1)';
  end if;

  -- v4.2 (tačka 2): operator kompatibilnost sa tipom izvora važi nezavisno od
  -- reference_type. Bez ovoga bi boolean izvor sa session_reference/
  -- individual_history/group_reference i operatorom gt/gte/lt/lte prošao,
  -- jer se ranija provera nalazila samo unutar "reference_type = 'static'" grane.
  -- 'between' takođe nije eq/neq, pa je time automatski pokriveno i "between
  -- nije dozvoljen za boolean izvor" bez posebne provere za to.
  if v_resolved_type = 'boolean' and NEW.operator not in ('eq','neq') then
    raise exception 'boolean source only supports eq/neq (got %)', NEW.operator;
  end if;

  if NEW.reference_type = 'static' then
    if v_resolved_type in ('numeric','integer','ordinal') then
      if jsonb_typeof(NEW.static_value) is distinct from 'number' then
        raise exception 'static_value must be a JSON number for numeric-compatible source (type %)', v_resolved_type;
      end if;
      -- v4.2 (tačka 4): integer/ordinal static_value ne sme imati decimalni deo.
      if v_resolved_type in ('integer','ordinal')
         and (NEW.static_value)::text::numeric <> trunc((NEW.static_value)::text::numeric) then
        raise exception 'static_value must be a whole number for source type %', v_resolved_type;
      end if;
      if NEW.operator = 'between' then
        if jsonb_typeof(NEW.static_value_upper) is distinct from 'number' then
          raise exception 'static_value_upper must be a JSON number for between';
        end if;
        if v_resolved_type in ('integer','ordinal')
           and (NEW.static_value_upper)::text::numeric <> trunc((NEW.static_value_upper)::text::numeric) then
          raise exception 'static_value_upper must be a whole number for source type %', v_resolved_type;
        end if;
        if (NEW.static_value)::text::numeric > (NEW.static_value_upper)::text::numeric then
          raise exception 'static_value must be <= static_value_upper';
        end if;
      end if;
    elsif v_resolved_type = 'boolean' then
      if jsonb_typeof(NEW.static_value) is distinct from 'boolean' then
        raise exception 'static_value must be a JSON boolean for boolean source';
      end if;
    end if;
  end if;

  if NEW.reference_type in ('individual_history','group_reference') and v_resolved_type not in ('numeric','integer','ordinal') then
    raise exception 'individual_history/group_reference require a numeric-compatible source (got %)', v_resolved_type;
  end if;

  return NEW;
end $$;

CREATE FUNCTION tests.enforce_criteria_set_version_battery_lock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_has_children boolean;
begin
  if NEW.battery_version_id is distinct from OLD.battery_version_id then
    select exists (
      select 1 from tests.test_criteria_set_version_sources where set_version_id = OLD.id
      union all
      select 1 from tests.test_criteria_rules where set_version_id = OLD.id
      union all
      select 1 from tests.test_criteria_outputs where set_version_id = OLD.id
      union all
      select 1 from tests.test_criteria_conditions where set_version_id = OLD.id
    ) into v_has_children;

    if v_has_children then
      raise exception 'Cannot change battery_version_id on a criteria set version that already has sources/rules/outputs/conditions';
    end if;
  end if;
  return NEW;
end $$;

CREATE FUNCTION tests.enforce_fork_lineage_matches_parent() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
declare
  v_stable_table text := TG_ARGV[0];
  v_stable_id_column text := TG_ARGV[1];
  v_fork_column text := TG_ARGV[2];
  v_stable_id uuid;
  v_local_fork_value uuid;
  v_parent_fork_value uuid;
begin
  if NEW.version_number <> 1 then
    return NEW;
  end if;

  execute format('select ($1).%I', v_stable_id_column) using NEW into v_stable_id;
  execute format('select ($1).%I', v_fork_column) using NEW into v_local_fork_value;
  execute format('select %I from %s where id = $1', v_fork_column, v_stable_table)
    using v_stable_id into v_parent_fork_value;

  if v_local_fork_value is distinct from v_parent_fork_value then
    raise exception 'version 1''s % (%) must match its stable parent''s % (%)',
      v_fork_column, v_local_fork_value, v_fork_column, v_parent_fork_value;
  end if;
  return NEW;
end $_$;

CREATE FUNCTION tests.enforce_immutable_active_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
declare
  v_column text := TG_ARGV[0];
  v_version_table text := TG_ARGV[1];
  v_old_version_id uuid;
  v_new_version_id uuid;
  v_old_status text;
  v_new_status text;
begin
  if TG_OP in ('UPDATE','DELETE') then
    execute format('select ($1).%I', v_column) using OLD into v_old_version_id;
    execute format('select status from %s where id = $1 for share', v_version_table) using v_old_version_id into v_old_status;
    if v_old_status in ('active','archived') then
      raise exception 'Cannot modify or delete a row belonging to a % version', v_old_status;
    end if;
  end if;

  if TG_OP in ('UPDATE','INSERT') then
    execute format('select ($1).%I', v_column) using NEW into v_new_version_id;
    execute format('select status from %s where id = $1 for share', v_version_table) using v_new_version_id into v_new_status;
    if v_new_status in ('active','archived') then
      raise exception 'Cannot insert or reparent a row into a % version', v_new_status;
    end if;
  end if;

  return case when TG_OP = 'DELETE' then OLD else NEW end;
end $_$;

CREATE FUNCTION tests.enforce_predefined_reference_native_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_source_kind text;
  v_native_param_id uuid;
  v_native_value_type text;
  v_ref_param_id uuid;
begin
  if NEW.reference_type <> 'predefined_reference' then
    return NEW;
  end if;

  v_source_kind := null;
  v_native_param_id := null;

  if NEW.parameter_source_kind = 'battery_item_parameter_selection' then
    select source_kind, test_parameter_id into v_source_kind, v_native_param_id
    from tests.test_battery_item_parameter_selections
    where id = NEW.source_battery_item_parameter_selection_id;
  elsif NEW.parameter_source_kind = 'declared_source' then
    select source_kind, test_parameter_id into v_source_kind, v_native_param_id
    from tests.test_criteria_set_version_sources
    where id = NEW.source_declaration_id;
  else
    v_source_kind := 'derived';
  end if;

  if v_source_kind is distinct from 'native' then
    raise exception 'predefined_reference is only allowed for native parameter sources (got %)', v_source_kind;
  end if;

  -- v4.1: native izvor mora dodatno biti numerički kompatibilan (tačka 7).
  select value_type into v_native_value_type from tests.test_parameters where id = v_native_param_id;
  if v_native_value_type not in ('numeric','integer','ordinal') then
    raise exception 'predefined_reference requires a numeric-compatible native parameter (got %)', v_native_value_type;
  end if;

  select test_parameter_id into v_ref_param_id
  from tests.test_parameter_reference_values where id = NEW.reference_value_id;

  if v_ref_param_id is distinct from v_native_param_id then
    raise exception 'reference_value_id must belong to the same native test parameter as the condition source';
  end if;

  return NEW;
end $$;

CREATE FUNCTION tests.enforce_standalone_set_sources() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_battery_version_id uuid;
begin
  select battery_version_id into v_battery_version_id
  from tests.test_criteria_set_versions where id = NEW.set_version_id;

  if v_battery_version_id is not null then
    raise exception 'test_criteria_set_version_sources may only reference a standalone (battery_version_id IS NULL) criteria set version';
  end if;
  return NEW;
end $$;

CREATE FUNCTION tests.enforce_supersede_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_row record;
  v_partner record;
  v_current uuid;
  v_visited uuid[];
  v_hops integer := 0;
begin
  if TG_TABLE_NAME = 'test_assessments' then
    select * into v_row from tests.test_assessments where id = NEW.id;
  else
    select * into v_row from tests.test_battery_assessments where id = NEW.id;
  end if;
  if v_row.id is null then
    return NEW; -- red je posle toga obrisan u istoj transakciji (draft delete) - nema šta da se proveri
  end if;

  if v_row.supersedes_assessment_id is not null then
    if TG_TABLE_NAME = 'test_assessments' then
      select * into v_partner from tests.test_assessments where id = v_row.supersedes_assessment_id;
    else
      select * into v_partner from tests.test_battery_assessments where id = v_row.supersedes_assessment_id;
    end if;
    if v_partner.id is null then
      raise exception '%.% supersedes a non-existent row %', TG_TABLE_NAME, v_row.id, v_row.supersedes_assessment_id;
    end if;
    if v_row.status <> 'completed' then
      raise exception '%.% supersedes % but is not itself completed (status=%)', TG_TABLE_NAME, v_row.id, v_partner.id, v_row.status;
    end if;
    if v_partner.status <> 'invalidated' or v_partner.superseded_by_assessment_id is distinct from v_row.id then
      raise exception '%.% claims to supersede % but that link is not reciprocated by commit time (predecessor status=%, superseded_by=%) - the supersede must fully commit or fully roll back', TG_TABLE_NAME, v_row.id, v_partner.id, v_partner.status, v_partner.superseded_by_assessment_id;
    end if;
    if v_partner.athlete_id is distinct from v_row.athlete_id
       or v_partner.assignment_id is distinct from v_row.assignment_id
       or (TG_TABLE_NAME = 'test_assessments' and (
             v_partner.test_version_id is distinct from v_row.test_version_id
             or v_partner.battery_assessment_id is distinct from v_row.battery_assessment_id
             or v_partner.battery_version_id is distinct from v_row.battery_version_id
             or v_partner.battery_item_id is distinct from v_row.battery_item_id
             or v_partner.attempt_number is distinct from v_row.attempt_number
           ))
       or (TG_TABLE_NAME = 'test_battery_assessments' and v_partner.battery_version_id is distinct from v_row.battery_version_id)
    then
      raise exception '%.% and predecessor % must share identical athlete/test-or-battery-version/assignment/battery-context/attempt', TG_TABLE_NAME, v_row.id, v_partner.id;
    end if;
  end if;

  if v_row.superseded_by_assessment_id is not null then
    if TG_TABLE_NAME = 'test_assessments' then
      select * into v_partner from tests.test_assessments where id = v_row.superseded_by_assessment_id;
    else
      select * into v_partner from tests.test_battery_assessments where id = v_row.superseded_by_assessment_id;
    end if;
    if v_partner.id is null then
      raise exception '%.% is superseded by a non-existent row %', TG_TABLE_NAME, v_row.id, v_row.superseded_by_assessment_id;
    end if;
    if v_row.status <> 'invalidated' then
      raise exception '%.% has superseded_by_assessment_id set but is not itself invalidated (status=%)', TG_TABLE_NAME, v_row.id, v_row.status;
    end if;
    if v_partner.status <> 'completed' or v_partner.supersedes_assessment_id is distinct from v_row.id then
      raise exception '%.% claims to be superseded by % but that link is not reciprocated by commit time (successor status=%, supersedes=%)', TG_TABLE_NAME, v_row.id, v_partner.id, v_partner.status, v_partner.supersedes_assessment_id;
    end if;
  end if;

  -- Ograničena provera ciklusa: prati supersedes_assessment_id lanac
  -- unazad, odbij ako se bilo koji id ponovi.
  v_current := v_row.id;
  v_visited := array[v_current];
  loop
    if TG_TABLE_NAME = 'test_assessments' then
      select supersedes_assessment_id into v_current from tests.test_assessments where id = v_current;
    else
      select supersedes_assessment_id into v_current from tests.test_battery_assessments where id = v_current;
    end if;
    exit when v_current is null;
    v_hops := v_hops + 1;
    if v_hops > 1000 then
      raise exception '%.% supersede chain exceeds 1000 hops - probable cycle', TG_TABLE_NAME, v_row.id;
    end if;
    if v_current = any(v_visited) then
      raise exception '%.% supersede chain contains a cycle at %', TG_TABLE_NAME, v_row.id, v_current;
    end if;
    v_visited := v_visited || v_current;
  end loop;

  return NEW;
end $$;

CREATE FUNCTION tests.enforce_version_row_immutability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_excluded text[] := array['status','updated_at','archived_at','archived_by'];
begin
  if TG_OP = 'DELETE' then
    if OLD.status in ('active','archived') then
      raise exception 'Cannot delete a % version row', OLD.status;
    end if;
    return OLD;
  end if;

  if OLD.status = 'draft' then
    if NEW.status not in ('draft','active') then
      raise exception 'Invalid version status transition: % -> %', OLD.status, NEW.status;
    end if;
    if NEW.status = 'active' then
      if TG_TABLE_NAME = 'test_versions' then
        perform tests.validate_test_version_derived_parameters(NEW.id);
      elsif TG_TABLE_NAME = 'test_battery_versions' then
        perform tests.validate_battery_derived_parameters(NEW.id);
      end if;
      if NEW.published_at is null then
        NEW.published_at := now();
      end if;
    end if;
    return NEW;

  elsif OLD.status = 'active' then
    if NEW.status is distinct from 'archived' then
      raise exception 'Invalid version status transition: % -> %', OLD.status, NEW.status;
    end if;
    if NEW.archived_at is null then
      NEW.archived_at := now();
    end if;
    if (to_jsonb(OLD) - v_excluded) is distinct from (to_jsonb(NEW) - v_excluded) then
      raise exception 'Only status/archived_at/archived_by/updated_at may change when archiving an active version';
    end if;
    return NEW;

  elsif OLD.status = 'archived' then
    raise exception 'Archived version rows are fully immutable';

  else
    raise exception 'Unexpected status %', OLD.status;
  end if;
end $$;

CREATE FUNCTION tests.generate_test_schedule_occurrence(p_schedule_id uuid, p_scheduled_date date) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
declare
  v_schedule tests.test_schedules%rowtype;
  v_occurrence_id uuid;
begin
  select * into v_schedule from tests.test_schedules where id = p_schedule_id for share;
  if v_schedule.id is null then
    raise exception 'schedule % does not exist', p_schedule_id;
  end if;
  if p_scheduled_date < v_schedule.start_date or (v_schedule.end_date is not null and p_scheduled_date > v_schedule.end_date) then
    raise exception 'scheduled_date % is outside schedule %''s start_date/end_date window', p_scheduled_date, p_schedule_id;
  end if;

  insert into tests.test_schedule_occurrences (schedule_id, scheduled_date, opens_at, due_at, closes_at)
  values (
    p_schedule_id,
    p_scheduled_date,
    (p_scheduled_date + v_schedule.opens_time) at time zone v_schedule.timezone,
    case when v_schedule.due_time is null then null else (p_scheduled_date + v_schedule.due_time) at time zone v_schedule.timezone end,
    (p_scheduled_date + v_schedule.closes_time) at time zone v_schedule.timezone
  )
  on conflict (schedule_id, scheduled_date) do nothing
  returning id into v_occurrence_id;

  if v_occurrence_id is null then
    select id into v_occurrence_id from tests.test_schedule_occurrences
    where schedule_id = p_schedule_id and scheduled_date = p_scheduled_date;
  end if;
  return v_occurrence_id;
end $$;

CREATE FUNCTION tests.materialize_test_assignments_for_occurrence(p_occurrence_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  v_occurrence tests.test_schedule_occurrences%rowtype;
  v_schedule tests.test_schedules%rowtype;
  v_inserted_count integer;
begin
  -- FOR UPDATE locks this occurrence row for the rest of the transaction -
  -- unchanged from Phase 1: a second concurrent call for the SAME
  -- occurrence blocks here until the first commits, then re-reads fresh
  -- state (including whether the snapshot was just taken by the call that
  -- won the race).
  select * into v_occurrence from tests.test_schedule_occurrences where id = p_occurrence_id for update;
  if v_occurrence.id is null then
    raise exception 'occurrence % does not exist', p_occurrence_id;
  end if;

  select * into v_schedule from tests.test_schedules where id = v_occurrence.schedule_id;
  -- v_schedule.id cannot be null here: test_schedule_occurrences.schedule_id
  -- is a NOT NULL FK to tests.test_schedules with no ON DELETE that could
  -- orphan it while the occurrence itself still exists.

  if v_occurrence.assignments_materialized_at is null then
    -- Freeze ONLY membership, exactly ONCE, using the same target
    -- resolution the rest of this migration shares (tests.resolve_
    -- schedule_target_athletes). A team/club member added AFTER this point
    -- must never appear here later - this INSERT never runs again for this
    -- occurrence. Effective_timezone is deliberately NOT frozen here
    -- anymore (round 2 correction) - see this file's header for why: it is
    -- read fresh, per athlete, below, at the moment their row actually gets
    -- inserted, not at snapshot time.
    insert into tests.test_occurrence_target_snapshot (occurrence_id, athlete_id)
    select p_occurrence_id, ta.athlete_id
    from tests.resolve_schedule_target_athletes(v_schedule.id) ta
    on conflict (occurrence_id, athlete_id) do nothing;

    update tests.test_schedule_occurrences set assignments_materialized_at = now() where id = p_occurrence_id;
  end if;

  -- Every call (first or repeated) inserts real assignment rows for
  -- whichever snapshotted athletes are ELIGIBLE right now, reading each
  -- one's CURRENT device_timezone fresh (round 2 correction - never the
  -- stale value from whenever the membership snapshot happened to be
  -- taken): eligible means (now() at time zone their CURRENT effective_
  -- timezone)::date equals this occurrence's own scheduled_date - the SAME
  -- condition for one_time and daily/recurring alike (round 2 correction:
  -- the old one_time bypass let every snapshotted athlete's row insert
  -- unconditionally, which contradicted "a one-time date is never
  -- reinterpreted per timezone" - a one_time occurrence has exactly one
  -- real scheduled_date, and an athlete is only ever inserted once their
  -- own real local date actually reaches it). This is what lets an athlete
  -- significantly ahead of (or behind) the schedule's own reference
  -- timezone still get assigned, on a LATER cycle, once their own day
  -- actually reaches this occurrence's date - without ever re-resolving
  -- membership. Each athlete's own row is still only ever inserted once
  -- (on conflict do nothing) - once inserted, its window is immutable (see
  -- the trigger below), so a device-timezone change afterward can only ever
  -- affect a DIFFERENT, not-yet-inserted assignment.
  insert into tests.test_assignments (occurrence_id, athlete_id, timezone, local_scheduled_date, opens_at, due_at, closes_at)
  select
    p_occurrence_id,
    e.athlete_id,
    e.effective_timezone,
    v_occurrence.scheduled_date,
    (v_occurrence.scheduled_date + v_schedule.opens_time) at time zone e.effective_timezone,
    case when v_schedule.due_time is null then null else (v_occurrence.scheduled_date + v_schedule.due_time) at time zone e.effective_timezone end,
    (v_occurrence.scheduled_date + v_schedule.closes_time) at time zone e.effective_timezone
  from (
    select s.athlete_id, coalesce(a.device_timezone, v_schedule.timezone) as effective_timezone
    from tests.test_occurrence_target_snapshot s
    join public.athletes a on a.id = s.athlete_id
    where s.occurrence_id = p_occurrence_id
  ) e
  where (now() at time zone e.effective_timezone)::date = v_occurrence.scheduled_date
  on conflict (occurrence_id, athlete_id) do nothing;

  get diagnostics v_inserted_count = row_count;

  return v_inserted_count;
end $$;

CREATE FUNCTION tests.protect_assignment_identity_and_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_old_rank integer;
  v_new_rank integer;
begin
  if NEW.occurrence_id is distinct from OLD.occurrence_id
     or NEW.athlete_id is distinct from OLD.athlete_id
     or NEW.snapshot_test_version_id is distinct from OLD.snapshot_test_version_id
     or NEW.snapshot_test_battery_version_id is distinct from OLD.snapshot_test_battery_version_id
  then
    raise exception 'test_assignments.% identity/snapshot columns (occurrence_id/athlete_id/snapshot_test_version_id/snapshot_test_battery_version_id) are immutable after creation', OLD.id;
  end if;

  if NEW.timezone is distinct from OLD.timezone
     or NEW.local_scheduled_date is distinct from OLD.local_scheduled_date
     or NEW.opens_at is distinct from OLD.opens_at
     or NEW.due_at is distinct from OLD.due_at
     or NEW.closes_at is distinct from OLD.closes_at
  then
    raise exception 'test_assignments.% timezone/local_scheduled_date/opens_at/due_at/closes_at are an immutable snapshot, taken once at materialization - they can never be changed afterward, including by a device-timezone change (which only ever affects a LATER, not-yet-materialized assignment)', OLD.id;
  end if;

  v_old_rank := case OLD.status when 'pending' then 1 when 'open' then 2 when 'in_progress' then 3 else 4 end;
  v_new_rank := case NEW.status when 'pending' then 1 when 'open' then 2 when 'in_progress' then 3 else 4 end;
  if v_old_rank = 4 and NEW.status <> OLD.status then
    raise exception 'test_assignments.% status % is terminal - cannot transition to %', OLD.id, OLD.status, NEW.status;
  end if;
  if v_new_rank < v_old_rank then
    raise exception 'test_assignments.% status cannot move backward from % to %', OLD.id, OLD.status, NEW.status;
  end if;

  return NEW;
end $$;

CREATE FUNCTION tests.protect_completed_assessment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_successor record;
begin
  if TG_OP = 'DELETE' then
    if OLD.status <> 'draft' then
      raise exception '% % has status % - completed/invalidated assessments cannot be physically deleted, use supersede instead', TG_TABLE_NAME, OLD.id, OLD.status;
    end if;
    return OLD;
  end if;

  -- TG_OP = 'UPDATE'
  if OLD.status = 'draft' then
    -- Draft sme postati 'draft' (slobodno izmenljiv) ili 'completed' (kroz
    -- tests.completeTestAssessmentWithDerivedResults) - NIKAD direktno
    -- 'invalidated'. invalidated se dostiže isključivo iz completed, kroz
    -- validan supersede (provere ispod).
    if NEW.status = 'invalidated' then
      raise exception '% % is draft - cannot transition directly to invalidated, only a completed row can via a valid supersede', TG_TABLE_NAME, OLD.id;
    end if;
    return NEW;
  end if;

  if OLD.status = 'invalidated' then
    raise exception '% % is invalidated - fully immutable, no further changes of any kind are allowed', TG_TABLE_NAME, OLD.id;
  end if;

  -- OLD.status = 'completed' od ovde nadalje. Jedina dozvoljena tranzicija:
  -- invalidated + superseded_by_assessment_id postavljen u ISTOJ izmeni.
  if not (NEW.status = 'invalidated' and NEW.superseded_by_assessment_id is not null) then
    raise exception '% % is completed - cannot be mutated except the completed->invalidated supersede transition', TG_TABLE_NAME, OLD.id;
  end if;

  -- Ništa osim status/superseded_by_assessment_id/updated_at sme da se
  -- razlikuje - poređenje celog reda kao jsonb pokriva SVAKU kolonu bez
  -- ručnog nabrajanja, i NULL-safe je (IS DISTINCT FROM).
  --
  -- standalone_assignment_id (generated always as ... stored, samo na
  -- test_assessments) je isključena OVDE (fix - videti header komentar
  -- ovog fajla): generisane kolone nisu još izračunate unutar BEFORE
  -- trigera, pa bi NEW uvek pokazivao null bez obzira da li se stvarna
  -- vrednost promenila - potpuno pokriveno već upoređenim
  -- assignment_id/battery_assessment_id ulazima, tako da se isključivanjem
  -- ne gubi nikakva stvarna provera.
  if (to_jsonb(OLD) - 'status' - 'superseded_by_assessment_id' - 'updated_at' - 'standalone_assignment_id')
     is distinct from
     (to_jsonb(NEW) - 'status' - 'superseded_by_assessment_id' - 'updated_at' - 'standalone_assignment_id')
  then
    raise exception '% % supersede transition may only change status/superseded_by_assessment_id/updated_at - every other column must stay identical', TG_TABLE_NAME, OLD.id;
  end if;

  -- Lockuje i validira naslednika ATOMSKI, u istoj transakciji - sprečava
  -- trku između dva paralelna pokušaja korekcije istog originala.
  if TG_TABLE_NAME = 'test_assessments' then
    select * into v_successor from tests.test_assessments where id = NEW.superseded_by_assessment_id for update;
    if v_successor.id is null then
      raise exception 'superseded_by_assessment_id % does not reference an existing test_assessments row', NEW.superseded_by_assessment_id;
    end if;
    if v_successor.status <> 'completed' then
      raise exception 'successor % must itself be completed before it can supersede %', v_successor.id, OLD.id;
    end if;
    if v_successor.supersedes_assessment_id is distinct from OLD.id then
      raise exception 'successor % must already have supersedes_assessment_id = % (set at step 1, before this transition) - bidirectional link is not established', v_successor.id, OLD.id;
    end if;
    if v_successor.athlete_id is distinct from OLD.athlete_id
       or v_successor.test_version_id is distinct from OLD.test_version_id
       or v_successor.assignment_id is distinct from OLD.assignment_id
       or v_successor.battery_assessment_id is distinct from OLD.battery_assessment_id
       or v_successor.battery_version_id is distinct from OLD.battery_version_id
       or v_successor.battery_item_id is distinct from OLD.battery_item_id
       or v_successor.attempt_number is distinct from OLD.attempt_number
    then
      raise exception 'successor % must match predecessor %''s athlete/test_version/assignment/battery context/attempt exactly - a correction changes VALUES, never identity', v_successor.id, OLD.id;
    end if;
  elsif TG_TABLE_NAME = 'test_battery_assessments' then
    select * into v_successor from tests.test_battery_assessments where id = NEW.superseded_by_assessment_id for update;
    if v_successor.id is null then
      raise exception 'superseded_by_assessment_id % does not reference an existing test_battery_assessments row', NEW.superseded_by_assessment_id;
    end if;
    if v_successor.status <> 'completed' then
      raise exception 'successor % must itself be completed before it can supersede %', v_successor.id, OLD.id;
    end if;
    if v_successor.supersedes_assessment_id is distinct from OLD.id then
      raise exception 'successor % must already have supersedes_assessment_id = % (set at step 1, before this transition) - bidirectional link is not established', v_successor.id, OLD.id;
    end if;
    if v_successor.athlete_id is distinct from OLD.athlete_id
       or v_successor.battery_version_id is distinct from OLD.battery_version_id
       or v_successor.assignment_id is distinct from OLD.assignment_id
    then
      raise exception 'successor % must match predecessor %''s athlete/battery_version/assignment exactly - a correction changes VALUES, never identity', v_successor.id, OLD.id;
    end if;
  end if;

  return NEW;
end $$;

CREATE FUNCTION tests.protect_draft_only_children() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
declare
  v_old_parent_id uuid;
  v_new_parent_id uuid;
  v_old_status varchar(15);
  v_new_status varchar(15);
  v_parent_table text;
begin
  v_parent_table := case TG_TABLE_NAME
    when 'test_battery_assessment_derived_results' then 'test_battery_assessments'
    else 'test_assessments'
  end;

  if TG_TABLE_NAME = 'test_assessment_values' then
    v_old_parent_id := OLD.assessment_id; v_new_parent_id := NEW.assessment_id;
  elsif TG_TABLE_NAME = 'test_assessment_derived_results' then
    v_old_parent_id := OLD.assessment_id; v_new_parent_id := NEW.assessment_id;
  elsif TG_TABLE_NAME = 'test_battery_assessment_derived_results' then
    v_old_parent_id := OLD.battery_assessment_id; v_new_parent_id := NEW.battery_assessment_id;
  end if;

  if TG_OP in ('UPDATE','DELETE') then
    execute format('select status from tests.%I where id = $1', v_parent_table) into v_old_status using v_old_parent_id;
    if v_old_status is distinct from 'draft' then
      raise exception '% row for parent % cannot change - parent (%) status is %, not draft', TG_TABLE_NAME, v_old_parent_id, v_parent_table, v_old_status;
    end if;
  end if;
  if TG_OP in ('INSERT','UPDATE') then
    execute format('select status from tests.%I where id = $1', v_parent_table) into v_new_status using v_new_parent_id;
    if v_new_status is distinct from 'draft' then
      raise exception '% row for parent % cannot change - parent (%) status is %, not draft', TG_TABLE_NAME, v_new_parent_id, v_parent_table, v_new_status;
    end if;
  end if;

  if TG_OP = 'DELETE' then return OLD; end if;
  return NEW;
end $_$;

CREATE FUNCTION tests.protect_evaluation_immutability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'test_assessment_evaluations rows are write-once history - % is not allowed on row %', TG_OP, OLD.id;
end $$;

CREATE FUNCTION tests.protect_occurrence_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if NEW.schedule_id is distinct from OLD.schedule_id
     or NEW.scheduled_date is distinct from OLD.scheduled_date
     or NEW.snapshot_test_version_id is distinct from OLD.snapshot_test_version_id
     or NEW.snapshot_test_battery_version_id is distinct from OLD.snapshot_test_battery_version_id
     or NEW.opens_at is distinct from OLD.opens_at
     or NEW.due_at is distinct from OLD.due_at
     or NEW.closes_at is distinct from OLD.closes_at
  then
    raise exception 'test_schedule_occurrences.% identity/snapshot columns are immutable after creation - only status/assignments_materialized_at may change', OLD.id;
  end if;

  if OLD.assignments_materialized_at is not null
     and NEW.assignments_materialized_at is distinct from OLD.assignments_materialized_at
  then
    raise exception 'test_schedule_occurrences.% assignments_materialized_at is immutable once set (was %, attempted %)', OLD.id, OLD.assignments_materialized_at, NEW.assignments_materialized_at;
  end if;

  return NEW;
end $$;

CREATE FUNCTION tests.protect_presentation_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_version_id uuid;
  v_status varchar(10);
begin
  if TG_OP = 'UPDATE' then
    if NEW.test_version_id is distinct from OLD.test_version_id
       or NEW.test_parameter_id is distinct from OLD.test_parameter_id then
      raise exception 'test_parameter_presentation.% identity (test_version_id/test_parameter_id) is immutable - reparenting is never allowed, insert a new row for the new draft version instead', OLD.id;
    end if;
  end if;

  v_version_id := case when TG_OP = 'DELETE' then OLD.test_version_id else NEW.test_version_id end;
  select status into v_status from tests.test_versions where id = v_version_id for share;
  if v_status is distinct from 'draft' then
    raise exception 'test_parameter_presentation rows can only be inserted, updated or deleted while their test_version is draft (test_version % is %)', v_version_id, coalesce(v_status, 'unknown');
  end if;

  return case when TG_OP = 'DELETE' then OLD else NEW end;
end $$;

CREATE FUNCTION tests.resolve_current_target_dates(p_schedule_id uuid) RETURNS TABLE(local_date date)
    LANGUAGE sql STABLE
    AS $$
  with sch as (
    select * from tests.test_schedules where id = p_schedule_id
  ),
  per_athlete as (
    select
      (now() at time zone coalesce(a.device_timezone, sch.timezone))::date as local_date,
      sch.schedule_kind, sch.start_date, sch.end_date
    from tests.resolve_schedule_target_athletes(p_schedule_id) ta
    join public.athletes a on a.id = ta.athlete_id
    cross join sch
  ),
  from_current_targets as (
    select distinct local_date
    from per_athlete
    where local_date >= start_date
      and (end_date is null or local_date <= end_date)
      and (schedule_kind <> 'one_time' or local_date = start_date)
  ),
  from_outstanding_snapshot as (
    select distinct o.scheduled_date as local_date
    from tests.test_schedule_occurrences o
    join tests.test_occurrence_target_snapshot s on s.occurrence_id = o.id
    where o.schedule_id = p_schedule_id
      and not exists (
        select 1 from tests.test_assignments asg
        where asg.occurrence_id = o.id and asg.athlete_id = s.athlete_id
      )
  )
  select local_date from from_current_targets
  union
  select local_date from from_outstanding_snapshot
$$;

CREATE FUNCTION tests.resolve_schedule_target_athletes(p_schedule_id uuid) RETURNS TABLE(athlete_id uuid)
    LANGUAGE sql STABLE
    AS $$
  select t.target_athlete_id as athlete_id
  from tests.test_schedule_targets t
  where t.schedule_id = p_schedule_id and t.target_kind = 'athlete'

  union

  select m.athlete_id
  from tests.test_schedule_targets t
  join public.athlete_memberships m
    on m.membership_type = 'team' and m.team_id = t.target_team_id and m.status = 'active'
  where t.schedule_id = p_schedule_id and t.target_kind = 'team'

  union

  select m.athlete_id
  from tests.test_schedule_targets t
  join public.athlete_memberships m
    on m.membership_type = 'club' and m.club_id = t.target_club_id and m.status = 'active'
  where t.schedule_id = p_schedule_id and t.target_kind = 'club'
$$;

CREATE FUNCTION tests.snapshot_assignment_test_reference() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_occurrence tests.test_schedule_occurrences%rowtype;
begin
  select * into v_occurrence from tests.test_schedule_occurrences where id = NEW.occurrence_id;
  if v_occurrence.id is null then
    raise exception 'test_assignments.occurrence_id % does not reference an existing occurrence', NEW.occurrence_id;
  end if;
  NEW.snapshot_test_version_id := v_occurrence.snapshot_test_version_id;
  NEW.snapshot_test_battery_version_id := v_occurrence.snapshot_test_battery_version_id;
  return NEW;
end $$;

CREATE FUNCTION tests.snapshot_occurrence_test_reference() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_schedule tests.test_schedules%rowtype;
begin
  select * into v_schedule from tests.test_schedules where id = NEW.schedule_id;
  if v_schedule.id is null then
    raise exception 'test_schedule_occurrences.schedule_id % does not reference an existing schedule', NEW.schedule_id;
  end if;
  -- Only an 'active' schedule may generate new occurrences - 'paused' must
  -- block generation exactly like 'cancelled' (a paused schedule is not
  -- currently running, not merely "cancelled but softer"); an occurrence
  -- already generated before pausing is untouched.
  if v_schedule.status <> 'active' then
    raise exception 'cannot generate an occurrence for schedule % - status is %, not active', NEW.schedule_id, v_schedule.status;
  end if;

  NEW.snapshot_test_version_id := v_schedule.test_version_id;
  NEW.snapshot_test_battery_version_id := v_schedule.test_battery_version_id;
  return NEW;
end $$;

CREATE FUNCTION tests.validate_assessment_derived_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_result_type varchar(20);
  v_definition_version integer;
begin
  if TG_TABLE_NAME = 'test_assessment_derived_results' then
    select result_type, definition_version into v_result_type, v_definition_version
    from tests.test_version_derived_parameters
    where id = NEW.test_version_derived_parameter_id and test_version_id = NEW.test_version_id;
  else
    select result_type, definition_version into v_result_type, v_definition_version
    from tests.test_battery_derived_parameters
    where id = NEW.test_battery_derived_parameter_id and battery_version_id = NEW.battery_version_id;
  end if;

  if v_result_type is null then
    raise exception '% references a derived parameter definition that does not exist for this version', TG_TABLE_NAME;
  end if;

  if NEW.definition_version <> v_definition_version then
    raise exception '% definition_version (%) does not match the derived parameter''s current definition_version (%) - stale or forged definition_version', TG_TABLE_NAME, NEW.definition_version, v_definition_version;
  end if;

  if v_result_type in ('numeric','integer','ordinal') and NEW.result_numeric is null then
    raise exception '% derived parameter result_type % requires result_numeric', TG_TABLE_NAME, v_result_type;
  elsif v_result_type in ('integer','ordinal') and NEW.result_numeric <> trunc(NEW.result_numeric) then
    raise exception '% derived parameter result_type % requires a whole-number result_numeric (got %)', TG_TABLE_NAME, v_result_type, NEW.result_numeric;
  elsif v_result_type = 'boolean' and NEW.result_boolean is null then
    raise exception '% derived parameter result_type boolean requires result_boolean, not a numeric/text column', TG_TABLE_NAME;
  elsif v_result_type = 'text' and NEW.result_text is null then
    raise exception '% derived parameter result_type text requires result_text', TG_TABLE_NAME;
  end if;

  return NEW;
end $$;

CREATE FUNCTION tests.validate_assessment_value() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_value_type varchar(20);
  v_min numeric;
  v_max numeric;
  v_decimal_places integer;
begin
  select value_type, minimum_value, maximum_value, decimal_places
    into v_value_type, v_min, v_max, v_decimal_places
  from tests.test_parameters
  where id = NEW.test_parameter_id and test_version_id = NEW.test_version_id;

  if v_value_type is null then
    raise exception 'test_parameter % not found for test_version %', NEW.test_parameter_id, NEW.test_version_id;
  end if;

  if v_value_type in ('numeric','integer','ordinal') then
    if NEW.value_numeric is null then
      raise exception 'parameter % (type %) requires value_numeric', NEW.test_parameter_id, v_value_type;
    end if;
    if v_value_type in ('integer','ordinal') and NEW.value_numeric <> trunc(NEW.value_numeric) then
      raise exception 'parameter % (type %) requires a whole-number value_numeric (got %)', NEW.test_parameter_id, v_value_type, NEW.value_numeric;
    end if;
    if v_min is not null and NEW.value_numeric < v_min then
      raise exception 'parameter % value % is below minimum_value %', NEW.test_parameter_id, NEW.value_numeric, v_min;
    end if;
    if v_max is not null and NEW.value_numeric > v_max then
      raise exception 'parameter % value % is above maximum_value %', NEW.test_parameter_id, NEW.value_numeric, v_max;
    end if;
  elsif v_value_type = 'boolean' then
    if NEW.value_boolean is null then
      raise exception 'parameter % (type boolean) requires value_boolean', NEW.test_parameter_id;
    end if;
  elsif v_value_type = 'text' then
    if NEW.value_text is null then
      raise exception 'parameter % (type text) requires value_text', NEW.test_parameter_id;
    end if;
  end if;

  return NEW;
end $$;

CREATE FUNCTION tests.validate_battery_derived_parameters(p_battery_version_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  r record;
  v_input record;
  v_input_type text;
  v_sel_source_kind text;
  v_sel_native_id uuid;
  v_sel_derived_id uuid;
  v_role_set text[];
begin
  for r in
    select * from tests.test_battery_derived_parameters where battery_version_id = p_battery_version_id
  loop
    if not exists (select 1 from tests.test_battery_derived_parameter_inputs where derived_parameter_id = r.id) then
      raise exception 'Battery derived parameter % (%) has no inputs', r.parameter_key, r.id;
    end if;

    if r.calculation_method in ('sum','average','weighted_sum') then
      for v_input in
        select * from tests.test_battery_derived_parameter_inputs where derived_parameter_id = r.id
      loop
        v_input_type := null;
        if v_input.input_source_kind = 'battery_item_parameter_selection' then
          select source_kind, test_parameter_id, test_version_derived_parameter_id
            into v_sel_source_kind, v_sel_native_id, v_sel_derived_id
          from tests.test_battery_item_parameter_selections
          where id = v_input.source_battery_item_parameter_selection_id;

          if v_sel_source_kind = 'native' then
            select value_type into v_input_type from tests.test_parameters where id = v_sel_native_id;
          else
            select result_type into v_input_type from tests.test_version_derived_parameters where id = v_sel_derived_id;
          end if;
        else
          select result_type into v_input_type from tests.test_battery_derived_parameters where id = v_input.source_derived_parameter_id;
        end if;

        if v_input_type not in ('numeric','integer','ordinal') then
          raise exception 'Battery derived parameter % has non-numeric input (role %, type %) for method %',
            r.parameter_key, v_input.role, v_input_type, r.calculation_method;
        end if;
      end loop;

      if r.result_type not in ('numeric','integer','ordinal') then
        raise exception 'Battery derived parameter % has result_type % incompatible with method %',
          r.parameter_key, r.result_type, r.calculation_method;
      end if;
    end if;

    if r.calculation_method = 'conditional' then
      perform tests.validate_conditional_definition_battery_level(r.id, r.calculation_definition, r.result_type, r.definition_version);
    end if;

    if r.calculation_definition is not null then
      select array_agg(distinct role_ref) into v_role_set
      from (
        select jsonb_array_elements(coalesce(r.calculation_definition #> '{when,any}', r.calculation_definition #> '{when,all}', '[]'::jsonb)) ->> 'role' as role_ref
        union all
        select r.calculation_definition #>> '{then,role}'
        union all
        select r.calculation_definition #>> '{else,role}'
      ) x where role_ref is not null;

      if v_role_set is not null and array_length(v_role_set, 1) > 0 then
        if exists (
          select 1 from unnest(v_role_set) as needed_role
          where not exists (
            select 1 from tests.test_battery_derived_parameter_inputs
            where derived_parameter_id = r.id and role = needed_role
          )
        ) then
          raise exception 'Battery derived parameter % calculation_definition references a role not present in its inputs', r.parameter_key;
        end if;
      end if;
    end if;
  end loop;

  if exists (
    with recursive dep as (
      select derived_parameter_id as start_id, source_derived_parameter_id as dep_id,
             array[derived_parameter_id] as visited
      from tests.test_battery_derived_parameter_inputs
      where battery_version_id = p_battery_version_id and input_source_kind = 'battery_derived'
      union all
      select d.start_id, i.source_derived_parameter_id, d.visited || d.dep_id
      from dep d
      join tests.test_battery_derived_parameter_inputs i
        on i.derived_parameter_id = d.dep_id and i.input_source_kind = 'battery_derived'
      where not (d.dep_id = any(d.visited))
    )
    select 1 from dep where dep_id = start_id
  ) then
    raise exception 'Cycle detected in battery-level derived parameter graph for battery_version %', p_battery_version_id;
  end if;
end $$;

CREATE FUNCTION tests.validate_conditional_definition_battery_level(p_derived_id uuid, p_definition jsonb, p_result_type text, p_definition_version integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_cond jsonb;
  v_role text;
  v_operator text;
  v_value jsonb;
  v_role_type text;
  v_sel_source_kind text;
  v_sel_native_id uuid;
  v_sel_derived_id uuid;
  v_selection_id uuid;
  v_input_kind text;
  v_source_derived_id uuid;
  v_branch jsonb;
  v_branch_type text;
  v_when_obj jsonb;
  v_when_list jsonb;
begin
  if p_definition is null or jsonb_typeof(p_definition) is distinct from 'object' then
    raise exception 'conditional calculation_definition must be a JSON object';
  end if;

  if p_definition_version <> 1 then
    raise exception 'unsupported definition_version % (only 1 is supported)', p_definition_version;
  end if;
  -- v4.2 (tačka 5): proveri JSON tip PRE cast-a, inače string/object/boolean "version"
  -- baca generičku cast grešku umesto kontrolisane validacione poruke.
  if p_definition -> 'version' is null or jsonb_typeof(p_definition -> 'version') is distinct from 'number' then
    raise exception 'calculation_definition.version must be a JSON number';
  end if;
  if (p_definition ->> 'version')::numeric <> 1 then
    raise exception 'calculation_definition.version must be 1 (and match definition_version column)';
  end if;

  v_when_obj := p_definition -> 'when';
  if v_when_obj is null or jsonb_typeof(v_when_obj) is distinct from 'object' then
    raise exception 'calculation_definition.when must be a JSON object';
  end if;
  if (v_when_obj ? 'any') and (v_when_obj ? 'all') then
    raise exception 'calculation_definition.when must not contain both any and all';
  end if;
  if not (v_when_obj ? 'any') and not (v_when_obj ? 'all') then
    raise exception 'calculation_definition.when must contain exactly one of any or all';
  end if;

  v_when_list := coalesce(v_when_obj -> 'any', v_when_obj -> 'all');
  if jsonb_typeof(v_when_list) is distinct from 'array' or jsonb_array_length(v_when_list) = 0 then
    raise exception 'calculation_definition.when.any/all must be a non-empty JSON array';
  end if;

  for v_cond in select * from jsonb_array_elements(v_when_list)
  loop
    if jsonb_typeof(v_cond) is distinct from 'object' then
      raise exception 'each when condition must be a JSON object';
    end if;

    v_role := v_cond ->> 'role';
    v_operator := v_cond ->> 'operator';
    v_value := v_cond -> 'value';

    if v_role is null then
      raise exception 'when condition is missing role';
    end if;
    if v_operator is null then
      raise exception 'when condition is missing operator for role %', v_role;
    end if;
    if v_operator not in ('eq','neq','gt','gte','lt','lte') then
      raise exception 'unsupported operator % for role %', v_operator, v_role;
    end if;
    if v_value is null or jsonb_typeof(v_value) = 'null' then
      raise exception 'when condition is missing value for role %', v_role;
    end if;

    select input_source_kind, source_battery_item_parameter_selection_id, source_derived_parameter_id
      into v_input_kind, v_selection_id, v_source_derived_id
    from tests.test_battery_derived_parameter_inputs
    where derived_parameter_id = p_derived_id and role = v_role;

    if v_input_kind is null then
      raise exception 'conditional definition references undeclared role %', v_role;
    end if;

    v_role_type := null;

    if v_input_kind = 'battery_item_parameter_selection' then
      select source_kind, test_parameter_id, test_version_derived_parameter_id
        into v_sel_source_kind, v_sel_native_id, v_sel_derived_id
      from tests.test_battery_item_parameter_selections where id = v_selection_id;

      if v_sel_source_kind = 'native' then
        select value_type into v_role_type from tests.test_parameters where id = v_sel_native_id;
      else
        select result_type into v_role_type from tests.test_version_derived_parameters where id = v_sel_derived_id;
      end if;
    else
      select result_type into v_role_type from tests.test_battery_derived_parameters where id = v_source_derived_id;
    end if;

    if v_role_type is null then
      raise exception 'conditional definition role % could not be resolved to a type', v_role;
    end if;

    if v_role_type in ('numeric','integer','ordinal') then
      if jsonb_typeof(v_value) is distinct from 'number' then
        raise exception 'numeric-compatible role % (type %) requires a JSON number value', v_role, v_role_type;
      end if;
      -- v4.2 (tačka 4): integer/ordinal ne sme imati decimalni deo. Bezbedna Postgres
      -- provera preko trunc(), ne string parsiranje.
      if v_role_type in ('integer','ordinal')
         and (v_value)::text::numeric <> trunc((v_value)::text::numeric) then
        raise exception 'integer/ordinal role % (type %) requires a whole-number JSON value (got %)', v_role, v_role_type, v_value;
      end if;
    elsif v_role_type = 'boolean' then
      if jsonb_typeof(v_value) is distinct from 'boolean' then
        raise exception 'boolean role % requires a JSON boolean value', v_role;
      end if;
      if v_operator not in ('eq','neq') then
        raise exception 'boolean role % only supports eq/neq (got %)', v_role, v_operator;
      end if;
    elsif v_role_type = 'text' then
      if jsonb_typeof(v_value) is distinct from 'string' then
        raise exception 'text role % requires a JSON string value', v_role;
      end if;
      if v_operator not in ('eq','neq') then
        raise exception 'text role % only supports eq/neq (got %)', v_role, v_operator;
      end if;
    end if;
  end loop;

  for v_branch in select unnest(array[p_definition -> 'then', p_definition -> 'else'])
  loop
    if v_branch is null or jsonb_typeof(v_branch) is distinct from 'object' then
      raise exception 'conditional then/else must be a JSON object';
    end if;

    if (v_branch ? 'constant') and (v_branch ? 'role') then
      raise exception 'conditional then/else must have exactly one of constant or role, not both';
    end if;

    if v_branch ? 'constant' then
      v_branch_type := jsonb_typeof(v_branch -> 'constant');
      if p_result_type in ('numeric','integer','ordinal') and v_branch_type is distinct from 'number' then
        raise exception 'conditional branch constant type mismatch with result_type %', p_result_type;
      end if;
      -- v4.2 (tačka 4): integer/ordinal constant ne sme imati decimalni deo.
      if p_result_type in ('integer','ordinal') and v_branch_type = 'number'
         and (v_branch -> 'constant')::text::numeric <> trunc((v_branch -> 'constant')::text::numeric) then
        raise exception 'conditional branch constant must be a whole number for result_type %', p_result_type;
      end if;
      if p_result_type = 'boolean' and v_branch_type is distinct from 'boolean' then
        raise exception 'conditional branch constant type mismatch with result_type boolean';
      end if;
      if p_result_type = 'text' and v_branch_type is distinct from 'string' then
        raise exception 'conditional branch constant type mismatch with result_type text';
      end if;

    elsif v_branch ? 'role' then
      v_role := v_branch ->> 'role';

      select input_source_kind, source_battery_item_parameter_selection_id, source_derived_parameter_id
        into v_input_kind, v_selection_id, v_source_derived_id
      from tests.test_battery_derived_parameter_inputs
      where derived_parameter_id = p_derived_id and role = v_role;

      if v_input_kind is null then
        raise exception 'conditional then/else references undeclared role %', v_role;
      end if;

      v_role_type := null;

      if v_input_kind = 'battery_item_parameter_selection' then
        select source_kind, test_parameter_id, test_version_derived_parameter_id
          into v_sel_source_kind, v_sel_native_id, v_sel_derived_id
        from tests.test_battery_item_parameter_selections where id = v_selection_id;

        if v_sel_source_kind = 'native' then
          select value_type into v_role_type from tests.test_parameters where id = v_sel_native_id;
        else
          select result_type into v_role_type from tests.test_version_derived_parameters where id = v_sel_derived_id;
        end if;
      else
        select result_type into v_role_type from tests.test_battery_derived_parameters where id = v_source_derived_id;
      end if;

      if v_role_type is null then
        raise exception 'conditional then/else role % could not be resolved to a type', v_role;
      end if;

      if p_result_type in ('numeric','integer','ordinal') then
        if v_role_type not in ('numeric','integer','ordinal') then
          raise exception 'conditional then/else role % (type %) incompatible with result_type %', v_role, v_role_type, p_result_type;
        end if;
      elsif p_result_type = 'boolean' then
        if v_role_type is distinct from 'boolean' then
          raise exception 'conditional then/else role % (type %) incompatible with result_type boolean', v_role, v_role_type;
        end if;
      elsif p_result_type = 'text' then
        if v_role_type is distinct from 'text' then
          raise exception 'conditional then/else role % (type %) incompatible with result_type text', v_role, v_role_type;
        end if;
      end if;

    else
      raise exception 'conditional then/else must have constant or role';
    end if;
  end loop;
end $$;

CREATE FUNCTION tests.validate_conditional_definition_test_level(p_derived_id uuid, p_definition jsonb, p_result_type text, p_definition_version integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_cond jsonb;
  v_role text;
  v_operator text;
  v_value jsonb;
  v_role_type text;
  v_branch jsonb;
  v_branch_type text;
  v_when_obj jsonb;
  v_when_list jsonb;
begin
  if p_definition is null or jsonb_typeof(p_definition) is distinct from 'object' then
    raise exception 'conditional calculation_definition must be a JSON object';
  end if;

  if p_definition_version <> 1 then
    raise exception 'unsupported definition_version % (only 1 is supported)', p_definition_version;
  end if;
  -- v4.2 (tačka 5): proveri JSON tip PRE cast-a, inače string/object/boolean "version"
  -- baca generičku cast grešku umesto kontrolisane validacione poruke.
  if p_definition -> 'version' is null or jsonb_typeof(p_definition -> 'version') is distinct from 'number' then
    raise exception 'calculation_definition.version must be a JSON number';
  end if;
  if (p_definition ->> 'version')::numeric <> 1 then
    raise exception 'calculation_definition.version must be 1 (and match definition_version column)';
  end if;

  v_when_obj := p_definition -> 'when';
  if v_when_obj is null or jsonb_typeof(v_when_obj) is distinct from 'object' then
    raise exception 'calculation_definition.when must be a JSON object';
  end if;
  if (v_when_obj ? 'any') and (v_when_obj ? 'all') then
    raise exception 'calculation_definition.when must not contain both any and all';
  end if;
  if not (v_when_obj ? 'any') and not (v_when_obj ? 'all') then
    raise exception 'calculation_definition.when must contain exactly one of any or all';
  end if;

  v_when_list := coalesce(v_when_obj -> 'any', v_when_obj -> 'all');
  if jsonb_typeof(v_when_list) is distinct from 'array' or jsonb_array_length(v_when_list) = 0 then
    raise exception 'calculation_definition.when.any/all must be a non-empty JSON array';
  end if;

  for v_cond in select * from jsonb_array_elements(v_when_list)
  loop
    if jsonb_typeof(v_cond) is distinct from 'object' then
      raise exception 'each when condition must be a JSON object';
    end if;

    v_role := v_cond ->> 'role';
    v_operator := v_cond ->> 'operator';
    v_value := v_cond -> 'value';

    if v_role is null then
      raise exception 'when condition is missing role';
    end if;
    if v_operator is null then
      raise exception 'when condition is missing operator for role %', v_role;
    end if;
    if v_operator not in ('eq','neq','gt','gte','lt','lte') then
      raise exception 'unsupported operator % for role %', v_operator, v_role;
    end if;
    if v_value is null or jsonb_typeof(v_value) = 'null' then
      raise exception 'when condition is missing value for role %', v_role;
    end if;

    v_role_type := null;

    select tp.value_type into v_role_type
    from tests.test_version_derived_parameter_inputs i
    join tests.test_parameters tp on tp.id = i.source_test_parameter_id
    where i.derived_parameter_id = p_derived_id and i.role = v_role and i.input_source_kind = 'native';

    if v_role_type is null then
      select dp.result_type into v_role_type
      from tests.test_version_derived_parameter_inputs i
      join tests.test_version_derived_parameters dp on dp.id = i.source_derived_parameter_id
      where i.derived_parameter_id = p_derived_id and i.role = v_role and i.input_source_kind = 'test_derived';
    end if;

    if v_role_type is null then
      raise exception 'conditional definition references undeclared role %', v_role;
    end if;

    if v_role_type in ('numeric','integer','ordinal') then
      if jsonb_typeof(v_value) is distinct from 'number' then
        raise exception 'numeric-compatible role % (type %) requires a JSON number value', v_role, v_role_type;
      end if;
      -- v4.2 (tačka 4): integer/ordinal ne sme imati decimalni deo. Bezbedna Postgres
      -- provera preko trunc(), ne string parsiranje.
      if v_role_type in ('integer','ordinal')
         and (v_value)::text::numeric <> trunc((v_value)::text::numeric) then
        raise exception 'integer/ordinal role % (type %) requires a whole-number JSON value (got %)', v_role, v_role_type, v_value;
      end if;
    elsif v_role_type = 'boolean' then
      if jsonb_typeof(v_value) is distinct from 'boolean' then
        raise exception 'boolean role % requires a JSON boolean value', v_role;
      end if;
      if v_operator not in ('eq','neq') then
        raise exception 'boolean role % only supports eq/neq (got %)', v_role, v_operator;
      end if;
    elsif v_role_type = 'text' then
      if jsonb_typeof(v_value) is distinct from 'string' then
        raise exception 'text role % requires a JSON string value', v_role;
      end if;
      if v_operator not in ('eq','neq') then
        raise exception 'text role % only supports eq/neq (got %)', v_role, v_operator;
      end if;
    end if;
  end loop;

  for v_branch in select unnest(array[p_definition -> 'then', p_definition -> 'else'])
  loop
    if v_branch is null or jsonb_typeof(v_branch) is distinct from 'object' then
      raise exception 'conditional then/else must be a JSON object';
    end if;

    if (v_branch ? 'constant') and (v_branch ? 'role') then
      raise exception 'conditional then/else must have exactly one of constant or role, not both';
    end if;

    if v_branch ? 'constant' then
      v_branch_type := jsonb_typeof(v_branch -> 'constant');
      if p_result_type in ('numeric','integer','ordinal') and v_branch_type is distinct from 'number' then
        raise exception 'conditional branch constant type mismatch with result_type %', p_result_type;
      end if;
      -- v4.2 (tačka 4): integer/ordinal constant ne sme imati decimalni deo.
      if p_result_type in ('integer','ordinal') and v_branch_type = 'number'
         and (v_branch -> 'constant')::text::numeric <> trunc((v_branch -> 'constant')::text::numeric) then
        raise exception 'conditional branch constant must be a whole number for result_type %', p_result_type;
      end if;
      if p_result_type = 'boolean' and v_branch_type is distinct from 'boolean' then
        raise exception 'conditional branch constant type mismatch with result_type boolean';
      end if;
      if p_result_type = 'text' and v_branch_type is distinct from 'string' then
        raise exception 'conditional branch constant type mismatch with result_type text';
      end if;

    elsif v_branch ? 'role' then
      v_role := v_branch ->> 'role';
      v_role_type := null;

      select tp.value_type into v_role_type
      from tests.test_version_derived_parameter_inputs i
      join tests.test_parameters tp on tp.id = i.source_test_parameter_id
      where i.derived_parameter_id = p_derived_id and i.role = v_role and i.input_source_kind = 'native';

      if v_role_type is null then
        select dp.result_type into v_role_type
        from tests.test_version_derived_parameter_inputs i
        join tests.test_version_derived_parameters dp on dp.id = i.source_derived_parameter_id
        where i.derived_parameter_id = p_derived_id and i.role = v_role and i.input_source_kind = 'test_derived';
      end if;

      if v_role_type is null then
        raise exception 'conditional then/else references undeclared role %', v_role;
      end if;

      if p_result_type in ('numeric','integer','ordinal') then
        if v_role_type not in ('numeric','integer','ordinal') then
          raise exception 'conditional then/else role % (type %) incompatible with result_type %', v_role, v_role_type, p_result_type;
        end if;
      elsif p_result_type = 'boolean' then
        if v_role_type is distinct from 'boolean' then
          raise exception 'conditional then/else role % (type %) incompatible with result_type boolean', v_role, v_role_type;
        end if;
      elsif p_result_type = 'text' then
        if v_role_type is distinct from 'text' then
          raise exception 'conditional then/else role % (type %) incompatible with result_type text', v_role, v_role_type;
        end if;
      end if;

    else
      raise exception 'conditional then/else must have constant or role';
    end if;
  end loop;
end $$;

CREATE FUNCTION tests.validate_schedule_timezone_and_recurrence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_version jsonb;
begin
  if not exists (select 1 from pg_timezone_names where name = NEW.timezone) then
    raise exception 'timezone % is not a recognized IANA timezone name', NEW.timezone;
  end if;

  if NEW.recurrence_rule is not null then
    v_version := NEW.recurrence_rule -> 'version';
    if v_version is null or jsonb_typeof(v_version) is distinct from 'number' then
      raise exception 'recurrence_rule.version must be a JSON number';
    end if;
    if (v_version #>> '{}')::numeric <> NEW.recurrence_rule_version then
      raise exception 'recurrence_rule.version (%) must match recurrence_rule_version column (%)', v_version, NEW.recurrence_rule_version;
    end if;
  end if;

  return NEW;
end $$;

CREATE FUNCTION tests.validate_test_version_derived_parameters(p_test_version_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  r record;
  v_input record;
  v_input_type text;
  v_role_set text[];
begin
  for r in
    select * from tests.test_version_derived_parameters where test_version_id = p_test_version_id
  loop
    if not exists (select 1 from tests.test_version_derived_parameter_inputs where derived_parameter_id = r.id) then
      raise exception 'Derived parameter % (%) has no inputs', r.parameter_key, r.id;
    end if;

    if r.calculation_method in ('sum','average','weighted_sum') then
      for v_input in
        select * from tests.test_version_derived_parameter_inputs where derived_parameter_id = r.id
      loop
        v_input_type := null;
        if v_input.input_source_kind = 'native' then
          select value_type into v_input_type from tests.test_parameters where id = v_input.source_test_parameter_id;
        else
          select result_type into v_input_type from tests.test_version_derived_parameters where id = v_input.source_derived_parameter_id;
        end if;

        if v_input_type not in ('numeric','integer','ordinal') then
          raise exception 'Derived parameter % has non-numeric input (role %, type %) for method %',
            r.parameter_key, v_input.role, v_input_type, r.calculation_method;
        end if;
      end loop;

      if r.result_type not in ('numeric','integer','ordinal') then
        raise exception 'Derived parameter % has result_type % incompatible with method %',
          r.parameter_key, r.result_type, r.calculation_method;
      end if;
    end if;

    if r.calculation_method = 'conditional' then
      perform tests.validate_conditional_definition_test_level(r.id, r.calculation_definition, r.result_type, r.definition_version);
    end if;

    if r.calculation_definition is not null then
      select array_agg(distinct role_ref) into v_role_set
      from (
        select jsonb_array_elements(coalesce(r.calculation_definition #> '{when,any}', r.calculation_definition #> '{when,all}', '[]'::jsonb)) ->> 'role' as role_ref
        union all
        select r.calculation_definition #>> '{then,role}'
        union all
        select r.calculation_definition #>> '{else,role}'
      ) x where role_ref is not null;

      if v_role_set is not null and array_length(v_role_set, 1) > 0 then
        if exists (
          select 1 from unnest(v_role_set) as needed_role
          where not exists (
            select 1 from tests.test_version_derived_parameter_inputs
            where derived_parameter_id = r.id and role = needed_role
          )
        ) then
          raise exception 'Derived parameter % calculation_definition references a role not present in its inputs', r.parameter_key;
        end if;
      end if;
    end if;
  end loop;

  if exists (
    with recursive dep as (
      select derived_parameter_id as start_id, source_derived_parameter_id as dep_id,
             array[derived_parameter_id] as visited
      from tests.test_version_derived_parameter_inputs
      where test_version_id = p_test_version_id and input_source_kind = 'test_derived'
      union all
      select d.start_id, i.source_derived_parameter_id, d.visited || d.dep_id
      from dep d
      join tests.test_version_derived_parameter_inputs i
        on i.derived_parameter_id = d.dep_id and i.input_source_kind = 'test_derived'
      where not (d.dep_id = any(d.visited))
    )
    select 1 from dep where dep_id = start_id
  ) then
    raise exception 'Cycle detected in test-level derived parameter graph for test_version %', p_test_version_id;
  end if;
end $$;

CREATE FUNCTION training.activity_alias_ids(p_canonical_activity_id uuid) RETURNS TABLE(activity_id uuid)
    LANGUAGE sql STABLE
    AS $$
  with recursive chain as (
    select p_canonical_activity_id as activity_id
    union all
    select a.id from training.activities a join chain c on a.superseded_by_activity_id = c.activity_id
  )
  select activity_id from chain;
$$;

CREATE FUNCTION training.activity_has_roster(p_activity_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select a.owner_scope = 'team'
     and not (
       case when a.origin in ('planned_session', 'external_assignment')
            then (select count(*)
                    from training.activity_participants p
                   where p.merge_status = 'canonical'
                     and p.activity_id in (select x.activity_id from training.activity_alias_ids(a.id) x)) <= 1
                 and not exists (select 1
                                   from training.canonical_activity_results(a.id) x
                                  where x.fact_kind = 'metric_value'
                                    and x.detail ->> 'entryMethod' in ('api_import', 'csv_import'))
            else false
       end
     )
    from training.activities a
   where a.id = p_activity_id;
$$;

CREATE FUNCTION training.activity_roster(p_activity_id uuid) RETURNS TABLE(athlete_id uuid, member_from timestamp with time zone, member_to timestamp with time zone, left_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
  with a as (
    select owner_team_id, started_at,
           (occurred_local_date::timestamp at time zone timezone_snapshot) as day_start,
           ((occurred_local_date + 1)::timestamp at time zone timezone_snapshot) as day_end
      from training.activities
     where id = p_activity_id and owner_scope = 'team'
       and coalesce(training.activity_has_roster(id), false)
  ),
  team_periods as (
    select p.athlete_id, p.valid_from, p.valid_to
      from a join public.athlete_membership_periods p
        on p.team_id = a.owner_team_id and p.membership_type = 'team'
  ),
  covering as (
    select tp.athlete_id, tp.valid_from, tp.valid_to
      from team_periods tp cross join a
     where case when a.started_at is not null
                then tp.valid_from <= a.started_at and a.started_at < coalesce(tp.valid_to, 'infinity')
                else tp.valid_from < a.day_end and coalesce(tp.valid_to, 'infinity') > a.day_start
           end
  )
  select c.athlete_id,
         min(c.valid_from),
         case when bool_or(c.valid_to is null) then null else max(c.valid_to) end,
         (select case when bool_or(tp.valid_to is null) then null else max(tp.valid_to) end
            from team_periods tp where tp.athlete_id = c.athlete_id)
    from covering c
   group by c.athlete_id;
$$;

CREATE FUNCTION training.activity_roster_needs_state(p_canonical_activity_id uuid) RETURNS TABLE(athlete_id uuid)
    LANGUAGE sql STABLE
    AS $$
  with r as (
    select athlete_id from training.activity_roster(p_canonical_activity_id)
  ),
  d as (
    select d.athlete_id, d.decision_kind, coalesce(d.reason_key, '') as reason_key
      from training.activity_athlete_decisions d
     where d.activity_id in (select activity_id from training.activity_alias_ids(p_canonical_activity_id))
       and d.superseded_by_decision_id is null
  ),
  m as (
    select distinct x.athlete_id
      from training.canonical_activity_results(p_canonical_activity_id) x
     where x.fact_kind = 'metric_value' and x.detail ->> 'entryMethod' in ('api_import', 'csv_import')
  )
  select r.athlete_id
    from r
   where ((select count(*) from d where d.athlete_id = r.athlete_id) > 1
          and (select count(distinct (d.decision_kind, d.reason_key)) from d where d.athlete_id = r.athlete_id) > 1)
      or (not exists (select 1 from d where d.athlete_id = r.athlete_id and d.decision_kind <> 'cleared')
          and not exists (select 1 from m where m.athlete_id = r.athlete_id));
$$;

CREATE FUNCTION training.assert_canonical_team_activity(p_activity_id uuid, p_owner_team_id uuid, p_what text) RETURNS uuid
    LANGUAGE plpgsql STABLE
    AS $$
declare
  act record;
begin
  select owner_scope, owner_team_id, superseded_by_activity_id into act from training.activities where id = p_activity_id;
  if not found then
    raise exception '%: activity % does not exist', p_what, p_activity_id;
  end if;
  if act.superseded_by_activity_id is not null then
    raise exception '%: activity % was superseded by %; write to the canonical activity', p_what, p_activity_id, act.superseded_by_activity_id;
  end if;
  if act.owner_scope <> 'team' then
    raise exception '%: activity % is not team-owned; only a team session has a roster', p_what, p_activity_id;
  end if;
  if p_owner_team_id is not null and act.owner_team_id is distinct from p_owner_team_id then
    raise exception '%: owner_team_id % is not the team of activity %', p_what, p_owner_team_id, p_activity_id;
  end if;
  return act.owner_team_id;
end;
$$;

CREATE FUNCTION training.canonical_activity_results(p_activity_id uuid) RETURNS TABLE(canonical_activity_id uuid, canonical_participant_id uuid, athlete_id uuid, fact_kind text, detail jsonb)
    LANGUAGE sql STABLE
    AS $$
with resolved as (
  select training.resolve_canonical_activity_id(p_activity_id) as canonical_activity_id
),
alias_activities as (
  select r.canonical_activity_id, aa.activity_id
  from resolved r
  cross join lateral training.activity_alias_ids(r.canonical_activity_id) aa
),
raw_participants as (
  select aa.canonical_activity_id, ap.id as participant_id
  from alias_activities aa
  join training.activity_participants ap on ap.activity_id = aa.activity_id
),
canonical_participants as (
  select distinct rp.canonical_activity_id, training.resolve_canonical_participant_id(rp.participant_id) as canonical_participant_id
  from raw_participants rp
),
alias_participants as (
  select cp.canonical_activity_id, cp.canonical_participant_id, pa.participant_id as alias_participant_id, ap2.athlete_id
  from canonical_participants cp
  cross join lateral training.participant_alias_ids(cp.canonical_participant_id) pa
  join training.activity_participants ap2 on ap2.id = pa.participant_id
)
select ap.canonical_activity_id, ap.canonical_participant_id, ap.athlete_id, 'rpe'::text,
  jsonb_build_object('sessionFeedbackId', sf.id, 'rpe', sf.rpe, 'durationMinutes', sf.duration_minutes, 'srpe', sf.srpe, 'source', sf.source, 'aliasParticipantId', ap.alias_participant_id)
from alias_participants ap
join training.activity_participant_session_links l on l.activity_participant_id = ap.alias_participant_id and l.link_status = 'confirmed'
join training_load.session_feedback sf on sf.athlete_id = ap.athlete_id
  and ((l.logical_session_id is not null and sf.logical_session_id = l.logical_session_id) or (l.external_assignment_id is not null and sf.external_assignment_id = l.external_assignment_id))

union all

select ap.canonical_activity_id, ap.canonical_participant_id, ap.athlete_id, 'metric_value'::text,
  jsonb_build_object(
    'occasionId', o.id, 'sourceIdentityId', o.source_identity_id, 'entryMethod', o.entry_method,
    'metricDefinitionId', v.metric_definition_id, 'metricDefinitionVersionId', v.metric_definition_version_id,
    'valueNumeric', v.value_numeric, 'valueBoolean', v.value_boolean, 'valueText', v.value_text, 'unitAtCapture', v.unit_at_capture,
    'aggregationRole', v.aggregation_role, 'coverage', v.coverage, 'isDerived', v.is_derived, 'computedByRef', v.computed_by_ref,
    'segmentId', o.segment_id, 'aliasParticipantId', ap.alias_participant_id
  )
from alias_participants ap
join training.activity_participant_metric_participant_links mpl on mpl.activity_participant_id = ap.alias_participant_id and mpl.link_status = 'confirmed'
join training_load.metric_measurement_occasions o on o.event_participant_id = mpl.metric_event_participant_id
join training_load.metric_values v on v.occasion_id = o.id
-- The SAME "effective" contract Metrics Core itself uses: never a
-- superseded revision, never one flagged needs_review/
-- stale_resend_ignored/no_reliable_identifier, and — for an imported fact
-- — only when it is genuinely its own identity's CURRENT occasion.
where o.superseded_by_occasion_id is null
  and o.import_conflict_status is null
  and (o.source_identity_id is null or exists (
    select 1 from training_load.metric_source_identities si where si.id = o.source_identity_id and si.current_occasion_id = o.id
  ))

union all

select ap.canonical_activity_id, ap.canonical_participant_id, ap.athlete_id, 'component_performance'::text,
  jsonb_build_object(
    'componentId', c.id, 'name', c.name_snapshot, 'componentTypeKey', c.component_type_key, 'status', pc.status,
    'actualDurationSeconds', pc.actual_duration_seconds, 'note', pc.note, 'actualPrescriptionSnapshot', pc.actual_prescription_snapshot,
    'activityParticipantComponentId', pc.id, 'aliasParticipantId', ap.alias_participant_id
  )
from alias_participants ap
join training.activity_participant_components pc on pc.activity_participant_id = ap.alias_participant_id
join training.activity_components c on c.id = pc.activity_component_id

union all

select aa.canonical_activity_id, null::uuid, null::uuid, 'metric_event_link'::text,
  jsonb_build_object('metricEventId', mel.metric_event_id, 'linkStatus', mel.link_status, 'fromActivityId', mel.activity_id)
from alias_activities aa
join training.activity_metric_event_links mel on mel.activity_id = aa.activity_id and mel.link_status = 'confirmed'

union all

select aa.canonical_activity_id, null::uuid, null::uuid, 'component_metric_segment_link'::text,
  jsonb_build_object('componentId', csl.activity_component_id, 'metricEventSegmentId', csl.metric_event_segment_id, 'linkStatus', csl.link_status)
from alias_activities aa
join training.activity_components c on c.activity_id = aa.activity_id
join training.activity_component_metric_segment_links csl on csl.activity_component_id = c.id and csl.link_status = 'confirmed';
$$;

CREATE FUNCTION training.check_activity_athlete_decision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'activity_athlete_decisions is append-only; a decision is superseded, never deleted (decision %)', old.id;
  end if;
  if tg_op = 'UPDATE' then
    if old.superseded_by_decision_id is not null or new.superseded_by_decision_id is null
       or new.id is distinct from old.id or new.activity_id is distinct from old.activity_id
       or new.athlete_id is distinct from old.athlete_id or new.owner_team_id is distinct from old.owner_team_id
       or new.request_id is distinct from old.request_id or new.decision_kind is distinct from old.decision_kind
       or new.reason_key is distinct from old.reason_key or new.note is distinct from old.note
       or new.occasion_id is distinct from old.occasion_id or new.decided_by_user_id is distinct from old.decided_by_user_id
       or new.decided_by_basis is distinct from old.decided_by_basis or new.decided_at is distinct from old.decided_at then
      raise exception 'activity_athlete_decisions: a decision only gets superseded, once (decision %)', old.id;
    end if;
    return new;
  end if;

  -- INSERT
  if new.superseded_by_decision_id is not null then
    raise exception 'activity_athlete_decisions: a new decision is current';
  end if;
  perform training.assert_canonical_team_activity(new.activity_id, new.owner_team_id, 'activity_athlete_decisions');
  if not exists (select 1 from training.activity_roster(new.activity_id) r where r.athlete_id = new.athlete_id) then
    raise exception 'activity_athlete_decisions: athlete % is not on the roster of activity %', new.athlete_id, new.activity_id;
  end if;
  if new.decision_kind in ('manual_values', 'estimated') then
    raise exception 'activity_athlete_decisions: % is not available yet (Phase 5b)', new.decision_kind;
  end if;
  if new.reason_key is not null and not exists (
    select 1 from training.participation_reasons where key = new.reason_key and is_active
  ) then
    raise exception 'activity_athlete_decisions: reason % is not active', new.reason_key;
  end if;
  -- A measured record is never overridden by a coach decision; only
  -- 'cleared' (back to the derived state) is allowed next to one.
  if new.decision_kind <> 'cleared' and exists (
    select 1 from training.canonical_activity_results(new.activity_id) r
     where r.fact_kind = 'metric_value' and r.athlete_id = new.athlete_id
       and r.detail ->> 'entryMethod' in ('api_import', 'csv_import')
  ) then
    raise exception 'activity_athlete_decisions: athlete % has a measured record in activity %', new.athlete_id, new.activity_id
      using errcode = 'check_violation';
  end if;
  perform training.lock_activity_decider(new.decided_by_user_id, new.owner_team_id, new.decided_by_basis);
  return new;
end;
$$;

CREATE FUNCTION training.check_activity_athlete_decision_alias_set() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if exists (
    select 1 from training.activity_athlete_decisions d
     where d.activity_id in (select activity_id from training.activity_alias_ids(training.resolve_canonical_activity_id(new.activity_id)))
       and d.athlete_id = new.athlete_id and d.superseded_by_decision_id is null and d.id <> new.id
  ) then
    raise exception 'activity_athlete_decisions: athlete % already has a current decision in the alias set of activity %; supersede it first', new.athlete_id, new.activity_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.check_activity_athlete_decision_links() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  req_activity uuid;
  sup record;
begin
  select activity_id into req_activity from training.activity_roster_requests where id = new.request_id;
  if req_activity is distinct from new.activity_id then
    raise exception 'activity_athlete_decisions: request % does not belong to activity %', new.request_id, new.activity_id;
  end if;
  if new.superseded_by_decision_id is not null then
    select athlete_id, owner_team_id, activity_id into sup from training.activity_athlete_decisions where id = new.superseded_by_decision_id;
    if not found or sup.athlete_id is distinct from new.athlete_id or sup.owner_team_id is distinct from new.owner_team_id
       or training.resolve_canonical_activity_id(sup.activity_id) is distinct from training.resolve_canonical_activity_id(new.activity_id) then
      raise exception 'activity_athlete_decisions: decision % cannot be superseded by %', new.id, new.superseded_by_decision_id;
    end if;
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.check_activity_completion_audited() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (
    select 1 from training.activity_completion_log l
     where l.activity_id = new.activity_id and l.revision = new.revision and l.to_status = new.status
  ) then
    raise exception 'activity_completions: revision % of activity % has no completion log row', new.revision, new.activity_id;
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.check_activity_completion_log_links() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  req_activity uuid;
begin
  if new.request_id is null then
    return null;
  end if;
  select activity_id into req_activity from training.activity_roster_requests where id = new.request_id;
  if req_activity is null
     or (req_activity is distinct from new.activity_id
         and training.resolve_canonical_activity_id(req_activity) is distinct from training.resolve_canonical_activity_id(new.activity_id)) then
    raise exception 'activity_completion_log: request % does not belong to activity % or its alias set', new.request_id, new.activity_id;
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.check_activity_completion_log_rules() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  comp record;
  prev_status varchar;
  v_basis text := new.detail ->> 'basis';
begin
  select * into comp from training.activity_completions where activity_id = new.activity_id;
  if not found or comp.revision <> new.revision or comp.status <> new.to_status then
    raise exception 'activity_completion_log: the log row does not describe completion revision % of activity %', new.revision, new.activity_id;
  end if;
  select to_status into prev_status from training.activity_completion_log where activity_id = new.activity_id and revision = new.revision - 1;
  if new.from_status is distinct from coalesce(prev_status, 'not_complete') then
    raise exception 'activity_completion_log: revision % of activity % does not continue from %', new.revision, new.activity_id, coalesce(prev_status, 'not_complete');
  end if;

  if new.cause = 'completed' then
    if new.to_status <> 'complete' or new.from_status not in ('not_complete', 'needs_review') then
      raise exception 'activity_completion_log: completed is % -> complete only', new.from_status;
    end if;
  elsif new.cause = 'reopened' then
    if new.to_status <> 'not_complete' or new.from_status not in ('complete', 'needs_review') then
      raise exception 'activity_completion_log: reopened is complete | needs_review -> not_complete only';
    end if;
    if length(btrim(coalesce(new.detail ->> 'reason', ''))) = 0 then
      raise exception 'activity_completion_log: a reopen carries its reason';
    end if;
  elsif new.cause = 'decision_changed' then
    if (new.from_status, new.to_status) not in (('not_complete', 'not_complete'), ('complete', 'needs_review'), ('needs_review', 'needs_review')) then
      raise exception 'activity_completion_log: decision_changed is not % -> %', new.from_status, new.to_status;
    end if;
  elsif new.to_status <> 'needs_review' or new.from_status not in ('complete', 'needs_review') then
    raise exception 'activity_completion_log: % only turns complete or needs_review into needs_review', new.cause;
  end if;

  if new.cause in ('completed', 'reopened', 'decision_changed') then
    if new.request_id is null or new.performed_by_user_id is null then
      raise exception 'activity_completion_log: % carries its request and user', new.cause;
    end if;
  end if;
  if new.cause in ('completed', 'reopened') then
    if v_basis is null then
      raise exception 'activity_completion_log: % carries the basis it was done on', new.cause;
    end if;
    perform training.lock_activity_decider(new.performed_by_user_id, comp.owner_team_id, v_basis);
    if new.cause = 'completed' and (comp.completed_by_user_id is distinct from new.performed_by_user_id or comp.completed_by_basis is distinct from v_basis) then
      raise exception 'activity_completion_log: completed by % as % does not match the completion row', new.performed_by_user_id, v_basis;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.check_activity_completion_rules() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' and new.revision <> 1 then
    raise exception 'activity_completions: a completion row is created at revision 1 (activity %)', new.activity_id;
  end if;
  if new.status = 'complete' and (tg_op = 'INSERT' or old.status is distinct from 'complete') then
    if not exists (select 1 from training.activity_roster(new.activity_id)) then
      raise exception 'activity_completions: activity % has nobody on its roster; it cannot be complete', new.activity_id;
    end if;
    if exists (select 1 from training.activity_roster_needs_state(new.activity_id)) then
      raise exception 'activity_completions: somebody on the roster of activity % still needs a state', new.activity_id;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.check_activity_source_observation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_team_id uuid;
  conn record;
begin
  if new.resolved_at is not null then
    raise exception 'activity_source_observations: an observation is recorded open';
  end if;
  v_team_id := training.assert_canonical_team_activity(new.activity_id, null, 'activity_source_observations');
  select owner_scope, owner_team_id into conn from training_load.metric_source_connections where id = new.source_connection_id;
  if not found or conn.owner_scope <> 'team' or conn.owner_team_id is distinct from v_team_id then
    raise exception 'activity_source_observations: connection % does not belong to the team of activity %', new.source_connection_id, new.activity_id;
  end if;
  if not exists (select 1 from training.activity_roster(new.activity_id) r where r.athlete_id = new.athlete_id) then
    raise exception 'activity_source_observations: athlete % is not on the roster of activity %', new.athlete_id, new.activity_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.check_component_metric_segment_link_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_activity_id uuid;
  v_segment_event_id uuid;
  v_event_linked boolean;
begin
  if new.link_status <> 'confirmed' then
    return new;
  end if;
  select activity_id into v_activity_id from training.activity_components where id = new.activity_component_id;
  select event_id into v_segment_event_id from training_load.metric_event_segments where id = new.metric_event_segment_id;
  select exists (
    select 1 from training.activity_metric_event_links
    where activity_id = v_activity_id and metric_event_id = v_segment_event_id and link_status = 'confirmed'
  ) into v_event_linked;
  if not v_event_linked then
    raise exception 'activity_component_metric_segment_links (id=%): the segment''s event is not confirmedly linked to the component''s own activity', new.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.check_component_parent_no_cycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_current uuid := new.parent_component_id;
  v_hops int := 0;
begin
  while v_current is not null loop
    if v_current = new.id then
      raise exception 'training.activity_components (id=%): parent_component_id introduces a cycle', new.id;
    end if;
    v_hops := v_hops + 1;
    if v_hops > 100 then
      raise exception 'training.activity_components (id=%): component hierarchy exceeds 100 levels — refusing, likely a cycle', new.id;
    end if;
    select parent_component_id into v_current from training.activity_components where id = v_current;
  end loop;
  return new;
end;
$$;

CREATE FUNCTION training.check_link_chain_reciprocal() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
declare
  v_status varchar;
  v_superseded_by uuid;
  v_supersedes uuid;
  v_other_supersedes uuid;
  v_other_superseded_by uuid;
  v_anchor_expr text;
  v_old_anchor text;
  v_new_anchor text;
begin
  -- IMPORTANT: this is a DEFERRED constraint trigger — NEW is the
  -- point-in-time row image from whichever statement fired it, captured
  -- BEFORE later statements in the same transaction (e.g. the 3-step
  -- relink's own final "point the old row at the new one" step) have run.
  -- Checking new.* directly would spuriously reject a fully legitimate,
  -- by-now-complete relink using its OWN stale mid-sequence snapshot —
  -- every check below therefore re-reads the row's CURRENT, live state
  -- (as of when this deferred trigger actually fires, at commit) by id,
  -- exactly like the reciprocal cross-row lookups already have to.
  execute format('select link_status, superseded_by_link_id, supersedes_link_id from %I.%I where id = $1', tg_table_schema, tg_table_name)
    into v_status, v_superseded_by, v_supersedes using new.id;

  if v_status = 'superseded' and v_superseded_by is null then
    raise exception '%.%: a superseded row must (by commit time) carry a non-null superseded_by_link_id (row %)', tg_table_schema, tg_table_name, new.id;
  end if;
  if v_status in ('suggested', 'rejected') and (v_superseded_by is not null or v_supersedes is not null) then
    raise exception '%.%: a % row must carry NO chain pointers (row %)', tg_table_schema, tg_table_name, v_status, new.id;
  end if;

  if v_superseded_by is not null then
    execute format('select supersedes_link_id from %I.%I where id = $1', tg_table_schema, tg_table_name)
      into v_other_supersedes using v_superseded_by;
    if v_other_supersedes is distinct from new.id then
      raise exception '%.%: reciprocal chain violation — row % has superseded_by_link_id=% but that row''s own supersedes_link_id is % (expected %)',
        tg_table_schema, tg_table_name, new.id, v_superseded_by, v_other_supersedes, new.id;
    end if;
  end if;
  if v_supersedes is not null then
    execute format('select superseded_by_link_id from %I.%I where id = $1', tg_table_schema, tg_table_name)
      into v_other_superseded_by using v_supersedes;
    if v_other_superseded_by is distinct from new.id then
      raise exception '%.%: reciprocal chain violation — row % has supersedes_link_id=% but that row''s own superseded_by_link_id is % (expected %)',
        tg_table_schema, tg_table_name, new.id, v_supersedes, v_other_superseded_by, new.id;
    end if;

    -- The stable anchor for activity_participant_session_links is a
    -- NORMALIZED source identity string, `logical:<id>` or
    -- `external:<id>` — never activity_participant_id, which a
    -- legitimate relink is specifically allowed to change (moving the
    -- link onto a different, e.g. canonical, participant row). For the
    -- other 4 tables the plain foreign column already IS the stable
    -- external fact, unchanged.
    v_anchor_expr := case tg_table_name
      when 'activity_participant_session_links' then $sql$coalesce('logical:' || logical_session_id::text, 'external:' || external_assignment_id::text)$sql$
      when 'activity_external_occurrence_links' then 'external_occurrence_id::text'
      when 'activity_metric_event_links' then 'metric_event_id::text'
      when 'activity_participant_metric_participant_links' then 'metric_event_participant_id::text'
      when 'activity_component_metric_segment_links' then 'metric_event_segment_id::text'
    end;
    execute format('select %s from %I.%I where id = $1', v_anchor_expr, tg_table_schema, tg_table_name)
      into v_old_anchor using v_supersedes;
    execute format('select %s from %I.%I where id = $1', v_anchor_expr, tg_table_schema, tg_table_name)
      into v_new_anchor using new.id;
    if v_old_anchor is distinct from v_new_anchor then
      raise exception '%.%: a successor (row %) must share the SAME source identity as its predecessor (%) — got % vs %, refusing to chain two unrelated lineages together (or mix a logical and an external identity)',
        tg_table_schema, tg_table_name, new.id, v_supersedes, v_new_anchor, v_old_anchor;
    end if;
  end if;
  return new;
end;
$_$;

CREATE FUNCTION training.check_metric_event_link_no_orphan_descendants() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_has_descendants boolean;
begin
  if old.link_status = 'confirmed' and new.link_status = 'superseded' then
    select
      exists (
        select 1 from training.activity_participant_metric_participant_links mpl
        join training_load.metric_event_participants mep on mep.id = mpl.metric_event_participant_id
        where mep.event_id = old.metric_event_id and mpl.link_status = 'confirmed'
      )
      or exists (
        select 1 from training.activity_component_metric_segment_links csl
        join training_load.metric_event_segments mes on mes.id = csl.metric_event_segment_id
        where mes.event_id = old.metric_event_id and csl.link_status = 'confirmed'
      )
      into v_has_descendants;
    if v_has_descendants then
      raise exception 'activity_metric_event_links (id=%): cannot supersede — CONFIRMED participant/segment links still depend on this activity/event pair; relink them first', old.id;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.check_metric_event_link_owner_compat() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_a_scope varchar; v_a_user uuid; v_a_club uuid; v_a_team uuid;
  v_e_scope varchar; v_e_user uuid; v_e_club uuid; v_e_team uuid;
begin
  if new.link_status <> 'confirmed' then
    return new;
  end if;
  select owner_scope, owner_user_id, owner_club_id, owner_team_id into v_a_scope, v_a_user, v_a_club, v_a_team
    from training.activities where id = new.activity_id;
  select owner_scope, owner_user_id, owner_club_id, owner_team_id into v_e_scope, v_e_user, v_e_club, v_e_team
    from training_load.metric_events where id = new.metric_event_id;
  if v_a_scope is distinct from v_e_scope or v_a_user is distinct from v_e_user
     or v_a_club is distinct from v_e_club or v_a_team is distinct from v_e_team then
    raise exception 'activity_metric_event_links (id=%): metric_event owner scope does not match the activity''s owner scope', new.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.check_participant_metric_link_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_participant_athlete uuid; v_activity_id uuid;
  v_metric_athlete uuid; v_metric_event_id uuid;
  v_event_linked boolean;
begin
  select athlete_id, activity_id into v_participant_athlete, v_activity_id
    from training.activity_participants where id = new.activity_participant_id;
  select athlete_id, event_id into v_metric_athlete, v_metric_event_id
    from training_load.metric_event_participants where id = new.metric_event_participant_id;
  if v_metric_athlete is distinct from v_participant_athlete then
    raise exception 'activity_participant_metric_participant_links (id=%): metric participant athlete does not match the activity participant', new.id;
  end if;
  if new.link_status = 'confirmed' then
    select exists (
      select 1 from training.activity_metric_event_links
      where activity_id = v_activity_id and metric_event_id = v_metric_event_id and link_status = 'confirmed'
    ) into v_event_linked;
    if not v_event_linked then
      raise exception 'activity_participant_metric_participant_links (id=%): the metric event is not confirmedly linked to the SAME activity', new.id;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.check_session_link_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_participant_athlete uuid;
  v_activity_id uuid;
  v_owner_scope varchar; v_owner_user uuid; v_owner_club uuid; v_owner_team uuid;
  v_assignment_athlete uuid;
  v_sched_owner_scope varchar; v_sched_owner_user uuid; v_sched_owner_club uuid; v_sched_owner_team uuid;
  v_live_ok boolean;
begin
  select ap.athlete_id, ap.activity_id, a.owner_scope, a.owner_user_id, a.owner_club_id, a.owner_team_id
    into v_participant_athlete, v_activity_id, v_owner_scope, v_owner_user, v_owner_club, v_owner_team
    from training.activity_participants ap join training.activities a on a.id = ap.activity_id
    where ap.id = new.activity_participant_id;

  if new.athlete_id is distinct from v_participant_athlete then
    raise exception 'activity_participant_session_links: athlete_id must match the participant''s own athlete_id';
  end if;

  if new.link_status <> 'confirmed' then
    return new;
  end if;

  if new.external_assignment_id is not null then
    select ea.athlete_id, es.owner_scope, es.owner_user_id, es.owner_club_id, es.owner_team_id
      into v_assignment_athlete, v_sched_owner_scope, v_sched_owner_user, v_sched_owner_club, v_sched_owner_team
      from training_load.external_assignments ea
      join training_load.external_schedule_occurrences eo on eo.id = ea.occurrence_id
      join training_load.external_schedules es on es.id = eo.schedule_id
      where ea.id = new.external_assignment_id;
    if v_assignment_athlete is distinct from v_participant_athlete then
      raise exception 'activity_participant_session_links (id=%): external_assignment athlete does not match the participant', new.id;
    end if;
    if v_sched_owner_scope is distinct from v_owner_scope or v_sched_owner_user is distinct from v_owner_user
       or v_sched_owner_club is distinct from v_owner_club or v_sched_owner_team is distinct from v_owner_team then
      raise exception 'activity_participant_session_links (id=%): external schedule owner scope does not match the activity''s owner scope', new.id;
    end if;
  end if;

  if new.logical_session_id is not null then
    select exists (
      select 1
      from plans.plan_sessions ps
      join plans.plan_days pd on pd.id = ps.plan_day_id
      join plans.plans p on p.id = pd.plan_id
      left join training_load.plan_workspace_ownership pwo on pwo.plan_id = p.id
      where ps.logical_session_id = new.logical_session_id
        -- The plan's OWN athlete must be the SAME athlete as this
        -- participant — workspace/owner-scope agreement alone is not
        -- enough (two different athletes' plans can share the exact
        -- same owning club/team), so without this a session belonging
        -- to athlete B could otherwise be confirmed-linked to athlete
        -- A's own participant row.
        and p.athlete_id = v_participant_athlete
        and p.is_active = true and p.is_edit_draft = false
        and p.plan_type = 'weekly' and p.status = 'active'
        and coalesce(pwo.owner_scope, 'unresolved') = v_owner_scope
        and pwo.owner_user_id is not distinct from v_owner_user
        and pwo.owner_club_id is not distinct from v_owner_club
        and pwo.owner_team_id is not distinct from v_owner_team
    ) into v_live_ok;
    if not v_live_ok then
      raise exception 'activity_participant_session_links (id=%): logical_session_id does not resolve to a REAL, live, PUBLISHED, same-workspace Weekly plan session', new.id;
    end if;
  end if;

  return new;
end;
$$;

CREATE FUNCTION training.correct_confirmed_activity_fields(p_activity_id uuid, p_occurred_local_date date, p_started_at timestamp with time zone, p_ended_at timestamp with time zone, p_timezone_snapshot text, p_activity_type_key text, p_performed_by uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_before training.activities%rowtype;
  v_after training.activities%rowtype;
begin
  select * into v_before from training.activities where id = p_activity_id for update;
  if not found then
    raise exception 'correct_confirmed_activity_fields: activity % not found', p_activity_id;
  end if;
  perform set_config('training.allow_confirmed_field_change', 'on', true);
  update training.activities
    set occurred_local_date = p_occurred_local_date, started_at = p_started_at, ended_at = p_ended_at,
        timezone_snapshot = p_timezone_snapshot, activity_type_key = p_activity_type_key, updated_at = now()
    where id = p_activity_id
    returning * into v_after;
  perform set_config('training.allow_confirmed_field_change', 'off', true);

  insert into training.activity_field_correction_log (activity_id, old_values, new_values, reason, performed_by_user_id)
    values (
      p_activity_id,
      jsonb_build_object('occurred_local_date', v_before.occurred_local_date, 'started_at', v_before.started_at, 'ended_at', v_before.ended_at, 'timezone_snapshot', v_before.timezone_snapshot, 'activity_type_key', v_before.activity_type_key),
      jsonb_build_object('occurred_local_date', v_after.occurred_local_date, 'started_at', v_after.started_at, 'ended_at', v_after.ended_at, 'timezone_snapshot', v_after.timezone_snapshot, 'activity_type_key', v_after.activity_type_key),
      p_reason, p_performed_by
    );
end;
$$;

CREATE FUNCTION training.lock_activity_decider(p_user_id uuid, p_team_id uuid, p_basis character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare
  v_club_id uuid;
begin
  if p_basis is null or p_basis not in ('team_coach', 'club_admin', 'platform_admin') then
    raise exception 'lock_activity_decider: unknown basis %', p_basis using errcode = 'invalid_parameter_value';
  end if;
  select club_id into v_club_id from public.teams where id = p_team_id and coalesce(is_active, true) for share;
  if not found then
    raise exception 'user % may not decide on the roster of team %', p_user_id, p_team_id using errcode = 'insufficient_privilege';
  end if;
  perform 1 from public.clubs where id = v_club_id and coalesce(is_active, true) for share;
  if not found then
    raise exception 'user % may not decide on the roster of team %: its club is archived', p_user_id, p_team_id using errcode = 'insufficient_privilege';
  end if;
  -- LO-2: the acting user first, then the role row (the order of the revocations).
  perform 1 from public.users u where u.id = p_user_id and u.is_active = true for share;
  if p_basis = 'team_coach' then
    perform 1 from public.user_team_roles r join public.users u on u.id = r.user_id
     where r.user_id = p_user_id and r.team_id = p_team_id and r.role = 'team_coach' and r.is_active = true and u.is_active = true
       for share of r;
  elsif p_basis = 'club_admin' then
    perform 1 from public.user_club_roles r join public.users u on u.id = r.user_id
     where r.user_id = p_user_id and r.club_id = v_club_id and r.role = 'club_admin' and r.is_active = true and u.is_active = true
       for share of r;
  else
    perform 1 from public.user_global_roles r join public.users u on u.id = r.user_id
     where r.user_id = p_user_id and r.role = 'platform_admin' and r.is_active = true and u.is_active = true
       for share of r;
  end if;
  if not found then
    raise exception 'user % may not decide on the roster of team % as %', p_user_id, p_team_id, p_basis using errcode = 'insufficient_privilege';
  end if;
  return p_basis;
end;
$$;

CREATE FUNCTION training.lock_roster_completions(p_activity_ids uuid[], p_exclusive boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_id uuid;
begin
  for v_id in select distinct x from unnest(p_activity_ids) x where x is not null order by 1 loop
    if p_exclusive then
      perform pg_advisory_xact_lock(hashtextextended('activity-roster-completion:' || v_id::text, 26));
    else
      perform pg_advisory_xact_lock_shared(hashtextextended('activity-roster-completion:' || v_id::text, 26));
    end if;
  end loop;
end;
$$;

CREATE FUNCTION training.lock_roster_team(p_team_id uuid, p_exclusive boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  if p_team_id is null then
    return;
  end if;
  if p_exclusive then
    perform pg_advisory_xact_lock(hashtextextended('activity-roster-team:' || p_team_id::text, 26));
  else
    perform pg_advisory_xact_lock_shared(hashtextextended('activity-roster-team:' || p_team_id::text, 26));
  end if;
end;
$$;

CREATE FUNCTION training.materialize_activity_group_from_external_occurrence(p_occurrence_id uuid, p_activity_type_key text, p_name text, p_performed_by uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
declare
  v_activity_id uuid;
  v_scheduled_date date;
  v_owner_scope varchar; v_owner_user_id uuid; v_owner_club_id uuid; v_owner_team_id uuid; v_timezone varchar;
  v_assignment_count int;
  v_rec record;
  v_participant_id uuid;
  v_already_linked boolean;
begin
  perform pg_advisory_xact_lock(hashtextextended('activity-group-occurrence:' || p_occurrence_id::text, 2));

  select eo.scheduled_date, es.owner_scope, es.owner_user_id, es.owner_club_id, es.owner_team_id, es.timezone
    into v_scheduled_date, v_owner_scope, v_owner_user_id, v_owner_club_id, v_owner_team_id, v_timezone
    from training_load.external_schedule_occurrences eo
    join training_load.external_schedules es on es.id = eo.schedule_id
    where eo.id = p_occurrence_id;
  if v_scheduled_date is null then
    raise exception 'materialize_activity_group_from_external_occurrence: unknown external occurrence %', p_occurrence_id;
  end if;

  select count(*) into v_assignment_count from training_load.external_assignments where occurrence_id = p_occurrence_id;
  if v_assignment_count = 0 then
    raise exception 'materialize_activity_group_from_external_occurrence: occurrence % has zero assignments yet — refusing to materialize an activity with no real target signal', p_occurrence_id;
  end if;

  -- Resolve through the canonical chain — a late assignment must land on
  -- the current canonical survivor, even if this occurrence's own
  -- confirmed link points at an activity later superseded via an
  -- unrelated participant-level merge.
  select training.resolve_canonical_activity_id(activity_id) into v_activity_id
    from training.activity_external_occurrence_links
    where external_occurrence_id = p_occurrence_id and link_status = 'confirmed';

  if v_activity_id is null then
    insert into training.activities (activity_type_key, name, occurred_local_date, timezone_snapshot, owner_scope, owner_user_id, owner_club_id, owner_team_id, origin, lifecycle_state, created_by_user_id)
      values (p_activity_type_key, p_name, v_scheduled_date, v_timezone, v_owner_scope, v_owner_user_id, v_owner_club_id, v_owner_team_id, 'external_assignment', 'confirmed', p_performed_by)
      returning id into v_activity_id;
    insert into training.activity_external_occurrence_links (activity_id, external_occurrence_id, link_method, link_status, confirmed_by_user_id, confirmed_at, created_by_user_id)
      values (v_activity_id, p_occurrence_id, 'automatic', 'confirmed', p_performed_by, now(), p_performed_by);
  end if;

  for v_rec in select id as assignment_id, athlete_id, timezone, local_scheduled_date from training_load.external_assignments where occurrence_id = p_occurrence_id loop
    insert into training.activity_participants (activity_id, athlete_id, local_date, timezone_snapshot, participation_status)
      values (v_activity_id, v_rec.athlete_id, v_rec.local_scheduled_date, v_rec.timezone, 'planned')
      on conflict (activity_id, athlete_id) do nothing
      returning id into v_participant_id;
    if v_participant_id is null then
      select id into v_participant_id from training.activity_participants where activity_id = v_activity_id and athlete_id = v_rec.athlete_id;
    end if;
    -- Checked by external_assignment_id ALONE (its own partial unique
    -- index is global, not per-participant) — an earlier confirmed claim
    -- may already exist on a DIFFERENT (now-alias) participant row, e.g.
    -- after a merge moved this athlete's canonical identity elsewhere;
    -- that earlier claim is still correctly reachable via canonical/alias
    -- resolution, so a fresh insert here must be skipped, never
    -- attempted (which would just hit the unique index).
    select exists (
      select 1 from training.activity_participant_session_links
      where external_assignment_id = v_rec.assignment_id and link_status = 'confirmed'
    ) into v_already_linked;
    if not v_already_linked then
      insert into training.activity_participant_session_links (activity_participant_id, athlete_id, external_assignment_id, link_method, link_status, confirmed_by_user_id, confirmed_at, created_by_user_id)
        values (v_participant_id, v_rec.athlete_id, v_rec.assignment_id, 'automatic', 'confirmed', p_performed_by, now(), p_performed_by);
    end if;
    v_participant_id := null;
  end loop;

  return v_activity_id;
end;
$$;

CREATE FUNCTION training.materialize_activity_group_from_metric_event(p_event_id uuid, p_activity_type_key text, p_name text, p_performed_by uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
declare
  v_activity_id uuid;
  v_occurred_date date;
  v_occurred_instant timestamptz;
  v_scope_level varchar;
  v_owner_scope varchar; v_owner_user_id uuid; v_owner_club_id uuid; v_owner_team_id uuid;
  v_timezone text;
  v_participant_count int;
  v_rec record;
  v_participant_id uuid;
  v_already_linked boolean;
  v_participant_local_date date;
begin
  perform pg_advisory_xact_lock(hashtextextended('activity-group-event:' || p_event_id::text, 3));

  select occurred_date, occurred_instant, scope_level, owner_scope, owner_user_id, owner_club_id, owner_team_id, event_timezone_snapshot
    into v_occurred_date, v_occurred_instant, v_scope_level, v_owner_scope, v_owner_user_id, v_owner_club_id, v_owner_team_id, v_timezone
    from training_load.metric_events where id = p_event_id;
  if v_occurred_date is null then
    raise exception 'materialize_activity_group_from_metric_event: unknown metric event %', p_event_id;
  end if;

  -- A metric_event with scope_level='day' is a DAY-LEVEL metric (sleep,
  -- recovery, resting HR, ...) — never a training. Only a 'session' event
  -- may become a training.activities row.
  if v_scope_level <> 'session' then
    raise exception 'materialize_activity_group_from_metric_event: event % has scope_level=''%'' — only session-level events may be materialized as a training activity', p_event_id, v_scope_level;
  end if;

  select count(*) into v_participant_count from training_load.metric_event_participants where event_id = p_event_id;
  if v_participant_count = 0 then
    raise exception 'materialize_activity_group_from_metric_event: event % has zero participants yet — refusing to materialize an activity with no real target signal', p_event_id;
  end if;

  -- metric_events carries no group-level timezone of its own beyond
  -- event_timezone_snapshot (v3) — that column is the ONLY source; a
  -- participant's personal athlete_timezone_snapshot is never used as a
  -- stand-in for the group event's own place/time context. If it is
  -- still unresolved, this function REFUSES to materialize at all (no
  -- silent UTC fallback, no silent first-participant fallback) rather
  -- than guessing.
  if v_timezone is null then
    raise exception 'materialize_activity_group_from_metric_event: event % has no event_timezone_snapshot set — refusing to guess (never falls back to a participant''s own timezone or a silent UTC default); set it explicitly first', p_event_id;
  end if;

  -- Resolve through the canonical chain — if this event's own confirmed
  -- group link points at an activity that was LATER superseded via an
  -- unrelated participant-level merge, a late participant must still
  -- land on the current canonical survivor, never on the dead row (the
  -- link itself is never repointed — only resolved at use-time).
  select training.resolve_canonical_activity_id(activity_id) into v_activity_id
    from training.activity_metric_event_links
    where metric_event_id = p_event_id and link_status = 'confirmed';

  -- occurred_instant is the SESSION's own START instant for a
  -- 'session'-scope event — carried straight onto activities.started_at.
  -- There is no real ended_instant/duration column on metric_events (a
  -- future provider-neutral addition, not introduced here) so
  -- activities.ended_at stays null via this path; a real implementation
  -- adding such a column should propagate it here the same way.
  if v_activity_id is null then
    insert into training.activities (activity_type_key, name, occurred_local_date, started_at, timezone_snapshot, owner_scope, owner_user_id, owner_club_id, owner_team_id, origin, lifecycle_state, created_by_user_id)
      values (p_activity_type_key, p_name, v_occurred_date, v_occurred_instant, v_timezone, v_owner_scope, v_owner_user_id, v_owner_club_id, v_owner_team_id, 'source_import', 'confirmed', p_performed_by)
      returning id into v_activity_id;
    insert into training.activity_metric_event_links (activity_id, metric_event_id, link_method, link_status, confirmed_by_user_id, confirmed_at, created_by_user_id)
      values (v_activity_id, p_event_id, 'automatic', 'confirmed', p_performed_by, now(), p_performed_by);
  end if;

  for v_rec in select id as metric_participant_id, athlete_id, athlete_timezone_snapshot from training_load.metric_event_participants where event_id = p_event_id loop
    -- Each PARTICIPANT's own local_date is computed from the real shared
    -- instant, converted into THEIR OWN athlete_timezone_snapshot — never
    -- the event-local date uniformly applied to everyone. Only when
    -- there is no instant at all (a pure date-only event) does the
    -- event-local date stand in, as an explicitly documented fallback —
    -- never a silent substitute for a real conversion. This is what lets
    -- an athlete on the other side of the world genuinely land on the
    -- FOLLOWING calendar day while remaining part of the exact same
    -- activity.
    if v_occurred_instant is not null then
      v_participant_local_date := (v_occurred_instant at time zone v_rec.athlete_timezone_snapshot)::date;
    else
      v_participant_local_date := v_occurred_date;
    end if;
    insert into training.activity_participants (activity_id, athlete_id, local_date, timezone_snapshot, participation_status)
      values (v_activity_id, v_rec.athlete_id, v_participant_local_date, v_rec.athlete_timezone_snapshot, 'planned')
      on conflict (activity_id, athlete_id) do nothing
      returning id into v_participant_id;
    if v_participant_id is null then
      select id into v_participant_id from training.activity_participants where activity_id = v_activity_id and athlete_id = v_rec.athlete_id;
    end if;
    -- Checked by metric_event_participant_id ALONE, same reasoning as the
    -- external-occurrence variant above.
    select exists (
      select 1 from training.activity_participant_metric_participant_links
      where metric_event_participant_id = v_rec.metric_participant_id and link_status = 'confirmed'
    ) into v_already_linked;
    if not v_already_linked then
      insert into training.activity_participant_metric_participant_links (activity_participant_id, metric_event_participant_id, link_method, link_status, confirmed_by_user_id, confirmed_at, created_by_user_id)
        values (v_participant_id, v_rec.metric_participant_id, 'automatic', 'confirmed', p_performed_by, now(), p_performed_by);
    end if;
    v_participant_id := null;
  end loop;

  return v_activity_id;
end;
$$;

CREATE FUNCTION training.merge_activity_participants(p_source_participant_id uuid, p_target_participant_id uuid, p_performed_by uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
declare
  v_lo_p uuid; v_hi_p uuid;
  v_lo_a uuid; v_hi_a uuid;
  v_source record; v_target record;
  v_source_owner record; v_target_owner record;
  v_remaining int;
begin
  if p_source_participant_id = p_target_participant_id then
    raise exception 'merge_activity_participants: source and target are the same participant';
  end if;

  -- Advisory-lock BOTH participant identities, sorted — the SAME lock
  -- namespace (salt 4) reparent_activity_participant uses, so a reparent
  -- and a merge racing over the SAME participant genuinely serialize
  -- against each other, not just merge-vs-merge.
  if p_source_participant_id < p_target_participant_id then v_lo_p := p_source_participant_id; v_hi_p := p_target_participant_id;
  else v_lo_p := p_target_participant_id; v_hi_p := p_source_participant_id; end if;
  perform pg_advisory_xact_lock(hashtextextended('activity-participant:' || v_lo_p::text, 4));
  perform pg_advisory_xact_lock(hashtextextended('activity-participant:' || v_hi_p::text, 4));

  -- Now reliably read source/target (no other conforming function can be
  -- mid-mutation of either while we hold both advisory locks).
  select * into v_source from training.activity_participants where id = p_source_participant_id;
  select * into v_target from training.activity_participants where id = p_target_participant_id;

  -- Idempotent replay: this exact merge already applied.
  if v_source.merge_status = 'superseded' and v_source.superseded_by_participant_id = p_target_participant_id then
    return p_target_participant_id;
  end if;

  if v_source.merge_status <> 'canonical' then
    raise exception 'merge_activity_participants: source participant % is already merged into a DIFFERENT participant — resolve to its canonical id first', p_source_participant_id;
  end if;
  if v_target.merge_status <> 'canonical' then
    raise exception 'merge_activity_participants: target participant % is itself an alias — merge into its canonical id instead', p_target_participant_id;
  end if;
  if v_source.athlete_id is distinct from v_target.athlete_id then
    raise exception 'merge_activity_participants: source and target represent DIFFERENT athletes — refusing';
  end if;

  -- Lock BOTH activities ascending by id (may be the same row — locking
  -- it once is harmless/idempotent within one transaction).
  if v_source.activity_id < v_target.activity_id then v_lo_a := v_source.activity_id; v_hi_a := v_target.activity_id;
  else v_lo_a := v_target.activity_id; v_hi_a := v_source.activity_id; end if;
  perform 1 from training.activities where id = v_lo_a for update;
  if v_hi_a <> v_lo_a then
    perform 1 from training.activities where id = v_hi_a for update;
  end if;

  -- Lock BOTH participant rows, sorted by id (redundant with the advisory
  -- lock for OTHER conforming callers, but keeps FOR UPDATE/FOR SHARE
  -- readers consistent too).
  perform 1 from training.activity_participants where id = v_lo_p for update;
  perform 1 from training.activity_participants where id = v_hi_p for update;

  select owner_scope, owner_user_id, owner_club_id, owner_team_id into v_source_owner from training.activities where id = v_source.activity_id;
  select owner_scope, owner_user_id, owner_club_id, owner_team_id into v_target_owner from training.activities where id = v_target.activity_id;
  if v_source_owner.owner_scope is distinct from v_target_owner.owner_scope or v_source_owner.owner_user_id is distinct from v_target_owner.owner_user_id
     or v_source_owner.owner_club_id is distinct from v_target_owner.owner_club_id or v_source_owner.owner_team_id is distinct from v_target_owner.owner_team_id then
    raise exception 'merge_activity_participants: source and target belong to activities in DIFFERENT owner scopes — refusing';
  end if;

  perform set_config('training.allow_participant_merge_write', 'on', true);
  update training.activity_participants
    set merge_status = 'superseded', superseded_by_participant_id = p_target_participant_id, updated_at = now()
    where id = p_source_participant_id;
  perform set_config('training.allow_participant_merge_write', 'off', true);

  insert into training.activity_participant_merge_log (source_participant_id, target_participant_id, source_activity_id, target_activity_id, reason, performed_by_user_id)
    values (p_source_participant_id, p_target_participant_id, v_source.activity_id, v_target.activity_id, p_reason, p_performed_by);

  -- If the source activity now has zero remaining CANONICAL participants,
  -- it is vestigial — supersede it too, pointing at the target's activity
  -- (same write-once/no-cycle guarantees as reparent's own version of
  -- this; both activities are already locked above, sorted, so no extra
  -- lock acquisition is needed here).
  if v_source.activity_id <> v_target.activity_id then
    select count(*) into v_remaining from training.activity_participants where activity_id = v_source.activity_id and merge_status = 'canonical';
    if v_remaining = 0 then
      perform set_config('training.allow_supersede_write', 'on', true);
      update training.activities set lifecycle_state = 'superseded', superseded_by_activity_id = v_target.activity_id, updated_at = now()
        where id = v_source.activity_id and lifecycle_state <> 'superseded';
      perform set_config('training.allow_supersede_write', 'off', true);
    end if;
  end if;

  return p_target_participant_id;
end;
$$;

CREATE FUNCTION training.participant_alias_ids(p_canonical_participant_id uuid) RETURNS TABLE(participant_id uuid)
    LANGUAGE sql STABLE
    AS $$
  with recursive chain as (
    select p_canonical_participant_id as participant_id
    union all
    select ap.id from training.activity_participants ap join chain c on ap.superseded_by_participant_id = c.participant_id
  )
  select participant_id from chain;
$$;

CREATE FUNCTION training.protect_activity_completion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'activity_completions: completion of activity % is never deleted', old.activity_id;
  end if;
  if tg_op = 'INSERT' then
    perform training.assert_canonical_team_activity(new.activity_id, new.owner_team_id, 'activity_completions');
  else
    if new.activity_id is distinct from old.activity_id or new.owner_team_id is distinct from old.owner_team_id then
      raise exception 'activity_completions: the activity and team of a completion never change (activity %)', old.activity_id;
    end if;
    if new.revision is distinct from old.revision + 1 then
      raise exception 'activity_completions: every change bumps the revision by one (activity %, % -> %)', old.activity_id, old.revision, new.revision;
    end if;
    new.updated_at := now();
  end if;
  if new.status = 'complete' and (tg_op = 'INSERT' or old.status is distinct from 'complete'
       or new.completed_by_user_id is distinct from old.completed_by_user_id
       or new.completed_by_basis is distinct from old.completed_by_basis) then
    perform training.lock_activity_decider(new.completed_by_user_id, new.owner_team_id, new.completed_by_basis);
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_activity_completion_log() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op <> 'INSERT' then
    raise exception 'activity_completion_log is append-only (% refused)', tg_op;
  end if;
  -- A log row belongs to the canonical team session it describes, like
  -- every other row that points at an activity.
  perform training.assert_canonical_team_activity(new.activity_id, null, 'activity_completion_log');
  return new;
end;
$$;

CREATE FUNCTION training.protect_activity_identity_fields() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.owner_scope is distinct from old.owner_scope
     or new.owner_user_id is distinct from old.owner_user_id
     or new.owner_club_id is distinct from old.owner_club_id
     or new.owner_team_id is distinct from old.owner_team_id then
    raise exception 'training.activities (id=%): owner scope is immutable — no silent reparenting', old.id;
  end if;
  if new.origin is distinct from old.origin then
    raise exception 'training.activities (id=%): origin is immutable', old.id;
  end if;
  if old.superseded_by_activity_id is not null and new.superseded_by_activity_id is distinct from old.superseded_by_activity_id then
    raise exception 'training.activities (id=%): superseded_by_activity_id is write-once — an existing supersede chain can never be altered', old.id;
  end if;
  if new.superseded_by_activity_id is not null and old.superseded_by_activity_id is null
     and current_setting('training.allow_supersede_write', true) is distinct from 'on' then
    raise exception 'training.activities (id=%): superseded_by_activity_id may only be set by a sanctioned merge/reparent function', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_activity_lifecycle_transitions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.lifecycle_state = old.lifecycle_state then
    return new;
  end if;
  if not (
    (old.lifecycle_state = 'provisional' and new.lifecycle_state in ('confirmed', 'superseded')) or
    (old.lifecycle_state = 'confirmed' and new.lifecycle_state = 'superseded')
  ) then
    raise exception 'training.activities (id=%): illegal lifecycle_state transition % -> %', old.id, old.lifecycle_state, new.lifecycle_state;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_activity_roster_request() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op <> 'INSERT' then
    raise exception 'activity_roster_requests is append-only (% refused)', tg_op;
  end if;
  perform training.assert_canonical_team_activity(new.activity_id, null, 'activity_roster_requests');
  return new;
end;
$$;

CREATE FUNCTION training.protect_activity_source_observation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'activity_source_observations: observation % is removed only by the undo of its import', old.id;
  end if;
  if old.resolved_at is not null or new.resolved_at is null
     or new.id is distinct from old.id or new.activity_id is distinct from old.activity_id
     or new.athlete_id is distinct from old.athlete_id or new.source_connection_id is distinct from old.source_connection_id
     or new.kind is distinct from old.kind or new.reason_code is distinct from old.reason_code
     or new.observed_at is distinct from old.observed_at or new.adapter_ref is distinct from old.adapter_ref then
    raise exception 'activity_source_observations: an observation is only resolved, once (observation %)', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_activity_source_observation_v57() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    if training_load.session_undo_marker_ok() then
      return old;
    end if;
    raise exception 'activity_source_observations: observation % is removed only by the undo of its import', old.id;
  end if;
  if old.resolved_at is not null or new.resolved_at is null
     or new.id is distinct from old.id or new.activity_id is distinct from old.activity_id
     or new.athlete_id is distinct from old.athlete_id or new.source_connection_id is distinct from old.source_connection_id
     or new.kind is distinct from old.kind or new.reason_code is distinct from old.reason_code
     or new.observed_at is distinct from old.observed_at or new.adapter_ref is distinct from old.adapter_ref then
    raise exception 'activity_source_observations: an observation is only resolved, once (observation %)', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_component_identity_once_used() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_locked boolean;
begin
  if new.activity_id is distinct from old.activity_id then
    raise exception 'training.activity_components (id=%): activity_id is unconditionally immutable — a reparent clones a NEW component row, it never repoints an existing one', old.id;
  end if;
  if new.origin is distinct from old.origin then
    raise exception 'training.activity_components (id=%): origin is unconditionally immutable', old.id;
  end if;

  if new.parent_component_id is not distinct from old.parent_component_id
     and new.component_type_key is not distinct from old.component_type_key
     and new.exercise_id is not distinct from old.exercise_id
     and new.name_snapshot is not distinct from old.name_snapshot
     and new.image_url_snapshot is not distinct from old.image_url_snapshot
     and new.instructions_snapshot is not distinct from old.instructions_snapshot
     and new.planned_prescription_snapshot is not distinct from old.planned_prescription_snapshot
     and new.planned_prescription_snapshot_version is not distinct from old.planned_prescription_snapshot_version
     and new.sort_order is not distinct from old.sort_order
     and new.planned_duration_seconds is not distinct from old.planned_duration_seconds then
    return new;
  end if;
  select
    exists (select 1 from training.activity_participant_components where activity_component_id = old.id)
    or exists (select 1 from training.activity_component_metric_segment_links where activity_component_id = old.id and link_status = 'confirmed')
    into v_locked;
  if v_locked then
    -- actual_duration_seconds (the "what really happened" capture field)
    -- is deliberately NOT in the guarded list above — it legitimately
    -- keeps being filled in after the component is already in use.
    raise exception 'training.activity_components (id=%): identity/snapshot/planned-order fields are immutable once used or confirmed', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_confirmed_activity_fields() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.lifecycle_state in ('confirmed', 'superseded') and (
       new.occurred_local_date is distinct from old.occurred_local_date
    or new.started_at is distinct from old.started_at
    or new.ended_at is distinct from old.ended_at
    or new.timezone_snapshot is distinct from old.timezone_snapshot
    or new.activity_type_key is distinct from old.activity_type_key
  ) and current_setting('training.allow_confirmed_field_change', true) is distinct from 'on' then
    raise exception 'training.activities (id=%): confirmed/superseded activity date/time/timezone/type fields are immutable — use correct_confirmed_activity_fields()', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_link_chain_write_once() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.superseded_by_link_id is not null and new.superseded_by_link_id is distinct from old.superseded_by_link_id then
    raise exception '%: superseded_by_link_id is write-once — an existing link chain can never be altered', tg_table_name;
  end if;
  if old.supersedes_link_id is not null and new.supersedes_link_id is distinct from old.supersedes_link_id then
    raise exception '%: supersedes_link_id is write-once', tg_table_name;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_link_identity_fields() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_mutable_keys text[] := array['link_status', 'confidence', 'reason', 'confirmed_by_user_id', 'confirmed_at', 'superseded_by_link_id', 'supersedes_link_id'];
  v_old jsonb := to_jsonb(old);
  v_new jsonb := to_jsonb(new);
  k text;
begin
  if tg_table_name = 'activity_participant_session_links' then
    v_mutable_keys := v_mutable_keys || array['activity_participant_id'];
  end if;
  foreach k in array v_mutable_keys loop
    v_old := v_old - k;
    v_new := v_new - k;
  end loop;
  if v_old is distinct from v_new then
    raise exception '%: identity/target fields are immutable after insert — a relink must insert a NEW row, never repoint an existing one', tg_table_name;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_link_status_transitions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.link_status = old.link_status then
    return new;
  end if;
  if not (
    (old.link_status = 'suggested' and new.link_status in ('confirmed', 'rejected')) or
    (old.link_status = 'confirmed' and new.link_status = 'superseded')
  ) then
    raise exception '%: illegal link_status transition % -> %', tg_table_name, old.link_status, new.link_status;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_match_suggestion_identity_and_transitions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.activity_id is distinct from old.activity_id
     or new.source_participant_id is distinct from old.source_participant_id
     or new.candidate_activity_id is distinct from old.candidate_activity_id
     or new.candidate_participant_id is distinct from old.candidate_participant_id
     or new.confidence is distinct from old.confidence
     or new.score_breakdown is distinct from old.score_breakdown
     or new.policy_version is distinct from old.policy_version
     or new.reason is distinct from old.reason
     or new.created_at is distinct from old.created_at then
    raise exception 'training.activity_match_suggestions (id=%): identity/candidate fields are immutable', old.id;
  end if;

  if new.status is distinct from old.status then
    if old.status <> 'open' or new.status not in ('accepted', 'dismissed') then
      raise exception 'training.activity_match_suggestions (id=%): illegal status transition % -> %', old.id, old.status, new.status;
    end if;
    if new.resolved_by_user_id is null or new.resolved_at is null then
      raise exception 'training.activity_match_suggestions (id=%): resolved_by_user_id and resolved_at must both be set when resolving a suggestion', old.id;
    end if;
  else
    if old.resolved_at is not null and (
      new.resolved_by_user_id is distinct from old.resolved_by_user_id
      or new.resolved_at is distinct from old.resolved_at
    ) then
      raise exception 'training.activity_match_suggestions (id=%): resolved_by_user_id/resolved_at are write-once once a suggestion is resolved', old.id;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_participant_component_fields() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (new.activity_participant_id is distinct from old.activity_participant_id
      or new.activity_component_id is distinct from old.activity_component_id
      or new.activity_id is distinct from old.activity_id)
     and current_setting('training.allow_component_repoint', true) is distinct from 'on' then
    raise exception 'training.activity_participant_components (id=%): participant/component/activity linkage may only be repointed by reparent_activity_participant()''s sanctioned component strategy', old.id;
  end if;
  if new.actual_prescription_snapshot is distinct from old.actual_prescription_snapshot
     or new.actual_prescription_snapshot_version is distinct from old.actual_prescription_snapshot_version then
    raise exception 'training.activity_participant_components (id=%): actual_prescription_snapshot is immutable once recorded', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_participant_identity_once_linked() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  is_load_bearing boolean;
begin
  if new.athlete_id is not distinct from old.athlete_id
     and new.timezone_snapshot is not distinct from old.timezone_snapshot
     and new.local_date is not distinct from old.local_date then
    -- fall through to the merge-status/activity_id write-once checks below
    null;
  else
    select
      exists (select 1 from training.activity_participant_session_links where activity_participant_id = old.id)
      or exists (select 1 from training.activity_participant_metric_participant_links where activity_participant_id = old.id)
      or exists (select 1 from training.activity_participant_components where activity_participant_id = old.id)
      or old.merge_status = 'superseded'
      or exists (select 1 from training.activity_participants where superseded_by_participant_id = old.id)
      into is_load_bearing;
    if is_load_bearing then
      raise exception 'training.activity_participants (id=%): athlete_id/timezone_snapshot/local_date are immutable once load-bearing (linked, itself an alias, or the target of an incoming alias) — reparent the ACTIVITY instead, never the athlete identity', old.id;
    end if;
  end if;

  -- activity_id may only be changed by reparent_activity_participant()
  -- (v4), gated behind the same session-local GUC every other
  -- sanctioned-function-only field in this schema uses.
  if new.activity_id is distinct from old.activity_id
     and current_setting('training.allow_reparent_write', true) is distinct from 'on' then
    raise exception 'training.activity_participants (id=%): activity_id may only be changed by reparent_activity_participant()', old.id;
  end if;

  if old.superseded_by_participant_id is not null and new.superseded_by_participant_id is distinct from old.superseded_by_participant_id then
    raise exception 'training.activity_participants (id=%): superseded_by_participant_id is write-once', old.id;
  end if;
  if new.superseded_by_participant_id is not null and old.superseded_by_participant_id is null
     and current_setting('training.allow_participant_merge_write', true) is distinct from 'on' then
    raise exception 'training.activity_participants (id=%): superseded_by_participant_id may only be set by merge_activity_participants()', old.id;
  end if;
  if new.merge_status is distinct from old.merge_status
     and current_setting('training.allow_participant_merge_write', true) is distinct from 'on' then
    raise exception 'training.activity_participants (id=%): merge_status may only be changed by merge_activity_participants()', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.protect_participation_reason() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'participation_reasons: reason % is deactivated, never deleted', old.key;
  end if;
  if new.key is distinct from old.key then
    raise exception 'participation_reasons: the key % never changes', old.key;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.reparent_activity_participant(p_participant_id uuid, p_to_activity_id uuid, p_performed_by uuid, p_reason text, p_component_strategy character varying DEFAULT 'none'::character varying, p_component_mapping jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_from_activity_id uuid;
  v_lo uuid; v_hi uuid;
  v_from_owner_scope varchar; v_from_owner_user uuid; v_from_owner_club uuid; v_from_owner_team uuid;
  v_to_owner_scope varchar; v_to_owner_user uuid; v_to_owner_club uuid; v_to_owner_team uuid;
  v_to_lifecycle varchar;
  v_remaining int;
  v_has_component_rows boolean;
  v_rec record;
  v_seg_rec record;
  v_mapped_id uuid;
  v_clone_id uuid;
  v_target_event_linked boolean;
  v_old_event_link_id uuid;
  v_new_event_link_id uuid;
  v_progress boolean;
  v_merge_status varchar;
  -- In-memory-only working state for the 'clone' strategy — see this
  -- function's own header comment for why these replace temp tables.
  v_seg_carryover jsonb;
  v_components_to_clone uuid[];
  v_new_parents uuid[];
  v_id_map jsonb;
  v_item jsonb;
begin
  -- Step 1: advisory-lock the participant identity FIRST. This alone is
  -- what makes every read below reliable without a peek/retry loop.
  perform pg_advisory_xact_lock(hashtextextended('activity-participant:' || p_participant_id::text, 4));

  select activity_id, merge_status into v_from_activity_id, v_merge_status from training.activity_participants where id = p_participant_id;
  if v_from_activity_id is null then
    raise exception 'activity_participant % not found', p_participant_id;
  end if;
  -- Round 4 fix: a SUPERSEDED (alias) participant must never be physically
  -- moved — its whole reason for existing is to resolve, via
  -- resolve_canonical_participant_id, to its canonical target; reparenting
  -- it directly would let the canonical result wrongly link the WRONG
  -- activities together (the alias would carry the move, but every
  -- lookup following the alias chain still lands on the canonical row,
  -- which never moved). Checked before ANY write below — zero partial
  -- writes on refusal.
  if v_merge_status <> 'canonical' then
    raise exception 'reparent_activity_participant: participant % is not canonical (merge_status=%) — resolve to its canonical id first, then reparent that', p_participant_id, v_merge_status;
  end if;
  if v_from_activity_id = p_to_activity_id then
    return; -- no-op, already there
  end if;

  -- Step 2: lock BOTH activities ascending by id.
  if v_from_activity_id < p_to_activity_id then v_lo := v_from_activity_id; v_hi := p_to_activity_id;
  else v_lo := p_to_activity_id; v_hi := v_from_activity_id; end if;
  perform 1 from training.activities where id = v_lo for update;
  perform 1 from training.activities where id = v_hi for update;

  -- Step 3: lock the participant row itself.
  perform 1 from training.activity_participants where id = p_participant_id for update;

  select owner_scope, owner_user_id, owner_club_id, owner_team_id into v_from_owner_scope, v_from_owner_user, v_from_owner_club, v_from_owner_team
    from training.activities where id = v_from_activity_id;
  select owner_scope, owner_user_id, owner_club_id, owner_team_id, lifecycle_state into v_to_owner_scope, v_to_owner_user, v_to_owner_club, v_to_owner_team, v_to_lifecycle
    from training.activities where id = p_to_activity_id;

  if v_to_lifecycle = 'superseded' then
    raise exception 'reparent_activity_participant: refusing to reparent into activity % — it is already superseded', p_to_activity_id;
  end if;
  if v_from_owner_scope is distinct from v_to_owner_scope or v_from_owner_user is distinct from v_to_owner_user
     or v_from_owner_club is distinct from v_to_owner_club or v_from_owner_team is distinct from v_to_owner_team then
    raise exception 'refusing to reparent activity_participant % across DIFFERENT owner scopes (from=%/%/%/% to=%/%/%/%)',
      p_participant_id, v_from_owner_scope, v_from_owner_club, v_from_owner_team, v_from_owner_user,
      v_to_owner_scope, v_to_owner_club, v_to_owner_team, v_to_owner_user;
  end if;

  -- Any of this participant's OWN confirmed metric-participant links must
  -- remain valid post-reparent — their event must ALREADY be confirmedly
  -- linked to the TARGET activity, or the whole operation is refused
  -- (never a silent orphan).
  for v_rec in
    select mep.event_id from training.activity_participant_metric_participant_links mpl
    join training_load.metric_event_participants mep on mep.id = mpl.metric_event_participant_id
    where mpl.activity_participant_id = p_participant_id and mpl.link_status = 'confirmed'
  loop
    select exists (
      select 1 from training.activity_metric_event_links
      where activity_id = p_to_activity_id and metric_event_id = v_rec.event_id and link_status = 'confirmed'
    ) into v_target_event_linked;
    if not v_target_event_linked then
      raise exception 'reparent_activity_participant: participant % has a CONFIRMED metric-participant link whose event (%) is not linked to the target activity — relink the event first', p_participant_id, v_rec.event_id;
    end if;
  end loop;

  select exists (select 1 from training.activity_participant_components where activity_participant_id = p_participant_id) into v_has_component_rows;
  if v_has_component_rows and p_component_strategy = 'none' then
    raise exception 'reparent_activity_participant: participant % has component performance data — pass component_strategy ''clone'' or ''map''', p_participant_id;
  end if;

  -- Pre-flight for 'clone': a metric_event can only ever be confirmedly
  -- linked to ONE activity at a time (the partial unique index on
  -- metric_event_id is global, not per-activity) — so "the target must
  -- ALREADY have the event linked" can never hold in practice; the event
  -- is always still linked to the SOURCE at this point. The correct
  -- operation is for the clone to RELINK the event itself, from source to
  -- target, as PART of carrying the segment link over — but ONLY when
  -- doing so is unambiguous: the event must have NO confirmed descendant
  -- (component-segment or participant-metric) OTHER than the exact
  -- segment link(s) this clone is about to carry over. If the event is
  -- shared with anything else, the whole reparent is refused — never a
  -- silent, semantically-wrong event relink.
  if v_has_component_rows and p_component_strategy = 'clone' then
    for v_seg_rec in
      select distinct mes.event_id
      from training.activity_participant_components pc
      join training.activity_component_metric_segment_links csl on csl.activity_component_id = pc.activity_component_id and csl.link_status = 'confirmed'
      join training_load.metric_event_segments mes on mes.id = csl.metric_event_segment_id
      where pc.activity_participant_id = p_participant_id
    loop
      declare
        v_own_segment_count int;
        v_total_segment_descendants int;
        v_total_participant_descendants int;
      begin
        select count(*) into v_own_segment_count
          from training.activity_participant_components pc
          join training.activity_component_metric_segment_links csl on csl.activity_component_id = pc.activity_component_id and csl.link_status = 'confirmed'
          join training_load.metric_event_segments mes on mes.id = csl.metric_event_segment_id
          where pc.activity_participant_id = p_participant_id and mes.event_id = v_seg_rec.event_id;
        select count(*) into v_total_segment_descendants
          from training.activity_component_metric_segment_links csl
          join training_load.metric_event_segments mes on mes.id = csl.metric_event_segment_id
          where mes.event_id = v_seg_rec.event_id and csl.link_status = 'confirmed';
        select count(*) into v_total_participant_descendants
          from training.activity_participant_metric_participant_links mpl
          join training_load.metric_event_participants mep on mep.id = mpl.metric_event_participant_id
          where mep.event_id = v_seg_rec.event_id and mpl.link_status = 'confirmed';
        if v_total_segment_descendants <> v_own_segment_count or v_total_participant_descendants <> 0 then
          raise exception 'reparent_activity_participant: metric event % has OTHER confirmed data depending on it besides this participant''s own component(s) — refusing to relink it automatically; use component_strategy ''map'' and relink manually', v_seg_rec.event_id;
        end if;
      end;
    end loop;
  end if;

  -- The participant row itself moves FIRST — activity_participant_components'
  -- own composite FK to (activity_participants.id, activity_id) requires a
  -- matching participant row at the TARGET activity to already exist before
  -- any junction row can be repointed at it below.
  perform set_config('training.allow_reparent_write', 'on', true);
  update training.activity_participants set activity_id = p_to_activity_id, updated_at = now() where id = p_participant_id;
  perform set_config('training.allow_reparent_write', 'off', true);

  if v_has_component_rows then
    perform set_config('training.allow_component_repoint', 'on', true);
    if p_component_strategy = 'clone' then
      v_seg_carryover := '[]'::jsonb;
      select coalesce(array_agg(distinct activity_component_id), '{}') into v_components_to_clone
        from training.activity_participant_components where activity_participant_id = p_participant_id;
      v_id_map := '{}'::jsonb;

      for v_rec in
        select pc.activity_component_id as old_component_id, csl.id as old_link_id, csl.metric_event_segment_id as segment_id
        from training.activity_participant_components pc
        join training.activity_component_metric_segment_links csl on csl.activity_component_id = pc.activity_component_id and csl.link_status = 'confirmed'
        where pc.activity_participant_id = p_participant_id
      loop
        v_seg_carryover := v_seg_carryover || jsonb_build_object('old_component_id', v_rec.old_component_id, 'old_link_id', v_rec.old_link_id, 'segment_id', v_rec.segment_id);
      end loop;

      -- Supersede EXACTLY the captured links (bulk, by id — never a
      -- fragile status-based re-query) — this is what unblocks the event
      -- relink below (the "no orphan descendants" trigger fires
      -- immediately, not deferred, and sees zero confirmed descendants
      -- once these are gone).
      if jsonb_array_length(v_seg_carryover) > 0 then
        update training.activity_component_metric_segment_links set link_status = 'superseded'
          where id in (select (elem ->> 'old_link_id')::uuid from jsonb_array_elements(v_seg_carryover) elem);
      end if;

      for v_seg_rec in
        select distinct mes.event_id
        from jsonb_array_elements(v_seg_carryover) elem
        join training_load.metric_event_segments mes on mes.id = (elem ->> 'segment_id')::uuid
      loop
        update training.activity_metric_event_links set link_status = 'superseded'
          where activity_id = v_from_activity_id and metric_event_id = v_seg_rec.event_id and link_status = 'confirmed'
          returning id into v_old_event_link_id;
        insert into training.activity_metric_event_links (activity_id, metric_event_id, link_method, link_status, confirmed_by_user_id, confirmed_at, supersedes_link_id, reason, created_by_user_id)
          values (p_to_activity_id, v_seg_rec.event_id, 'automatic', 'confirmed', p_performed_by, now(), v_old_event_link_id, 'relinked as part of reparent clone strategy', p_performed_by)
          returning id into v_new_event_link_id;
        update training.activity_metric_event_links set superseded_by_link_id = v_new_event_link_id where id = v_old_event_link_id;
      end loop;

      -- Full component set to clone: every LEAF the participant directly
      -- performed, plus every ancestor of each, walked to the root — a
      -- plain PL/pgSQL array used as a set (dedup via NOT ... = ANY(...)).
      loop
        select array_agg(distinct ac.parent_component_id) into v_new_parents
          from training.activity_components ac
          where ac.id = any(v_components_to_clone)
            and ac.parent_component_id is not null
            and not (ac.parent_component_id = any(v_components_to_clone));
        exit when v_new_parents is null;
        v_components_to_clone := v_components_to_clone || v_new_parents;
      end loop;

      -- Clone ancestor-first: a component is processed only once its own
      -- parent is already in the map (or has none) — a real topological
      -- pass, not a flat one, so parent_component_id on each clone points
      -- at the CORRESPONDING new clone, never NULL.
      loop
        v_progress := false;
        for v_rec in
          select ac.id, ac.parent_component_id, ac.component_type_key, ac.exercise_id, ac.name_snapshot, ac.image_url_snapshot, ac.instructions_snapshot,
                 ac.planned_prescription_snapshot, ac.planned_prescription_snapshot_version, ac.sort_order, ac.planned_duration_seconds, ac.origin
          from training.activity_components ac
          where ac.id = any(v_components_to_clone)
            and not (v_id_map ? ac.id::text)
            and (ac.parent_component_id is null or v_id_map ? ac.parent_component_id::text)
        loop
          insert into training.activity_components (activity_id, parent_component_id, component_type_key, exercise_id, name_snapshot, image_url_snapshot, instructions_snapshot, planned_prescription_snapshot, planned_prescription_snapshot_version, sort_order, planned_duration_seconds, origin)
            values (
              p_to_activity_id,
              case when v_rec.parent_component_id is null then null else (v_id_map ->> v_rec.parent_component_id::text)::uuid end,
              v_rec.component_type_key, v_rec.exercise_id, v_rec.name_snapshot, v_rec.image_url_snapshot, v_rec.instructions_snapshot,
              v_rec.planned_prescription_snapshot, v_rec.planned_prescription_snapshot_version, v_rec.sort_order, v_rec.planned_duration_seconds, v_rec.origin
            )
            returning id into v_clone_id;
          v_id_map := v_id_map || jsonb_build_object(v_rec.id::text, v_clone_id::text);
          v_progress := true;
        end loop;
        exit when not v_progress;
      end loop;

      -- Repoint the participant's own junction rows at the LEAF clones.
      for v_rec in select id, activity_component_id from training.activity_participant_components where activity_participant_id = p_participant_id loop
        update training.activity_participant_components
          set activity_component_id = (v_id_map ->> v_rec.activity_component_id::text)::uuid, activity_id = p_to_activity_id
          where id = v_rec.id;
      end loop;

      -- New confirmed segment links, driven by the EXACT captured tuples
      -- (never a re-derived query) — each pointing at its leaf's own clone.
      for v_item in select * from jsonb_array_elements(v_seg_carryover) loop
        insert into training.activity_component_metric_segment_links (activity_component_id, metric_event_segment_id, link_method, link_status, confirmed_by_user_id, confirmed_at, supersedes_link_id, reason, created_by_user_id)
          values ((v_id_map ->> (v_item ->> 'old_component_id'))::uuid, (v_item ->> 'segment_id')::uuid, 'automatic', 'confirmed', p_performed_by, now(), (v_item ->> 'old_link_id')::uuid, 'carried over by reparent clone strategy', p_performed_by)
          returning id into v_mapped_id;
        update training.activity_component_metric_segment_links set superseded_by_link_id = v_mapped_id where id = (v_item ->> 'old_link_id')::uuid;
      end loop;
    elsif p_component_strategy = 'map' then
      for v_rec in select id, activity_component_id from training.activity_participant_components where activity_participant_id = p_participant_id loop
        -- Round 4 fix: the service layer (trainingActivityMaterialize.js's
        -- reparentActivityParticipant) now validates component_mapping's
        -- shape (plain object, every key/value a real UUID string) BEFORE
        -- this function is ever called — this cast is a second, defensive
        -- line of DB-level protection for any future/raw caller that
        -- bypasses the service layer, so a malformed value here raises a
        -- clear, named exception instead of a bare, confusing Postgres
        -- 22P02 (invalid_text_representation).
        begin
          v_mapped_id := (p_component_mapping ->> v_rec.activity_component_id::text)::uuid;
        exception when invalid_text_representation then
          raise exception 'reparent_activity_participant: component_mapping entry for source component % is not a valid UUID', v_rec.activity_component_id;
        end;
        if v_mapped_id is null then
          raise exception 'reparent_activity_participant: component_mapping has no entry for source component %', v_rec.activity_component_id;
        end if;
        perform 1 from training.activity_components where id = v_mapped_id and activity_id = p_to_activity_id;
        if not found then
          raise exception 'reparent_activity_participant: mapped component % does not belong to target activity %', v_mapped_id, p_to_activity_id;
        end if;
        update training.activity_participant_components set activity_component_id = v_mapped_id, activity_id = p_to_activity_id where id = v_rec.id;
      end loop;
    else
      perform set_config('training.allow_component_repoint', 'off', true);
      raise exception 'reparent_activity_participant: unknown component_strategy %', p_component_strategy;
    end if;
    perform set_config('training.allow_component_repoint', 'off', true);
  end if;

  insert into training.activity_participant_reparent_log (activity_participant_id, from_activity_id, to_activity_id, component_strategy, reason, performed_by_user_id)
    values (p_participant_id, v_from_activity_id, p_to_activity_id, p_component_strategy, p_reason, p_performed_by);

  select count(*) into v_remaining from training.activity_participants where activity_id = v_from_activity_id and merge_status = 'canonical';
  if v_remaining = 0 then
    perform set_config('training.allow_supersede_write', 'on', true);
    update training.activities set lifecycle_state = 'superseded', superseded_by_activity_id = p_to_activity_id, updated_at = now()
      where id = v_from_activity_id;
    perform set_config('training.allow_supersede_write', 'off', true);
  end if;
end;
$$;

CREATE FUNCTION training.resolve_canonical_activity_id(p_activity_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE
    AS $$
declare
  v_current uuid := p_activity_id;
  v_next uuid;
  v_hops int := 0;
begin
  loop
    select superseded_by_activity_id into v_next from training.activities where id = v_current;
    exit when v_next is null;
    v_current := v_next;
    v_hops := v_hops + 1;
    if v_hops > 50 then
      raise exception 'resolve_canonical_activity_id: chain too long starting at % — possible cycle', p_activity_id;
    end if;
  end loop;
  return v_current;
end;
$$;

CREATE FUNCTION training.resolve_canonical_participant_id(p_participant_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE
    AS $$
declare
  v_current uuid := p_participant_id;
  v_next uuid;
  v_hops int := 0;
begin
  loop
    select superseded_by_participant_id into v_next from training.activity_participants where id = v_current;
    exit when v_next is null;
    v_current := v_next;
    v_hops := v_hops + 1;
    if v_hops > 50 then
      raise exception 'resolve_canonical_participant_id: chain too long starting at % — possible cycle', p_participant_id;
    end if;
  end loop;
  return v_current;
end;
$$;

CREATE FUNCTION training.roster_history_no_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception '%.% keeps history; TRUNCATE refused', tg_table_schema, tg_table_name;
end;
$$;

CREATE FUNCTION training.roster_on_activity_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_acts uuid[];
begin
  select array_agg(n.superseded_by_activity_id) into v_acts
    from old_rows o join new_rows n on n.id = o.id
   where n.superseded_by_activity_id is distinct from o.superseded_by_activity_id and n.superseded_by_activity_id is not null;
  if v_acts is not null then
    perform training.roster_record_change(v_acts, array_fill(null::uuid, array[cardinality(v_acts)]), 'activity_merged', null, null, false, 'activity_supersede');
  end if;
  v_acts := null;
  select array_agg(n.id) into v_acts
    from old_rows o join new_rows n on n.id = o.id
   where n.started_at is distinct from o.started_at
      or n.occurred_local_date is distinct from o.occurred_local_date
      or n.timezone_snapshot is distinct from o.timezone_snapshot;
  if v_acts is not null then
    perform training.roster_record_change(v_acts, array_fill(null::uuid, array[cardinality(v_acts)]), 'roster_changed', null, null, false, 'activity_time');
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.roster_on_decision_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  g record;
begin
  for g in
    select activity_id, request_id, decided_by_user_id, array_agg(athlete_id order by athlete_id) as athletes
      from new_rows
     group by activity_id, request_id, decided_by_user_id
     order by activity_id, request_id
  loop
    perform training.roster_record_change(
      array_fill(g.activity_id, array[cardinality(g.athletes)]), g.athletes, 'decision_changed',
      g.decided_by_user_id, g.request_id, true, 'decision');
  end loop;
  return null;
end;
$$;

CREATE FUNCTION training.roster_on_event_link_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_acts uuid[];
begin
  select array_agg(n.activity_id) into v_acts from new_rows n where n.link_status = 'confirmed';
  if v_acts is not null then
    perform training.roster_record_change(v_acts, array_fill(null::uuid, array[cardinality(v_acts)]), 'link_changed', null, null, false, 'event_link');
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.roster_on_event_link_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_acts uuid[];
begin
  select array_agg(n.activity_id) into v_acts
    from new_rows n join old_rows o on o.id = n.id
   where n.link_status is distinct from o.link_status and 'confirmed' in (n.link_status, o.link_status);
  if v_acts is not null then
    perform training.roster_record_change(v_acts, array_fill(null::uuid, array[cardinality(v_acts)]), 'link_changed', null, null, false, 'event_link');
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.roster_on_observation_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  g record;
begin
  for g in select kind, array_agg(activity_id) as acts, array_agg(athlete_id) as aths from new_rows group by kind order by kind loop
    perform training.roster_record_change(g.acts, g.aths, g.kind, null, null, false, 'observation_open');
  end loop;
  return null;
end;
$$;

CREATE FUNCTION training.roster_on_observation_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  g record;
begin
  for g in
    select n.kind, array_agg(n.activity_id) as acts, array_agg(n.athlete_id) as aths
      from new_rows n join old_rows o on o.id = n.id
     where n.resolved_at is distinct from o.resolved_at
     group by n.kind order by n.kind
  loop
    perform training.roster_record_change(g.acts, g.aths, g.kind, null, null, false, 'observation_resolve');
  end loop;
  return null;
end;
$$;

CREATE FUNCTION training.roster_on_occasion_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_acts uuid[];
  v_aths uuid[];
begin
  select array_agg(ap.activity_id), array_agg(ap.athlete_id) into v_acts, v_aths
    from (select distinct event_participant_id from new_rows) o
    join training.activity_participant_metric_participant_links l
      on l.metric_event_participant_id = o.event_participant_id and l.link_status = 'confirmed'
    join training.activity_participants ap on ap.id = l.activity_participant_id;
  if v_acts is not null then
    perform training.roster_record_change(v_acts, v_aths, 'measurement_changed', null, null, false, 'occasion_insert');
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.roster_on_occasion_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_acts uuid[];
  v_aths uuid[];
begin
  select array_agg(ap.activity_id), array_agg(ap.athlete_id) into v_acts, v_aths
    from (select distinct n.event_participant_id
            from new_rows n join old_rows o on o.id = n.id
           where n.import_conflict_status is distinct from o.import_conflict_status
              or n.superseded_by_occasion_id is distinct from o.superseded_by_occasion_id
              or n.event_participant_id is distinct from o.event_participant_id) ch
    join training.activity_participant_metric_participant_links l
      on l.metric_event_participant_id = ch.event_participant_id and l.link_status = 'confirmed'
    join training.activity_participants ap on ap.id = l.activity_participant_id;
  if v_acts is not null then
    perform training.roster_record_change(v_acts, v_aths, 'measurement_changed', null, null, false, 'occasion_update');
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.roster_on_participant_link_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_acts uuid[];
  v_aths uuid[];
begin
  select array_agg(ap.activity_id), array_agg(ap.athlete_id) into v_acts, v_aths
    from new_rows n join training.activity_participants ap on ap.id = n.activity_participant_id
   where n.link_status = 'confirmed';
  if v_acts is not null then
    perform training.roster_record_change(v_acts, v_aths, 'link_changed', null, null, false, 'participant_link');
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.roster_on_participant_link_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_acts uuid[];
  v_aths uuid[];
begin
  select array_agg(ap.activity_id), array_agg(ap.athlete_id) into v_acts, v_aths
    from new_rows n join old_rows o on o.id = n.id
    join training.activity_participants ap on ap.id = n.activity_participant_id
   where n.link_status is distinct from o.link_status and 'confirmed' in (n.link_status, o.link_status);
  if v_acts is not null then
    perform training.roster_record_change(v_acts, v_aths, 'link_changed', null, null, false, 'participant_link');
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.roster_on_participant_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_acts uuid[];
  v_aths uuid[];
begin
  select array_agg(x.activity_id), array_agg(x.athlete_id) into v_acts, v_aths
    from (select o.activity_id, o.athlete_id from old_rows o join new_rows n on n.id = o.id where n.activity_id is distinct from o.activity_id
          union all
          select n.activity_id, n.athlete_id from old_rows o join new_rows n on n.id = o.id where n.activity_id is distinct from o.activity_id) x;
  if v_acts is not null then
    perform training.roster_record_change(v_acts, v_aths, 'roster_changed', null, null, false, 'participant_reparent');
  end if;

  v_acts := null;
  v_aths := null;
  select array_agg(x.activity_id), array_agg(x.athlete_id) into v_acts, v_aths
    from (select n.activity_id, n.athlete_id
            from old_rows o join new_rows n on n.id = o.id
           where n.merge_status is distinct from o.merge_status
              or n.superseded_by_participant_id is distinct from o.superseded_by_participant_id
          union all
          select t.activity_id, t.athlete_id
            from old_rows o join new_rows n on n.id = o.id
            join training.activity_participants t on t.id = n.superseded_by_participant_id
           where n.superseded_by_participant_id is distinct from o.superseded_by_participant_id) x;
  if v_acts is not null then
    perform training.roster_record_change(v_acts, v_aths, 'activity_merged', null, null, false, 'participant_merge');
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.roster_on_period_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_team uuid;
  v_acts uuid[];
  v_aths uuid[];
begin
  if tg_op = 'INSERT' then
    for v_team in select distinct team_id from new_rows where membership_type = 'team' order by 1 loop
      perform training.lock_roster_team(v_team, false);
    end loop;
    select array_agg(s.activity_id), array_agg(n.athlete_id) into v_acts, v_aths
      from new_rows n
      cross join lateral training.roster_sessions_in_interval(n.team_id, n.valid_from, n.valid_to) s
     where n.membership_type = 'team';
  else
    for v_team in
      select distinct n.team_id from new_rows n join old_rows o on o.id = n.id
       where n.membership_type = 'team' and n.valid_to is distinct from o.valid_to order by 1
    loop
      perform training.lock_roster_team(v_team, false);
    end loop;
    select array_agg(s.activity_id), array_agg(n.athlete_id) into v_acts, v_aths
      from new_rows n join old_rows o on o.id = n.id
      cross join lateral training.roster_sessions_in_interval(n.team_id, n.valid_to, o.valid_to) s
     where n.membership_type = 'team' and n.valid_to is distinct from o.valid_to and n.valid_to is not null;
  end if;
  if v_acts is not null then
    perform training.roster_record_change(v_acts, v_aths, 'roster_changed', null, null, false, 'membership_period');
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.roster_on_source_identity_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_acts uuid[];
  v_aths uuid[];
begin
  select array_agg(ap.activity_id), array_agg(ap.athlete_id) into v_acts, v_aths
    from (select o.current_occasion_id as occasion_id
            from old_rows o join new_rows n on n.id = o.id
           where n.current_occasion_id is distinct from o.current_occasion_id
          union
          select n.current_occasion_id
            from old_rows o join new_rows n on n.id = o.id
           where n.current_occasion_id is distinct from o.current_occasion_id) ch
    join training_load.metric_measurement_occasions occ on occ.id = ch.occasion_id
    join training.activity_participant_metric_participant_links l
      on l.metric_event_participant_id = occ.event_participant_id and l.link_status = 'confirmed'
    join training.activity_participants ap on ap.id = l.activity_participant_id;
  if v_acts is not null then
    perform training.roster_record_change(v_acts, v_aths, 'measurement_changed', null, null, false, 'current_occasion');
  end if;
  return null;
end;
$$;

CREATE FUNCTION training.roster_record_change(p_activity_ids uuid[], p_athlete_ids uuid[], p_cause character varying, p_performed_by uuid, p_request_id uuid, p_decision boolean, p_source text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_ids uuid[];
  v_id uuid;
  v_team uuid;
  c record;
  v_status varchar;
  v_causes text[];
  v_detail jsonb;
begin
  if current_setting('optimove.roster_change_active', true) = 'on' then
    return;
  end if;
  select coalesce(array_agg(distinct a.id order by a.id), '{}')
    into v_ids
    from unnest(p_activity_ids) x
    join training.activities a on a.id = training.resolve_canonical_activity_id(x)
   where x is not null and a.owner_scope = 'team';
  if cardinality(v_ids) = 0 then
    return;
  end if;

  perform set_config('optimove.roster_change_active', 'on', true);
  perform training.lock_roster_completions(v_ids, false);
  foreach v_id in array v_ids loop
    select coalesce(jsonb_agg(distinct t.athlete_id order by t.athlete_id) filter (where t.athlete_id is not null), '[]'::jsonb)
      into v_detail
      from unnest(p_activity_ids, p_athlete_ids) as t(activity_id, athlete_id)
     where t.activity_id is not null and training.resolve_canonical_activity_id(t.activity_id) = v_id;
    v_detail := jsonb_build_object('athleteIds', v_detail, 'source', p_source);

    select * into c from training.activity_completions where activity_id = v_id for update;
    if not found then
      if p_decision then
        select owner_team_id into v_team from training.activities where id = v_id;
        insert into training.activity_completions (activity_id, owner_team_id, status, revision)
        values (v_id, v_team, 'not_complete', 1);
        insert into training.activity_completion_log (activity_id, request_id, revision, from_status, to_status, cause, performed_by_user_id, detail)
        values (v_id, p_request_id, 1, 'not_complete', 'not_complete', p_cause, p_performed_by, v_detail);
      end if;
      continue;
    end if;

    if c.status = 'complete' then
      v_status := 'needs_review';
      v_causes := array[p_cause]::text[];
    elsif c.status = 'needs_review' then
      v_status := 'needs_review';
      if p_cause = any(c.needs_review_causes) then
        if not p_decision then
          continue;
        end if;
        v_causes := c.needs_review_causes;
      else
        v_causes := c.needs_review_causes || p_cause::text;
      end if;
    else
      if not p_decision then
        continue;
      end if;
      v_status := 'not_complete';
      v_causes := '{}';
    end if;

    update training.activity_completions
       set status = v_status, revision = c.revision + 1, needs_review_causes = v_causes,
           completed_by_user_id = null, completed_by_basis = null, completed_at = null, input_fingerprint = null
     where activity_id = v_id;
    insert into training.activity_completion_log (activity_id, request_id, revision, from_status, to_status, cause, performed_by_user_id, detail)
    values (v_id, p_request_id, c.revision + 1, c.status, v_status, p_cause, p_performed_by,
            v_detail || case when c.status = 'complete'
                             then jsonb_build_object('completedByUserId', c.completed_by_user_id, 'completedAt', c.completed_at)
                             else '{}'::jsonb end);
  end loop;
  perform set_config('optimove.roster_change_active', '', true);
end;
$$;

CREATE FUNCTION training.roster_sessions_in_interval(p_team_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(activity_id uuid)
    LANGUAGE sql STABLE
    AS $$
  select a.id
    from training.activity_completions c
    join training.activities a on a.id = c.activity_id
   where c.owner_team_id = p_team_id and c.status in ('complete', 'needs_review')
     and a.owner_scope = 'team' and a.superseded_by_activity_id is null
     and case when a.started_at is not null
              then p_from <= a.started_at and a.started_at < coalesce(p_to, 'infinity')
              else p_from < ((a.occurred_local_date + 1)::timestamp at time zone a.timezone_snapshot)
                   and coalesce(p_to, 'infinity') > (a.occurred_local_date::timestamp at time zone a.timezone_snapshot)
         end;
$$;

CREATE FUNCTION training.validate_activity_timezone_and_interval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.timezone_snapshot is null or btrim(new.timezone_snapshot) = '' then
    raise exception 'training.activities: timezone_snapshot cannot be blank';
  end if;
  begin
    perform now() at time zone new.timezone_snapshot;
  exception when others then
    raise exception 'training.activities: "%" is not a timezone Postgres recognizes', new.timezone_snapshot;
  end;
  if new.started_at is not null and new.ended_at is not null and new.ended_at < new.started_at then
    raise exception 'training.activities (id=%): ended_at cannot be before started_at', coalesce(new.id::text, '(new)');
  end if;
  if new.started_at is not null
     and new.occurred_local_date is distinct from (new.started_at at time zone new.timezone_snapshot)::date then
    raise exception 'training.activities (id=%): occurred_local_date (%) does not match started_at (%) converted into timezone_snapshot (%)',
      coalesce(new.id::text, '(new)'), new.occurred_local_date, new.started_at, new.timezone_snapshot;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training.validate_participant_timezone() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.timezone_snapshot is null or btrim(new.timezone_snapshot) = '' then
    raise exception 'training.activity_participants: timezone_snapshot cannot be blank';
  end if;
  begin
    perform now() at time zone new.timezone_snapshot;
  exception when others then
    raise exception 'training.activity_participants: "%" is not a timezone Postgres recognizes', new.timezone_snapshot;
  end;
  return new;
end;
$$;

CREATE FUNCTION training_load.add_series(p_widget_id uuid, p_expected_widget_revision integer, p_series_order integer, p_metric_definition_id uuid DEFAULT NULL::uuid, p_built_in_series_key text DEFAULT NULL::text, p_template_metric_key_hints jsonb DEFAULT NULL::jsonb, p_axis character varying DEFAULT 'primary'::character varying, p_color text DEFAULT NULL::text, p_display_label text DEFAULT NULL::text, p_source_policy character varying DEFAULT 'all_with_conflicts'::character varying, p_source_connection_id uuid DEFAULT NULL::uuid, p_data_scope_level character varying DEFAULT 'session'::character varying, p_analytical_aggregation character varying DEFAULT 'sum'::character varying, p_aggregation_role_policy character varying DEFAULT 'standalone_and_source_rollup'::character varying, p_coverage_policy character varying DEFAULT 'complete_and_partial'::character varying, p_comparison_period character varying DEFAULT NULL::character varying, p_created_by_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(series_id uuid, widget_revision integer)
    LANGUAGE plpgsql
    AS $$
declare
  v_dashboard_id uuid;
  v_is_template boolean;
  v_current_widget_revision integer;
  v_series_id uuid;
  v_resolution_status varchar;
  v_hints jsonb;
  v_def_key text;
  v_def_value_type varchar;
  v_def_unit text;
  v_def_current_version_id uuid;
begin
  select w.dashboard_id into v_dashboard_id from training_load.dashboard_widgets w where w.id = p_widget_id;
  if not found then
    raise exception 'add_series: widget % not found', p_widget_id;
  end if;
  select d.is_template into v_is_template from training_load.dashboards d where d.id = v_dashboard_id for update;
  perform training_load.assert_dashboard_writable(v_dashboard_id);
  select w.revision into v_current_widget_revision from training_load.dashboard_widgets w where w.id = p_widget_id for update;
  if v_current_widget_revision <> p_expected_widget_revision then
    raise exception 'add_series: stale widget revision (expected %, widget is at %) — reload and retry', p_expected_widget_revision, v_current_widget_revision using errcode = '40001';
  end if;

  if p_metric_definition_id is not null then
    -- Deliberately TWO statements, never a single `for share of d` JOINed
    -- to metric_definition_versions on d.current_version_id — a real,
    -- empirically-confirmed PostgreSQL limitation: when this row is
    -- concurrently UPDATEd (createDefinitionVersion() changing
    -- current_version_id) while THIS statement is blocked on the FOR
    -- SHARE, EvalPlanQual correctly re-fetches the row's own fresh
    -- columns once unblocked, but does NOT reliably re-run the JOIN
    -- against the NEW current_version_id in the SAME statement — the row
    -- silently drops out and this raises a false "not found", even though
    -- the definition and its current version both genuinely exist. Locking
    -- ONLY the single table first (no join) makes EvalPlanQual's re-check
    -- reliable; the version lookup is then a plain, unlocked SELECT using
    -- the FRESH current_version_id already returned by the locked read.
    select d.key, d.current_version_id into v_def_key, v_def_current_version_id
      from training_load.metric_definitions d
      where d.id = p_metric_definition_id
      for share;
    if not found then
      raise exception 'add_series: metric_definition % not found', p_metric_definition_id;
    end if;
    select mdv.value_type, mdv.unit into v_def_value_type, v_def_unit
      from training_load.metric_definition_versions mdv
      where mdv.id = v_def_current_version_id;
    if not found then
      raise exception 'add_series: metric_definition % has no current version', p_metric_definition_id;
    end if;
    v_resolution_status := 'resolved';
    if v_is_template then
      v_hints := jsonb_build_array(jsonb_build_object('key', v_def_key, 'valueType', v_def_value_type, 'unit', v_def_unit, 'scopeLevel', coalesce(p_data_scope_level, 'session')));
    else
      v_hints := null;
    end if;
  elsif p_built_in_series_key is not null then
    v_resolution_status := 'resolved';
    v_hints := null;
  else
    v_resolution_status := 'unresolved';
    v_hints := p_template_metric_key_hints;
  end if;

  insert into training_load.dashboard_widget_series (
    widget_id, series_order, metric_definition_id, built_in_series_key, template_metric_key_hints,
    resolution_status, template_resolution_candidates,
    axis, color, display_label, source_policy, source_connection_id, data_scope_level, analytical_aggregation,
    aggregation_role_policy, coverage_policy, comparison_period, created_by_user_id
  ) values (
    p_widget_id, p_series_order, p_metric_definition_id, p_built_in_series_key, v_hints,
    v_resolution_status, null,
    coalesce(p_axis, 'primary'), p_color, p_display_label, coalesce(p_source_policy, 'all_with_conflicts'), p_source_connection_id,
    coalesce(p_data_scope_level, 'session'), coalesce(p_analytical_aggregation, 'sum'),
    coalesce(p_aggregation_role_policy, 'standalone_and_source_rollup'), coalesce(p_coverage_policy, 'complete_and_partial'),
    p_comparison_period, p_created_by_user_id
  ) returning id into v_series_id;
  return query select v_series_id, w.revision from training_load.dashboard_widgets w where w.id = p_widget_id;
end;
$$;

CREATE FUNCTION training_load.archive_dashboard(p_dashboard_id uuid, p_expected_revision integer) RETURNS TABLE(dashboard_id uuid, status character varying, revision integer)
    LANGUAGE plpgsql
    AS $$
declare
  v_current_revision integer;
begin
  select d.revision into v_current_revision from training_load.dashboards d where d.id = p_dashboard_id for update;
  if not found then
    raise exception 'archive_dashboard: dashboard % not found', p_dashboard_id;
  end if;
  if v_current_revision <> p_expected_revision then
    raise exception 'archive_dashboard: stale revision (expected %, dashboard is at %) — reload and retry', p_expected_revision, v_current_revision using errcode = '40001';
  end if;
  update training_load.dashboards set status = 'archived' where id = p_dashboard_id;
  return query select d.id, d.status, d.revision from training_load.dashboards d where d.id = p_dashboard_id;
end;
$$;

CREATE FUNCTION training_load.assert_active_platform_admin(p_user_id uuid, p_what text) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  perform 1
    from public.user_global_roles r
    join public.users u on u.id = r.user_id
   where r.user_id = p_user_id and r.role = 'platform_admin' and r.is_active = true and u.is_active = true
   for share of r;
  if not found then
    raise exception '%: user % is not an active platform admin', p_what, p_user_id
      using errcode = 'insufficient_privilege';
  end if;
end;
$$;

CREATE FUNCTION training_load.assert_dashboard_writable(p_dashboard_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_status varchar;
begin
  select status into v_status from training_load.dashboards where id = p_dashboard_id;
  if v_status = 'archived' then
    raise exception 'dashboard % is archived — read-only (query/clone/metadata/layout/widget/series writes are all refused)', p_dashboard_id using errcode = '40002';
  end if;
end;
$$;

CREATE FUNCTION training_load.bump_dashboard_revision(p_dashboard_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  update training_load.dashboards set revision = revision + 1, updated_at = now() where id = p_dashboard_id;
end;
$$;

CREATE FUNCTION training_load.bump_widget_revision(p_widget_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  update training_load.dashboard_widgets set revision = revision + 1, updated_at = now() where id = p_widget_id;
end;
$$;

CREATE FUNCTION training_load.check_metric_value_scope_capability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_segment_id uuid;
  v_event_scope_level varchar;
  v_scope_level varchar;
  v_allowed boolean;
  v_component_linked boolean;
begin
  -- Compatible lock, taken BEFORE reading capabilities below — the
  -- app-layer write paths already take this same `FOR KEY SHARE` lock
  -- earlier in their own transaction (see lockDefinitionsForKeyShare in
  -- trainingLoadMetricsMeasurements.js), but this trigger fires on
  -- EVERY insert into metric_values regardless of caller, so it is the
  -- one place that protects a future or raw write path that never went
  -- through that app-layer lock. `FOR KEY SHARE` conflicts with the
  -- `FOR UPDATE` setDefinitionScopeCapabilities takes on the same
  -- metric_definitions row (and only with that — it does not conflict
  -- with itself), so a capability removal and a value insert against
  -- the SAME definition always serialize through this one lock,
  -- regardless of which side got here first.
  perform 1 from training_load.metric_definitions where id = new.metric_definition_id for key share;

  select o.segment_id, e.scope_level into v_segment_id, v_event_scope_level
    from training_load.metric_measurement_occasions o
    join training_load.metric_event_participants p on p.id = o.event_participant_id
    join training_load.metric_events e on e.id = p.event_id
    where o.id = new.occasion_id;
  v_scope_level := case
    when v_event_scope_level = 'day' then 'day'
    when v_segment_id is not null then 'component'
    else 'session'
  end;

  -- Unconditional — a definition with ZERO declared capability rows is
  -- rejected exactly like one with the WRONG capability declared. This
  -- is deliberately the LAST strict line of defense regardless of
  -- caller: the application layer (trainingLoadMetricsCatalog.js /
  -- trainingLoadMetricsMeasurements.js) is expected to check this
  -- proactively and return a clean, actionable 409
  -- (`scopeCapabilitiesRequired`) before ever attempting the insert —
  -- see that layer's own comments — but this trigger must still catch
  -- anything that reaches metric_values by any other path.
  select exists (
    select 1 from training_load.metric_definition_scope_capabilities
    where metric_definition_id = new.metric_definition_id and scope_level = v_scope_level
  ) into v_allowed;
  if not v_allowed then
    raise exception 'metric_values: metric_definition % has no declared scope_capability for level ''%''', new.metric_definition_id, v_scope_level;
  end if;

  if v_scope_level = 'component' then
    select exists (
      select 1 from training.activity_component_metric_segment_links
      where metric_event_segment_id = v_segment_id and link_status = 'confirmed'
    ) into v_component_linked;
    if not v_component_linked then
      raise exception 'metric_values: a component-scope value requires its segment (%) to already have a CONFIRMED activity_component_metric_segment_links row', v_segment_id;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.clear_active_dashboard(p_user_id uuid, p_workspace_type character varying, p_scope_id uuid) RETURNS TABLE(cleared boolean)
    LANGUAGE plpgsql
    AS $$
declare
  v_dashboard_id uuid;
  v_deleted_id uuid;
begin
  select dashboard_id into v_dashboard_id from training_load.dashboard_active_selection
    where user_id = p_user_id and workspace_type = p_workspace_type and scope_id is not distinct from p_scope_id;
  if v_dashboard_id is not null then
    perform 1 from training_load.dashboards where id = v_dashboard_id for update;
  end if;
  delete from training_load.dashboard_active_selection
    where user_id = p_user_id and workspace_type = p_workspace_type and scope_id is not distinct from p_scope_id
    returning id into v_deleted_id;
  return query select (v_deleted_id is not null);
end;
$$;

CREATE FUNCTION training_load.club_variable_rows_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception '%: rows are never changed or removed', tg_table_name using errcode = '23514';
end;
$$;

CREATE TABLE training_load.dashboards (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    description text,
    owner_scope character varying(20) NOT NULL,
    owner_user_id uuid,
    owner_club_id uuid,
    owner_team_id uuid,
    data_workspace_type character varying(20),
    data_workspace_scope_id uuid,
    is_template boolean DEFAULT false NOT NULL,
    status character varying(20) DEFAULT 'active'::character varying NOT NULL,
    cloned_from_dashboard_id uuid,
    default_filter jsonb,
    revision integer DEFAULT 1 NOT NULL,
    created_by_user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dashboards_check CHECK (((((owner_scope)::text = 'system'::text) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'user'::text) AND (owner_user_id IS NOT NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'club'::text) AND (owner_club_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'team'::text) AND (owner_team_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL)))),
    CONSTRAINT dashboards_check1 CHECK ((((owner_scope)::text <> 'system'::text) OR (is_template = true))),
    CONSTRAINT dashboards_check2 CHECK (((((owner_scope)::text = 'system'::text) AND (data_workspace_type IS NULL) AND (data_workspace_scope_id IS NULL)) OR (((owner_scope)::text <> 'system'::text) AND (data_workspace_type IS NOT NULL) AND ((((data_workspace_type)::text = ANY ((ARRAY['club'::character varying, 'team'::character varying])::text[])) AND (data_workspace_scope_id IS NOT NULL)) OR (((data_workspace_type)::text = ANY ((ARRAY['platform'::character varying, 'private_coach'::character varying, 'athlete'::character varying])::text[])) AND (data_workspace_scope_id IS NULL)))))),
    CONSTRAINT dashboards_check3 CHECK ((((owner_scope)::text <> 'club'::text) OR (((data_workspace_type)::text = 'club'::text) AND (data_workspace_scope_id = owner_club_id)))),
    CONSTRAINT dashboards_check4 CHECK ((((owner_scope)::text <> 'team'::text) OR (((data_workspace_type)::text = 'team'::text) AND (data_workspace_scope_id = owner_team_id)))),
    CONSTRAINT dashboards_check5 CHECK (((cloned_from_dashboard_id IS NULL) OR (cloned_from_dashboard_id <> id))),
    CONSTRAINT dashboards_data_workspace_type_check CHECK (((data_workspace_type)::text = ANY ((ARRAY['platform'::character varying, 'private_coach'::character varying, 'club'::character varying, 'team'::character varying, 'athlete'::character varying])::text[]))),
    CONSTRAINT dashboards_description_check CHECK (((description IS NULL) OR (char_length(description) <= 2000))),
    CONSTRAINT dashboards_name_check CHECK (((char_length(name) >= 1) AND (char_length(name) <= 200))),
    CONSTRAINT dashboards_owner_scope_check CHECK (((owner_scope)::text = ANY ((ARRAY['system'::character varying, 'club'::character varying, 'team'::character varying, 'user'::character varying])::text[]))),
    CONSTRAINT dashboards_status_check CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'archived'::character varying])::text[])))
);

CREATE FUNCTION training_load.create_dashboard(p_name text, p_description text, p_owner_scope character varying, p_owner_user_id uuid, p_owner_club_id uuid, p_owner_team_id uuid, p_data_workspace_type character varying, p_data_workspace_scope_id uuid, p_is_template boolean, p_created_by_user_id uuid, p_default_filter jsonb DEFAULT NULL::jsonb) RETURNS SETOF training_load.dashboards
    LANGUAGE plpgsql
    AS $$
declare
  v_id uuid;
begin
  insert into training_load.dashboards (name, description, owner_scope, owner_user_id, owner_club_id, owner_team_id, data_workspace_type, data_workspace_scope_id, is_template, created_by_user_id, default_filter)
    values (p_name, p_description, p_owner_scope, p_owner_user_id, p_owner_club_id, p_owner_team_id, p_data_workspace_type, p_data_workspace_scope_id, coalesce(p_is_template, false), p_created_by_user_id, p_default_filter)
    returning id into v_id;
  return query select * from training_load.dashboards where id = v_id;
end;
$$;

CREATE FUNCTION training_load.create_widget(p_dashboard_id uuid, p_expected_dashboard_revision integer, p_widget_type text, p_title text, p_widget_order integer, p_x smallint, p_y smallint, p_width smallint, p_height smallint, p_mobile_order integer, p_group_by character varying DEFAULT 'day'::character varying, p_display_config jsonb DEFAULT '{"schemaVersion": 1}'::jsonb, p_local_filter_override jsonb DEFAULT NULL::jsonb) RETURNS TABLE(widget_id uuid, dashboard_revision integer)
    LANGUAGE plpgsql
    AS $$
declare
  v_current_revision integer;
  v_widget_id uuid;
begin
  select d.revision into v_current_revision from training_load.dashboards d where d.id = p_dashboard_id for update;
  if not found then
    raise exception 'create_widget: dashboard % not found', p_dashboard_id;
  end if;
  perform training_load.assert_dashboard_writable(p_dashboard_id);
  if v_current_revision <> p_expected_dashboard_revision then
    raise exception 'create_widget: stale dashboard revision (expected %, dashboard is at %) — reload and retry', p_expected_dashboard_revision, v_current_revision using errcode = '40001';
  end if;
  insert into training_load.dashboard_widgets (dashboard_id, widget_type, title, widget_order, x, y, width, height, mobile_order, group_by, display_config, local_filter_override)
    values (p_dashboard_id, p_widget_type, p_title, p_widget_order, p_x, p_y, p_width, p_height, p_mobile_order, coalesce(p_group_by, 'day'), coalesce(p_display_config, '{"schemaVersion": 1}'::jsonb), p_local_filter_override)
    returning id into v_widget_id;
  set constraints training_load.dashboard_widgets_check_no_overlap, training_load.dashboard_widgets_order_unique, training_load.dashboard_widgets_mobile_order_unique immediate;
  return query select v_widget_id, d.revision from training_load.dashboards d where d.id = p_dashboard_id;
end;
$$;

CREATE FUNCTION training_load.dashboard_active_selection_touch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_active_selection_validate_visibility() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_data_type varchar; v_data_scope uuid; v_status varchar;
begin
  perform 1 from training_load.dashboards where id = new.dashboard_id for update;
  select data_workspace_type, data_workspace_scope_id, status into v_data_type, v_data_scope, v_status
    from training_load.dashboards where id = new.dashboard_id;
  if v_status is distinct from 'active' then
    raise exception 'dashboard_active_selection: dashboard % is not active (status=%) and cannot be selected', new.dashboard_id, v_status;
  end if;
  if v_data_type is distinct from new.workspace_type or v_data_scope is distinct from new.scope_id then
    raise exception 'dashboard_active_selection: dashboard % (data workspace %/%) does not match the exact selection context %/% for user %', new.dashboard_id, v_data_type, v_data_scope, new.workspace_type, new.scope_id, new.user_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_deletion_log_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'training_load.dashboard_deletion_log is append-only (% refused)', tg_op;
end;
$$;

CREATE FUNCTION training_load.dashboard_widget_series_bump_widget_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform training_load.bump_widget_revision(coalesce(new.widget_id, old.widget_id));
  return coalesce(new, old);
end;
$$;

CREATE FUNCTION training_load.dashboard_widget_series_enforce_cap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_widget_type text;
  v_max_series smallint;
  v_count integer;
begin
  perform training_load.lock_widget_for_series_write(new.widget_id);
  select w.widget_type, t.max_series into v_widget_type, v_max_series
    from training_load.dashboard_widgets w join training_load.dashboard_widget_types t on t.key = w.widget_type
    where w.id = new.widget_id;
  if v_max_series is null then
    v_max_series := 20;
  end if;
  select count(*) into v_count from training_load.dashboard_widget_series where widget_id = new.widget_id;
  if v_count >= v_max_series then
    raise exception 'dashboard_widget_series: widget % (type %) already has % series, the max allowed is %', new.widget_id, v_widget_type, v_count, v_max_series;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widget_series_validate_aggregation_type_compat() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_value_type varchar;
begin
  if new.metric_definition_id is not null then
    perform 1 from training_load.metric_definitions where id = new.metric_definition_id for share;
    select mdv.value_type into v_value_type
      from training_load.metric_definitions md
      join training_load.metric_definition_versions mdv on mdv.id = md.current_version_id
      where md.id = new.metric_definition_id;
  elsif new.built_in_series_key is not null then
    perform 1 from training_load.dashboard_builtin_series where key = new.built_in_series_key for share;
    select value_type into v_value_type from training_load.dashboard_builtin_series where key = new.built_in_series_key;
  else
    return new;
  end if;
  if v_value_type in ('text', 'boolean') and new.analytical_aggregation not in ('last', 'none') then
    raise exception 'dashboard_widget_series: value_type % only supports analytical_aggregation last/none this phase (got %, widget %)', v_value_type, new.analytical_aggregation, new.widget_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widget_series_validate_axis_unit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_has_axis boolean;
  v_new_unit text;
  v_existing_unit text;
  v_conflict_id uuid;
begin
  perform training_load.lock_widget_for_series_write(new.widget_id);
  select t.has_shared_axis into v_has_axis
    from training_load.dashboard_widgets w join training_load.dashboard_widget_types t on t.key = w.widget_type
    where w.id = new.widget_id;
  if not v_has_axis then
    return new;
  end if;
  -- This trigger's read of the referenced metric_definition's/built-in's
  -- own unit must not depend on ANOTHER trigger having already locked it
  -- — every trigger that reads catalog/definition state here takes its
  -- OWN `FOR SHARE` lock as its first statement, independent of any other
  -- trigger's alphabetical firing order.
  if new.metric_definition_id is not null then
    perform 1 from training_load.metric_definitions where id = new.metric_definition_id for share;
    select mdv.unit into v_new_unit
      from training_load.metric_definitions md
      join training_load.metric_definition_versions mdv on mdv.id = md.current_version_id
      where md.id = new.metric_definition_id;
  elsif new.built_in_series_key is not null then
    perform 1 from training_load.dashboard_builtin_series where key = new.built_in_series_key for share;
    select unit into v_new_unit from training_load.dashboard_builtin_series where key = new.built_in_series_key;
  else
    return new;
  end if;

  select s.id, coalesce(
      (select mdv.unit from training_load.metric_definitions md join training_load.metric_definition_versions mdv on mdv.id = md.current_version_id where md.id = s.metric_definition_id),
      (select b.unit from training_load.dashboard_builtin_series b where b.key = s.built_in_series_key)
    )
    into v_conflict_id, v_existing_unit
    from training_load.dashboard_widget_series s
    where s.widget_id = new.widget_id and s.axis = new.axis and s.id <> new.id
      and (s.metric_definition_id is not null or s.built_in_series_key is not null)
      and coalesce(
        (select mdv.unit from training_load.metric_definitions md join training_load.metric_definition_versions mdv on mdv.id = md.current_version_id where md.id = s.metric_definition_id),
        (select b.unit from training_load.dashboard_builtin_series b where b.key = s.built_in_series_key)
      ) is distinct from v_new_unit
    limit 1;
  if v_conflict_id is not null then
    raise exception 'dashboard_widget_series: unit mismatch on widget % axis % — series % has unit %, this series has unit %', new.widget_id, new.axis, v_conflict_id, v_existing_unit, v_new_unit;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widget_series_validate_builtin_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_fixed varchar;
begin
  if new.built_in_series_key is null then
    return new;
  end if;
  select fixed_data_scope_level into v_fixed from training_load.dashboard_builtin_series where key = new.built_in_series_key for share;
  if new.data_scope_level <> v_fixed then
    raise exception 'dashboard_widget_series: built-in series % is always scope_level=% (got %)', new.built_in_series_key, v_fixed, new.data_scope_level;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widget_series_validate_comparison_period() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_supports boolean;
begin
  if new.comparison_period is null then
    return new;
  end if;
  select t.supports_comparison_period into v_supports
    from training_load.dashboard_widgets w join training_load.dashboard_widget_types t on t.key = w.widget_type
    where w.id = new.widget_id;
  if not v_supports then
    raise exception 'dashboard_widget_series: comparison_period is not supported by this widget''s type (widget %)', new.widget_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widget_series_validate_metric_active_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_state varchar;
begin
  if new.metric_definition_id is null then
    return new;
  end if;
  select state into v_state from training_load.metric_definitions where id = new.metric_definition_id for share;
  if v_state <> 'active' then
    raise exception 'dashboard_widget_series: metric_definition % is not active (state=%) — a series may only be newly bound to an ACTIVE metric (widget %)', new.metric_definition_id, v_state, new.widget_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widget_series_validate_metric_visibility() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_data_type varchar; v_data_scope uuid; v_dash_owner_scope varchar; v_dash_owner_user uuid;
  v_def_scope varchar; v_def_user uuid; v_def_club uuid; v_def_team uuid;
  v_team_club uuid;
begin
  if new.metric_definition_id is null then
    return new;
  end if;
  select d.data_workspace_type, d.data_workspace_scope_id, d.owner_scope, d.owner_user_id
    into v_data_type, v_data_scope, v_dash_owner_scope, v_dash_owner_user
    from training_load.dashboard_widgets w join training_load.dashboards d on d.id = w.dashboard_id
    where w.id = new.widget_id;
  -- FOR SHARE closes "series insert vs. a concurrent ownership/current_
  -- version change on this metric_definition" — a concurrent UPDATE
  -- (ownership or a legitimate current_version_id bump) holds an implicit
  -- row lock that conflicts with this share lock, so our visibility check
  -- below is guaranteed to run against either the fully-pre-update or
  -- fully-post-update row, never a value caught mid-flight.
  select owner_scope, owner_user_id, owner_club_id, owner_team_id
    into v_def_scope, v_def_user, v_def_club, v_def_team
    from training_load.metric_definitions where id = new.metric_definition_id for share;

  if v_def_scope = 'system' then
    return new;
  end if;
  -- The dashboard owner's OWN private catalog is always visible to their
  -- own dashboards, independent of which data workspace it is bound to
  -- (a coach's personal metrics travel with them across workspaces).
  if v_dash_owner_scope = 'user' and v_def_scope = 'user' and v_def_user = v_dash_owner_user then
    return new;
  end if;
  if v_def_scope = 'club' and v_data_type = 'club' and v_def_club = v_data_scope then
    return new;
  end if;
  if v_def_scope = 'team' and v_data_type = 'team' and v_def_team = v_data_scope then
    return new;
  end if;
  -- v55 (O7): a team's dashboards may use the variables of the team's own club. The team (active), then
  -- its club (active), each FOR SHARE, after the definition above: dashboard -> widget -> series, then
  -- definition -> team -> club. An archived team or club, or another club's variable, is refused by the
  -- same exception below as every other invisible definition.
  if v_def_scope = 'club' and v_data_type = 'team' then
    select t.club_id into v_team_club from public.teams t where t.id = v_data_scope and coalesce(t.is_active, true) for share;
    if found and v_team_club = v_def_club then
      perform 1 from public.clubs c where c.id = v_def_club and coalesce(c.is_active, true) for share;
      if found then
        return new;
      end if;
    end if;
  end if;
  raise exception 'dashboard_widget_series: metric_definition % (owner_scope=%/%/%/%) is not visible to this dashboard''s data workspace %/%',
    new.metric_definition_id, v_def_scope, v_def_club, v_def_team, v_def_user, v_data_type, v_data_scope;
end;
$$;

CREATE FUNCTION training_load.dashboard_widget_series_validate_resolution() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform training_load.lock_widget_for_series_write(new.widget_id);
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widget_series_validate_scope_capability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_has_any boolean;
  v_allowed boolean;
begin
  if new.metric_definition_id is null then
    return new;
  end if;
  perform 1 from training_load.metric_definitions where id = new.metric_definition_id for share;
  select exists (select 1 from training_load.metric_definition_scope_capabilities where metric_definition_id = new.metric_definition_id) into v_has_any;
  if not v_has_any then
    return new;
  end if;
  select exists (
    select 1 from training_load.metric_definition_scope_capabilities
    where metric_definition_id = new.metric_definition_id and scope_level = new.data_scope_level
  ) into v_allowed;
  if not v_allowed then
    raise exception 'dashboard_widget_series: metric_definition % has never been configured for scope_level=% (widget %)', new.metric_definition_id, new.data_scope_level, new.widget_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widget_series_validate_source_connection_active_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_state varchar;
begin
  if tg_op = 'UPDATE' and new.source_connection_id is not distinct from old.source_connection_id then
    return new;
  end if;
  if new.source_connection_id is null then
    return new;
  end if;
  select state into v_state from training_load.metric_source_connections where id = new.source_connection_id for share;
  if v_state <> 'active' then
    raise exception 'dashboard_widget_series: source_connection % is not active (state=%) — a series may only be newly bound to an ACTIVE source connection (widget %)', new.source_connection_id, v_state, new.widget_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widget_series_validate_source_connection_visibility() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_data_type varchar; v_data_scope uuid; v_dash_owner_scope varchar; v_dash_owner_user uuid;
  v_conn_scope varchar; v_conn_club uuid; v_conn_team uuid; v_conn_user uuid;
begin
  if new.source_connection_id is null then
    return new;
  end if;
  select d.data_workspace_type, d.data_workspace_scope_id, d.owner_scope, d.owner_user_id
    into v_data_type, v_data_scope, v_dash_owner_scope, v_dash_owner_user
    from training_load.dashboard_widgets w join training_load.dashboards d on d.id = w.dashboard_id
    where w.id = new.widget_id;
  select owner_scope, owner_club_id, owner_team_id, owner_user_id
    into v_conn_scope, v_conn_club, v_conn_team, v_conn_user
    from training_load.metric_source_connections where id = new.source_connection_id for share;
  if v_conn_scope = 'system' then
    return new;
  end if;
  -- A private coach's OWN import connection is always visible to their own
  -- dashboards, independent of which data workspace those dashboards are
  -- bound to. Another private coach's connection stays invisible
  -- (v_conn_user must equal the DASHBOARD's own owner_user_id, never
  -- merely compared against v_data_scope).
  if v_dash_owner_scope = 'user' and v_conn_scope = 'user' and v_conn_user = v_dash_owner_user then
    return new;
  end if;
  if v_conn_scope = 'club' and v_data_type = 'club' and v_conn_club = v_data_scope then
    return new;
  end if;
  if v_conn_scope = 'team' and v_data_type = 'team' and v_conn_team = v_data_scope then
    return new;
  end if;
  raise exception 'dashboard_widget_series: source_connection % (owner_scope=%/%/%/%) is not visible to this dashboard''s data workspace %/%',
    new.source_connection_id, v_conn_scope, v_conn_club, v_conn_team, v_conn_user, v_data_type, v_data_scope;
end;
$$;

CREATE FUNCTION training_load.dashboard_widgets_bump_parent_dashboard_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform training_load.bump_dashboard_revision(coalesce(new.dashboard_id, old.dashboard_id));
  return coalesce(new, old);
end;
$$;

CREATE FUNCTION training_load.dashboard_widgets_bump_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_layout_changed boolean;
  v_content_changed boolean;
begin
  v_layout_changed := (
    new.x is distinct from old.x or new.y is distinct from old.y
    or new.width is distinct from old.width or new.height is distinct from old.height
    or new.mobile_order is distinct from old.mobile_order
  );
  v_content_changed := (
    new.widget_type is distinct from old.widget_type
    or new.title is distinct from old.title
    or new.widget_order is distinct from old.widget_order
    or new.group_by is distinct from old.group_by
    or new.state is distinct from old.state
    or new.display_config is distinct from old.display_config
    or new.local_filter_override is distinct from old.local_filter_override
  );
  if v_layout_changed or v_content_changed then
    new.revision := old.revision + 1;
    new.updated_at := now();
  end if;
  -- Deadlock-safety note: calling bump_dashboard_revision from THIS
  -- before-row trigger does NOT, by itself, achieve dashboard-before-
  -- widget lock ordering for a raw ad-hoc UPDATE — Postgres already
  -- acquires THIS row's own lock before any before-row trigger body
  -- runs, so by the time this trigger tries to lock the dashboard, the
  -- WIDGET row is already locked — the reverse of dashboard-then-widget.
  -- This is still functionally correct (dashboard.revision DOES end up
  -- bumped) but is NOT proven deadlock-safe against a concurrent
  -- replace_dashboard_layout()/update_widget_layout() call, which lock
  -- dashboard-then-widget. Kept anyway as defense-in-depth correctness
  -- for any writer that bypasses the two sanctioned functions (v17) — the
  -- application layer must never rely on this trigger alone for a
  -- concurrent layout write.
  if v_layout_changed then
    perform training_load.bump_dashboard_revision(new.dashboard_id);
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widgets_check_no_overlap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_conflict record;
begin
  select a.id as a_id, b.id as b_id into v_conflict
    from training_load.dashboard_widgets a
    join training_load.dashboard_widgets b on b.dashboard_id = a.dashboard_id and b.id <> a.id
      and a.x < b.x + b.width and b.x < a.x + a.width
      and a.y < b.y + b.height and b.y < a.y + a.height
    where a.dashboard_id = new.dashboard_id
    limit 1;
  if v_conflict.a_id is not null then
    raise exception 'dashboard_widgets: final layout still has an overlap between widgets % and % on dashboard %', v_conflict.a_id, v_conflict.b_id, new.dashboard_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widgets_lock_dashboard_before_layout_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform 1 from training_load.dashboards where id = new.dashboard_id for update;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widgets_revalidate_series_on_type_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_max_series smallint;
  v_count integer;
  v_has_axis boolean;
  v_supports_comparison boolean;
  v_conflict record;
begin
  select max_series, has_shared_axis, supports_comparison_period into v_max_series, v_has_axis, v_supports_comparison
    from training_load.dashboard_widget_types where key = new.widget_type;
  if v_max_series is null then v_max_series := 20; end if;
  select count(*) into v_count from training_load.dashboard_widget_series where widget_id = new.id;
  if v_count > v_max_series then
    raise exception 'dashboard_widgets: cannot change widget % to type % — it already has % series, that type allows at most %', new.id, new.widget_type, v_count, v_max_series;
  end if;
  if not v_supports_comparison then
    if exists (select 1 from training_load.dashboard_widget_series where widget_id = new.id and comparison_period is not null) then
      raise exception 'dashboard_widgets: cannot change widget % to type % — an existing series still has a comparison_period set, only KPI supports it', new.id, new.widget_type;
    end if;
  end if;
  if v_has_axis then
    for v_conflict in
      select axis, count(distinct coalesce(
        (select mdv.unit from training_load.metric_definitions md join training_load.metric_definition_versions mdv on mdv.id = md.current_version_id where md.id = s.metric_definition_id),
        (select b.unit from training_load.dashboard_builtin_series b where b.key = s.built_in_series_key)
      )) as distinct_units
      from training_load.dashboard_widget_series s
      where s.widget_id = new.id and (s.metric_definition_id is not null or s.built_in_series_key is not null)
      group by axis having count(distinct coalesce(
        (select mdv.unit from training_load.metric_definitions md join training_load.metric_definition_versions mdv on mdv.id = md.current_version_id where md.id = s.metric_definition_id),
        (select b.unit from training_load.dashboard_builtin_series b where b.key = s.built_in_series_key)
      )) > 1
    loop
      raise exception 'dashboard_widgets: cannot change widget % to type % — axis % already mixes incompatible units among its existing series', new.id, new.widget_type, v_conflict.axis;
    end loop;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboard_widgets_validate_layout() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_min_w smallint; v_max_w smallint; v_min_h smallint; v_max_h smallint; v_active boolean;
  v_check_active boolean;
begin
  select min_width, max_width, min_height, max_height, is_active
    into v_min_w, v_max_w, v_min_h, v_max_h, v_active
    from training_load.dashboard_widget_types where key = new.widget_type for share;
  if not found then
    raise exception 'dashboard_widgets: unknown widget_type %', new.widget_type;
  end if;
  v_check_active := (tg_op = 'INSERT') or (tg_op = 'UPDATE' and new.widget_type is distinct from old.widget_type);
  if v_check_active and not v_active then
    raise exception 'dashboard_widgets: widget_type % is not active — cannot add/switch to this type', new.widget_type;
  end if;
  if new.width < v_min_w or new.width > v_max_w then
    raise exception 'dashboard_widgets: width % out of bounds [%, %] for widget_type %', new.width, v_min_w, v_max_w, new.widget_type;
  end if;
  if new.height < v_min_h or new.height > v_max_h then
    raise exception 'dashboard_widgets: height % out of bounds [%, %] for widget_type %', new.height, v_min_h, v_max_h, new.widget_type;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboards_archive_clears_active_selection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.status = 'archived' and old.status is distinct from 'archived' then
    delete from training_load.dashboard_active_selection where dashboard_id = new.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboards_bump_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.name is distinct from old.name
     or new.description is distinct from old.description
     or new.is_template is distinct from old.is_template
     or new.status is distinct from old.status
     or new.default_filter is distinct from old.default_filter then
    new.revision := old.revision + 1;
    new.updated_at := now();
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboards_protect_identity_once_created() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.created_by_user_id is distinct from old.created_by_user_id then
    raise exception 'training_load.dashboards (id=%): created_by_user_id is immutable', old.id;
  end if;
  if new.cloned_from_dashboard_id is distinct from old.cloned_from_dashboard_id then
    raise exception 'training_load.dashboards (id=%): cloned_from_dashboard_id is immutable after creation', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.dashboards_validate_clone_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_current uuid;
  v_is_template boolean;
  v_depth integer := 0;
begin
  if new.cloned_from_dashboard_id is null then
    return new;
  end if;
  perform 1 from training_load.dashboards where id = new.cloned_from_dashboard_id for share;
  select is_template into v_is_template from training_load.dashboards where id = new.cloned_from_dashboard_id;
  if not found then
    raise exception 'training_load.dashboards: cloned_from_dashboard_id % does not exist', new.cloned_from_dashboard_id;
  end if;
  if not v_is_template then
    raise exception 'training_load.dashboards: cloned_from_dashboard_id % is not a template (is_template=false) — cloned_from_dashboard_id must reference a valid template', new.cloned_from_dashboard_id;
  end if;
  -- Bounded walk up the clone-provenance chain. A real template in this
  -- model is always hand-authored with cloned_from_dashboard_id NULL, so
  -- in practice this loop terminates in one hop — but it walks for real,
  -- defensively, rather than trusting that convention alone, and is
  -- bounded at 50 hops so a corrupt chain can never hang the insert.
  v_current := new.cloned_from_dashboard_id;
  while v_current is not null and v_depth < 50 loop
    if v_current = new.id then
      raise exception 'training_load.dashboards (id=%): clone provenance cycle detected via %', new.id, new.cloned_from_dashboard_id;
    end if;
    select cloned_from_dashboard_id into v_current from training_load.dashboards where id = v_current;
    v_depth := v_depth + 1;
  end loop;
  if v_depth >= 50 then
    raise exception 'training_load.dashboards: clone provenance chain too deep (possible cycle) starting at %', new.cloned_from_dashboard_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.delete_dashboard(p_dashboard_id uuid, p_expected_revision integer, p_deleted_by_user_id uuid, p_authorized_via character varying) RETURNS TABLE(out_dashboard_id uuid, out_log_id uuid)
    LANGUAGE plpgsql
    AS $$
declare
  -- %rowtype is resolved at call time: renaming/dropping one of the
  -- dashboards columns read below breaks this function on its next call,
  -- not when that later migration is applied (db-reviewer) - grep for
  -- dashboards%rowtype before changing those columns.
  v_row training_load.dashboards%rowtype;
  v_widget_count integer;
  v_series_count integer;
  v_log_id uuid;
begin
  select * into v_row from training_load.dashboards where id = p_dashboard_id for update;
  if not found then
    -- P0002 (no_data_found), not a bare P0001: the route maps a bare
    -- P0001 to 400 invalidRequest, but a dashboard deleted by a concurrent
    -- request while this one waited on the row lock must read as 404, the
    -- same as any other dashboard that no longer exists.
    raise exception 'delete_dashboard: dashboard % not found', p_dashboard_id using errcode = 'P0002';
  end if;
  if v_row.revision <> p_expected_revision then
    raise exception 'delete_dashboard: stale revision (expected %, dashboard is at %) — reload and retry', p_expected_revision, v_row.revision using errcode = '40001';
  end if;
  -- Read under the dashboard lock: every widget/series write locks the
  -- dashboard row first (ADR-003), so these counts cannot move before the
  -- delete below.
  select count(*) into v_widget_count from training_load.dashboard_widgets w where w.dashboard_id = p_dashboard_id;
  select count(*) into v_series_count from training_load.dashboard_widget_series s
    join training_load.dashboard_widgets w on w.id = s.widget_id where w.dashboard_id = p_dashboard_id;
  -- Logged BEFORE the delete, in the same transaction: if the delete
  -- below fails (e.g. 23503, a clone still references this dashboard) the
  -- log row rolls back with it.
  insert into training_load.dashboard_deletion_log (
    deleted_by_user_id, authorized_via, dashboard_id, dashboard_name, owner_scope,
    owner_user_id, owner_club_id, owner_team_id, data_workspace_type, data_workspace_scope_id,
    is_template, status, revision, widget_count, series_count,
    dashboard_created_by_user_id, dashboard_created_at
  ) values (
    p_deleted_by_user_id, p_authorized_via, v_row.id, v_row.name, v_row.owner_scope,
    v_row.owner_user_id, v_row.owner_club_id, v_row.owner_team_id, v_row.data_workspace_type, v_row.data_workspace_scope_id,
    v_row.is_template, v_row.status, v_row.revision, v_widget_count, v_series_count,
    v_row.created_by_user_id, v_row.created_at
  ) returning id into v_log_id;
  delete from training_load.dashboard_active_selection where dashboard_id = p_dashboard_id;
  -- The cascade fires v16's after-delete triggers on each widget/series,
  -- which call bump_dashboard_revision()/bump the parent widget. Their
  -- UPDATE targets a row this same transaction just deleted, so it simply
  -- matches 0 rows - no error, no cross-transaction conflict (db-reviewer).
  delete from training_load.dashboards where id = p_dashboard_id;
  return query select p_dashboard_id, v_log_id;
end;
$$;

CREATE FUNCTION training_load.delete_series(p_series_id uuid, p_widget_id uuid, p_expected_widget_revision integer) RETURNS TABLE(widget_revision integer)
    LANGUAGE plpgsql
    AS $$
declare
  v_dashboard_id uuid;
  v_current_widget_revision integer;
  v_deleted uuid;
begin
  select w.dashboard_id into v_dashboard_id from training_load.dashboard_widgets w where w.id = p_widget_id;
  if not found then
    raise exception 'delete_series: widget % not found', p_widget_id;
  end if;
  perform 1 from training_load.dashboards d where d.id = v_dashboard_id for update;
  perform training_load.assert_dashboard_writable(v_dashboard_id);
  select w.revision into v_current_widget_revision from training_load.dashboard_widgets w where w.id = p_widget_id for update;
  if v_current_widget_revision <> p_expected_widget_revision then
    raise exception 'delete_series: stale widget revision (expected %, widget is at %) — reload and retry', p_expected_widget_revision, v_current_widget_revision using errcode = '40001';
  end if;
  delete from training_load.dashboard_widget_series where id = p_series_id and widget_id = p_widget_id returning id into v_deleted;
  if v_deleted is null then
    raise exception 'delete_series: series % not found under widget %', p_series_id, p_widget_id;
  end if;
  return query select w.revision from training_load.dashboard_widgets w where w.id = p_widget_id;
end;
$$;

CREATE FUNCTION training_load.delete_widget(p_widget_id uuid, p_expected_widget_revision integer) RETURNS TABLE(dashboard_id uuid, dashboard_revision integer)
    LANGUAGE plpgsql
    AS $$
declare
  v_dashboard_id uuid;
  v_current_widget_revision integer;
begin
  select w.dashboard_id into v_dashboard_id from training_load.dashboard_widgets w where w.id = p_widget_id;
  if not found then
    raise exception 'delete_widget: widget % not found', p_widget_id;
  end if;
  perform 1 from training_load.dashboards d where d.id = v_dashboard_id for update;
  perform training_load.assert_dashboard_writable(v_dashboard_id);
  select w.revision into v_current_widget_revision from training_load.dashboard_widgets w where w.id = p_widget_id for update;
  if not found then
    raise exception 'delete_widget: widget % disappeared concurrently', p_widget_id;
  end if;
  if v_current_widget_revision <> p_expected_widget_revision then
    raise exception 'delete_widget: stale widget revision (expected %, widget is at %) — reload and retry', p_expected_widget_revision, v_current_widget_revision using errcode = '40001';
  end if;
  delete from training_load.dashboard_widgets where id = p_widget_id;
  return query select v_dashboard_id, d.revision from training_load.dashboards d where d.id = v_dashboard_id;
end;
$$;

CREATE FUNCTION training_load.enforce_gpexe_event_uniqueness() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  system text;
begin
  -- A bound event's own identity is frozen. The binding is immutable and
  -- records WHICH GPEXE session produced these values; if the event could be
  -- moved to another external id — even a free one — the two would stop
  -- agreeing with nothing left to detect it. Checked before anything else,
  -- because clearing source_external_id or source_connection_id would
  -- otherwise fall through the early return below. It reads only the binding
  -- row and takes no lock of its own, leaving the connection -> identity ->
  -- event order as it was.
  --
  -- Why a plain read is enough against a concurrent binding insert: every
  -- such insert goes through validate_event_source_binding(), which locks
  -- THIS event row "for update" first, and an UPDATE of the same row blocks
  -- on that lock and re-runs its BEFORE triggers against the committed row.
  -- The shared row is what serializes the two, not the read. Do not remove
  -- that "for update" without re-examining this guard.
  if TG_OP = 'UPDATE'
     and (new.source_connection_id is distinct from old.source_connection_id
          or new.source_external_id is distinct from old.source_external_id)
     and exists (select 1 from training_load.metric_event_source_bindings b where b.event_id = old.id) then
    raise exception 'metric_events (id=%): source identity is immutable once the event is bound to a source session (recorded as %/%)',
      old.id, old.source_connection_id, old.source_external_id
      using errcode = 'integrity_constraint_violation';
  end if;
  if new.source_connection_id is null or new.source_external_id is null then
    return new;
  end if;
  select source_system into system from training_load.metric_source_connections
    where id = new.source_connection_id for update;
  if system is distinct from 'gpexe' then
    return new;
  end if;
  if exists (
    select 1 from training_load.metric_events
    where source_connection_id = new.source_connection_id
      and source_external_id = new.source_external_id
      and id is distinct from new.id
  ) then
    raise exception 'metric_events: connection % already has an event for gpexe source_external_id %',
      new.source_connection_id, new.source_external_id
      using errcode = 'unique_violation';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.forbid_event_source_binding_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'metric_event_source_bindings rows are immutable and cannot be deleted (event_id=%)', old.event_id;
end;
$$;

CREATE FUNCTION training_load.forbid_event_source_binding_delete_unless_session_undo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if training_load.session_undo_marker_ok() then
    return old;
  end if;
  raise exception 'metric_event_source_bindings rows are immutable and cannot be deleted (event_id=%)', old.event_id;
end;
$$;

CREATE FUNCTION training_load.forbid_event_source_binding_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'metric_event_source_bindings rows are immutable (event_id=%)', old.event_id;
end;
$$;

CREATE FUNCTION training_load.forbid_update_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'immutable row: % on %.% (id=%) is not permitted', tg_op, tg_table_schema, tg_table_name, coalesce(old.id::text, 'n/a');
end;
$$;

CREATE FUNCTION training_load.forbid_update_delete_unless_session_undo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' and training_load.session_undo_marker_ok() then
    return old;
  end if;
  raise exception 'immutable row: % on %.% (id=%) is not permitted', tg_op, tg_table_schema, tg_table_name, coalesce(old.id::text, 'n/a');
end;
$$;

CREATE FUNCTION training_load.freeze_gpexe_check_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.source_path is distinct from old.source_path
     or new.source_connection_id is distinct from old.source_connection_id
     or new.source_binding_id is distinct from old.source_binding_id
     or new.source_team_id is distinct from old.source_team_id
     or new.source_host_key is distinct from old.source_host_key then
    raise exception 'gpexe_import_checks: the credential path of check % is final', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.freeze_gpexe_check_team() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- Which team ran the check is part of what the row says: moving it would
  -- give another team a run it never made, and take a blocker off this one.
  if new.owner_team_id is distinct from old.owner_team_id then
    raise exception 'gpexe_import_checks: the OptiMove team of check % is final', old.id;
  end if;
  if new.gpexe_team_id is distinct from old.gpexe_team_id then
    raise exception 'gpexe_import_checks: the GPEXE team of check % is final (an empty one from before v24 stays empty)', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.generate_external_schedule_occurrence(p_schedule_id uuid, p_scheduled_date date) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
declare
  v_schedule training_load.external_schedules%rowtype;
  v_occurrence_id uuid;
begin
  select * into v_schedule from training_load.external_schedules where id = p_schedule_id for share;
  if v_schedule.id is null then
    raise exception 'external schedule % does not exist', p_schedule_id;
  end if;
  if v_schedule.status <> 'active' then
    raise exception 'cannot generate an occurrence for schedule % - status is %, not active', p_schedule_id, v_schedule.status;
  end if;

  if v_schedule.schedule_kind = 'dates' then
    if not exists (select 1 from training_load.external_schedule_dates d where d.schedule_id = p_schedule_id and d.scheduled_date = p_scheduled_date) then
      raise exception 'scheduled_date % is not one of schedule %''s own picked dates', p_scheduled_date, p_schedule_id;
    end if;
  elsif p_scheduled_date < v_schedule.start_date or (v_schedule.end_date is not null and p_scheduled_date > v_schedule.end_date) then
    raise exception 'scheduled_date % is outside schedule %''s start_date/end_date window', p_scheduled_date, p_schedule_id;
  end if;

  insert into training_load.external_schedule_occurrences (schedule_id, scheduled_date, opens_at, due_at, closes_at)
  values (
    p_schedule_id, p_scheduled_date,
    (p_scheduled_date + v_schedule.opens_time) at time zone v_schedule.timezone,
    case when v_schedule.due_time is null then null else (p_scheduled_date + v_schedule.due_time) at time zone v_schedule.timezone end,
    (p_scheduled_date + v_schedule.closes_time) at time zone v_schedule.timezone
  )
  on conflict (schedule_id, scheduled_date) do nothing
  returning id into v_occurrence_id;

  if v_occurrence_id is null then
    select id into v_occurrence_id from training_load.external_schedule_occurrences
    where schedule_id = p_schedule_id and scheduled_date = p_scheduled_date;
  end if;
  return v_occurrence_id;
end $$;

CREATE FUNCTION training_load.gpexe_athlete_identities_drop_for_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.state = 'active' and new.state <> 'active' then
    delete from training_load.gpexe_athlete_identities where binding_id = new.id;
    delete from training_load.gpexe_athlete_identity_suppressions where binding_id = new.id;
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.gpexe_athlete_identities_drop_for_club() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if coalesce(new.is_active, true) = false then
    delete from training_load.gpexe_athlete_identities i
     using public.teams t
     where t.id = i.owner_team_id and t.club_id = new.id;
    delete from training_load.gpexe_athlete_identity_suppressions s
     using public.teams t
     where t.id = s.owner_team_id and t.club_id = new.id;
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.gpexe_athlete_identities_drop_for_team() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if coalesce(new.is_active, true) = false then
    delete from training_load.gpexe_athlete_identities where owner_team_id = new.id;
    delete from training_load.gpexe_athlete_identity_suppressions where owner_team_id = new.id;
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.gpexe_athlete_identity_check() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  b record;
  team_row record;
  club_active boolean;
  conn_club uuid;
begin
  select id, team_id, connection_id, source_system, source_team_id, state
    into b from training_load.source_team_bindings where id = new.binding_id for share;
  if not found or b.state <> 'active' or b.source_system <> 'gpexe' then
    raise exception 'gpexe_athlete_identities: binding % is not an active gpexe binding', new.binding_id
      using errcode = 'check_violation', constraint = 'gpexe_athlete_identities_active_binding';
  end if;
  if b.team_id is distinct from new.owner_team_id or b.connection_id is distinct from new.connection_id or b.source_team_id is distinct from new.source_team_id then
    raise exception 'gpexe_athlete_identities: the row does not name its binding''s team, connection and source team'
      using errcode = 'check_violation', constraint = 'gpexe_athlete_identities_active_binding';
  end if;
  select id, club_id, coalesce(is_active, true) as active into team_row from public.teams where id = new.owner_team_id for share;
  if not found or team_row.active is not true then
    raise exception 'gpexe_athlete_identities: team % is not active', new.owner_team_id
      using errcode = 'check_violation', constraint = 'gpexe_athlete_identities_active_team';
  end if;
  select coalesce(is_active, true) into club_active from public.clubs where id = team_row.club_id for share;
  select owner_club_id into conn_club from training_load.source_credential_connections where id = new.connection_id;
  if club_active is not true or conn_club is distinct from team_row.club_id then
    raise exception 'gpexe_athlete_identities: the team''s club is not active or does not own the connection'
      using errcode = 'check_violation', constraint = 'gpexe_athlete_identities_active_team';
  end if;
  -- observed_at is when the answer arrived: never in the future, and never
  -- older than the longest load (the application's whole action is bounded
  -- well below this).
  if new.observed_at > clock_timestamp() + interval '1 minute' or new.observed_at < clock_timestamp() - interval '10 minutes' then
    raise exception 'gpexe_athlete_identities: observed_at is not the reading time'
      using errcode = 'check_violation', constraint = 'gpexe_athlete_identities_observed_at';
  end if;
  if new.birth_date is not null and new.birth_date > (clock_timestamp() at time zone 'UTC')::date + 1 then
    raise exception 'gpexe_athlete_identities: a date of birth in the future'
      using errcode = 'check_violation', constraint = 'gpexe_athlete_identities_birth_date';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.gpexe_athlete_identity_no_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'gpexe_athlete_identities: a row is never changed or extended; delete it and read again'
    using errcode = 'check_violation', constraint = 'gpexe_athlete_identities_no_update';
end;
$$;

CREATE FUNCTION training_load.gpexe_athlete_identity_request_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  b record;
begin
  if tg_op = 'INSERT' then
    select team_id, state, source_system into b from training_load.source_team_bindings where id = new.binding_id for share;
    if not found or b.state <> 'active' or b.source_system <> 'gpexe' or b.team_id is distinct from new.owner_team_id then
      raise exception 'gpexe_athlete_identity_requests: binding % is not an active gpexe binding of team %', new.binding_id, new.owner_team_id
        using errcode = 'check_violation', constraint = 'gpexe_athlete_identity_requests_active_binding';
    end if;
    return new;
  end if;
  if old.status <> 'running' then
    raise exception 'gpexe_athlete_identity_requests: request % is finished and final', old.id
      using errcode = 'check_violation', constraint = 'gpexe_athlete_identity_requests_final';
  end if;
  if new.id is distinct from old.id or new.owner_team_id is distinct from old.owner_team_id or new.binding_id is distinct from old.binding_id
     or new.requested_by_user_id is distinct from old.requested_by_user_id or new.request_key is distinct from old.request_key
     or new.started_at is distinct from old.started_at or new.targets is distinct from old.targets or new.status = 'running' then
    raise exception 'gpexe_athlete_identity_requests: only finishing request % is allowed', old.id
      using errcode = 'check_violation', constraint = 'gpexe_athlete_identity_requests_final';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.gpexe_athlete_identity_suppression_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  b record;
  team_active boolean;
begin
  if tg_op = 'UPDATE' then
    raise exception 'gpexe_athlete_identity_suppressions: a row is never changed or extended; delete it and record a new 404'
      using errcode = 'check_violation', constraint = 'gpexe_athlete_identity_suppressions_no_update';
  end if;
  select team_id, state, source_system into b from training_load.source_team_bindings where id = new.binding_id for share;
  if not found or b.state <> 'active' or b.source_system <> 'gpexe' or b.team_id is distinct from new.owner_team_id then
    raise exception 'gpexe_athlete_identity_suppressions: binding % is not an active gpexe binding of team %', new.binding_id, new.owner_team_id
      using errcode = 'check_violation', constraint = 'gpexe_athlete_identities_active_binding';
  end if;
  select coalesce(t.is_active, true) and coalesce(c.is_active, true) into team_active
    from public.teams t join public.clubs c on c.id = t.club_id where t.id = new.owner_team_id for share of t, c;
  if team_active is not true then
    raise exception 'gpexe_athlete_identity_suppressions: team % or its club is not active', new.owner_team_id
      using errcode = 'check_violation', constraint = 'gpexe_athlete_identities_active_team';
  end if;
  if new.observed_at > clock_timestamp() + interval '1 minute' or new.observed_at < clock_timestamp() - interval '10 minutes' then
    raise exception 'gpexe_athlete_identity_suppressions: observed_at is not the reading time'
      using errcode = 'check_violation', constraint = 'gpexe_athlete_identity_suppressions_observed_at';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.gpexe_check_status_final() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.status = 'running' then
    if new.status not in ('running', 'succeeded', 'failed') then
      raise exception 'gpexe_import_checks: check % may only move from running to succeeded or failed', old.id using errcode = '23514';
    end if;
    return new;
  end if;
  if new.status is distinct from old.status or new.finished_at is distinct from old.finished_at then
    raise exception 'gpexe_import_checks: check % has finished (%); its status and finished_at are final', old.id, old.status using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.gpexe_history_no_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception '%.% keeps history; TRUNCATE refused', tg_table_schema, tg_table_name;
end;
$$;

CREATE FUNCTION training_load.gpexe_import_check_observation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  k record;
begin
  if tg_op = 'UPDATE' then
    raise exception 'gpexe_import_check_observations: an observation is never changed' using errcode = '23514';
  end if;
  -- FOR SHARE: an insert waits for a finalization or an abandon sweep that
  -- holds the check row, and then sees the status it committed.
  select status, owner_team_id into k from training_load.gpexe_import_checks where id = new.check_id for share;
  if not found or k.status <> 'running' then
    raise exception 'gpexe_import_check_observations: check % is not running; an observation belongs to a running check', new.check_id using errcode = '23514';
  end if;
  if k.owner_team_id is distinct from new.owner_team_id then
    raise exception 'gpexe_import_check_observations: check % belongs to another team', new.check_id using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.gpexe_team_id_canonical(raw text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
    select case when raw ~ '^[0-9]{1,12}$' then regexp_replace(raw, '^0+([0-9])', '\1') else raw end
  $_$;

