CREATE FUNCTION training_load.jsonb_names_a_secret(doc jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    select exists (
      select 1 from jsonb_each(case when jsonb_typeof(doc) = 'object' then doc else '{}'::jsonb end) as e(k, v)
       where training_load.key_name_is_secret(k)
          -- a flat object only: nothing may hide a secret one level down
          or jsonb_typeof(v) in ('object', 'array')
    )
  $$;

CREATE FUNCTION training_load.key_name_is_secret(k text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
    with n as (select training_load.normalize_key_name(k) as name)
    select name not in ('host_key', 'credential_kind')
       and (
         name = any (array['token', 'access_token', 'refresh_token', 'id_token', 'password', 'passwd', 'pass', 'pwd', 'secret', 'auth',
                            'authorization', 'cookie', 'set_cookie', 'jwt', 'bearer', 'session', 'credential', 'credentials',
                            'ciphertext', 'nonce', 'auth_tag', 'key', 'keys', 'api_key', 'apikey', 'private', 'username', 'user', 'login', 'email',
                            'accesstoken', 'authtoken', 'refreshtoken', 'apitoken', 'idtoken', 'sessionid', 'sessionkey', 'passcode', 'passphrase', 'xauth', 'privatekey', 'secretkey', 'signingkey'])
         or name ~ '(^|_)(key|keys|token|tokens|secret|secrets|auth|password|passwd|pwd|nonce|jwt|bearer|session|cookie|cookies|credential|credentials|apikey|api_key|private_key|private)(_|$)'
         or name ~ '(passw|passcode|passphrase|credential|authoriz|cookie|jwt|bearer|session|ciphertext|api_key|apikey|token)'
       )
      from n
  $_$;

CREATE FUNCTION training_load.link_scope_within_target(link_scope character varying, link_club uuid, link_team uuid, link_user uuid, target_scope character varying, target_club uuid, target_team uuid, target_user uuid) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
begin
  if link_scope = 'user' then return true; end if;
  if target_scope = 'system' then return true; end if;
  if link_scope = 'system' then return false; end if;
  if link_scope = 'club' then return target_scope = 'club' and target_club = link_club; end if;
  if link_scope = 'team' then return target_scope = 'team' and target_team = link_team; end if;
  return false;
end;
$$;

CREATE FUNCTION training_load.lock_ancestors_before_occasion_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_event_id uuid;
begin
  if new.source_identity_id is not null then
    perform 1 from training_load.metric_source_identities where id = new.source_identity_id for update;
  end if;
  if new.import_batch_id is not null then
    perform 1 from training_load.metric_import_batches where id = new.import_batch_id for update;
  end if;
  select event_id into v_event_id from training_load.metric_event_participants where id = new.event_participant_id for update;
  perform 1 from training_load.metric_events where id = v_event_id for update;
  if new.segment_id is not null then
    perform 1 from training_load.metric_event_segments where id = new.segment_id for update;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.lock_and_validate_event_connection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  ref_scope varchar;
  ref_club uuid;
  ref_team uuid;
  ref_user uuid;
begin
  if new.source_connection_id is null then
    return new;
  end if;
  select owner_scope, owner_club_id, owner_team_id, owner_user_id into ref_scope, ref_club, ref_team, ref_user
    from training_load.metric_source_connections where id = new.source_connection_id for update;
  if new.owner_scope is distinct from ref_scope or new.owner_club_id is distinct from ref_club
     or new.owner_team_id is distinct from ref_team or new.owner_user_id is distinct from ref_user then
    raise exception 'event owner_scope does not match its source connection''s owner_scope (event=%/%/%/% connection=%/%/%/%)',
      new.owner_scope, new.owner_club_id, new.owner_team_id, new.owner_user_id, ref_scope, ref_club, ref_team, ref_user;
  end if;
  return new;
end;
$$;

