$$;

CREATE FUNCTION training_load.materialize_external_assignments_for_occurrence(p_occurrence_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  v_occurrence training_load.external_schedule_occurrences%rowtype;
  v_schedule training_load.external_schedules%rowtype;
  v_inserted_count integer;
begin
  select * into v_occurrence from training_load.external_schedule_occurrences where id = p_occurrence_id for update;
  if v_occurrence.id is null then raise exception 'occurrence % does not exist', p_occurrence_id; end if;
  select * into v_schedule from training_load.external_schedules where id = v_occurrence.schedule_id;

  if v_occurrence.assignments_materialized_at is null then
    insert into training_load.external_occurrence_target_snapshot (occurrence_id, athlete_id)
    select p_occurrence_id, ta.athlete_id
    from training_load.resolve_external_schedule_target_athletes(v_schedule.id) ta
    on conflict (occurrence_id, athlete_id) do nothing;
    update training_load.external_schedule_occurrences set assignments_materialized_at = now() where id = p_occurrence_id;
  end if;

  insert into training_load.external_assignments (occurrence_id, athlete_id, timezone, local_scheduled_date, opens_at, due_at, closes_at)
  select p_occurrence_id, e.athlete_id, e.effective_timezone, v_occurrence.scheduled_date,
         (v_occurrence.scheduled_date + v_schedule.opens_time) at time zone e.effective_timezone,
         case when v_schedule.due_time is null then null else (v_occurrence.scheduled_date + v_schedule.due_time) at time zone e.effective_timezone end,
         (v_occurrence.scheduled_date + v_schedule.closes_time) at time zone e.effective_timezone
  from (
    select s.athlete_id, coalesce(a.device_timezone, v_schedule.timezone) as effective_timezone
    from training_load.external_occurrence_target_snapshot s
    join public.athletes a on a.id = s.athlete_id
    where s.occurrence_id = p_occurrence_id
  ) e
  where (now() at time zone e.effective_timezone)::date = v_occurrence.scheduled_date
  on conflict (occurrence_id, athlete_id) do nothing;

  get diagnostics v_inserted_count = row_count;
  return v_inserted_count;
end $$;

CREATE FUNCTION training_load.metric_classification_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'metric classification: change and request records are append-only' using errcode = '23514';
end;
$$;

CREATE FUNCTION training_load.metric_classification_changes_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
  here bigint := training_load.source_metric_current_xmin();
  node record;
  link record;
begin
  if pg_trigger_depth() < 2 or new.xact_id is distinct from pg_current_xact_id() then
    raise exception 'metric_classification_changes: a change row is written only by its own change' using errcode = '23514';
  end if;
  if new.changed_by_user_id is distinct from actor then
    raise exception 'metric_classification_changes: the row names another user than the acting user' using errcode = '42501';
  end if;
  if new.object_kind = 'domain' then
    select owner_scope, owner_club_id, xmin::text::bigint as written_in into node
      from training_load.metric_domains where id = new.domain_id;
  elsif new.object_kind = 'category' then
    select owner_scope, owner_club_id, xmin::text::bigint as written_in into node
      from training_load.metric_categories where id = new.category_id;
  else
    select domain_id, category_id, metric_definition_id, owner_scope, owner_club_id, xmin::text::bigint as written_in into link
      from training_load.metric_structure_links where id = new.link_id;
    if not found
       or (new.kind = 'link' and link.written_in is distinct from here)
       or link.domain_id is distinct from new.domain_id
       or link.category_id is distinct from new.category_id
       or link.metric_definition_id is distinct from new.metric_definition_id
       or link.owner_scope is distinct from new.owner_scope
       or link.owner_club_id is distinct from new.owner_club_id then
      raise exception 'metric_classification_changes: a change row is written only by its own change' using errcode = '23514';
    end if;
    return new;
  end if;
  if not found
     or node.written_in is distinct from here
     or node.owner_scope is distinct from new.owner_scope
     or node.owner_club_id is distinct from new.owner_club_id then
    raise exception 'metric_classification_changes: a change row is written only by its own change' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_classification_changes_request_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from training_load.metric_classification_requests where metric_classification_change_id = new.id) then
    raise exception 'metric_classification_changes: a change is written with its own request row' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.metric_classification_link_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid;
  basis text;
  dom record;
  cat record;
  def record;
begin
  if tg_op = 'UPDATE' then
    if old.owner_scope in ('system', 'club') or new.owner_scope in ('system', 'club') then
      raise exception 'metric classification: a canonical link is created or removed, never changed' using errcode = '23514';
    end if;
    return new;
  end if;
  if tg_op = 'DELETE' then
    if old.owner_scope not in ('system', 'club') then
      return old;
    end if;
    actor := training_load.source_metric_context_actor();
    basis := training_load.source_metric_actor_basis(actor, old.owner_club_id);
    if basis is null then
      raise exception 'metric classification: the acting user may not write this owner scope' using errcode = '42501';
    end if;
    -- The removed link's change row, from the row itself, before it goes.
    insert into training_load.metric_classification_changes
      (object_kind, kind, domain_id, category_id, metric_definition_id, link_id, owner_scope, owner_club_id,
       changed_by_user_id, xact_id)
    values
      ('link', 'remove', old.domain_id, old.category_id, old.metric_definition_id, old.id, old.owner_scope,
       old.owner_club_id, actor, pg_current_xact_id());
    return old;
  end if;
  -- INSERT
  if new.owner_scope not in ('system', 'club') then
    return new;
  end if;
  actor := training_load.source_metric_context_actor();
  if new.created_by_user_id is distinct from actor then
    raise exception 'metric classification: the row names another user than the acting user' using errcode = '42501';
  end if;
  basis := training_load.source_metric_actor_basis(actor, new.owner_club_id);
  if basis is null then
    raise exception 'metric classification: the acting user may not write this owner scope' using errcode = '42501';
  end if;
  if num_nonnulls(new.domain_id, new.category_id, new.metric_definition_id) <> 2 or new.temporal_smoothing_enabled then
    raise exception 'metric classification: a canonical link names exactly two of a variable, a category and a domain' using errcode = '23514';
  end if;
  -- The targets, FOR SHARE in the service's order: domain, category, variable.
  if new.domain_id is not null then
    select owner_scope, owner_club_id, is_active into dom
      from training_load.metric_domains where id = new.domain_id for share;
  end if;
  if new.category_id is not null then
    select owner_scope, owner_club_id, is_active into cat
      from training_load.metric_categories where id = new.category_id for share;
  end if;
  if new.metric_definition_id is not null then
    select owner_scope, owner_club_id, state into def
      from training_load.metric_definitions where id = new.metric_definition_id for share;
  end if;
  -- O4: the container (the category of a variable link, the domain of a
  -- variable -> domain link, the category of a category -> domain link) is
  -- the link's own owner's; the other end is the same owner's or the system's.
  if new.metric_definition_id is not null and new.category_id is not null then
    if cat.owner_scope is distinct from new.owner_scope or cat.owner_club_id is distinct from new.owner_club_id
       or not (def.owner_scope = 'system' or (def.owner_scope = new.owner_scope and def.owner_club_id is not distinct from new.owner_club_id)) then
      raise exception 'metric classification: a link reaches outside its owner' using errcode = '23514';
    end if;
  elsif new.metric_definition_id is not null then
    if dom.owner_scope is distinct from new.owner_scope or dom.owner_club_id is distinct from new.owner_club_id
       or not (def.owner_scope = 'system' or (def.owner_scope = new.owner_scope and def.owner_club_id is not distinct from new.owner_club_id)) then
      raise exception 'metric classification: a link reaches outside its owner' using errcode = '23514';
    end if;
  else
    if cat.owner_scope is distinct from new.owner_scope or cat.owner_club_id is distinct from new.owner_club_id
       or not (dom.owner_scope = 'system' or (dom.owner_scope = new.owner_scope and dom.owner_club_id is not distinct from new.owner_club_id)) then
      raise exception 'metric classification: a link reaches outside its owner' using errcode = '23514';
    end if;
  end if;
  -- One IF per target: a record a branch never read is not assigned.
  if new.domain_id is not null then
    if dom.is_active is distinct from true then
      raise exception 'metric classification: a link never points at an archived domain or category' using errcode = '23514';
    end if;
  end if;
  if new.category_id is not null then
    if cat.is_active is distinct from true then
      raise exception 'metric classification: a link never points at an archived domain or category' using errcode = '23514';
    end if;
  end if;
  if new.metric_definition_id is not null then
    if def.state is distinct from 'active' then
      raise exception 'metric classification: a link never points at an archived variable' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_classification_links_no_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if exists (select 1 from training_load.metric_structure_links where owner_scope in ('system', 'club')) then
    raise exception 'metric classification: a canonical link is removed one at a time, never truncated' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.metric_classification_node_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid;
  basis text;
begin
  if tg_op = 'DELETE' then
    if old.owner_scope in ('system', 'club') then
      raise exception 'metric classification: a canonical domain or category is archived, never deleted' using errcode = '23514';
    end if;
    return old;
  end if;
  if tg_op = 'INSERT' then
    if new.owner_scope not in ('system', 'club') then
      return new;
    end if;
    actor := training_load.source_metric_context_actor();
    if new.created_by_user_id is distinct from actor then
      raise exception 'metric classification: the row names another user than the acting user' using errcode = '42501';
    end if;
    basis := training_load.source_metric_actor_basis(actor, new.owner_club_id);
    if basis is null then
      raise exception 'metric classification: the acting user may not write this owner scope' using errcode = '42501';
    end if;
    if new.is_active is distinct from true or new.key is null then
      raise exception 'metric classification: a canonical domain or category is created active, with its key' using errcode = '23514';
    end if;
    if not training_load.source_metric_text_ok(new.name, 80)
       or (new.description is not null and not training_load.source_metric_text_ok(new.description, 500)) then
      raise exception 'metric classification: a name or description is not bounded text' using errcode = '23514';
    end if;
    return new;
  end if;
  -- UPDATE
  if old.owner_scope not in ('system', 'club') and new.owner_scope not in ('system', 'club') then
    return new;
  end if;
  actor := training_load.source_metric_context_actor();
  basis := training_load.source_metric_actor_basis(actor, old.owner_club_id);
  if basis is null then
    raise exception 'metric classification: the acting user may not write this owner scope' using errcode = '42501';
  end if;
  if new.id is distinct from old.id
     or new.owner_scope is distinct from old.owner_scope
     or new.owner_user_id is distinct from old.owner_user_id
     or new.owner_club_id is distinct from old.owner_club_id
     or new.owner_team_id is distinct from old.owner_team_id
     or new.key is distinct from old.key
     or new.created_by_user_id is distinct from old.created_by_user_id
     or new.created_at is distinct from old.created_at then
    raise exception 'metric classification: only the name, the description and the state of a canonical domain or category change' using errcode = '23514';
  end if;
  if new.is_active is distinct from old.is_active then
    if new.name is distinct from old.name or new.description is distinct from old.description then
      raise exception 'metric classification: a rename, an archive and a restore are separate changes' using errcode = '23514';
    end if;
    if new.icon_url is distinct from old.icon_url then
      raise exception 'metric classification: an icon change is a change of its own' using errcode = '23514';
    end if;
  elsif new.icon_url is distinct from old.icon_url then
    -- v46: an icon change alone, of an active node.
    if new.name is distinct from old.name or new.description is distinct from old.description then
      raise exception 'metric classification: an icon change is a change of its own' using errcode = '23514';
    end if;
    if old.is_active is distinct from true then
      raise exception 'metric classification: an archived domain or category is restored before its icon changes' using errcode = '23514';
    end if;
  elsif new.name is not distinct from old.name and new.description is not distinct from old.description then
    raise exception 'metric classification: the change changes nothing' using errcode = '23514';
  else
    if old.is_active is distinct from true then
      raise exception 'metric classification: an archived domain or category is restored before it is renamed' using errcode = '23514';
    end if;
    -- A value the rename leaves as it was is exempt (the v38 pattern).
    if (new.name is distinct from old.name and not training_load.source_metric_text_ok(new.name, 80))
       or (new.description is distinct from old.description and new.description is not null
           and not training_load.source_metric_text_ok(new.description, 500)) then
      raise exception 'metric classification: a name or description is not bounded text' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_classification_record_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  insert into training_load.metric_classification_changes
    (object_kind, kind, domain_id, category_id, metric_definition_id, link_id, owner_scope, owner_club_id,
     changed_by_user_id, xact_id)
  values
    ('link', 'link', new.domain_id, new.category_id, new.metric_definition_id, new.id, new.owner_scope,
     new.owner_club_id, training_load.source_metric_context_actor(), pg_current_xact_id());
  return null;
end;
$$;

CREATE FUNCTION training_load.metric_classification_record_node_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
  is_domain boolean := tg_table_name = 'metric_domains';
begin
  if tg_op = 'INSERT' then
    insert into training_load.metric_classification_changes
      (object_kind, kind, domain_id, category_id, owner_scope, owner_club_id, new_name, new_description, new_active,
       new_icon_url, changed_by_user_id, xact_id)
    values
      (case when is_domain then 'domain' else 'category' end, 'create',
       case when is_domain then new.id end, case when is_domain then null else new.id end,
       new.owner_scope, new.owner_club_id, new.name, new.description, new.is_active, new.icon_url, actor, pg_current_xact_id());
  else
    insert into training_load.metric_classification_changes
      (object_kind, kind, domain_id, category_id, owner_scope, owner_club_id, old_name, new_name, old_description,
       new_description, old_active, new_active, old_icon_url, new_icon_url, changed_by_user_id, xact_id)
    values
      (case when is_domain then 'domain' else 'category' end,
       case when old.is_active = new.is_active then case when old.icon_url is distinct from new.icon_url then 'icon' else 'rename' end
            when new.is_active then 'restore' else 'archive' end,
       case when is_domain then new.id end, case when is_domain then null else new.id end,
       new.owner_scope, new.owner_club_id, old.name, new.name, old.description, new.description, old.is_active,
       new.is_active, old.icon_url, new.icon_url, actor, pg_current_xact_id());
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.metric_classification_requests_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
  here bigint := training_load.source_metric_current_xmin();
  this_xact xid8 := pg_current_xact_id();
  chg record;
  node record;
  derived text;
  expected_object text;
  expected_kind text;
begin
  if new.requested_by_user_id is distinct from actor then
    raise exception 'metric classification request: the row names another user than the acting user' using errcode = '42501';
  end if;
  derived := training_load.source_metric_actor_basis(actor, new.owner_club_id);
  if derived is null then
    raise exception 'metric classification request: the acting user may not write this owner scope' using errcode = '42501';
  end if;
  if new.basis is distinct from derived then
    raise exception 'metric classification request: the basis is not the acting user''s own' using errcode = '42501';
  end if;
  expected_object := split_part(new.operation, '_', 1);
  expected_kind := case new.operation
    when 'link_create' then 'link' when 'link_remove' then 'remove' else split_part(new.operation, '_', 2) end;
  select id, object_kind, kind, domain_id, category_id, metric_definition_id, link_id, owner_scope, owner_club_id,
         new_name, new_description, new_active, new_icon_url, changed_by_user_id, xact_id, xmin::text::bigint as written_in into chg
    from training_load.metric_classification_changes where id = new.metric_classification_change_id;
  if not found
     or chg.xact_id is distinct from this_xact
     or chg.written_in is distinct from here
     or chg.changed_by_user_id is distinct from actor
     or chg.owner_scope is distinct from new.owner_scope
     or chg.owner_club_id is distinct from new.owner_club_id
     or chg.object_kind is distinct from expected_object
     or chg.kind is distinct from expected_kind then
    raise exception 'metric_classification_requests: the request must follow its own change in the same transaction' using errcode = '23514';
  end if;
  if chg.object_kind = 'link' then
    if (select count(*) from training_load.metric_classification_changes where link_id = chg.link_id and xact_id = this_xact) <> 1
       or (chg.kind = 'link' and not exists (select 1 from training_load.metric_structure_links
                                              where id = chg.link_id and xmin::text::bigint = here))
       or (chg.kind = 'remove' and exists (select 1 from training_load.metric_structure_links where id = chg.link_id)) then
      raise exception 'metric_classification_requests: the request must follow its own change in the same transaction' using errcode = '23514';
    end if;
    return new;
  end if;
  if chg.object_kind = 'domain' then
    select name, description, is_active, icon_url, xmin::text::bigint as written_in into node
      from training_load.metric_domains where id = chg.domain_id;
    if (select count(*) from training_load.metric_classification_changes where domain_id = chg.domain_id and object_kind = 'domain'
         and xact_id = this_xact) <> 1 then
      raise exception 'metric_classification_requests: the request must follow its own change in the same transaction' using errcode = '23514';
    end if;
  else
    select name, description, is_active, icon_url, xmin::text::bigint as written_in into node
      from training_load.metric_categories where id = chg.category_id;
    if (select count(*) from training_load.metric_classification_changes where category_id = chg.category_id and object_kind = 'category'
         and xact_id = this_xact) <> 1 then
      raise exception 'metric_classification_requests: the request must follow its own change in the same transaction' using errcode = '23514';
    end if;
  end if;
  if not found
     or node.written_in is distinct from here
     or node.name is distinct from chg.new_name
     or node.description is distinct from chg.new_description
     or node.is_active is distinct from chg.new_active
     or node.icon_url is distinct from chg.new_icon_url then
    raise exception 'metric_classification_requests: the request must follow its own change in the same transaction' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_definition_club_hides_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
  basis text;
  def record;
begin
  if new.hidden_by_user_id is distinct from actor then
    raise exception 'metric variable hide: the row names another user than the acting user' using errcode = '42501';
  end if;
  -- The rights rows first (row locks); no row lock after the hide lock.
  basis := training_load.source_metric_actor_basis(actor, new.club_id);
  if basis is null or new.hidden_basis is distinct from basis then
    raise exception 'metric variable hide: the acting user may not hide for this club' using errcode = '42501';
  end if;
  if new.shown_at is not null or new.shown_by_user_id is not null or new.shown_basis is not null
     or new.show_request_key is not null or new.show_request_hash is not null then
    raise exception 'metric_definition_club_hides: a hide is created open' using errcode = '23514';
  end if;
  if new.hidden_at is distinct from now() then
    raise exception 'metric_definition_club_hides: a hide is dated by its own transaction' using errcode = '23514';
  end if;
  -- A plain read: the service holds the definition FOR KEY SHARE from before.
  select owner_scope into def from training_load.metric_definitions where id = new.metric_definition_id;
  if def.owner_scope is distinct from 'system' then
    raise exception 'metric_definition_club_hides: only a system variable is hidden' using errcode = '23514';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('club-variable-hide:' || new.club_id::text || ':' || new.metric_definition_id::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('club-variable-hide-key:' || actor::text || ':' || new.hide_request_key::text, 0));
  if exists (select 1 from training_load.metric_definition_club_hides h
              where h.shown_by_user_id = actor and h.show_request_key = new.hide_request_key) then
    raise exception 'metric_definition_club_hides: a request key serves one act only' using errcode = '23514';
  end if;
  if exists (select 1
               from training_load.source_metric_mapping_activations a
               join training_load.source_metric_mappings m on m.id = a.mapping_id
              where a.metric_definition_id = new.metric_definition_id
                and a.ended_at is null
                and m.owner_scope = 'system'
                and training_load.source_metric_binding_club(a.source_team_binding_id) = new.club_id) then
    raise exception 'metric_definition_club_hides: the variable is switched on for the club''s teams' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_definition_club_hides_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
  basis text;
begin
  if old.shown_at is not null then
    raise exception 'metric_definition_club_hides: a hide is shown again once' using errcode = '23514';
  end if;
  if new.id is distinct from old.id
     or new.club_id is distinct from old.club_id
     or new.metric_definition_id is distinct from old.metric_definition_id
     or new.hidden_by_user_id is distinct from old.hidden_by_user_id
     or new.hidden_basis is distinct from old.hidden_basis
     or new.hide_request_key is distinct from old.hide_request_key
     or new.hide_request_hash is distinct from old.hide_request_hash
     or new.hidden_at is distinct from old.hidden_at then
    raise exception 'metric_definition_club_hides: only the show facts change' using errcode = '23514';
  end if;
  if new.shown_at is null then
    raise exception 'metric_definition_club_hides: only the show facts change' using errcode = '23514';
  end if;
  if new.shown_by_user_id is distinct from actor then
    raise exception 'metric variable hide: the row names another user than the acting user' using errcode = '42501';
  end if;
  basis := training_load.source_metric_actor_basis(actor, new.club_id);
  if basis is null or new.shown_basis is distinct from basis then
    raise exception 'metric variable hide: the acting user may not hide for this club' using errcode = '42501';
  end if;
  if new.shown_at is distinct from now() then
    raise exception 'metric_definition_club_hides: a show is dated by its own transaction' using errcode = '23514';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('club-variable-hide:' || new.club_id::text || ':' || new.metric_definition_id::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('club-variable-hide-key:' || actor::text || ':' || new.show_request_key::text, 0));
  if exists (select 1 from training_load.metric_definition_club_hides h
              where h.hidden_by_user_id = actor and h.hide_request_key = new.show_request_key) then
    raise exception 'metric_definition_club_hides: a request key serves one act only' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_definition_club_hides_xact_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (select h.xmin::text::bigint from training_load.metric_definition_club_hides h where h.id = new.id)
     is distinct from training_load.source_metric_current_xmin() then
    raise exception 'metric_definition_club_hides: a hide or a show is written outside a savepoint' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.metric_definition_copies_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
  here bigint := training_load.source_metric_current_xmin();
  basis text;
  cdef record;
  cver record;
  sdef record;
  sver record;
begin
  if new.copied_by_user_id is distinct from actor then
    raise exception 'metric variable copy: the row names another user than the acting user' using errcode = '42501';
  end if;
  basis := training_load.source_metric_actor_basis(actor, new.club_id);
  if basis is null or new.basis is distinct from basis then
    raise exception 'metric variable copy: the acting user may not copy into this club' using errcode = '42501';
  end if;
  -- The club side: the club's own new variable, written in this transaction
  -- by the acting user, at its version 1.
  select owner_scope, owner_club_id, state, current_version_id, created_by_user_id, xmin::text::bigint as written_in into cdef
    from training_load.metric_definitions where id = new.club_definition_id;
  if not found
     or cdef.owner_scope is distinct from 'club'
     or cdef.owner_club_id is distinct from new.club_id
     or cdef.state is distinct from 'active'
     or cdef.written_in is distinct from here
     or cdef.created_by_user_id is distinct from actor then
    raise exception 'metric_definition_copies: the copy must be the club variable written in this transaction' using errcode = '23514';
  end if;
  select version_number, unit, value_type, min_value, max_value, condition_description, daily_aggregation_method,
         created_by_user_id, xmin::text::bigint as written_in into cver
    from training_load.metric_definition_versions
   where id = cdef.current_version_id and metric_definition_id = new.club_definition_id;
  if not found or cver.version_number <> 1 or cver.written_in is distinct from here or cver.created_by_user_id is distinct from actor then
    raise exception 'metric_definition_copies: the copy must be the club variable written in this transaction' using errcode = '23514';
  end if;
  -- The system side (the service holds both rows FOR SHARE already, D's order).
  select owner_scope, state, current_version_id into sdef
    from training_load.metric_definitions where id = new.system_definition_id for share;
  if not found
     or sdef.owner_scope is distinct from 'system'
     or sdef.state is distinct from 'active'
     or sdef.current_version_id is distinct from new.system_version_id then
    raise exception 'metric_definition_copies: the source must be an active system variable at its current version' using errcode = '23514';
  end if;
  select unit, value_type, min_value, max_value, condition_description, daily_aggregation_method into sver
    from training_load.metric_definition_versions
   where id = new.system_version_id and metric_definition_id = new.system_definition_id for share;
  if exists (select 1 from training_load.metric_definition_copies c where c.club_definition_id = new.system_definition_id) then
    raise exception 'metric_definition_copies: the source must be an active system variable at its current version' using errcode = '23514';
  end if;
  if cver.unit is distinct from sver.unit
     or cver.value_type is distinct from sver.value_type
     or cver.min_value is distinct from sver.min_value
     or cver.max_value is distinct from sver.max_value
     or cver.condition_description is distinct from sver.condition_description
     or cver.daily_aggregation_method is distinct from sver.daily_aggregation_method then
    raise exception 'metric_definition_copies: version 1 of the copy must equal the system version in every semantic fact' using errcode = '23514';
  end if;
  if exists ((select scope_level from training_load.metric_definition_scope_capabilities where metric_definition_id = new.club_definition_id)
             except
             (select scope_level from training_load.metric_definition_scope_capabilities where metric_definition_id = new.system_definition_id))
     or exists ((select scope_level from training_load.metric_definition_scope_capabilities where metric_definition_id = new.system_definition_id)
                except
                (select scope_level from training_load.metric_definition_scope_capabilities where metric_definition_id = new.club_definition_id)) then
    raise exception 'metric_definition_copies: the copy''s scope capabilities must equal the system variable''s' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_definition_copies_request_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from training_load.metric_variable_requests r
                  where r.operation = 'variable_copy'
                    and r.metric_definition_id = new.club_definition_id
                    and r.operation_id = new.operation_id) then
    raise exception 'metric_definition_copies: a copy needs its variable_copy request in the same operation' using errcode = '23514';
  end if;
  if (select c.xmin::text::bigint from training_load.metric_definition_copies c where c.club_definition_id = new.club_definition_id)
     is distinct from training_load.source_metric_current_xmin() then
    raise exception 'metric_definition_copies: a copy is written outside a savepoint' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.metric_definitions_key_freeze() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.key is distinct from old.key and (old.owner_scope in ('system', 'club') or new.owner_scope in ('system', 'club')) then
    raise exception 'metric_definitions: the key of a canonical variable never changes' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_definitions_record_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
begin
  insert into training_load.metric_variable_changes
    (metric_definition_id, owner_scope, owner_club_id, kind, old_label, new_label, old_short_label, new_short_label,
     old_description, new_description, old_state, new_state, old_icon_url, new_icon_url, changed_by_user_id, xact_id)
  values
    (new.id, new.owner_scope, new.owner_club_id,
     case when old.state is distinct from new.state then case when new.state = 'archived' then 'archive' else 'restore' end
          when old.label is not distinct from new.label and old.short_label is not distinct from new.short_label
               and old.description is not distinct from new.description then 'icon'
          else 'rename' end,
     old.label, new.label, old.short_label, new.short_label, old.description, new.description, old.state, new.state,
     old.icon_url, new.icon_url, actor, pg_current_xact_id());
  return null;
end;
$$;

CREATE FUNCTION training_load.metric_source_connections_end_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from training_load.source_metric_audit
                  where action = 'source_instance_end' and metric_source_connection_id = new.id
                    and from_status = 'active' and to_status = 'inactive') then
    raise exception 'metric_source_connections: a source instance is ended with its audit row' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.metric_source_connections_instance_write_once() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (old.source_host_key is not null or old.source_instance_key is not null)
     and (new.source_host_key is distinct from old.source_host_key or new.source_instance_key is distinct from old.source_instance_key) then
    raise exception 'metric_source_connections: the source instance of a connection is written once' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_source_connections_state_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid;
begin
  if old.state = 'inactive' then
    raise exception 'metric_source_connections: an ended source instance is final' using errcode = '23514';
  end if;
  if old.owner_scope is distinct from 'team' or old.source_host_key is null or old.source_instance_key is null
     or new.source_system is distinct from old.source_system
     or new.owner_scope is distinct from old.owner_scope or new.owner_team_id is distinct from old.owner_team_id
     or new.owner_club_id is distinct from old.owner_club_id or new.owner_user_id is distinct from old.owner_user_id then
    raise exception 'metric_source_connections: only a team''s source instance is ended' using errcode = '23514';
  end if;
  actor := training_load.source_metric_context_actor();
  if training_load.source_metric_actor_basis(actor, null) is distinct from 'platform_admin' then
    raise exception 'metric source connection: the acting user may not end this source instance' using errcode = '42501';
  end if;
  perform training_load.hold_gpexe_team_lock(old.owner_team_id, 'ending a source instance');
  if exists (select 1
               from training_load.source_team_bindings b
               join training_load.source_credential_connections cc on cc.id = b.connection_id
              where b.team_id = old.owner_team_id and b.state = 'active' and b.source_system = old.source_system
                and b.source_team_id = old.source_instance_key and cc.host_key = old.source_host_key) then
    raise exception 'metric_source_connections: the owner team still holds an active binding of this source team' using errcode = '23514';
  end if;
  if exists (select 1
               from training_load.source_metric_mapping_activations a
               join training_load.source_team_bindings b on b.id = a.source_team_binding_id
               join training_load.source_credential_connections cc on cc.id = b.connection_id
              where a.ended_at is null and b.team_id = old.owner_team_id and b.source_system = old.source_system
                and b.source_team_id = old.source_instance_key and cc.host_key = old.source_host_key) then
    raise exception 'metric_source_connections: an activation of this source team is still open' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_value_provenance_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  act record;
  ver record;
  rev_unit text;
  val record;
  bnd record;
  conn_host text;
  msc record;
  occasion_connection uuid;
  value_level text;
begin
  -- C49 / C55: never a new fact through an ended activation, an ended
  -- binding or an inactive Metrics Core source instance. Lock order of a new
  -- fact: the activation (T5) -> its team binding -> the Metrics Core
  -- connection, each FOR SHARE, so an ending of any of them either waits for
  -- this fact or lands first and the fact is refused. An ending never
  -- changes an existing fact.
  select ended_at, team_id, applies_to_session, applies_to_drill into act
    from training_load.source_metric_mapping_activations
   where id = new.activation_id and mapping_version_id = new.mapping_version_id
     and source_team_binding_id = new.source_team_binding_id for share;
  if not found then
    raise exception 'metric_value_source_provenance: the activation does not match the fact' using errcode = '23514';
  end if;
  if act.ended_at is not null then
    raise exception 'metric_value_source_provenance: a fact is never written through an ended activation' using errcode = '23514';
  end if;
  select state, source_system, source_team_id, connection_id into bnd
    from training_load.source_team_bindings where id = new.source_team_binding_id for share;
  if bnd.state is distinct from 'active' then
    raise exception 'metric_value_source_provenance: a fact is never written through an ended binding' using errcode = '23514';
  end if;
  select state, source_system, source_host_key, source_instance_key into msc
    from training_load.metric_source_connections where id = new.metric_source_connection_id for share;
  if msc.state is distinct from 'active' then
    raise exception 'metric_value_source_provenance: a fact is never written through an inactive source instance' using errcode = '23514';
  end if;
  select mapping_id, source_metric_version_id, metric_definition_id, metric_definition_version_id, target_unit, source_unit,
         scale, scale_divisor, "offset" into ver
    from training_load.source_metric_mapping_versions where id = new.mapping_version_id;
  if ver.mapping_id is distinct from new.mapping_id or ver.source_metric_version_id is distinct from new.source_metric_version_id then
    raise exception 'metric_value_source_provenance: the fact must name its mapping version''s mapping and revision' using errcode = '23514';
  end if;
  select source_unit into rev_unit from training_load.source_metric_definition_versions where id = new.source_metric_version_id;
  if new.source_unit is distinct from rev_unit or new.source_unit is distinct from ver.source_unit then
    raise exception 'metric_value_source_provenance: the source unit must be the revision''s proven unit' using errcode = '23514';
  end if;
  select v.metric_definition_id, v.metric_definition_version_id, v.unit_at_capture, v.value_numeric, o.source_identity_id,
         o.segment_id, e.scope_level, e.owner_scope, e.owner_team_id into val
    from training_load.metric_values v
    join training_load.metric_measurement_occasions o on o.id = v.occasion_id
    join training_load.metric_event_participants p on p.id = o.event_participant_id
    join training_load.metric_events e on e.id = p.event_id
   where v.id = new.metric_value_id;
  if not found then
    raise exception 'metric_value_source_provenance: the value does not exist' using errcode = '23514';
  end if;
  -- C55: the value's event belongs to the binding's team (the activation's
  -- team is the binding's, by the T5 foreign key), and the value's level is
  -- one the activation covers (session <-> applies_to_session, a drill
  -- segment <-> applies_to_drill; a day-level event is neither).
  if val.owner_scope is distinct from 'team' or val.owner_team_id is distinct from act.team_id then
    raise exception 'metric_value_source_provenance: the value must belong to the binding''s team' using errcode = '23514';
  end if;
  value_level := case when val.scope_level is distinct from 'session' then null
                      when val.segment_id is null then 'session' else 'drill' end;
  if value_level is null or (value_level = 'session' and not act.applies_to_session)
     or (value_level = 'drill' and not act.applies_to_drill) then
    raise exception 'metric_value_source_provenance: the value''s level is not one the activation covers' using errcode = '23514';
  end if;
  if val.metric_definition_id is distinct from ver.metric_definition_id
     or val.metric_definition_version_id is distinct from ver.metric_definition_version_id then
    raise exception 'metric_value_source_provenance: the value must be of the pinned canonical version' using errcode = '23514';
  end if;
  if val.unit_at_capture is distinct from ver.target_unit then
    raise exception 'metric_value_source_provenance: the value''s unit must be the mapping''s target unit' using errcode = '23514';
  end if;
  if val.value_numeric is null
     or not training_load.source_metric_value_matches(new.source_value_numeric, val.value_numeric, ver.scale, ver.scale_divisor, ver."offset") then
    raise exception 'metric_value_source_provenance: the value is not the source value converted at the storage scale' using errcode = '23514';
  end if;
  select host_key into conn_host from training_load.source_credential_connections where id = bnd.connection_id;
  if msc.source_system is distinct from bnd.source_system or msc.source_host_key is distinct from conn_host
     or msc.source_instance_key is distinct from bnd.source_team_id then
    raise exception 'metric_value_source_provenance: the Metrics Core source instance must be the binding''s' using errcode = '23514';
  end if;
  select source_connection_id into occasion_connection
    from training_load.metric_source_identities where id = val.source_identity_id;
  if occasion_connection is distinct from new.metric_source_connection_id then
    raise exception 'metric_value_source_provenance: the value''s occasion must come from the same source instance' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_variable_change_basis(p_actor uuid, p_owner_club uuid, p_team uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
begin
  perform 1 from public.users u where u.id = p_actor and u.is_active = true for share;
  perform 1
    from public.user_global_roles g
    join public.users u on u.id = g.user_id
   where g.user_id = p_actor and g.role = 'platform_admin' and g.is_active = true and u.is_active = true
     for share of g;
  if found then
    if p_owner_club is not null then
      perform 1 from public.clubs where id = p_owner_club and coalesce(is_active, true) for share;
      if not found then
        return null;
      end if;
    end if;
    return 'platform_admin';
  end if;
  if p_owner_club is null then
    return null;
  end if;
  perform 1
    from public.user_club_roles r
    join public.users u on u.id = r.user_id
    join public.clubs c on c.id = r.club_id
   where r.user_id = p_actor and r.club_id = p_owner_club and r.role = 'club_admin' and r.is_active = true
     and u.is_active = true and coalesce(c.is_active, true)
     for share of r, c;
  if found then
    return 'club_admin';
  end if;
  if p_team is null then
    return null;
  end if;
  perform 1 from public.teams where id = p_team and club_id = p_owner_club and coalesce(is_active, true) for share;
  if not found then
    return null;
  end if;
  perform 1 from public.clubs where id = p_owner_club and coalesce(is_active, true) for share;
  if not found then
    return null;
  end if;
  perform 1
    from public.user_team_roles r
    join public.users u on u.id = r.user_id
   where r.user_id = p_actor and r.team_id = p_team and r.role = 'team_coach' and r.is_active = true and u.is_active = true
     for share of r;
  if found then
    return 'team_coach';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.metric_variable_changes_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'metric_variable_changes: change records are append-only' using errcode = '23514';
end;
$$;

CREATE FUNCTION training_load.metric_variable_changes_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
  def record;
begin
  if pg_trigger_depth() < 2 or new.xact_id is distinct from pg_current_xact_id() then
    raise exception 'metric_variable_changes: a change row is written only by the definition''s own change' using errcode = '23514';
  end if;
  if new.changed_by_user_id is distinct from actor then
    raise exception 'metric_variable_changes: the row names another user than the acting user' using errcode = '42501';
  end if;
  select owner_scope, owner_club_id, xmin::text::bigint as written_in into def
    from training_load.metric_definitions where id = new.metric_definition_id;
  if not found
     or def.written_in is distinct from training_load.source_metric_current_xmin()
     or def.owner_scope is distinct from new.owner_scope
     or def.owner_club_id is distinct from new.owner_club_id then
    raise exception 'metric_variable_changes: a change row is written only by the definition''s own change' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_variable_changes_request_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from training_load.metric_variable_requests where metric_variable_change_id = new.id) then
    raise exception 'metric_variable_changes: a change is written with its own request row' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.metric_variable_requests_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'metric_variable_requests: request records are append-only' using errcode = '23514';
end;
$$;

CREATE FUNCTION training_load.metric_variable_requests_change_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
  here bigint := training_load.source_metric_current_xmin();
  def record;
  chg record;
  prior record;
  derived text;
  this_xact xid8 := pg_current_xact_id();
begin
  if new.requested_by_user_id is distinct from actor then
    raise exception 'metric variable request: the row names another user than the acting user' using errcode = '42501';
  end if;
  select owner_scope, owner_club_id, label, short_label, description, state, icon_url, current_version_id,
         xmin::text::bigint as written_in into def
    from training_load.metric_definitions where id = new.metric_definition_id;
  if not found
     or def.owner_scope not in ('system', 'club')
     or def.owner_scope is distinct from new.owner_scope
     or def.owner_club_id is distinct from new.owner_club_id then
    raise exception 'metric_variable_requests: the request must follow its own change in the same transaction' using errcode = '23514';
  end if;
  derived := training_load.metric_variable_change_basis(actor, def.owner_club_id, new.basis_team_id);
  if derived is null then
    raise exception 'metric variable request: the acting user may not write this owner scope' using errcode = '42501';
  end if;
  if new.basis is distinct from derived then
    raise exception 'metric variable request: the basis is not the acting user''s own' using errcode = '42501';
  end if;
  select id, seq, metric_definition_id, owner_scope, owner_club_id, kind, old_label, new_label, old_short_label, new_short_label,
         old_description, new_description, old_state, new_state, old_icon_url, new_icon_url, changed_by_user_id, xact_id,
         xmin::text::bigint as written_in into chg
    from training_load.metric_variable_changes where id = new.metric_variable_change_id;
  if not found
     or chg.metric_definition_id is distinct from new.metric_definition_id
     or chg.owner_scope is distinct from def.owner_scope
     or chg.owner_club_id is distinct from def.owner_club_id
     or chg.xact_id is distinct from this_xact
     or chg.written_in is distinct from here
     or chg.changed_by_user_id is distinct from actor
     or def.written_in is distinct from here
     or (select count(*) from training_load.metric_variable_changes
          where metric_definition_id = new.metric_definition_id and xact_id = this_xact) <> 1
     or (def.label, def.short_label, def.description, def.state, def.icon_url)
        is distinct from (chg.new_label, chg.new_short_label, chg.new_description, chg.new_state, chg.new_icon_url) then
    raise exception 'metric_variable_requests: the request must follow its own change in the same transaction' using errcode = '23514';
  end if;
  if (new.operation = 'variable_rename' and chg.kind is distinct from 'rename')
     or (new.operation = 'variable_archive' and chg.kind is distinct from 'archive')
     or (new.operation = 'variable_restore' and chg.kind is distinct from 'restore')
     or (new.operation = 'variable_icon' and chg.kind is distinct from 'icon')
     or (chg.kind <> 'icon' and chg.old_icon_url is distinct from chg.new_icon_url)
     or (chg.kind <> 'rename'
         and (chg.old_label, chg.old_short_label, chg.old_description)
             is distinct from (chg.new_label, chg.new_short_label, chg.new_description)) then
    raise exception 'metric_variable_requests: the change does not match the operation' using errcode = '23514';
  end if;
  -- A rename's new texts are bounded text; a value it leaves as it was is
  -- exempt (a legacy variable keeps its longer label while its description
  -- changes).
  if chg.kind = 'rename'
     and not ((chg.new_label is not distinct from chg.old_label or training_load.source_metric_text_ok(chg.new_label, 80))
              and (chg.new_short_label is null or chg.new_short_label is not distinct from chg.old_short_label
                   or training_load.source_metric_text_ok(chg.new_short_label, 20))
              and (chg.new_description is null or chg.new_description is not distinct from chg.old_description
                   or training_load.source_metric_text_ok(chg.new_description, 500))) then
    raise exception 'metric_variable_requests: a new label, short label or description is not bounded text' using errcode = '23514';
  end if;
  if derived = 'team_coach' then
    -- Q4: a coach does not rename a variable an active mapping version pins.
    if chg.kind = 'rename' and exists (
         select 1 from training_load.source_metric_mapping_versions
          where metric_definition_id = new.metric_definition_id and metric_definition_version_id = def.current_version_id
            and status = 'active') then
      raise exception 'metric_variable_requests: a team coach does not rename a pinned variable' using errcode = '23514';
    end if;
    -- Q8: a coach restores only an archive a coach made - the definition's
    -- most recent change before this one is an archive whose request had the
    -- team_coach basis. An archive with no change row (legacy, or written with
    -- the trigger off) is no coach's: refused.
    if chg.kind = 'restore' then
      select c.kind, r.basis into prior
        from training_load.metric_variable_changes c
        left join training_load.metric_variable_requests r on r.metric_variable_change_id = c.id
       where c.metric_definition_id = new.metric_definition_id and c.seq < chg.seq
       order by c.seq desc
       limit 1;
      if not found or prior.kind is distinct from 'archive' or prior.basis is distinct from 'team_coach' then
        raise exception 'metric_variable_requests: a team coach restores only a coach''s archive' using errcode = '23514';
      end if;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.metric_variable_requests_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
  here bigint := training_load.source_metric_current_xmin();
  def record;
  ver record;
  derived text;
begin
  if new.requested_by_user_id is distinct from actor then
    raise exception 'metric variable request: the row names another user than the acting user' using errcode = '42501';
  end if;
  select owner_scope, owner_club_id, state, current_version_id, created_by_user_id, xmin::text::bigint as written_in into def
    from training_load.metric_definitions where id = new.metric_definition_id;
  if not found or def.owner_scope is distinct from new.owner_scope or def.owner_club_id is distinct from new.owner_club_id then
    raise exception 'metric_variable_requests: the request must follow its own operation in the same transaction' using errcode = '23514';
  end if;
  derived := training_load.source_metric_actor_basis(actor, new.owner_club_id);
  if derived is null then
    raise exception 'metric variable request: the acting user may not write this owner scope' using errcode = '42501';
  end if;
  if new.basis is distinct from derived then
    raise exception 'metric variable request: the basis is not the acting user''s own' using errcode = '42501';
  end if;
  select version_number, created_by_user_id, xmin::text::bigint as written_in into ver
    from training_load.metric_definition_versions
   where id = new.metric_definition_version_id and metric_definition_id = new.metric_definition_id;
  -- v53 (J15 7.4): a copy is checked as a create, and its copy row of the
  -- same operation must be written in this transaction.
  if not found
     or ver.written_in is distinct from here
     or ver.created_by_user_id is distinct from actor
     or def.written_in is distinct from here
     or def.state is distinct from 'active'
     or def.current_version_id is distinct from new.metric_definition_version_id
     or (new.operation in ('variable_create', 'variable_copy') and (ver.version_number <> 1 or def.created_by_user_id is distinct from actor))
     or (new.operation = 'variable_version_create' and ver.version_number <= 1)
     or (new.operation = 'variable_copy' and not exists (
           select 1 from training_load.metric_definition_copies c
            where c.club_definition_id = new.metric_definition_id
              and c.operation_id = new.operation_id
              and c.xmin::text::bigint = here)) then
    raise exception 'metric_variable_requests: the request must follow its own operation in the same transaction' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.normalize_key_name(k text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    select lower(regexp_replace(regexp_replace(regexp_replace(k, '([a-z0-9])([A-Z])', '\1_\2', 'g'), '[-.\s]+', '_', 'g'), '_+', '_', 'g'))
  $$;

CREATE FUNCTION training_load.planned_rpe_actionable(p_plan_id uuid, p_date date, p_training_load_enabled boolean, p_rpe_enabled boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select coalesce(p_training_load_enabled, false)
     and coalesce(p_rpe_enabled, false)
     and training_load.planned_rpe_effective_for_plan(p_plan_id, p_date)
$$;

CREATE FUNCTION training_load.planned_rpe_effective_for_plan(p_plan_id uuid, p_date date) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select exists (
    select 1
    from training_load.plan_workspace_ownership o
    join training_load.planned_rpe_workspace_settings s
      on s.owner_scope = o.owner_scope
     and s.owner_user_id is not distinct from o.owner_user_id
     and s.owner_club_id is not distinct from o.owner_club_id
     and s.owner_team_id is not distinct from o.owner_team_id
    join plans.plans p on p.id = o.plan_id
    join public.athletes a on a.id = p.athlete_id
    where o.plan_id = p_plan_id
      and s.enabled = true
      and p_date >= (s.enabled_at at time zone coalesce(a.device_timezone, 'UTC'))::date
  )
$$;

CREATE FUNCTION training_load.protect_batch_ownership_once_used() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  in_use boolean;
begin
  if new.owner_scope is not distinct from old.owner_scope
     and new.owner_user_id is not distinct from old.owner_user_id
     and new.owner_club_id is not distinct from old.owner_club_id
     and new.owner_team_id is not distinct from old.owner_team_id then
    return new;
  end if;
  select exists (select 1 from training_load.metric_measurement_occasions where import_batch_id = old.id) into in_use;
  if in_use then
    raise exception 'metric_import_batches (id=%) is already in use: owner_scope is immutable', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_builtin_series_semantics_once_used() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  in_use boolean;
begin
  if new.unit is not distinct from old.unit
     and new.value_type is not distinct from old.value_type
     and new.fixed_data_scope_level is not distinct from old.fixed_data_scope_level then
    return new;
  end if;
  select exists (select 1 from training_load.dashboard_widget_series where built_in_series_key = old.key) into in_use;
  if in_use then
    raise exception 'dashboard_builtin_series (key=%): already referenced by a widget — unit/value_type/scope semantics are immutable', old.key;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_connection_ownership_once_used() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  in_use boolean;
begin
  if new.owner_scope is not distinct from old.owner_scope
     and new.owner_user_id is not distinct from old.owner_user_id
     and new.owner_club_id is not distinct from old.owner_club_id
     and new.owner_team_id is not distinct from old.owner_team_id then
    return new;
  end if;
  select exists (select 1 from training_load.metric_events where source_connection_id = old.id)
      or exists (select 1 from training_load.metric_source_identities where source_connection_id = old.id)
    into in_use;
  if in_use then
    raise exception 'metric_source_connections (id=%) is already in use: owner_scope is immutable', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_dashboard_ownership_once_used() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.owner_scope is distinct from old.owner_scope
     or new.owner_user_id is distinct from old.owner_user_id
     or new.owner_club_id is distinct from old.owner_club_id
     or new.owner_team_id is distinct from old.owner_team_id
     or new.data_workspace_type is distinct from old.data_workspace_type
     or new.data_workspace_scope_id is distinct from old.data_workspace_scope_id then
    raise exception 'training_load.dashboards (id=%): owner_scope and data_workspace are immutable from creation — create or clone a new dashboard instead', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_dashboard_widget_series_widget_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.widget_id is distinct from old.widget_id then
    raise exception 'dashboard_widget_series (id=%): widget_id is immutable — delete and recreate the series under the new widget instead', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_dashboard_widget_types_once_used() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  in_use boolean;
begin
  if new.min_width is not distinct from old.min_width
     and new.max_width is not distinct from old.max_width
     and new.min_height is not distinct from old.min_height
     and new.max_height is not distinct from old.max_height
     and new.max_series is not distinct from old.max_series
     and new.has_shared_axis is not distinct from old.has_shared_axis
     and new.supports_comparison_period is not distinct from old.supports_comparison_period then
    return new;
  end if;
  select exists (select 1 from training_load.dashboard_widgets where widget_type = old.key) into in_use;
  if in_use then
    raise exception 'dashboard_widget_types (key=%): already referenced by a widget — size/series-cap/axis/comparison-period contract is immutable once in use; is_active, label, and the default_width/default_height picker hints stay mutable', old.key;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_dashboard_widgets_dashboard_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.dashboard_id is distinct from old.dashboard_id then
    raise exception 'dashboard_widgets (id=%): dashboard_id is immutable — delete and recreate the widget under the new dashboard instead', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_event_identity_once_measured() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  has_measurements boolean;
begin
  if new.owner_scope is not distinct from old.owner_scope
     and new.owner_user_id is not distinct from old.owner_user_id
     and new.owner_club_id is not distinct from old.owner_club_id
     and new.owner_team_id is not distinct from old.owner_team_id
     and new.source_connection_id is not distinct from old.source_connection_id
     and new.occurred_date is not distinct from old.occurred_date
     and new.occurred_instant is not distinct from old.occurred_instant
     and new.scope_level is not distinct from old.scope_level then
    return new;
  end if;
  select exists (
    select 1 from training_load.metric_event_participants p
    join training_load.metric_measurement_occasions o on o.event_participant_id = p.id
    where p.event_id = old.id
  ) into has_measurements;
  if has_measurements then
    raise exception 'metric_events (id=%) has dependent measurements: identity/date/scope fields are immutable', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_event_timezone_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_has_confirmed_link boolean;
begin
  if tg_op = 'UPDATE' and new.event_timezone_snapshot is distinct from old.event_timezone_snapshot then
    if old.event_timezone_snapshot is not null then
      raise exception 'metric_events (id=%): event_timezone_snapshot is write-once once set', old.id;
    end if;
    if new.event_timezone_snapshot is not null then
      select exists (
        select 1 from training.activity_metric_event_links where metric_event_id = old.id and link_status = 'confirmed'
      ) into v_has_confirmed_link;
      if v_has_confirmed_link then
        raise exception 'metric_events (id=%): cannot set event_timezone_snapshot once a CONFIRMED activity link already exists', old.id;
      end if;
    end if;
  end if;

  if new.event_timezone_snapshot is not null then
    if btrim(new.event_timezone_snapshot) = '' then
      raise exception 'metric_events (id=%): event_timezone_snapshot cannot be blank', coalesce(new.id, old.id);
    end if;
    begin
      perform now() at time zone new.event_timezone_snapshot;
    exception when others then
      raise exception 'metric_events (id=%): "%" is not a timezone Postgres recognizes', coalesce(new.id, old.id), new.event_timezone_snapshot;
    end;
  end if;

  if new.occurred_instant is not null and new.event_timezone_snapshot is not null
     and new.occurred_date is distinct from (new.occurred_instant at time zone new.event_timezone_snapshot)::date then
    raise exception 'metric_events (id=%): occurred_date (%) does not match occurred_instant (%) converted into event_timezone_snapshot (%)',
      coalesce(new.id, old.id), new.occurred_date, new.occurred_instant, new.event_timezone_snapshot;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_external_assignment_identity_and_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_old_rank integer; v_new_rank integer;
begin
  if NEW.occurrence_id is distinct from OLD.occurrence_id or NEW.athlete_id is distinct from OLD.athlete_id then
    raise exception 'training_load.external_assignments.% identity columns are immutable after creation', OLD.id;
  end if;
  if NEW.timezone is distinct from OLD.timezone
     or NEW.local_scheduled_date is distinct from OLD.local_scheduled_date
     or NEW.opens_at is distinct from OLD.opens_at
     or NEW.due_at is distinct from OLD.due_at
     or NEW.closes_at is distinct from OLD.closes_at
  then
    raise exception 'training_load.external_assignments.% timezone/window is an immutable snapshot taken once at materialization', OLD.id;
  end if;
  v_old_rank := case OLD.status when 'pending' then 1 when 'open' then 2 when 'in_progress' then 3 else 4 end;
  v_new_rank := case NEW.status when 'pending' then 1 when 'open' then 2 when 'in_progress' then 3 else 4 end;
  if v_old_rank = 4 and NEW.status <> OLD.status then
    raise exception 'training_load.external_assignments.% status % is terminal', OLD.id, OLD.status;
  end if;
  if v_new_rank < v_old_rank then
    raise exception 'training_load.external_assignments.% status cannot move backward from % to %', OLD.id, OLD.status, NEW.status;
  end if;
  return NEW;
end $$;

CREATE FUNCTION training_load.protect_external_occurrence_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if NEW.schedule_id is distinct from OLD.schedule_id
     or NEW.scheduled_date is distinct from OLD.scheduled_date
     or NEW.opens_at is distinct from OLD.opens_at
     or NEW.due_at is distinct from OLD.due_at
     or NEW.closes_at is distinct from OLD.closes_at
  then
    raise exception 'training_load.external_schedule_occurrences.% identity/window columns are immutable after creation - only status/assignments_materialized_at may change', OLD.id;
  end if;
  if OLD.assignments_materialized_at is not null
     and NEW.assignments_materialized_at is distinct from OLD.assignments_materialized_at
  then
    raise exception 'training_load.external_schedule_occurrences.% assignments_materialized_at is immutable once set', OLD.id;
  end if;
  return NEW;
end $$;

CREATE FUNCTION training_load.protect_gpexe_import_candidate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status = 'imported' then
      raise exception 'gpexe_import_candidates: a candidate is never inserted as imported; only its approval imports it';
    end if;
    return new;
  end if;
  if tg_op = 'DELETE' then
    if old.status = 'imported' then
      raise exception 'gpexe_import_candidates: candidate % was imported; its record is never deleted', old.id;
    end if;
    return old;
  end if;
  if new.owner_team_id is distinct from old.owner_team_id
     or new.gpexe_team_session_id is distinct from old.gpexe_team_session_id
     or new.bundle_hash is distinct from old.bundle_hash
     or new.first_seen_check_id is distinct from old.first_seen_check_id
     or new.first_seen_at is distinct from old.first_seen_at then
    raise exception 'gpexe_import_candidates: the team, session, content and first sighting of candidate % never change', old.id;
  end if;
  if old.status = 'imported' and (new.status is distinct from old.status or new.imported_at is distinct from old.imported_at) then
    raise exception 'gpexe_import_candidates: candidate % was imported; its status and import time are final', old.id;
  end if;
  if new.status = 'imported' and old.status is distinct from 'imported' then
    if old.status <> 'pending' then
      raise exception 'gpexe_import_candidates: candidate % is %, only a pending candidate can be imported', old.id, old.status;
    end if;
    if not exists (select 1 from training_load.gpexe_import_approvals a where a.candidate_id = new.id) then
      raise exception 'gpexe_import_candidates: candidate % has no recorded approval', old.id;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_gpexe_import_candidate_v57() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status = 'imported' then
      raise exception 'gpexe_import_candidates: a candidate is never inserted as imported; only its approval imports it';
    end if;
    if new.import_undone_at is not null or new.import_undone_request_id is not null then
      raise exception 'gpexe_import_candidates: a candidate is never inserted as undone';
    end if;
    return new;
  end if;
  if tg_op = 'DELETE' then
    if old.status = 'imported' then
      raise exception 'gpexe_import_candidates: candidate % was imported; its record is never deleted', old.id;
    end if;
    return old;
  end if;
  if new.owner_team_id is distinct from old.owner_team_id
     or new.gpexe_team_session_id is distinct from old.gpexe_team_session_id
     or new.bundle_hash is distinct from old.bundle_hash
     or new.first_seen_check_id is distinct from old.first_seen_check_id
     or new.first_seen_at is distinct from old.first_seen_at then
    raise exception 'gpexe_import_candidates: the team, session, content and first sighting of candidate % never change', old.id;
  end if;
  if old.import_undone_at is not null then
    if new.import_undone_at is distinct from old.import_undone_at
       or new.import_undone_request_id is distinct from old.import_undone_request_id then
      raise exception 'gpexe_import_candidates: the undo of candidate % is final', old.id;
    end if;
  elsif new.import_undone_at is not null or new.import_undone_request_id is not null then
    if old.status is distinct from 'imported' then
      raise exception 'gpexe_import_candidates: only an imported candidate can be undone (candidate % is %)', old.id, old.status;
    end if;
    if not training_load.session_undo_marker_ok() then
      raise exception 'gpexe_import_candidates: a candidate is marked undone only by undo_imported_session' using errcode = '42501';
    end if;
  end if;
  if old.status = 'imported' and (new.status is distinct from old.status or new.imported_at is distinct from old.imported_at) then
    raise exception 'gpexe_import_candidates: candidate % was imported; its status and import time are final', old.id;
  end if;
  if new.status = 'imported' and old.status is distinct from 'imported' then
    if old.status <> 'pending' then
      raise exception 'gpexe_import_candidates: candidate % is %, only a pending candidate can be imported', old.id, old.status;
    end if;
    if not exists (select 1 from training_load.gpexe_import_approvals a where a.candidate_id = new.id) then
      raise exception 'gpexe_import_candidates: candidate % has no recorded approval', old.id;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_identity_source_once_measured() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  has_measurements boolean;
begin
  if new.source_connection_id is not distinct from old.source_connection_id
     and new.source_external_id is not distinct from old.source_external_id then
    return new;
  end if;
  select exists (select 1 from training_load.metric_measurement_occasions where source_identity_id = old.id) into has_measurements;
  if has_measurements then
    raise exception 'metric_source_identities (id=%) has dependent measurements: source_connection_id/source_external_id is immutable', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_occasion_identity_always() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.event_participant_id is distinct from old.event_participant_id
     or new.segment_id is distinct from old.segment_id
     or new.source_identity_id is distinct from old.source_identity_id
     or new.import_batch_id is distinct from old.import_batch_id
     or new.entry_method is distinct from old.entry_method
     or new.content_hash is distinct from old.content_hash
     or new.source_reported_at is distinct from old.source_reported_at
  then
    raise exception 'metric_measurement_occasions (id=%) identity/content fields are immutable after insert — reparenting an existing measurement is not a valid correction, supersede with a new occasion instead', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_participant_identity_once_measured() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  has_measurements boolean;
begin
  if new.event_id is not distinct from old.event_id
     and new.athlete_id is not distinct from old.athlete_id
     and new.athlete_timezone_snapshot is not distinct from old.athlete_timezone_snapshot
     and new.logical_session_id is not distinct from old.logical_session_id
     and new.external_assignment_id is not distinct from old.external_assignment_id
     and new.linked_session_name_snapshot is not distinct from old.linked_session_name_snapshot
     and new.linked_plan_name_snapshot is not distinct from old.linked_plan_name_snapshot then
