  end if;
  select exists (select 1 from training_load.metric_measurement_occasions where event_participant_id = old.id) into has_measurements;
  if has_measurements then
    raise exception 'metric_event_participants (id=%) has dependent measurements: identity/snapshot fields are immutable', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_scope_capability_with_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_has_history boolean;
begin
  select exists (
    select 1
    from training_load.metric_values v
    join training_load.metric_measurement_occasions o on o.id = v.occasion_id
    join training_load.metric_event_participants p on p.id = o.event_participant_id
    join training_load.metric_events e on e.id = p.event_id
    where v.metric_definition_id = old.metric_definition_id
      and (case when e.scope_level = 'day' then 'day' when o.segment_id is not null then 'component' else 'session' end) = old.scope_level
  ) into v_has_history;
  if v_has_history then
    raise exception 'metric_definition_scope_capabilities: cannot remove scope ''%'' for definition % — real historical values already exist at that scope', old.scope_level, old.metric_definition_id;
  end if;
  return old;
end;
$$;

CREATE FUNCTION training_load.protect_segment_identity_once_measured() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  has_measurements boolean;
begin
  if new.event_id is not distinct from old.event_id then
    return new;
  end if;
  select exists (select 1 from training_load.metric_measurement_occasions where segment_id = old.id) into has_measurements;
  if has_measurements then
    raise exception 'metric_event_segments (id=%) has dependent measurements: event_id is immutable', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.protect_session_feedback_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if NEW.athlete_id is distinct from OLD.athlete_id
     or NEW.logical_session_id is distinct from OLD.logical_session_id
     or NEW.source is distinct from OLD.source
     or NEW.external_assignment_id is distinct from OLD.external_assignment_id
     or NEW.event_name is distinct from OLD.event_name
     or NEW.session_date is distinct from OLD.session_date
     or NEW.plan_name is distinct from OLD.plan_name
     or NEW.plan_week_start is distinct from OLD.plan_week_start
     or NEW.session_name is distinct from OLD.session_name
     or NEW.session_time is distinct from OLD.session_time
     or NEW.session_am_pm is distinct from OLD.session_am_pm
     or NEW.session_bta is distinct from OLD.session_bta
     or NEW.rpe is distinct from OLD.rpe
     or NEW.duration_minutes is distinct from OLD.duration_minutes
     or NEW.athlete_note is distinct from OLD.athlete_note
     or NEW.submitted_at is distinct from OLD.submitted_at
     or NEW.created_at is distinct from OLD.created_at
  then
    raise exception 'training_load.session_feedback.% is an immutable snapshot once created - only plan_session_id (the nullable best-effort backreference) may ever change', OLD.id;
  end if;
  return NEW;
end $$;

CREATE FUNCTION training_load.purge_expired_gpexe_athlete_identities(p_limit integer DEFAULT 200) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  purged integer;
begin
  delete from training_load.gpexe_athlete_identities
   where id in (
     select id from training_load.gpexe_athlete_identities
      where expires_at <= now()
      order by expires_at
      limit greatest(p_limit, 1)
      for update skip locked
   );
  get diagnostics purged = row_count;
  return purged;
end;
$$;

CREATE FUNCTION training_load.purge_expired_gpexe_athlete_identity_suppressions(p_limit integer DEFAULT 200) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  purged integer;
begin
  delete from training_load.gpexe_athlete_identity_suppressions
   where id in (
     select id from training_load.gpexe_athlete_identity_suppressions
      where retry_after <= now()
      order by retry_after
      limit greatest(p_limit, 1)
      for update skip locked
   );
  get diagnostics purged = row_count;
  return purged;
end;
$$;

CREATE FUNCTION training_load.purge_expired_gpexe_raw(p_limit integer DEFAULT 200) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  purged integer;
begin
  update training_load.gpexe_import_candidates c
     set raw_bundle = null, preview = null, raw_purged_at = now()
   where c.id in (
     select id from training_load.gpexe_import_candidates
      where raw_bundle is not null and raw_expires_at <= now()
      order by raw_expires_at
      limit greatest(p_limit, 1)
      for update skip locked
   );
  get diagnostics purged = row_count;
  return purged;
end;
$$;

CREATE FUNCTION training_load.record_gpexe_team_setting() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  insert into training_load.gpexe_team_settings_history (owner_team_id, gpexe_team_id, configured_by_user_id, configured_at, change_reason)
  values (new.owner_team_id, new.gpexe_team_id, new.configured_by_user_id, new.configured_at, new.change_reason);
  return new;
end;
$$;

CREATE FUNCTION training_load.record_import_prerequisite(p_actor uuid, p_kind text, p_recorded_on date, p_note text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
declare
  v_id uuid;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  perform 1 from public.users u where u.id = p_actor and u.is_active = true for share;
  if not found then
    raise exception 'user % may not record import prerequisites', p_actor using errcode = '42501';
  end if;
  perform 1 from public.user_global_roles r where r.user_id = p_actor and r.role = 'platform_admin' and r.is_active = true for share;
  if not found then
    raise exception 'user % may not record import prerequisites', p_actor using errcode = '42501';
  end if;
  if p_kind is null or p_kind not in ('backup', 'restore_probe', 'wrong_link_procedure', 'archived_team_check_stop') then
    raise exception 'record_import_prerequisite: unknown kind' using errcode = '22023';
  end if;
  if p_recorded_on is null or p_recorded_on > current_date or p_recorded_on < current_date - 400 then
    raise exception 'record_import_prerequisite: the date must be today or in the past (at most 400 days)' using errcode = '22023';
  end if;
  if v_note is not null and (length(v_note) > 300 or v_note ~ '[[:cntrl:]]') then
    raise exception 'record_import_prerequisite: the note is at most 300 characters without control characters' using errcode = '22023';
  end if;
  perform set_config('optimove.team_import_tx', txid_current()::text, true);
  insert into training_load.gpexe_import_prerequisite_records (kind, recorded_on, recorded_by_user_id, note)
    values (p_kind, p_recorded_on, p_actor, v_note) returning id into v_id;
  return v_id;
end;
$$;

CREATE FUNCTION training_load.refuse_gpexe_check_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'gpexe_import_checks: a check of team % is never deleted (it records which GPEXE team was read)', old.owner_team_id;
end;
$$;

CREATE FUNCTION training_load.refuse_gpexe_settings_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'gpexe_team_settings: a GPEXE connection is never deleted (team %, GPEXE team %); disconnecting is not supported yet',
    old.owner_team_id, old.gpexe_team_id;
end;
$$;

CREATE FUNCTION training_load.refuse_gpexe_settings_orphans() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  orphan text;
begin
  perform training_load.hold_gpexe_team_lock(new.owner_team_id, 'first connection');
  select what into orphan from (
    select 'a session found by a check' as what
      where exists (select 1 from training_load.gpexe_import_candidates where owner_team_id = new.owner_team_id)
    union all
    select 'a check'
      where exists (select 1 from training_load.gpexe_import_checks where owner_team_id = new.owner_team_id)
    union all
    select 'a GPEXE athlete linked to an OptiMove athlete'
      where exists (select 1 from training_load.gpexe_athlete_links where owner_team_id = new.owner_team_id)
    union all
    select 'an approved import'
      where exists (select 1 from training_load.gpexe_import_approvals where owner_team_id = new.owner_team_id)
    union all
    select 'imported GPEXE data'
      where exists (
        select 1 from training_load.metric_source_connections c
        where c.source_system = 'gpexe' and c.owner_scope = 'team' and c.owner_team_id = new.owner_team_id
          and (c.state = 'active' or exists (select 1 from training_load.metric_events e where e.source_connection_id = c.id))
      )
  ) orphans limit 1;
  if orphan is not null then
    raise exception 'gpexe_team_settings: team % already has % from a GPEXE team that is not recorded; connecting it needs a platform admin to resolve that first',
      new.owner_team_id, orphan;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.refuse_gpexe_team_change_while_bound() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if training_load.gpexe_team_id_canonical(new.gpexe_team_id) is not distinct from training_load.gpexe_team_id_canonical(old.gpexe_team_id)
     and new.owner_team_id is not distinct from old.owner_team_id then
    return new;
  end if;
  if exists (
    select 1 from training_load.source_team_bindings b
     where b.team_id = old.owner_team_id and b.source_system = 'gpexe' and b.state = 'active'
  ) then
    raise exception 'gpexe_team_settings: team % is bound to GPEXE team % through a source connection; the approved GPEXE team cannot change while that binding is active (end the binding first)',
      old.owner_team_id, old.gpexe_team_id
      using errcode = 'check_violation', constraint = 'gpexe_team_settings_bound_team_final';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.refuse_gpexe_team_repoint() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  depends_on text;
begin
  -- The row belongs to one OptiMove team for good: moving it would carry a
  -- GPEXE team, its links and its imported data to another team's name.
  if new.owner_team_id is distinct from old.owner_team_id then
    raise exception 'gpexe_team_settings: the OptiMove team of a GPEXE connection is final (% -> %)',
      old.owner_team_id, new.owner_team_id;
  end if;
  if new.gpexe_team_id is not distinct from old.gpexe_team_id then
    -- Same GPEXE team: the only accepted write is one that changes nothing.
    -- Returning null cancels it, so the history trigger never fires and no
    -- row is appended for a write that said nothing new.
    if new.change_reason is not distinct from old.change_reason
       and new.configured_by_user_id is not distinct from old.configured_by_user_id
       and new.configured_at is not distinct from old.configured_at then
      return null;
    end if;
    raise exception 'gpexe_team_settings: for team %, the reason, the author and the time can only change together with the GPEXE team',
      old.owner_team_id;
  end if;
  -- The rows below are only evidence if nothing may be writing them right
  -- now, so this refusal holds the team import lock the application takes
  -- (gpexeImportWriter.lockTeamForImport, seed 21). A session that already
  -- holds it - the application's own change - gets it again at once; a raw
  -- UPDATE racing a check, a link or an import does not, and is refused
  -- instead of waiting: waiting here would deadlock against the application,
  -- which takes this lock first and the row second.
  perform training_load.hold_gpexe_team_lock(old.owner_team_id, 'connection change');
  if new.change_reason is null then
    raise exception 'gpexe_team_settings: changing the GPEXE team of % needs a reason', old.owner_team_id
      using errcode = 'check_violation';
  end if;
  select what into depends_on from (
    select 'a session found by a check' as what
      where exists (select 1 from training_load.gpexe_import_candidates where owner_team_id = old.owner_team_id)
    union all
    select 'a check'
      where exists (select 1 from training_load.gpexe_import_checks where owner_team_id = old.owner_team_id)
    union all
    select 'a GPEXE athlete linked to an OptiMove athlete'
      where exists (select 1 from training_load.gpexe_athlete_links where owner_team_id = old.owner_team_id)
    union all
    select 'an approved import'
      where exists (select 1 from training_load.gpexe_import_approvals where owner_team_id = old.owner_team_id)
    union all
    select 'imported GPEXE data'
      where exists (
        select 1 from training_load.metric_source_connections c
        where c.source_system = 'gpexe' and c.owner_scope = 'team' and c.owner_team_id = old.owner_team_id
          and (c.state = 'active' or exists (select 1 from training_load.metric_events e where e.source_connection_id = c.id))
      )
  ) blockers limit 1;
  if depends_on is not null then
    -- Default SQLSTATE P0001, like the other guards in this subsystem.
    raise exception 'gpexe_team_settings: team % already has % from GPEXE team %; the connection can no longer be changed',
      old.owner_team_id, depends_on, old.gpexe_team_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.refuse_unapproved_gpexe_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  approved text;
begin
  if new.source_system <> 'gpexe' or new.state <> 'active' then
    return new;
  end if;
  if new.legacy_gpexe_settings_team_id is null or new.legacy_gpexe_settings_team_id is distinct from new.team_id then
    raise exception 'source_team_bindings: an active GPEXE binding of team % must point at that team''s own approved GPEXE setting (legacy_gpexe_settings_team_id)', new.team_id
      using errcode = 'check_violation', constraint = 'source_team_bindings_approved_pair';
  end if;
  select gpexe_team_id into approved from training_load.gpexe_team_settings where owner_team_id = new.team_id for share;
  if not found then
    raise exception 'source_team_bindings: team % has no approved GPEXE team in gpexe_team_settings; nothing can be bound', new.team_id
      using errcode = 'check_violation', constraint = 'source_team_bindings_approved_pair_missing';
  end if;
  if training_load.gpexe_team_id_canonical(approved) is distinct from training_load.gpexe_team_id_canonical(new.source_team_id) then
    raise exception 'source_team_bindings: team % is approved for GPEXE team %, not for %', new.team_id, approved, new.source_team_id
      using errcode = 'check_violation', constraint = 'source_team_bindings_approved_pair';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.reorder_series(p_widget_id uuid, p_expected_widget_revision integer, p_order jsonb) RETURNS TABLE(widget_revision integer)
    LANGUAGE plpgsql
    AS $$
declare
  v_dashboard_id uuid;
  v_current_widget_revision integer;
  v_entry jsonb;
  v_updated uuid;
begin
  select w.dashboard_id into v_dashboard_id from training_load.dashboard_widgets w where w.id = p_widget_id;
  if not found then
    raise exception 'reorder_series: widget % not found', p_widget_id;
  end if;
  perform 1 from training_load.dashboards d where d.id = v_dashboard_id for update;
  perform training_load.assert_dashboard_writable(v_dashboard_id);
  select w.revision into v_current_widget_revision from training_load.dashboard_widgets w where w.id = p_widget_id for update;
  if v_current_widget_revision <> p_expected_widget_revision then
    raise exception 'reorder_series: stale widget revision (expected %, widget is at %) — reload and retry', p_expected_widget_revision, v_current_widget_revision using errcode = '40001';
  end if;
  for v_entry in select * from jsonb_array_elements(p_order) loop
    update training_load.dashboard_widget_series s set series_order = (v_entry ->> 'seriesOrder')::integer
      where s.id = (v_entry ->> 'seriesId')::uuid and s.widget_id = p_widget_id
      returning s.id into v_updated;
    if v_updated is null then
      raise exception 'reorder_series: series % does not belong to widget %', v_entry ->> 'seriesId', p_widget_id;
    end if;
  end loop;
  set constraints training_load.dashboard_widget_series_order_unique immediate;
  return query select w.revision from training_load.dashboard_widgets w where w.id = p_widget_id;
end;
$$;

CREATE FUNCTION training_load.replace_dashboard_layout(p_dashboard_id uuid, p_expected_revision integer, p_layout jsonb) RETURNS TABLE(widget_id uuid, x smallint, y smallint, width smallint, height smallint, mobile_order integer, revision integer, dashboard_revision integer)
    LANGUAGE plpgsql
    AS $$
declare
  v_current_revision integer;
  v_entry jsonb;
begin
  select d.revision into v_current_revision from training_load.dashboards d where d.id = p_dashboard_id for update;
  if not found then
    raise exception 'replace_dashboard_layout: dashboard % not found', p_dashboard_id;
  end if;
  perform training_load.assert_dashboard_writable(p_dashboard_id);
  if v_current_revision <> p_expected_revision then
    raise exception 'replace_dashboard_layout: stale revision (expected %, dashboard is at %) — reload and retry', p_expected_revision, v_current_revision using errcode = '40001';
  end if;

  for v_entry in select * from jsonb_array_elements(p_layout) loop
    -- Table alias `w` + qualified column references throughout — the
    -- bare column names (x, width, ...) would otherwise collide with
    -- this FUNCTION's own RETURNS TABLE out-parameter names.
    update training_load.dashboard_widgets w
      set x = coalesce((v_entry ->> 'x')::smallint, w.x),
          y = coalesce((v_entry ->> 'y')::smallint, w.y),
          width = coalesce((v_entry ->> 'width')::smallint, w.width),
          height = coalesce((v_entry ->> 'height')::smallint, w.height),
          mobile_order = coalesce((v_entry ->> 'mobileOrder')::integer, w.mobile_order)
      where w.id = (v_entry ->> 'widgetId')::uuid and w.dashboard_id = p_dashboard_id;
    if not found then
      raise exception 'replace_dashboard_layout: widget % does not belong to dashboard %', v_entry ->> 'widgetId', p_dashboard_id;
    end if;
  end loop;

  -- Force the deferred overlap check (and the deferred widget_order/
  -- mobile_order uniqueness constraints) to run NOW, inside this
  -- function's own transaction scope.
  set constraints training_load.dashboard_widgets_check_no_overlap, training_load.dashboard_widgets_order_unique, training_load.dashboard_widgets_mobile_order_unique immediate;

  -- Each per-widget UPDATE above already bumps dashboards.revision on its
  -- own (dashboard_widgets_bump_revision's layout branch) — this extra,
  -- explicit call is kept anyway as a deliberate, unconditional
  -- guarantee, and keeps this function's own correctness independent of
  -- exactly how that trigger is implemented. A harmless double-bump on
  -- the normal (non-empty) path is explicitly fine — the caller's own
  -- contract is "the returned token is fresh and sole-authoritative", not
  -- "revision increments by exactly 1".
  perform training_load.bump_dashboard_revision(p_dashboard_id);

  return query
    select w.id, w.x, w.y, w.width, w.height, w.mobile_order, w.revision, d.revision
    from training_load.dashboard_widgets w
    join training_load.dashboards d on d.id = w.dashboard_id
    where w.dashboard_id = p_dashboard_id and w.id in (select (e ->> 'widgetId')::uuid from jsonb_array_elements(p_layout) e);
end;
$$;

CREATE FUNCTION training_load.require_gpexe_check_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  b record;
  c record;
begin
  -- The same team import try-lock every writer of these facts takes (v24
  -- hold_gpexe_team_lock; reentrant for the application, which already holds
  -- it): the reads below cannot race a bind, an Unbind or a Reconnect,
  -- whatever order a future trigger sorts in.
  perform training_load.hold_gpexe_team_lock(new.owner_team_id, 'check source');
  if new.source_path = 'legacy_env' then
    -- The environment token is for a team that NEVER had a gpexe source
    -- binding: once one exists, active or ended, a legacy row is refused by
    -- the database itself, whoever writes it. Rows from before the team's
    -- first binding stay (history).
    if exists (select 1 from training_load.source_team_bindings sb
                where sb.team_id = new.owner_team_id and sb.source_system = 'gpexe') then
      raise exception 'gpexe_import_checks: check of team % cannot read through the environment token: the team has or had a gpexe source binding', new.owner_team_id
        using errcode = 'check_violation', constraint = 'gpexe_import_checks_legacy_path_never_bound';
    end if;
    return new;
  end if;
  select team_id, connection_id, source_team_id, state, source_system
    into b
    from training_load.source_team_bindings
   where id = new.source_binding_id;
  if b is null then
    raise exception 'gpexe_import_checks: check of team % names a source binding that does not exist', new.owner_team_id;
  end if;
  if b.source_system <> 'gpexe' then
    raise exception 'gpexe_import_checks: check of team % names a binding of another source than gpexe', new.owner_team_id;
  end if;
  if b.state <> 'active' then
    raise exception 'gpexe_import_checks: check of team % names a source binding that is not active', new.owner_team_id;
  end if;
  if b.team_id is distinct from new.owner_team_id then
    raise exception 'gpexe_import_checks: check of team % names a source binding of another team', new.owner_team_id;
  end if;
  if b.connection_id is distinct from new.source_connection_id then
    raise exception 'gpexe_import_checks: check of team % names a connection other than its binding''s', new.owner_team_id;
  end if;
  if b.source_team_id is distinct from new.source_team_id then
    raise exception 'gpexe_import_checks: check of team % names a source team other than its binding''s', new.owner_team_id;
  end if;
  select host_key, source_system
    into c
    from training_load.source_credential_connections
   where id = new.source_connection_id;
  if c is null then
    raise exception 'gpexe_import_checks: check of team % names a source connection that does not exist', new.owner_team_id;
  end if;
  if c.host_key is distinct from new.source_host_key then
    raise exception 'gpexe_import_checks: check of team % names a host key other than its connection''s', new.owner_team_id;
  end if;
  if c.source_system is distinct from b.source_system then
    raise exception 'gpexe_import_checks: check of team % names a connection of another source than its binding', new.owner_team_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.require_gpexe_check_team() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  connected text;
begin
  perform training_load.hold_gpexe_team_lock(new.owner_team_id, 'check');
  select gpexe_team_id into connected from training_load.gpexe_team_settings where owner_team_id = new.owner_team_id;
  if connected is null then
    raise exception 'gpexe_import_checks: team % has no GPEXE team yet', new.owner_team_id;
  end if;
  if new.gpexe_team_id is null then
    raise exception 'gpexe_import_checks: a check records the GPEXE team it reads (team %)', new.owner_team_id;
  end if;
  if new.gpexe_team_id is distinct from connected then
    raise exception 'gpexe_import_checks: check of team % says GPEXE team % while the team is connected to %',
      new.owner_team_id, new.gpexe_team_id, connected;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.require_gpexe_connection_for_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  -- The owning team never changes (v22's own link guard refuses that), and
  -- this trigger also runs on INSERT, where OLD has no tuple at all: NEW is
  -- the one row both operations always have.
  team uuid := new.owner_team_id;
begin
  perform training_load.hold_gpexe_team_lock(team, 'athlete link');
  if tg_op = 'INSERT' and not exists (select 1 from training_load.gpexe_team_settings where owner_team_id = team) then
    raise exception 'gpexe_athlete_links: team % has no GPEXE team yet, so a GPEXE athlete number means nothing for it', team;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.resolve_current_external_target_dates(p_schedule_id uuid) RETURNS TABLE(local_date date)
    LANGUAGE sql STABLE
    AS $$
  with sch as (select * from training_load.external_schedules where id = p_schedule_id),
  per_athlete as (
    select (now() at time zone coalesce(a.device_timezone, sch.timezone))::date as local_date,
           sch.schedule_kind, sch.start_date, sch.end_date
    from training_load.resolve_external_schedule_target_athletes(p_schedule_id) ta
    join public.athletes a on a.id = ta.athlete_id
    cross join sch
  ),
  from_current_targets as (
    select distinct local_date from per_athlete
    where (
      (schedule_kind = 'one_time' and local_date = start_date)
      or (schedule_kind = 'recurring' and local_date >= start_date and (end_date is null or local_date <= end_date))
      or (schedule_kind = 'dates' and exists (
            select 1 from training_load.external_schedule_dates d
            where d.schedule_id = p_schedule_id and d.scheduled_date = per_athlete.local_date
          ))
    )
  ),
  from_outstanding_snapshot as (
    select distinct o.scheduled_date as local_date
    from training_load.external_schedule_occurrences o
    join training_load.external_occurrence_target_snapshot s on s.occurrence_id = o.id
    where o.schedule_id = p_schedule_id
      and not exists (
        select 1 from training_load.external_assignments asg
        where asg.occurrence_id = o.id and asg.athlete_id = s.athlete_id
      )
  )
  select local_date from from_current_targets
  union
  select local_date from from_outstanding_snapshot
$$;

CREATE FUNCTION training_load.resolve_external_schedule_target_athletes(p_schedule_id uuid) RETURNS TABLE(athlete_id uuid)
    LANGUAGE sql STABLE
    AS $$
  select t.target_athlete_id as athlete_id
  from training_load.external_schedule_targets t
  where t.schedule_id = p_schedule_id and t.target_kind = 'athlete'
  union
  select m.athlete_id
  from training_load.external_schedule_targets t
  join public.athlete_memberships m on m.membership_type = 'team' and m.team_id = t.target_team_id and m.status = 'active'
  where t.schedule_id = p_schedule_id and t.target_kind = 'team'
  union
  select m.athlete_id
  from training_load.external_schedule_targets t
  join public.athlete_memberships m on m.membership_type = 'club' and m.club_id = t.target_club_id and m.status = 'active'
  where t.schedule_id = p_schedule_id and t.target_kind = 'club'
$$;

CREATE FUNCTION training_load.resolve_series_binding(p_series_id uuid, p_widget_id uuid, p_expected_widget_revision integer, p_metric_definition_id uuid) RETURNS TABLE(series_id uuid, widget_revision integer)
    LANGUAGE plpgsql
    AS $$
declare
  v_dashboard_id uuid;
  v_current_widget_revision integer;
  v_current_status varchar;
begin
  select w.dashboard_id into v_dashboard_id from training_load.dashboard_widgets w where w.id = p_widget_id;
  if not found then
    raise exception 'resolve_series_binding: widget % not found', p_widget_id;
  end if;
  perform 1 from training_load.dashboards d where d.id = v_dashboard_id for update;
  perform training_load.assert_dashboard_writable(v_dashboard_id);
  select w.revision into v_current_widget_revision from training_load.dashboard_widgets w where w.id = p_widget_id for update;
  if v_current_widget_revision <> p_expected_widget_revision then
    raise exception 'resolve_series_binding: stale widget revision (expected %, widget is at %) — reload and retry', p_expected_widget_revision, v_current_widget_revision using errcode = '40001';
  end if;
  select resolution_status into v_current_status from training_load.dashboard_widget_series where id = p_series_id and widget_id = p_widget_id;
  if not found then
    raise exception 'resolve_series_binding: series % not found under widget %', p_series_id, p_widget_id;
  end if;
  if v_current_status = 'resolved' then
    raise exception 'resolve_series_binding: series % is already resolved — nothing to bind', p_series_id;
  end if;
  if p_metric_definition_id is null then
    raise exception 'resolve_series_binding: p_metric_definition_id is required';
  end if;
  update training_load.dashboard_widget_series s set
    metric_definition_id = p_metric_definition_id,
    resolution_status = 'resolved',
    template_resolution_candidates = null
  where s.id = p_series_id and s.widget_id = p_widget_id;
  return query select p_series_id, w.revision from training_load.dashboard_widgets w where w.id = p_widget_id;
end;
$$;

CREATE FUNCTION training_load.session_undo_add(p_counts jsonb, p_label text, p_n integer) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  select p_counts || jsonb_build_object(p_label, coalesce((p_counts ->> p_label)::int, 0) + p_n);
$$;

CREATE FUNCTION training_load.session_undo_marker_ok() RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select coalesce(current_setting('optimove.session_undo_tx', true) = txid_current()::text, false);
$$;

CREATE FUNCTION training_load.session_undo_refuse(p_code text, p_detail text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'session_undo:%', p_code using errcode = '55000', detail = coalesce(p_detail, '');
end;
$$;

CREATE FUNCTION training_load.session_undo_request_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op <> 'INSERT' then
    raise exception 'gpexe_session_undo_requests is append-only (% refused)', tg_op using errcode = '23514';
  end if;
  if not training_load.session_undo_marker_ok() then
    raise exception 'gpexe_session_undo_requests is written only by undo_imported_session' using errcode = '42501';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.session_undo_scope(p_event uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
declare
  v_event record;
  v_part uuid[];
  v_occ uuid[];
  v_seg uuid[];
  v_ident uuid[];
  v_batch uuid[];
  v_act uuid[];
  v_obs uuid[];
  v_reached uuid[];
  v_alias uuid[];
  v_binding record;
  v_values integer := 0;
  v_manual integer := 0;
  v_shared integer := 0;
  v_other_links integer := 0;
  v_entangled integer := 0;
  v_calendar integer := 0;
  v_write_requests integer := 0;
  v_work record;
begin
  select e.id, e.source_connection_id, e.source_external_id, e.owner_team_id, e.occurred_date, c.source_system
    into v_event
    from training_load.metric_events e
    left join training_load.metric_source_connections c on c.id = e.source_connection_id
   where e.id = p_event;
  if not found then
    perform training_load.session_undo_refuse('event_missing');
  end if;
  v_part := coalesce(array(select id from training_load.metric_event_participants where event_id = p_event order by id), '{}');
  v_occ := coalesce(array(select id from training_load.metric_measurement_occasions where event_participant_id = any(v_part) order by id), '{}');
  select count(*)::int into v_manual from training_load.metric_measurement_occasions where id = any(v_occ) and entry_method = 'manual';
  select count(*)::int into v_values from training_load.metric_values where occasion_id = any(v_occ);
  v_seg := coalesce(array(select id from training_load.metric_event_segments where event_id = p_event order by id), '{}');
  select b.event_id, b.reference_set_external_id into v_binding from training_load.metric_event_source_bindings b where b.event_id = p_event;
  v_batch := coalesce(array(select distinct import_batch_id from training_load.metric_measurement_occasions where id = any(v_occ) and import_batch_id is not null order by 1), '{}');
  -- The occasions' identities and the session's own reservation identity (found through the EVENT's connection and
  -- external id, not the binding's: a binding may be absent).
  v_ident := coalesce(array(
    select id from (
      select source_identity_id as id from training_load.metric_measurement_occasions where id = any(v_occ) and source_identity_id is not null
      union
      select si.id from training_load.metric_source_identities si
       where v_event.source_connection_id is not null and v_event.source_external_id is not null
         and si.source_connection_id = v_event.source_connection_id and si.source_external_id = v_event.source_external_id
    ) x order by id), '{}');
  -- The activities this session reaches: through its participants OR a direct event link.
  v_reached := coalesce(array(
    select activity_id from (
      select ap.activity_id
        from training.activity_participants ap
        join training.activity_participant_metric_participant_links pl on pl.activity_participant_id = ap.id
       where pl.metric_event_participant_id = any(v_part)
      union
      select activity_id from training.activity_metric_event_links where metric_event_id = p_event
    ) r order by activity_id), '{}');
  v_act := coalesce(array(
    select distinct ap.activity_id
      from training.activity_participants ap
      join training.activity_participant_metric_participant_links l on l.activity_participant_id = ap.id
     where l.metric_event_participant_id = any(v_part)
     order by 1), '{}');
  select count(*)::int into v_shared
    from training.activity_participants ap2
    join training.activity_participant_metric_participant_links l2 on l2.activity_participant_id = ap2.id
    join training_load.metric_event_participants p2 on p2.id = l2.metric_event_participant_id
   where ap2.activity_id = any(v_act) and p2.event_id <> p_event;
  select count(*)::int into v_other_links
    from training.activity_metric_event_links l
   where l.activity_id = any(v_reached) and l.metric_event_id <> p_event;
  select count(*)::int into v_entangled
    from training.activities a
   where a.id = any(v_reached)
     and (a.lifecycle_state = 'superseded' or a.superseded_by_activity_id is not null
          or exists (select 1 from training.activity_participant_merge_log m where m.source_activity_id = a.id or m.target_activity_id = a.id)
          or exists (select 1 from training.activity_participant_reparent_log r where r.from_activity_id = a.id or r.to_activity_id = a.id));
  -- The whole alias set of every reached activity (v25 rosters).
  v_alias := coalesce(array(
    select aa.activity_id
      from (select distinct training.resolve_canonical_activity_id(r) as canonical_id from unnest(v_reached) r) c
      cross join lateral training.activity_alias_ids(c.canonical_id) aa
     order by 1), '{}');
  select (select count(*)::int from training.activity_athlete_decisions where activity_id = any(v_alias)) as decisions,
         (select count(*)::int from training.activity_roster_requests where activity_id = any(v_alias)) as requests,
         (select count(*)::int from training.activity_completions where activity_id = any(v_alias)) as completions,
         (select count(*)::int from training.activity_completion_log where activity_id = any(v_alias)) as completion_log
    into v_work;
  v_obs := coalesce(array(select id from training.activity_source_observations where activity_id = any(v_alias) order by id), '{}');
  select count(*)::int into v_calendar from calendar.event_activity_links where activity_id = any(v_reached) or activity_id = any(v_alias);
  select count(*)::int into v_write_requests from training_load.metric_write_requests
   where result_event_id = p_event or result_occasion_id = any(v_occ);
  return jsonb_build_object(
    'eventId', p_event,
    'connectionId', v_event.source_connection_id,
    'ownerTeamId', v_event.owner_team_id,
    'occurredDate', v_event.occurred_date,
    'sourceSystem', v_event.source_system,
    'externalId', v_event.source_external_id,
    'participantIds', to_jsonb(v_part),
    'occasionIds', to_jsonb(v_occ),
    'valueCount', v_values,
    'segmentIds', to_jsonb(v_seg),
    'identityIds', to_jsonb(v_ident),
    'hasBinding', v_binding.event_id is not null,
    'referenceSetExternalId', v_binding.reference_set_external_id,
    'activityIds', to_jsonb(v_act),
    'batchIds', to_jsonb(v_batch),
    'observationIds', to_jsonb(v_obs),
    'manualOccasionCount', v_manual,
    'sharedActivityCount', v_shared,
    'otherEventLinkCount', v_other_links,
    'entangledActivityCount', v_entangled,
    'calendarLinkCount', v_calendar,
    'manualWriteRequestCount', v_write_requests,
    'rosterWork', jsonb_build_object('decisions', v_work.decisions, 'requests', v_work.requests,
                                     'completions', v_work.completions, 'completionLog', v_work.completion_log));
end;
-- Volatile on purpose: every statement of the body takes its own snapshot, so the second look (after the activities are
-- locked) sees a link committed while the lock was waited for.
$$;

CREATE FUNCTION training_load.set_active_dashboard(p_user_id uuid, p_workspace_type character varying, p_scope_id uuid, p_dashboard_id uuid) RETURNS TABLE(out_selection_id uuid, out_dashboard_id uuid, out_workspace_type character varying, out_scope_id uuid, out_updated_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
declare
  v_selection_id uuid;
begin
  perform 1 from training_load.dashboards where id = p_dashboard_id for update;
  insert into training_load.dashboard_active_selection (user_id, workspace_type, scope_id, dashboard_id)
  values (p_user_id, p_workspace_type, p_scope_id, p_dashboard_id)
  on conflict (user_id, workspace_type, scope_id)
  do update set dashboard_id = excluded.dashboard_id
  returning id into v_selection_id;
  return query
    select s.id, s.dashboard_id, s.workspace_type, s.scope_id, s.updated_at
    from training_load.dashboard_active_selection s where s.id = v_selection_id;
end;
$$;

CREATE FUNCTION training_load.set_team_import_switch(p_actor uuid, p_team uuid, p_enabled boolean, p_mode text, p_reason text) RETURNS TABLE(enabled boolean, mode text, changed_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
declare
  v_basis text;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_cur record;
  v_mode text;
  v_prev_mode text;
begin
  -- The acting user's right first (a caller who is not entitled sees the same refusal whatever the input), then the input.
  v_basis := training_load.team_import_actor_basis(p_actor, p_team);
  if p_enabled is null or (p_mode is not null and p_mode not in ('pilot', 'team')) then
    raise exception 'set_team_import_switch: enabled and mode must be valid' using errcode = '22023';
  end if;
  if length(v_reason) not between 1 and 500 or v_reason ~ '[[:cntrl:]]' then
    raise exception 'set_team_import_switch: the reason is required (1-500 characters, no control characters)' using errcode = '22023';
  end if;
  -- The team and its club, active, FOR SHARE (this function takes no import lock, so the early team row lock closes no cycle).
  perform 1 from public.teams t where t.id = p_team and coalesce(t.is_active, true) for share;
  if not found then
    raise exception 'team % is not available', p_team using errcode = '42501';
  end if;
  perform 1 from public.teams t join public.clubs c on c.id = t.club_id where t.id = p_team and coalesce(c.is_active, true) for share of c;
  if not found then
    raise exception 'team % is not available', p_team using errcode = '42501';
  end if;
  -- A club admin's role was verified against the club the team had when the basis was read (no lock yet); the team row is now
  -- share-locked, so its club cannot change any more: verify the role again against THAT club (a team moved meanwhile is refused).
  if v_basis = 'club_admin' then
    perform 1 from public.user_club_roles cr join public.teams t on t.club_id = cr.club_id
     where t.id = p_team and cr.user_id = p_actor and cr.role = 'club_admin' and cr.is_active = true for share of cr;
    if not found then
      raise exception 'team % is not available', p_team using errcode = '42501';
    end if;
  end if;
  -- A team with no switch row yet has nothing to lock: serialize the first write per team, so the decision below (the previous
  -- mode, 'pilot' when absent) is never taken against a first row that another writer has not committed.
  perform pg_advisory_xact_lock(hashtextextended('team_import_switch:' || p_team::text, 0));
  select s.owner_team_id, s.enabled as is_on, s.mode as cur_mode into v_cur
    from training_load.gpexe_team_import_switch s where s.owner_team_id = p_team for update;
  v_prev_mode := coalesce(v_cur.cur_mode, 'pilot');
  v_mode := coalesce(p_mode, v_prev_mode);
  if v_basis = 'club_admin' then
    -- A club admin does not move a team between modes (the end of the pilot is a platform admin's act) and turns a team on
    -- only once the pilot is over for it.
    if v_mode <> v_prev_mode then
      raise exception 'team_import_mode_platform_admin_only' using errcode = '42501';
    end if;
    if p_enabled and (v_cur.owner_team_id is null or v_cur.cur_mode <> 'team') then
      raise exception 'team_import_pilot_platform_admin_only' using errcode = '42501';
    end if;
  end if;
  -- The conditions guard TURNING ON (a team that is off, or a move to team mode); lowering the mode of a team that is
  -- already on, or repeating the same state, needs none.
  if p_enabled and (not coalesce(v_cur.is_on, false) or (v_mode = 'team' and v_prev_mode <> 'team')) then
    -- The conditions, read here, inside the database, at this moment.
    if not exists (select 1 from training_load.gpexe_import_prerequisite_records r
                    where r.kind = 'backup' and r.recorded_on between current_date - 2 and current_date) then
      raise exception 'team_import_condition:backup' using errcode = '55000';
    end if;
    if not exists (select 1 from training_load.gpexe_import_prerequisite_records r
                    where r.kind = 'restore_probe' and r.recorded_on between current_date - 35 and current_date) then
      raise exception 'team_import_condition:restore_probe' using errcode = '55000';
    end if;
    if v_mode = 'team' then
      if not exists (select 1 from training_load.gpexe_import_prerequisite_records r where r.kind = 'wrong_link_procedure') then
        raise exception 'team_import_condition:wrong_link_procedure' using errcode = '55000';
      end if;
      if not exists (select 1 from training_load.gpexe_import_prerequisite_records r where r.kind = 'archived_team_check_stop') then
        raise exception 'team_import_condition:archived_team_check_stop' using errcode = '55000';
      end if;
    end if;
  end if;
  perform set_config('optimove.team_import_tx', txid_current()::text, true);
  insert into training_load.gpexe_team_import_switch as s (owner_team_id, enabled, mode, changed_by_user_id, changed_at, change_reason)
    values (p_team, p_enabled, v_mode, p_actor, clock_timestamp(), v_reason)
  on conflict (owner_team_id) do update
    set enabled = excluded.enabled, mode = excluded.mode, changed_by_user_id = excluded.changed_by_user_id,
        changed_at = excluded.changed_at, change_reason = excluded.change_reason;
  insert into training_load.gpexe_team_import_switch_history (owner_team_id, enabled, mode, changed_by_user_id, basis, changed_at, change_reason)
    values (p_team, p_enabled, v_mode, p_actor, v_basis, clock_timestamp(), v_reason);
  return query select s2.enabled, s2.mode::text, s2.changed_at from training_load.gpexe_team_import_switch s2 where s2.owner_team_id = p_team;
end;
$$;

CREATE FUNCTION training_load.source_connection_audit_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'source_connection_audit is append-only (% refused)', tg_op;
end;
$$;

CREATE FUNCTION training_load.source_connection_bound_team_ids(connection uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE
    AS $$
    select team_id from training_load.source_team_bindings
     where connection_id = connection and state = 'active'
     order by team_id
  $$;

CREATE FUNCTION training_load.source_credential_connection_check_host() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  host_state text;
begin
  if tg_op = 'UPDATE' and new.host_key is not distinct from old.host_key and new.source_system is not distinct from old.source_system then
    return new;
  end if;
  select state into host_state from training_load.source_host_catalog
   where source_system = new.source_system and host_key = new.host_key for share;
  if host_state is null then
    raise exception 'source_credential_connections: host key % is not in the catalog for %', new.host_key, new.source_system
      using errcode = 'foreign_key_violation';
  end if;
  if host_state <> 'approved' then
    raise exception 'source_credential_connections: host key % of % is retired', new.host_key, new.source_system
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_credential_connection_protect_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.id is distinct from old.id then
    raise exception 'source_credential_connections: id is immutable';
  end if;
  -- Owner, source, host and credential_kind are the data every ciphertext
  -- is bound to (the AAD): none of them may change while the stored
  -- ciphertext stays as it is, or the row would look healthy and fail only
  -- at the next decryption. Wiping the credential in the same statement, or
  -- re-encrypting it, is allowed. This is a single-statement guard: the
  -- database cannot verify the AEAD itself, so a wipe-then-restore of the
  -- old bytes in two statements still fails at decryption. Writers and
  -- rotation scripts re-encrypt; they never restore bytes.
  if (new.credential_kind is distinct from old.credential_kind
      or new.source_system is distinct from old.source_system
      or new.owner_scope is distinct from old.owner_scope
      or new.owner_club_id is distinct from old.owner_club_id
      or new.owner_team_id is distinct from old.owner_team_id
      or new.host_key is distinct from old.host_key)
     and new.credential_ciphertext is not null
     and new.credential_ciphertext is not distinct from old.credential_ciphertext then
    raise exception 'source_credential_connections (id=%): the credential context changed while its ciphertext stayed; wipe or re-encrypt the credential in the same statement', old.id;
  end if;
  if new.source_system is not distinct from old.source_system
     and new.owner_scope is not distinct from old.owner_scope
     and new.owner_club_id is not distinct from old.owner_club_id
     and new.owner_team_id is not distinct from old.owner_team_id
     and new.host_key is not distinct from old.host_key then
    return new;
  end if;
  if exists (select 1 from training_load.source_team_bindings where connection_id = old.id) then
    raise exception 'source_credential_connections (id=%) has been bound: owner, source and host are immutable', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_history_no_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception '%.% keeps history; TRUNCATE refused', tg_table_schema, tg_table_name;
end;
$$;

CREATE FUNCTION training_load.source_host_catalog_api_family_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.api_family is distinct from old.api_family then
    raise exception 'source_host_catalog: the API family of a host key is immutable' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_host_catalog_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'source_host_catalog keeps every key: DELETE refused (retire it instead)';
  end if;
  if new.source_system is distinct from old.source_system or new.host_key is distinct from old.host_key then
    raise exception 'source_host_catalog: a host key is immutable (add a new row instead)';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_activations_end_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  ended record;
  ver record;
begin
  select operation_id into ended from training_load.source_metric_audit
   where action = 'activation_end' and activation_id = new.id;
  if not found then
    raise exception 'source_metric_mapping_activations: an activation is ended with its activation_end audit row' using errcode = '23514';
  end if;
  if new.end_reason in ('mapping_version_replaced', 'mapping_version_disabled') then
    select status, xmin::text::bigint as written_in into ver
      from training_load.source_metric_mapping_versions where id = new.mapping_version_id;
    if ver.status is distinct from 'disabled' or ver.written_in is distinct from training_load.source_metric_current_xmin() then
      raise exception 'source_metric_mapping_activations: a version-driven end sits in the transaction that disabled its version' using errcode = '23514';
    end if;
    if new.end_reason = 'mapping_version_replaced' and not exists (
         select 1 from training_load.source_metric_audit
          where action = 'mapping_version_replaced' and mapping_id = new.mapping_id and operation_id = ended.operation_id) then
      raise exception 'source_metric_mapping_activations: a replaced end sits in the operation of its mapping''s replacement' using errcode = '23514';
    end if;
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.source_metric_activations_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  ver record;
  def record;
  map record;
  bnd record;
  conn record;
  actor uuid := training_load.source_metric_context_actor();
  club uuid;
  basis text;
begin
  -- v48: the row names the acting user of this transaction (v35's setting).
  if new.activated_by_user_id is distinct from actor then
    raise exception 'source metric activation: the acting user may not write this activation' using errcode = '42501';
  end if;
  if new.ended_at is not null or new.ended_by_user_id is not null or new.ended_basis is not null or new.end_reason is not null then
    raise exception 'source_metric_mapping_activations: an activation is created open' using errcode = '23514';
  end if;
  select status, applies_to_session, applies_to_drill into ver
    from training_load.source_metric_mapping_versions where id = new.mapping_version_id for share;
  if ver.status is distinct from 'active' then
    raise exception 'source_metric_mapping_activations: only an active mapping version is activated' using errcode = '23514';
  end if;
  if new.applies_to_session is distinct from ver.applies_to_session or new.applies_to_drill is distinct from ver.applies_to_drill then
    raise exception 'source_metric_mapping_activations: the levels must be the mapping version''s' using errcode = '23514';
  end if;
  -- C42: an active source field (implied by the active version's chain; a backstop).
  select source_system, api_family, state into def
    from training_load.source_metric_definitions where id = new.source_metric_definition_id;
  if def.state is distinct from 'active' then
    raise exception 'source_metric_mapping_activations: the source metric is retired' using errcode = '23514';
  end if;
  -- The owner comes from T3, never from the caller.
  select owner_scope, owner_club_id into map from training_load.source_metric_mappings where id = new.mapping_id;
  -- v27 rows, plain reads (an Unbind is never inverted).
  select connection_id, team_id, source_system, state into bnd
    from training_load.source_team_bindings where id = new.source_team_binding_id;
  if bnd.state is distinct from 'active' then
    raise exception 'source_metric_mapping_activations: the team binding is not active' using errcode = '23514';
  end if;
  if bnd.source_system is distinct from def.source_system then
    raise exception 'source_metric_mapping_activations: the binding''s source is not the source metric''s' using errcode = '23514';
  end if;
  select c.owner_scope, c.owner_club_id, c.owner_team_id, h.api_family into conn
    from training_load.source_credential_connections c
    join training_load.source_host_catalog h on h.source_system = c.source_system and h.host_key = c.host_key
   where c.id = bnd.connection_id;
  if conn.api_family is distinct from def.api_family then
    raise exception 'source_metric_mapping_activations: the API family of the binding''s host is not the source metric''s' using errcode = '23514';
  end if;
  -- v48 (C106): the binding's club is its connection's owner club
  -- (source_metric_binding_club); a connection that is not club-owned takes no
  -- activation until its rule is decided (so the team-owned branch below is
  -- never reached).
  club := training_load.source_metric_binding_club(new.source_team_binding_id);
  if club is null then
    raise exception 'source_metric_mapping_activations: the binding''s connection is not owned by a club' using errcode = '23514';
  end if;
  if map.owner_scope = 'club' then
    -- C35: a club mapping only on a connection owned by that club; never on a team-owned one.
    if conn.owner_scope is distinct from 'club' or conn.owner_club_id is distinct from map.owner_club_id then
      raise exception 'source_metric_mapping_activations: a club mapping is activated only on a binding of a connection owned by that club' using errcode = '23514';
    end if;
  elsif conn.owner_scope = 'team' and conn.owner_team_id is distinct from bnd.team_id then
    raise exception 'source_metric_mapping_activations: a team-owned connection hosts a system mapping only for its own team' using errcode = '23514';
  end if;
  -- v48 (C106): the basis the database derives for the binding's club -
  -- platform_admin for an active platform admin, club_admin for that club's
  -- active admin, both only while the club is active (replaces v34's
  -- source_metric_require_platform_admin).
  basis := training_load.source_metric_actor_basis(actor, club);
  if basis is null or new.activated_basis is distinct from basis then
    raise exception 'source metric activation: the acting user may not write this activation' using errcode = '42501';
  end if;
  -- v53 (J15 7.5, C132): a system mapping is not switched on for a club that
  -- hides its variable, whoever starts it. The hide lock comes after every
  -- row lock above (D's order), and the hide row is read after it.
  if map.owner_scope = 'system' then
    perform pg_advisory_xact_lock(hashtextextended('club-variable-hide:' || club::text || ':' || new.metric_definition_id::text, 0));
    if exists (select 1 from training_load.metric_definition_club_hides h
                where h.club_id = club and h.metric_definition_id = new.metric_definition_id and h.shown_at is null) then
      raise exception 'source_metric_mapping_activations: the variable is hidden in the binding''s club' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_activations_start_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from training_load.source_metric_audit
                  where action = 'activation_start' and activation_id = new.id) then
    raise exception 'source_metric_mapping_activations: an activation is started with its activation_start audit row' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.source_metric_activations_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid;
  club uuid;
  basis text;
  map record;
begin
  if tg_op = 'DELETE' then
    raise exception 'source_metric_mapping_activations: an activation is never deleted; end it' using errcode = '23514';
  end if;
  if old.ended_at is not null then
    raise exception 'source_metric_mapping_activations: an ended activation is immutable' using errcode = '23514';
  end if;
  if new.id is distinct from old.id or new.mapping_version_id is distinct from old.mapping_version_id
     or new.mapping_id is distinct from old.mapping_id or new.source_metric_definition_id is distinct from old.source_metric_definition_id
     or new.metric_definition_id is distinct from old.metric_definition_id or new.parameter_fingerprint is distinct from old.parameter_fingerprint
     or new.source_team_binding_id is distinct from old.source_team_binding_id or new.team_id is distinct from old.team_id
     or new.applies_to_session is distinct from old.applies_to_session or new.applies_to_drill is distinct from old.applies_to_drill
     or new.requirement is distinct from old.requirement or new.activated_by_user_id is distinct from old.activated_by_user_id
     or new.activated_basis is distinct from old.activated_basis or new.activated_at is distinct from old.activated_at
     or new.reason is distinct from old.reason then
    raise exception 'source_metric_mapping_activations: only the end of an activation is written' using errcode = '23514';
  end if;
  if new.ended_at is not null then
    -- v48 (C106): the ender is the acting user, with the basis the database
    -- derives - for the binding's club on an admin_ended end; for an end
    -- written by a version's replacement or disable, the basis of that
    -- transition (v52, J14 section 2.4: an active platform admin whatever the
    -- club's state, or the club's active admin for its club's version) - at
    -- the time of its own transaction (replaces v34's
    -- source_metric_require_platform_admin).
    actor := training_load.source_metric_context_actor();
    if new.ended_by_user_id is distinct from actor then
      raise exception 'source metric activation: the acting user may not write this activation' using errcode = '42501';
    end if;
    if new.end_reason = 'admin_ended' then
      club := training_load.source_metric_binding_club(new.source_team_binding_id);
      basis := case when club is null then null else training_load.source_metric_actor_basis(actor, club) end;
    else
      -- v52 (J14 section 2.4): a version-driven end - its version's
      -- replacement or disable - by the basis of the version's own transition:
      -- an active platform admin whatever the club's state, else, for a club
      -- mapping's version, the club's active admin of an active club. The
      -- version's mapping (T3, immutable) by a plain read; a club version's
      -- activation must sit on a binding of its own club (R3), a binding
      -- with no club included.
      basis := training_load.source_metric_actor_basis(actor, null);
      if basis is null then
        select owner_scope, owner_club_id into map from training_load.source_metric_mappings where id = new.mapping_id;
        if map.owner_scope = 'club' then
          if training_load.source_metric_binding_club(new.source_team_binding_id) is distinct from map.owner_club_id then
            raise exception 'source_metric_mapping_activations: a club version''s activation is on another club''s binding' using errcode = '23514';
          end if;
          basis := training_load.source_metric_actor_basis(actor, map.owner_club_id);
        end if;
      end if;
    end if;
    if basis is null or new.ended_basis is distinct from basis then
      raise exception 'source metric activation: the acting user may not write this activation' using errcode = '42501';
    end if;
    if new.ended_at is distinct from now() then
      raise exception 'source_metric_mapping_activations: an end carries the time of its own transaction' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_actor_basis(p_actor uuid, p_owner_club uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
begin
  perform 1 from public.users u where u.id = p_actor and u.is_active = true for share;
  perform 1
    from public.user_global_roles r
    join public.users u on u.id = r.user_id
   where r.user_id = p_actor and r.role = 'platform_admin' and r.is_active = true and u.is_active = true
     for share of r;
  if found then
    if p_owner_club is not null then
      perform 1 from public.clubs where id = p_owner_club and coalesce(is_active, true) for share;
      if not found then
        return null;
      end if;
    end if;
    return 'platform_admin';
  end if;
  if p_owner_club is null then
    return null;
  end if;
  perform 1
    from public.user_club_roles r
    join public.users u on u.id = r.user_id
    join public.clubs c on c.id = r.club_id
   where r.user_id = p_actor and r.club_id = p_owner_club and r.role = 'club_admin' and r.is_active = true
     and u.is_active = true and coalesce(c.is_active, true)
     for share of r, c;
  if found then
    return 'club_admin';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.source_metric_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception '%.% is append-only; % refused', tg_table_schema, tg_table_name, tg_op using errcode = '23514';
end;
$$;

CREATE FUNCTION training_load.source_metric_append_only_unless_session_undo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' and training_load.session_undo_marker_ok() then
    return old;
  end if;
  raise exception '%.% is append-only; % refused', tg_table_schema, tg_table_name, tg_op using errcode = '23514';
end;
$$;

CREATE FUNCTION training_load.source_metric_audit_actor_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
  here bigint := training_load.source_metric_current_xmin();
  map record;
  ver record;
  basis text;
  activation record;
  club uuid;
begin
  if new.performed_by_user_id is distinct from actor then
    raise exception 'source metric mapping: the row names another user than the acting user' using errcode = '42501';
  end if;
  if new.action in ('activation_start', 'activation_end') then
    -- v48 (C106): the basis derived as the activation's own write derived it -
    -- for the binding's club on a start and an admin_ended end; for an end
    -- written by a version's replacement or disable, as v52's T5 guard
    -- derives it (J14 section 2.4), with the same backstop.
    select source_team_binding_id, end_reason, mapping_id into activation
      from training_load.source_metric_mapping_activations where id = new.activation_id;
    if not found then
      raise exception 'source metric activation: the acting user may not write this audit row' using errcode = '42501';
    end if;
    if new.action = 'activation_end' and activation.end_reason in ('mapping_version_replaced', 'mapping_version_disabled') then
      basis := training_load.source_metric_actor_basis(actor, null);
      if basis is null then
        select owner_scope, owner_club_id into map from training_load.source_metric_mappings where id = activation.mapping_id;
        if map.owner_scope = 'club' then
          if training_load.source_metric_binding_club(activation.source_team_binding_id) is distinct from map.owner_club_id then
            raise exception 'source_metric_mapping_activations: a club version''s activation is on another club''s binding' using errcode = '23514';
          end if;
          basis := training_load.source_metric_actor_basis(actor, map.owner_club_id);
        end if;
      end if;
    else
      club := training_load.source_metric_binding_club(activation.source_team_binding_id);
      basis := case when club is null then null else training_load.source_metric_actor_basis(actor, club) end;
    end if;
    if basis is null or new.basis is distinct from basis then
      raise exception 'source metric activation: the acting user may not write this audit row' using errcode = '42501';
    end if;
    return new;
  end if;
  if new.action not in ('mapping_create', 'mapping_version_create', 'mapping_status', 'mapping_version_replaced') then
    -- Every other action: an active platform admin; its chain comes with the
    -- PR that writes it.
    if training_load.source_metric_actor_basis(actor, null) is distinct from 'platform_admin' or new.basis is distinct from 'platform_admin' then
      raise exception 'source metric mapping: the acting user may not write this audit row' using errcode = '42501';
    end if;
    return new;
  end if;
  select owner_scope, owner_club_id, created_by_user_id, xmin::text::bigint as written_in into map
    from training_load.source_metric_mappings where id = new.mapping_id for share;
  if not found then
    raise exception 'source_metric_audit: the audit row must follow its own operation in the same transaction' using errcode = '23514';
  end if;
  basis := training_load.source_metric_actor_basis(actor, case when map.owner_scope = 'club' then map.owner_club_id end);
  if basis is null then
    raise exception 'source metric mapping: the acting user may not write this mapping' using errcode = '42501';
  end if;
  if new.basis is distinct from basis then
    raise exception 'source metric mapping: the basis is not the acting user''s own' using errcode = '42501';
  end if;
  if new.action = 'mapping_create' then
    if map.written_in is distinct from here or map.created_by_user_id is distinct from actor then
      raise exception 'source_metric_audit: the audit row must follow its own operation in the same transaction' using errcode = '23514';
    end if;
    if exists (select 1 from training_load.source_metric_audit where action = 'mapping_create' and mapping_id = new.mapping_id) then
      raise exception 'source_metric_audit: the operation already has its audit row' using errcode = '23514';
    end if;
    return new;
  end if;
  select status, created_by_user_id, submitted_by_user_id, submitted_basis, activated_by_user_id, activated_basis,
         disabled_by_user_id, disabled_basis, xmin::text::bigint as written_in into ver
    from training_load.source_metric_mapping_versions where id = new.mapping_version_id and mapping_id = new.mapping_id;
  if not found or ver.written_in is distinct from here then
    raise exception 'source_metric_audit: the audit row must follow its own operation in the same transaction' using errcode = '23514';
  end if;
  if new.action = 'mapping_version_create' then
    if ver.status is distinct from 'draft' or ver.created_by_user_id is distinct from actor then
      raise exception 'source_metric_audit: the audit row must follow its own operation in the same transaction' using errcode = '23514';
    end if;
    if exists (select 1 from training_load.source_metric_audit
                where action = 'mapping_version_create' and mapping_version_id = new.mapping_version_id) then
      raise exception 'source_metric_audit: the operation already has its audit row' using errcode = '23514';
    end if;
    return new;
  end if;
  -- mapping_status / mapping_version_replaced: the version's current status is
  -- the transition's target, written by this user with this basis.
  if ver.status is distinct from new.to_status
     or (new.to_status = 'needs_review' and (ver.submitted_by_user_id, ver.submitted_basis) is distinct from (actor, new.basis))
     or (new.to_status = 'active' and (ver.activated_by_user_id, ver.activated_basis) is distinct from (actor, new.basis))
     or (new.to_status = 'disabled' and (ver.disabled_by_user_id, ver.disabled_basis) is distinct from (actor, new.basis))
     or new.to_status not in ('needs_review', 'active', 'disabled') then
    raise exception 'source_metric_audit: the audit row must follow its own operation in the same transaction' using errcode = '23514';
  end if;
  if exists (select 1 from training_load.source_metric_audit
              where action in ('mapping_status', 'mapping_version_replaced')
                and mapping_version_id = new.mapping_version_id and to_status = new.to_status) then
    raise exception 'source_metric_audit: the operation already has its audit row' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_audit_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.basis = 'club_admin' then
    if new.action in ('activation_start', 'activation_end') then
      -- v48 (C106): a club-admin activation row names its club through its
      -- activation's binding (the connection's owner club), never through the
      -- team or a mapping.
      if training_load.source_metric_binding_club(
           (select source_team_binding_id from training_load.source_metric_mapping_activations where id = new.activation_id)) is null then
        raise exception 'source_metric_audit: a club-admin activation row names an activation on a club''s binding' using errcode = '23514';
      end if;
    elsif not exists (
         select 1 from training_load.source_metric_mappings where id = new.mapping_id and owner_scope = 'club') then
      raise exception 'source_metric_audit: a club-admin row names a club mapping' using errcode = '23514';
    end if;
  end if;
  if new.activation_id is not null and not exists (
       select 1 from training_load.source_metric_mapping_activations
        where id = new.activation_id and mapping_version_id = new.mapping_version_id and team_id = new.team_id) then
    raise exception 'source_metric_audit: an activation row must name its own mapping version and team' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_audit_replacement_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.action = 'mapping_version_replaced' then
    if not exists (
         select 1
           from training_load.source_metric_audit a
           join training_load.source_metric_mapping_versions v
             on v.id = a.mapping_version_id and v.mapping_id = a.mapping_id
          where a.operation_id = new.operation_id
            and a.action = 'mapping_status' and a.from_status = 'active' and a.to_status = 'disabled'
            and a.mapping_id = new.mapping_id and a.mapping_version_id <> new.mapping_version_id
            and a.performed_by_user_id = new.performed_by_user_id
            and v.status = 'disabled' and v.disable_reason = new.reason) then
      raise exception 'source_metric_audit: a replacement records the disable of the version it replaces in its own operation' using errcode = '23514';
    end if;
  elsif new.action = 'mapping_status' and new.from_status = 'needs_review' and new.to_status = 'active' then
    if exists (
         select 1 from training_load.source_metric_audit a
          where a.operation_id = new.operation_id
            and a.action = 'mapping_status' and a.from_status = 'active' and a.to_status = 'disabled'
            and a.mapping_id = new.mapping_id) then
      raise exception 'source_metric_audit: an activation that disables another version of its mapping is recorded as a replacement' using errcode = '23514';
    end if;
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.source_metric_audit_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid;
  here bigint;
  rev record;
begin
  if new.action in ('mapping_create', 'mapping_version_create', 'mapping_status', 'mapping_version_replaced') then
    -- v35's chain (source_metric_audit_v35_actor_guard).
    return new;
  end if;

  if new.action in ('source_metric_revision_create', 'source_metric_revision_activate', 'source_metric_revision_retire') then
    actor := training_load.source_metric_context_actor();
    here := training_load.source_metric_current_xmin();
    if new.performed_by_user_id is distinct from actor or new.basis is distinct from 'platform_admin'
       or training_load.source_metric_actor_basis(actor, null) is distinct from 'platform_admin' then
      raise exception 'source metric revision: the acting user may not write this audit row' using errcode = '42501';
    end if;
    select state, created_by_user_id, activated_by_user_id, activated_at, retired_by_user_id, retired_reason, evidence_ref,
           xmin::text::bigint as written_in into rev
      from training_load.source_metric_definition_versions
     where id = new.source_metric_version_id and source_metric_definition_id = new.source_metric_definition_id;
    if not found or rev.written_in is distinct from here then
      raise exception 'source_metric_audit: the audit row must follow its own revision change in the same transaction' using errcode = '23514';
    end if;
    if (new.action = 'source_metric_revision_create'
        and (rev.created_by_user_id is distinct from actor or new.reason is not null
             or (new.evidence_ref is not null and new.evidence_ref is distinct from rev.evidence_ref)))
       or (new.action = 'source_metric_revision_activate'
           and (rev.state is distinct from 'active' or rev.activated_by_user_id is distinct from actor
                or new.reason is not null or new.evidence_ref is not null))
       or (new.action = 'source_metric_revision_retire'
           and (rev.state is distinct from 'retired' or rev.retired_by_user_id is distinct from actor
                or new.reason is distinct from rev.retired_reason or new.evidence_ref is not null
                or new.from_status is distinct from (case when rev.activated_at is null then 'draft' else 'active' end))) then
      raise exception 'source_metric_audit: the audit row must follow its own revision change in the same transaction' using errcode = '23514';
    end if;
    if exists (select 1 from training_load.source_metric_audit
                where action = new.action and source_metric_version_id = new.source_metric_version_id) then
      raise exception 'source_metric_audit: the revision change already has its audit row' using errcode = '23514';
    end if;
    return new;
  end if;

  if new.action in ('unit_conversion_create', 'unit_conversion_retire') then
    -- v47: a conversion's audit row follows its own create or retirement, once.
    actor := training_load.source_metric_context_actor();
    here := training_load.source_metric_current_xmin();
    if new.performed_by_user_id is distinct from actor or new.basis is distinct from 'platform_admin'
       or training_load.source_metric_actor_basis(actor, null) is distinct from 'platform_admin' then
      raise exception 'unit conversion: the acting user may not write this audit row' using errcode = '42501';
    end if;
    select state, created_by_user_id, retired_by_user_id, retired_reason, evidence_ref, xmin::text::bigint as written_in into rev
      from training_load.unit_conversions
     where id = new.unit_conversion_id;
    if not found or rev.written_in is distinct from here then
      raise exception 'source_metric_audit: the audit row must follow its own conversion change in the same transaction' using errcode = '23514';
    end if;
    if (new.action = 'unit_conversion_create'
        and (rev.state is distinct from 'active' or rev.created_by_user_id is distinct from actor
             or new.evidence_ref is distinct from rev.evidence_ref or new.reason is not null))
       or (new.action = 'unit_conversion_retire'
           and (rev.state is distinct from 'retired' or rev.retired_by_user_id is distinct from actor
                or new.reason is distinct from rev.retired_reason or new.from_status is distinct from 'active'
                or new.evidence_ref is not null)) then
      raise exception 'source_metric_audit: the audit row must follow its own conversion change in the same transaction' using errcode = '23514';
    end if;
    if exists (select 1 from training_load.source_metric_audit
                where action = new.action and unit_conversion_id = new.unit_conversion_id) then
      raise exception 'source_metric_audit: the conversion change already has its audit row' using errcode = '23514';
    end if;
    return new;
  end if;

  if new.action in ('activation_start', 'activation_end') then
    -- v48: an activation's audit row follows its own start or end in the same
    -- transaction, by its writer: a start carries the activation's reason; an
    -- end carries a reason, and an end written by a version's replacement or
    -- disable carries that version's disable_reason. No evidence. Once per
    -- activation and action (the unique index makes it physical).
    actor := training_load.source_metric_context_actor();
    here := training_load.source_metric_current_xmin();
    select a.activated_by_user_id, a.activated_basis, a.reason, a.ended_at, a.ended_by_user_id, a.ended_basis, a.end_reason,
           a.xmin::text::bigint as written_in, v.disable_reason into rev
      from training_load.source_metric_mapping_activations a
      join training_load.source_metric_mapping_versions v on v.id = a.mapping_version_id
     where a.id = new.activation_id;
    if not found or rev.written_in is distinct from here then
      raise exception 'source_metric_audit: the audit row must follow its own activation change in the same transaction' using errcode = '23514';
    end if;
    if (new.action = 'activation_start'
        and (rev.activated_by_user_id is distinct from actor or new.basis is distinct from rev.activated_basis
             or new.reason is distinct from rev.reason or new.evidence_ref is not null))
       or (new.action = 'activation_end'
           and (rev.ended_at is null or rev.ended_by_user_id is distinct from actor or new.basis is distinct from rev.ended_basis
                or new.reason is null or new.evidence_ref is not null
                or (rev.end_reason in ('mapping_version_replaced', 'mapping_version_disabled')
                    and new.reason is distinct from rev.disable_reason))) then
      raise exception 'source_metric_audit: the audit row must follow its own activation change in the same transaction' using errcode = '23514';
    end if;
    if exists (select 1 from training_load.source_metric_audit
                where action = new.action and activation_id = new.activation_id) then
      raise exception 'source_metric_audit: the activation change already has its audit row' using errcode = '23514';
    end if;
    return new;
  end if;

  if new.action = 'source_instance_end' then
    -- v50: an instance's end follows its own state change in the same
    -- transaction, by a platform admin, for the owner team, with a reason and
    -- no evidence, once per connection (the unique index makes it physical).
    actor := training_load.source_metric_context_actor();
    here := training_load.source_metric_current_xmin();
    if new.performed_by_user_id is distinct from actor or new.basis is distinct from 'platform_admin'
       or training_load.source_metric_actor_basis(actor, null) is distinct from 'platform_admin' then
      raise exception 'source instance: the acting user may not write this audit row' using errcode = '42501';
    end if;
    select state, owner_scope, owner_team_id, source_host_key, source_instance_key, xmin::text::bigint as written_in into rev
      from training_load.metric_source_connections
     where id = new.metric_source_connection_id;
    if not found or rev.written_in is distinct from here or rev.state is distinct from 'inactive'
       or rev.owner_scope is distinct from 'team' or rev.source_host_key is null or rev.source_instance_key is null
       or new.team_id is distinct from rev.owner_team_id or new.reason is null or new.evidence_ref is not null
       or new.from_status is distinct from 'active' or new.to_status is distinct from 'inactive' then
      raise exception 'source_metric_audit: the audit row must follow its own source instance end in the same transaction' using errcode = '23514';
    end if;
    if exists (select 1 from training_load.source_metric_audit
                where action = 'source_instance_end' and metric_source_connection_id = new.metric_source_connection_id) then
      raise exception 'source_metric_audit: the source instance end already has its audit row' using errcode = '23514';
    end if;
    return new;
  end if;

  if new.action not in ('source_metric_unit_verified', 'source_metric_meaning_verified') then
    raise exception 'source_metric_audit: no writer of this action exists yet' using errcode = '23514';
  end if;
  -- v37, unchanged: a verification row follows its own act, once.
  actor := training_load.source_metric_context_actor();
  here := training_load.source_metric_current_xmin();
  select unit_verified_by_user_id, unit_verified_at, unit_evidence_ref,
         meaning_verified_by_user_id, meaning_verified_at, meaning_evidence_ref,
         xmin::text::bigint as written_in into rev
    from training_load.source_metric_definition_versions
   where id = new.source_metric_version_id and source_metric_definition_id = new.source_metric_definition_id;
  if not found or rev.written_in is distinct from here then
    raise exception 'source_metric_audit: the audit row must follow its own verification in the same transaction' using errcode = '23514';
  end if;
  if new.action = 'source_metric_unit_verified' then
    if rev.unit_verified_at is null or rev.unit_verified_by_user_id is distinct from actor
       or rev.unit_evidence_ref is distinct from new.evidence_ref then
      raise exception 'source_metric_audit: the audit row must follow its own verification in the same transaction' using errcode = '23514';
    end if;
  elsif rev.meaning_verified_at is null or rev.meaning_verified_by_user_id is distinct from actor
        or rev.meaning_evidence_ref is distinct from new.evidence_ref then
    raise exception 'source_metric_audit: the audit row must follow its own verification in the same transaction' using errcode = '23514';
  end if;
  if exists (select 1 from training_load.source_metric_audit
              where action = new.action and source_metric_version_id = new.source_metric_version_id) then
    raise exception 'source_metric_audit: the verification already has its audit row' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_audit_row_ok(p_action text, p_targets text, p_from text, p_to text, p_reason text, p_evidence text, p_basis text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    select coalesce(case p_action
      when 'source_metric_create' then
        p_targets = '10000000' and p_from is null and p_to = 'active' and p_basis = 'platform_admin'
      when 'source_metric_retire' then
        p_targets = '10000000' and p_from = 'active' and p_to = 'retired' and p_reason is not null and p_basis = 'platform_admin'
      when 'source_metric_revision_create' then
        p_targets = '11000000' and p_from is null and p_to = 'draft' and p_basis = 'platform_admin'
      when 'source_metric_unit_verified' then
        p_targets = '11000000' and p_from is null and p_to is null and p_evidence is not null and p_basis = 'platform_admin'
      when 'source_metric_meaning_verified' then
        p_targets = '11000000' and p_from is null and p_to is null and p_evidence is not null and p_basis = 'platform_admin'
      when 'source_metric_revision_activate' then
        p_targets = '11000000' and p_from = 'draft' and p_to = 'active' and p_basis = 'platform_admin'
      when 'source_metric_revision_retire' then
        p_targets = '11000000' and p_from in ('draft', 'active') and p_to = 'retired' and p_reason is not null and p_basis = 'platform_admin'
      when 'mapping_create' then
        p_targets = '00100000' and p_from is null and p_to is null and p_basis in ('platform_admin', 'club_admin')
      when 'mapping_version_create' then
        p_targets = '00110000' and p_from is null and p_to = 'draft' and p_basis in ('platform_admin', 'club_admin')
      when 'mapping_status' then
        p_targets = '00110000' and (
             (p_from = 'draft' and p_to = 'needs_review' and p_basis in ('platform_admin', 'club_admin'))
          or (p_from = 'needs_review' and p_to = 'active' and p_basis in ('platform_admin', 'club_admin'))
          or (p_from in ('draft', 'needs_review', 'active') and p_to = 'disabled' and p_reason is not null and p_basis in ('platform_admin', 'club_admin')))
      when 'mapping_version_replaced' then
        p_targets = '00110000' and p_from = 'needs_review' and p_to = 'active' and p_reason is not null and p_basis in ('platform_admin', 'club_admin')
      when 'activation_start' then
        p_targets = '00011001' and p_from is null and p_to is null and p_reason is not null and p_basis in ('platform_admin', 'club_admin')
      when 'activation_end' then
        p_targets = '00011001' and p_from is null and p_to is null and p_basis in ('platform_admin', 'club_admin')
      when 'unit_conversion_create' then
        p_targets = '00000100' and p_from is null and p_to = 'active' and p_evidence is not null and p_basis = 'platform_admin'
      when 'unit_conversion_retire' then
        p_targets = '00000100' and p_from = 'active' and p_to = 'retired' and p_reason is not null and p_basis = 'platform_admin'
      when 'source_instance_end' then
        p_targets in ('00000010', '00000011') and p_from = 'active' and p_to = 'inactive' and p_reason is not null and p_basis = 'platform_admin'
      else false end, false)
  $$;

CREATE FUNCTION training_load.source_metric_audit_transition_facts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  ver record;
  fact_at timestamptz;
begin
  select submitted_at, activated_at, disabled_at, disable_reason into ver
    from training_load.source_metric_mapping_versions
   where id = new.mapping_version_id and mapping_id = new.mapping_id;
  if not found then
    raise exception 'source_metric_audit: a transition row must agree with its version' using errcode = '23514';
  end if;
  if new.to_status = 'disabled' and new.reason is distinct from ver.disable_reason then
    raise exception 'source_metric_audit: a disable row carries its version''s disable reason' using errcode = '23514';
  end if;
  if new.performed_at is distinct from now() then
    raise exception 'source_metric_audit: a transition row carries its transaction''s time' using errcode = '23514';
  end if;
  fact_at := case new.to_status
               when 'needs_review' then ver.submitted_at
               when 'active' then ver.activated_at
               when 'disabled' then ver.disabled_at
             end;
  if fact_at is null or fact_at < now() or fact_at > clock_timestamp() then
    raise exception 'source_metric_audit: a transition''s time lies within its own transaction' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_binding_club(p_binding uuid) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
    select c.owner_club_id
      from training_load.source_team_bindings b
      join training_load.source_credential_connections c on c.id = b.connection_id
     where b.id = p_binding and c.owner_scope = 'club'
  $$;

CREATE FUNCTION training_load.source_metric_check_conversion(p_from text, p_to text, p_scale numeric, p_div numeric, p_off numeric, p_parameter boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  if p_from = p_to then
    if not (p_scale = 1 and p_div = 1 and p_off = 0) then
      if p_parameter then
        raise exception 'source_metric_mapping_versions: equal bound units take the identity conversion (1, 1, 0)' using errcode = '23514';
      end if;
      raise exception 'source_metric_mapping_versions: equal units take the identity conversion (1, 1, 0)' using errcode = '23514';
    end if;
    return;
  end if;
  if (select count(*) from training_load.unit_conversions
       where from_unit = p_from and to_unit = p_to and state = 'active'
         and scale = p_scale and scale_divisor = p_div and "offset" = p_off) <> 1 then
    if p_parameter then
      raise exception 'source_metric_mapping_versions: the bound conversion must equal the active unit conversion of its unit pair' using errcode = '23514';
    end if;
    raise exception 'source_metric_mapping_versions: the conversion must equal the active unit conversion of its unit pair' using errcode = '23514';
  end if;
end;
$$;

CREATE FUNCTION training_load.source_metric_check_levels(p_definition uuid, p_session boolean, p_drill boolean, p_lock boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  if p_lock then
    perform 1 from training_load.metric_definition_scope_capabilities
     where metric_definition_id = p_definition order by scope_level for share;
  end if;
  if p_session and not exists (select 1 from training_load.metric_definition_scope_capabilities
                                where metric_definition_id = p_definition and scope_level = 'session') then
    raise exception 'source_metric_mapping_versions: the session level is not a scope of the canonical definition' using errcode = '23514';
  end if;
  if p_drill and not exists (select 1 from training_load.metric_definition_scope_capabilities
                              where metric_definition_id = p_definition and scope_level = 'component') then
    raise exception 'source_metric_mapping_versions: the drill level is not a scope of the canonical definition' using errcode = '23514';
  end if;
end;
$$;

CREATE FUNCTION training_load.source_metric_check_parameters(p_kind text, p_operator text, p_bound_unit text, p_source jsonb, p_canonical jsonb, p_cd jsonb, p_scale numeric, p_div numeric, p_off numeric, p_check_conversion boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  cd_keys text[];
  canon jsonb;
begin
  if not training_load.source_metric_parameters_shape_ok(p_kind, 'source', p_source)
     or not training_load.source_metric_parameters_shape_ok(p_kind, 'canonical', p_canonical) then
    raise exception 'source_metric_mapping_versions: the parameters do not have the contract shape' using errcode = '23514';
  end if;
  if p_kind = 'none' then
    if not (p_scale = 1 and p_div = 1 and p_off = 0) then
      raise exception 'source_metric_mapping_versions: a contract without parameters takes the identity parameter conversion' using errcode = '23514';
    end if;
    return;
  end if;
  if (p_source ->> 'operator') is distinct from p_operator or (p_canonical ->> 'operator') is distinct from p_operator then
    raise exception 'source_metric_mapping_versions: the operator must be the revision''s proven operator' using errcode = '23514';
  end if;
  if (p_source ->> 'unit') is distinct from p_bound_unit then
    raise exception 'source_metric_mapping_versions: the source bound unit must be the revision''s proven bound unit' using errcode = '23514';
  end if;
  if p_cd is null or jsonb_typeof(p_cd) <> 'object' then
    raise exception 'source_metric_mapping_versions: the canonical condition description has no supported shape' using errcode = '23514';
  end if;
  select array_agg(k order by k collate "C") into cd_keys from jsonb_object_keys(p_cd) as k;
  if p_kind = 'zone_bounds' then
    if (p_cd ->> 'operator') = 'between' and cd_keys = array['max', 'min', 'operator', 'unit']
       and jsonb_typeof(p_cd -> 'min') = 'number' and jsonb_typeof(p_cd -> 'max') = 'number' and jsonb_typeof(p_cd -> 'unit') = 'string' then
      canon := jsonb_build_object('operator', p_cd -> 'operator', 'lower', p_cd -> 'min', 'upper', p_cd -> 'max', 'unit', p_cd -> 'unit');
    elsif (p_cd ->> 'operator') in ('>=', '>', '<=', '<') and cd_keys = array['operator', 'unit', 'value']
       and jsonb_typeof(p_cd -> 'value') = 'number' and jsonb_typeof(p_cd -> 'unit') = 'string' then
      canon := jsonb_build_object('operator', p_cd -> 'operator', 'lower', p_cd -> 'value', 'upper', 'null'::jsonb, 'unit', p_cd -> 'unit');
    else
      raise exception 'source_metric_mapping_versions: the canonical condition description has no supported shape' using errcode = '23514';
    end if;
    if (p_canonical ->> 'operator') is distinct from (canon ->> 'operator') or (p_canonical ->> 'unit') is distinct from (canon ->> 'unit')
       or (p_canonical ->> 'lower')::numeric <> (canon ->> 'lower')::numeric
       or jsonb_typeof(p_canonical -> 'upper') is distinct from jsonb_typeof(canon -> 'upper')
       or (jsonb_typeof(canon -> 'upper') = 'number' and (p_canonical ->> 'upper')::numeric <> (canon ->> 'upper')::numeric) then
      raise exception 'source_metric_mapping_versions: the canonical parameters must equal the canonical condition description' using errcode = '23514';
    end if;
    if (p_canonical ->> 'lower')::numeric * p_div <> (p_source ->> 'lower')::numeric * p_scale + p_off * p_div
       or jsonb_typeof(p_source -> 'upper') is distinct from jsonb_typeof(p_canonical -> 'upper')
       or (jsonb_typeof(p_source -> 'upper') = 'number'
           and (p_canonical ->> 'upper')::numeric * p_div <> (p_source ->> 'upper')::numeric * p_scale + p_off * p_div) then
      raise exception 'source_metric_mapping_versions: the source and canonical bounds are not equivalent' using errcode = '23514';
    end if;
  else
    if not ((p_cd ->> 'operator') in ('>=', '>', '<=', '<') and cd_keys = array['duration_seconds', 'operator', 'unit', 'value']
            and jsonb_typeof(p_cd -> 'value') = 'number' and jsonb_typeof(p_cd -> 'duration_seconds') = 'number'
            and jsonb_typeof(p_cd -> 'unit') = 'string') then
      raise exception 'source_metric_mapping_versions: the canonical condition description has no supported shape' using errcode = '23514';
    end if;
    if (p_canonical ->> 'operator') is distinct from (p_cd ->> 'operator') or (p_canonical ->> 'unit') is distinct from (p_cd ->> 'unit')
       or (p_canonical ->> 'value')::numeric <> (p_cd ->> 'value')::numeric
       or (p_canonical ->> 'duration_seconds')::numeric <> (p_cd ->> 'duration_seconds')::numeric then
      raise exception 'source_metric_mapping_versions: the canonical parameters must equal the canonical condition description' using errcode = '23514';
    end if;
    if (p_canonical ->> 'value')::numeric * p_div <> (p_source ->> 'threshold_value')::numeric * p_scale + p_off * p_div
       or (p_canonical ->> 'duration_seconds')::numeric <> (p_source ->> 'duration_seconds')::numeric then
      raise exception 'source_metric_mapping_versions: the source and canonical thresholds are not equivalent' using errcode = '23514';
    end if;
  end if;
  if p_check_conversion then
    perform training_load.source_metric_check_conversion(p_source ->> 'unit', p_canonical ->> 'unit', p_scale, p_div, p_off, true);
  end if;
end;
$$;

CREATE FUNCTION training_load.source_metric_context_actor() RETURNS uuid
    LANGUAGE plpgsql
    AS $_$
declare
  raw text := current_setting('optimove.source_metric_actor', true);
begin
  if raw is null
     or raw !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9]{1,20}$'
     or split_part(raw, ':', 2) is distinct from pg_current_xact_id()::text then
    raise exception 'source metric mapping: no acting user is set for this transaction' using errcode = '42501';
  end if;
  return split_part(raw, ':', 1)::uuid;
end;
$_$;

CREATE FUNCTION training_load.source_metric_current_xmin() RETURNS bigint
    LANGUAGE sql
    AS $$
    select pg_current_xact_id()::text::bigint % 4294967296
  $$;

CREATE FUNCTION training_load.source_metric_definitions_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'source_metric_definitions: a source metric is never deleted; retire it' using errcode = '23514';
  end if;
  if tg_op = 'INSERT' then
    if new.state is distinct from 'active' then
      raise exception 'source_metric_definitions: a source metric is created active' using errcode = '23514';
    end if;
    if new.seed_migration is not null then
      perform training_load.source_metric_require_seed_window(new.seed_migration);
    end if;
    return new;
  end if;
  if new.id is distinct from old.id or new.source_system is distinct from old.source_system
     or new.api_family is distinct from old.api_family or new.source_metric_key is distinct from old.source_metric_key
     or new.created_by_user_id is distinct from old.created_by_user_id or new.created_at is distinct from old.created_at
     or new.seed_migration is distinct from old.seed_migration then
    raise exception 'source_metric_definitions: the identity of a source metric is immutable' using errcode = '23514';
  end if;
  if old.state = 'retired' then
    if (new.state, new.retired_by_user_id, new.retired_at, new.retired_reason)
       is distinct from (old.state, old.retired_by_user_id, old.retired_at, old.retired_reason) then
      raise exception 'source_metric_definitions: a retired source metric stays retired' using errcode = '23514';
    end if;
    return new;
  end if;
  if new.state = 'retired' then
    if exists (select 1 from training_load.source_metric_definition_versions
                where source_metric_definition_id = old.id and state in ('draft', 'active')) then
      raise exception 'source_metric_definitions: a source metric with a draft or active revision is not retired' using errcode = '23514';
    end if;
    if exists (select 1 from training_load.source_metric_mapping_activations
                where source_metric_definition_id = old.id and ended_at is null) then
      raise exception 'source_metric_definitions: a source metric with an open activation is not retired' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_evidence_ref_ok(v text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
    select coalesce(char_length(v) between 1 and 300
       and v ~ '^docs(/[A-Za-z0-9_-][A-Za-z0-9_.-]*)+#[A-Za-z0-9_-]+$', false)
  $_$;

CREATE FUNCTION training_load.source_metric_factor_pair_normal(p_scale numeric, p_divisor numeric) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $$
declare
  n numeric;
begin
  if not (p_scale > 0 and p_scale < 'Infinity'::numeric and p_divisor > 0 and p_divisor < 'Infinity'::numeric) then
    return false;
  end if;
  if p_divisor = 1 then
    return true;
  end if;
  if p_scale <> 1 then
    return false;
  end if;
  n := replace(trim_scale(p_divisor)::text, '.', '')::numeric;
  while mod(n, 2) = 0 loop
    n := div(n, 2);
  end loop;
  while mod(n, 5) = 0 loop
    n := div(n, 5);
  end loop;
  return n <> 1;
end;
$$;

CREATE FUNCTION training_load.source_metric_guard_canonical_definition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (new.current_version_id is distinct from old.current_version_id or new.state is distinct from old.state)
     and exists (select 1 from training_load.source_metric_mapping_versions
                  where metric_definition_id = old.id and metric_definition_version_id = old.current_version_id and status = 'active') then
    raise exception 'metric_definitions: an active mapping version pins the current version; disable it first' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_guard_canonical_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (new.owner_scope, new.owner_user_id, new.owner_club_id, new.owner_team_id)
     is distinct from (old.owner_scope, old.owner_user_id, old.owner_club_id, old.owner_team_id) then
    if exists (select 1 from training_load.source_metric_mappings where metric_definition_id = old.id) then
      raise exception 'metric_definitions: a canonical definition named by a mapping keeps its owner' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_guard_scope_capability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'UPDATE' and new.metric_definition_id is not distinct from old.metric_definition_id
     and new.scope_level is not distinct from old.scope_level then
    return new;
  end if;
  if exists (select 1 from training_load.source_metric_mapping_versions
              where metric_definition_id = old.metric_definition_id and status = 'active'
                and ((old.scope_level = 'session' and applies_to_session) or (old.scope_level = 'component' and applies_to_drill))) then
    raise exception 'metric_definition_scope_capabilities: an active mapping version applies to this level; disable it first' using errcode = '23514';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_lock_conversions(p_from text, p_to text, p_bound_from text, p_bound_to text) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  perform 1 from training_load.unit_conversions
   where state = 'active'
     and ((p_from is distinct from p_to and from_unit = p_from and to_unit = p_to)
       or (p_bound_from is distinct from p_bound_to and from_unit = p_bound_from and to_unit = p_bound_to))
   order by id for share;
end;
$$;

CREATE FUNCTION training_load.source_metric_mapping_version_copies_audit_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from training_load.source_metric_audit a
                  where a.action = 'mapping_version_create'
                    and a.mapping_version_id = new.club_version_id
                    and a.operation_id = new.operation_id) then
    raise exception 'source_metric_mapping_version_copies: a link needs its version''s audit row in the same operation' using errcode = '23514';
  end if;
  if (select l.xmin::text::bigint from training_load.source_metric_mapping_version_copies l where l.club_version_id = new.club_version_id)
     is distinct from training_load.source_metric_current_xmin() then
    raise exception 'source_metric_mapping_version_copies: a link is written outside a savepoint' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.source_metric_mapping_version_copies_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
  here bigint := training_load.source_metric_current_xmin();
  cv record;
  sv record;
  cm record;
  sm record;
  cp record;
  first_version uuid;
begin
  select v.*, v.xmin::text::bigint as written_in into cv
    from training_load.source_metric_mapping_versions v where v.id = new.club_version_id;
  if not found
     or cv.owner_key = 'system'
     or cv.status is distinct from 'draft'
     or cv.written_in is distinct from here
     or cv.created_by_user_id is distinct from actor then
    raise exception 'source_metric_mapping_version_copies: the club version must be the club''s draft written in this transaction' using errcode = '23514';
  end if;
  select v.* into sv from training_load.source_metric_mapping_versions v where v.id = new.system_version_id;
  if not found
     or sv.owner_key is distinct from 'system'
     or sv.status is distinct from 'active'
     or sv.activated_at is null then
    raise exception 'source_metric_mapping_version_copies: the system version must be an active system version' using errcode = '23514';
  end if;
  select metric_definition_id, owner_club_id into cm from training_load.source_metric_mappings where id = cv.mapping_id;
  select metric_definition_id into sm from training_load.source_metric_mappings where id = sv.mapping_id;
  select c.* into cp from training_load.metric_definition_copies c
   where c.club_definition_id = cm.metric_definition_id
     and c.club_id = cm.owner_club_id
     and c.system_definition_id = sm.metric_definition_id;
  if not found then
    raise exception 'source_metric_mapping_version_copies: the club version must target the copy of the system version''s variable' using errcode = '23514';
  end if;
  if new.operation_id is distinct from cp.operation_id then
    raise exception 'source_metric_mapping_version_copies: the link belongs to its copy''s operation' using errcode = '23514';
  end if;
  select id into first_version from training_load.metric_definition_versions
   where metric_definition_id = cp.club_definition_id and version_number = 1;
  if sv.metric_definition_version_id is distinct from cp.system_version_id
     or cv.metric_definition_version_id is distinct from first_version then
    raise exception 'source_metric_mapping_version_copies: the versions must pin the variable versions of the copy' using errcode = '23514';
  end if;
  -- Identical, null-safe; conversion_note and rounding_decimals are left out
  -- on purpose (free text and presentation).
  if cv.source_metric_version_id is distinct from sv.source_metric_version_id
     or cv.parameter_kind is distinct from sv.parameter_kind
     or cv.source_parameters is distinct from sv.source_parameters
     or cv.parameter_fingerprint is distinct from sv.parameter_fingerprint
     or cv.source_unit is distinct from sv.source_unit
     or cv.target_unit is distinct from sv.target_unit
     or cv.scale is distinct from sv.scale
     or cv.scale_divisor is distinct from sv.scale_divisor
     or cv."offset" is distinct from sv."offset"
     or cv.parameter_scale is distinct from sv.parameter_scale
     or cv.parameter_scale_divisor is distinct from sv.parameter_scale_divisor
     or cv.parameter_offset is distinct from sv.parameter_offset
     or cv.applies_to_session is distinct from sv.applies_to_session
     or cv.applies_to_drill is distinct from sv.applies_to_drill
     or cv.canonical_parameters is distinct from sv.canonical_parameters then
    raise exception 'source_metric_mapping_version_copies: the club version must be identical to the system version' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_mapping_versions_actor_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid;
  map record;
  basis text;
begin
  -- Not a protected change: v34 refuses every other column change itself.
  if tg_op = 'UPDATE'
     and new.status is not distinct from old.status
     and new.submitted_by_user_id is not distinct from old.submitted_by_user_id
     and new.activated_by_user_id is not distinct from old.activated_by_user_id
     and new.disabled_by_user_id is not distinct from old.disabled_by_user_id then
    return new;
  end if;
  actor := training_load.source_metric_context_actor();
  select owner_scope, owner_club_id into map
    from training_load.source_metric_mappings where id = new.mapping_id for share;
  basis := training_load.source_metric_actor_basis(actor, case when map.owner_scope = 'club' then map.owner_club_id end);
  if basis is null then
    raise exception 'source metric mapping: the acting user may not write this mapping' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    if new.created_by_user_id is distinct from actor then
      raise exception 'source metric mapping: the row names another user than the acting user' using errcode = '42501';
    end if;
    return new;
  end if;
  if new.status is not distinct from old.status then
    -- An actor column changed without a transition (v34 refuses it too).
    raise exception 'source metric mapping: the row names another user than the acting user' using errcode = '42501';
  end if;
  if new.status = 'needs_review' then
    if new.submitted_by_user_id is distinct from actor then
      raise exception 'source metric mapping: the row names another user than the acting user' using errcode = '42501';
    end if;
    if new.submitted_basis is distinct from basis then
      raise exception 'source metric mapping: the basis is not the acting user''s own' using errcode = '42501';
    end if;
  elsif new.status = 'active' then
    if new.activated_by_user_id is distinct from actor then
      raise exception 'source metric mapping: the row names another user than the acting user' using errcode = '42501';
    end if;
    if new.activated_basis is distinct from basis then
      raise exception 'source metric mapping: the basis is not the acting user''s own' using errcode = '42501';
    end if;
  elsif new.status = 'disabled' then
    if new.disabled_by_user_id is distinct from actor then
      raise exception 'source metric mapping: the row names another user than the acting user' using errcode = '42501';
    end if;
    if new.disabled_basis is distinct from basis then
      raise exception 'source metric mapping: the basis is not the acting user''s own' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_mapping_versions_audit_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if not exists (select 1 from training_load.source_metric_audit
                    where action = 'mapping_version_create' and mapping_version_id = new.id) then
      raise exception 'source_metric_mapping_versions: a version is written with its mapping_version_create audit row' using errcode = '23514';
    end if;
  elsif not exists (select 1 from training_load.source_metric_audit
                     where action in ('mapping_status', 'mapping_version_replaced') and mapping_version_id = new.id
                       and from_status = old.status and to_status = new.status) then
    raise exception 'source_metric_mapping_versions: a status transition is written with its mapping_status audit row' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.source_metric_mapping_versions_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  rev record;
  map_owner text;
  mdv record;
begin
  -- D6: every later state is a checked transition with its acting user.
  if new.status is distinct from 'draft' then
    raise exception 'source_metric_mapping_versions: a mapping version is created as draft' using errcode = '23514';
  end if;
  select state, source_unit, source_bound_unit, bound_operator, parameter_kind, supports_session, supports_drill into rev
    from training_load.source_metric_definition_versions
   where id = new.source_metric_version_id and source_metric_definition_id = new.source_metric_definition_id for share;
  if not found then
    raise exception 'source_metric_mapping_versions: the source revision does not belong to the mapping''s source metric' using errcode = '23514';
  end if;
  if rev.state not in ('draft', 'active') or rev.source_unit is null then
    raise exception 'source_metric_mapping_versions: a mapping version needs a draft or active source revision with a proven unit' using errcode = '23514';
  end if;
  select owner_key into map_owner from training_load.source_metric_mappings
   where id = new.mapping_id and source_metric_definition_id = new.source_metric_definition_id and metric_definition_id = new.metric_definition_id;
  if not found then
    raise exception 'source_metric_mapping_versions: the version must name its mapping''s source metric and canonical definition' using errcode = '23514';
  end if;
  if new.owner_key is null then
    new.owner_key := map_owner;
  elsif new.owner_key is distinct from map_owner then
    raise exception 'source_metric_mapping_versions: the owner key must be the mapping''s own' using errcode = '23514';
  end if;
  if new.source_unit is distinct from rev.source_unit then
    raise exception 'source_metric_mapping_versions: the source unit must be the revision''s proven unit' using errcode = '23514';
  end if;
  if new.parameter_kind is distinct from rev.parameter_kind then
    raise exception 'source_metric_mapping_versions: the parameter kind must be the revision''s' using errcode = '23514';
  end if;
  if (new.applies_to_session and not rev.supports_session) or (new.applies_to_drill and not rev.supports_drill) then
    raise exception 'source_metric_mapping_versions: a level outside the revision''s levels' using errcode = '23514';
  end if;
  select value_type, unit, condition_description into mdv from training_load.metric_definition_versions
   where id = new.metric_definition_version_id and metric_definition_id = new.metric_definition_id;
  if not found then
    raise exception 'source_metric_mapping_versions: the canonical version does not belong to the canonical definition' using errcode = '23514';
  end if;
  if mdv.value_type is distinct from 'numeric' then
    raise exception 'source_metric_mapping_versions: the canonical version is not numeric' using errcode = '23514';
  end if;
  if mdv.unit is null or char_length(mdv.unit) not between 1 and 30 then
    raise exception 'source_metric_mapping_versions: canonical_unit_missing' using errcode = '23514';
  end if;
  -- C56: the canonical unit must be a unit token (the D3 / C53 rule of every
  -- source unit). Metrics Core keeps its free-text units and its rows are not
  -- changed; such a version only is not a mapping target. The canonical
  -- version is immutable (v10) and an activation re-checks that it is still
  -- the definition's current one, so this check at creation holds for the
  -- version's whole life.
  if not training_load.source_metric_unit_token_ok(mdv.unit) then
    raise exception 'source_metric_mapping_versions: canonical_unit_not_a_token' using errcode = '23514';
  end if;
  if new.target_unit is distinct from mdv.unit then
    raise exception 'source_metric_mapping_versions: the target unit must be the canonical version''s unit' using errcode = '23514';
  end if;
  perform training_load.source_metric_check_levels(new.metric_definition_id, new.applies_to_session, new.applies_to_drill, false);
  perform training_load.source_metric_check_conversion(new.source_unit, new.target_unit, new.scale, new.scale_divisor, new."offset", false);
  perform training_load.source_metric_check_parameters(new.parameter_kind, rev.bound_operator, rev.source_bound_unit,
    new.source_parameters, new.canonical_parameters, mdv.condition_description,
    new.parameter_scale, new.parameter_scale_divisor, new.parameter_offset, true);
  -- Never the caller's value (C32).
  new.parameter_fingerprint := training_load.source_metric_parameter_fingerprint(new.parameter_kind, new.source_parameters);
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_mapping_versions_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  rev record;
  map record;
  md record;
  mdv record;
begin
  if tg_op = 'DELETE' then
    raise exception 'source_metric_mapping_versions: a mapping version is never deleted; disable it' using errcode = '23514';
  end if;
  if new.id is distinct from old.id or new.mapping_id is distinct from old.mapping_id
     or new.source_metric_definition_id is distinct from old.source_metric_definition_id
     or new.metric_definition_id is distinct from old.metric_definition_id or new.owner_key is distinct from old.owner_key
     or new.source_metric_version_id is distinct from old.source_metric_version_id or new.version_number is distinct from old.version_number
     or new.metric_definition_version_id is distinct from old.metric_definition_version_id
     or new.conversion_kind is distinct from old.conversion_kind
     or new.scale::text is distinct from old.scale::text or new.scale_divisor::text is distinct from old.scale_divisor::text
     or new."offset"::text is distinct from old."offset"::text or new.rounding_decimals is distinct from old.rounding_decimals
     or new.source_unit is distinct from old.source_unit or new.target_unit is distinct from old.target_unit
     or new.conversion_note is distinct from old.conversion_note or new.parameter_kind is distinct from old.parameter_kind
     or new.source_parameters::text is distinct from old.source_parameters::text
     or new.canonical_parameters::text is distinct from old.canonical_parameters::text
     or new.parameter_fingerprint is distinct from old.parameter_fingerprint
     or new.parameter_scale::text is distinct from old.parameter_scale::text
     or new.parameter_scale_divisor::text is distinct from old.parameter_scale_divisor::text
     or new.parameter_offset::text is distinct from old.parameter_offset::text
     or new.applies_to_session is distinct from old.applies_to_session or new.applies_to_drill is distinct from old.applies_to_drill
     or new.created_by_user_id is distinct from old.created_by_user_id or new.created_at is distinct from old.created_at then
    raise exception 'source_metric_mapping_versions: only the status of a mapping version changes' using errcode = '23514';
  end if;
  -- Status facts are written once, by their own transition.
  if (old.submitted_at is not null and (new.submitted_by_user_id, new.submitted_at, new.submitted_basis)
        is distinct from (old.submitted_by_user_id, old.submitted_at, old.submitted_basis))
     or (old.activated_at is not null and (new.activated_by_user_id, new.activated_at, new.activated_basis)
        is distinct from (old.activated_by_user_id, old.activated_at, old.activated_basis))
     or (old.disabled_at is not null and (new.disabled_by_user_id, new.disabled_at, new.disabled_basis, new.disable_reason)
        is distinct from (old.disabled_by_user_id, old.disabled_at, old.disabled_basis, old.disable_reason)) then
    raise exception 'source_metric_mapping_versions: the status facts are written once' using errcode = '23514';
  end if;
  if new.status is not distinct from old.status then
    if (new.submitted_at, new.activated_at, new.disabled_at) is distinct from (old.submitted_at, old.activated_at, old.disabled_at) then
      raise exception 'source_metric_mapping_versions: the status facts are written by their transition' using errcode = '23514';
    end if;
    return new;
  end if;

  if old.status = 'draft' and new.status = 'needs_review' then
    select state into rev from training_load.source_metric_definition_versions where id = new.source_metric_version_id for share;
    if rev.state not in ('draft', 'active') then
      raise exception 'source_metric_mapping_versions: the source revision is retired' using errcode = '23514';
    end if;
    select owner_scope, owner_club_id into map from training_load.source_metric_mappings where id = new.mapping_id for share;
    if new.submitted_basis = 'platform_admin' then
      perform training_load.source_metric_require_platform_admin(new.submitted_by_user_id);
    elsif new.submitted_basis = 'club_admin' and map.owner_scope = 'club' then
      perform training_load.source_metric_require_club_admin(new.submitted_by_user_id, map.owner_club_id);
    else
      raise exception 'source metric mapping: the acting user may not submit this mapping version' using errcode = '42501';
    end if;
  elsif old.status = 'needs_review' and new.status = 'active' then
    -- Lock order of an activation: unit_conversions -> T2b -> T3 ->
    -- metric_definitions -> its scope capabilities -> the acting user's rows.
    perform training_load.source_metric_lock_conversions(new.source_unit, new.target_unit,
      new.source_parameters ->> 'unit', new.canonical_parameters ->> 'unit');
    select state, evidence_status, bound_operator, source_bound_unit into rev
      from training_load.source_metric_definition_versions where id = new.source_metric_version_id for share;
    if rev.state is distinct from 'active' or rev.evidence_status is distinct from 'verified' then
      raise exception 'source_metric_mapping_versions: the source revision must be active and verified' using errcode = '23514';
    end if;
    select owner_scope, owner_club_id into map from training_load.source_metric_mappings where id = new.mapping_id for share;
    select state, current_version_id into md from training_load.metric_definitions where id = new.metric_definition_id for share;
    if md.state is distinct from 'active' or md.current_version_id is distinct from new.metric_definition_version_id then
      raise exception 'source_metric_mapping_versions: the canonical definition must be active with the pinned version current' using errcode = '23514';
    end if;
    select condition_description into mdv from training_load.metric_definition_versions where id = new.metric_definition_version_id;
    -- C52: the value and bound conversions are checked again against the rows
    -- locked above (a retired row fails the activation; equal units stay the
    -- identity without a row). Active versions and history are not touched.
    perform training_load.source_metric_check_conversion(new.source_unit, new.target_unit, new.scale, new.scale_divisor, new."offset", false);
    perform training_load.source_metric_check_parameters(new.parameter_kind, rev.bound_operator, rev.source_bound_unit,
      new.source_parameters, new.canonical_parameters, mdv.condition_description,
      new.parameter_scale, new.parameter_scale_divisor, new.parameter_offset, true);
    perform training_load.source_metric_check_levels(new.metric_definition_id, new.applies_to_session, new.applies_to_drill, true);
    -- v52 (C108, J14): a club mapping's version is also activated by its
    -- club's active admin; a system mapping's only by a platform admin.
    if new.activated_basis = 'platform_admin' then
      perform training_load.source_metric_require_platform_admin(new.activated_by_user_id);
    elsif new.activated_basis = 'club_admin' and map.owner_scope = 'club' then
      perform training_load.source_metric_require_club_admin(new.activated_by_user_id, map.owner_club_id);
    else
      raise exception 'source metric mapping: the acting user may not activate this mapping version' using errcode = '42501';
    end if;
  elsif new.status = 'disabled' and old.status in ('draft', 'needs_review', 'active') then
    -- A transition writes only its own facts: disabling never adds a
    -- submission or an activation that did not happen.
    if (new.submitted_by_user_id, new.submitted_at, new.submitted_basis, new.activated_by_user_id, new.activated_at, new.activated_basis)
       is distinct from (old.submitted_by_user_id, old.submitted_at, old.submitted_basis, old.activated_by_user_id, old.activated_at, old.activated_basis) then
      raise exception 'source_metric_mapping_versions: the status facts are written by their transition' using errcode = '23514';
    end if;
    if exists (select 1 from training_load.source_metric_mapping_activations
                where mapping_version_id = old.id and ended_at is null) then
      raise exception 'source_metric_mapping_versions: a mapping version with an open activation is not disabled' using errcode = '23514';
    end if;
    -- v52 (C108, J14): as the activation, by the disabling user's basis.
    select owner_scope, owner_club_id into map from training_load.source_metric_mappings where id = new.mapping_id for share;
    if new.disabled_basis = 'platform_admin' then
      perform training_load.source_metric_require_platform_admin(new.disabled_by_user_id);
    elsif new.disabled_basis = 'club_admin' and map.owner_scope = 'club' then
      perform training_load.source_metric_require_club_admin(new.disabled_by_user_id, map.owner_club_id);
    else
      raise exception 'source metric mapping: the acting user may not disable this mapping version' using errcode = '42501';
    end if;
  else
    raise exception 'source_metric_mapping_versions: this status transition is not allowed' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_mappings_actor_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid := training_load.source_metric_context_actor();
begin
  if new.created_by_user_id is distinct from actor then
    raise exception 'source metric mapping: the row names another user than the acting user' using errcode = '42501';
  end if;
  if training_load.source_metric_actor_basis(actor, case when new.owner_scope = 'club' then new.owner_club_id end) is null then
    raise exception 'source metric mapping: the acting user may not write this mapping' using errcode = '42501';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_mappings_audit_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from training_load.source_metric_audit where action = 'mapping_create' and mapping_id = new.id) then
    raise exception 'source_metric_mappings: a mapping is written with its mapping_create audit row' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.source_metric_mappings_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  md record;
begin
  if tg_op = 'DELETE' then
    raise exception 'source_metric_mappings: a mapping is never deleted' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' then
    raise exception 'source_metric_mappings: a mapping identity is immutable; change it through a new version' using errcode = '23514';
  end if;
  select owner_scope, owner_club_id, state into md
    from training_load.metric_definitions where id = new.metric_definition_id for share;
  if not found or md.state is distinct from 'active' then
    raise exception 'source_metric_mappings: the canonical definition must be active' using errcode = '23514';
  end if;
  if new.owner_scope = 'system' and md.owner_scope is distinct from 'system' then
    raise exception 'source_metric_mappings: a system mapping targets a system definition' using errcode = '23514';
  end if;
  if new.owner_scope = 'club' and (md.owner_scope is distinct from 'club' or md.owner_club_id is distinct from new.owner_club_id) then
    raise exception 'source_metric_mappings: a club mapping targets a definition of the same club' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_no_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception '%.% keeps history; TRUNCATE refused', tg_table_schema, tg_table_name using errcode = '23514';
end;
$$;

CREATE FUNCTION training_load.source_metric_numeric_finite(n numeric) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    select coalesce(n::text not in ('NaN', 'Infinity', '-Infinity'), false)
  $$;

CREATE FUNCTION training_load.source_metric_parameter_fingerprint(p_kind text, p jsonb) RETURNS text
    LANGUAGE sql STABLE
    AS $$
    select case when p_kind = 'none' then ''
      else 'v1:' || encode(sha256(convert_to(
        p_kind || coalesce((
          select string_agg('|' || e.key || '=' || case jsonb_typeof(e.value)
                   when 'number' then trim_scale((e.value #>> '{}')::numeric)::text
                   when 'null' then 'null'
                   when 'string' then e.value #>> '{}'
                   else e.value::text end, '' order by e.key collate "C")
            from jsonb_each(p) as e), ''), 'UTF8')), 'hex')
    end
  $$;

CREATE FUNCTION training_load.source_metric_parameters_shape_ok(p_kind text, p_side text, p jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    select coalesce(case
      when p is null or jsonb_typeof(p) <> 'object' then false
      when p_kind = 'none' then p = '{}'::jsonb
      when p_kind = 'zone_bounds' then
        (select array_agg(k order by k collate "C") from jsonb_object_keys(p) as k) = array['lower', 'operator', 'unit', 'upper']
        and jsonb_typeof(p -> 'lower') = 'number'
        and jsonb_typeof(p -> 'upper') in ('number', 'null')
        and jsonb_typeof(p -> 'unit') = 'string' and training_load.source_metric_unit_token_ok(p ->> 'unit')
        and jsonb_typeof(p -> 'operator') = 'string' and (p ->> 'operator') in ('between', '>=', '>', '<=', '<')
        and ((p ->> 'operator') = 'between') = (jsonb_typeof(p -> 'upper') = 'number')
        and case when jsonb_typeof(p -> 'lower') = 'number' and jsonb_typeof(p -> 'upper') = 'number'
                 then (p ->> 'lower')::numeric < (p ->> 'upper')::numeric else true end
      when p_kind = 'event_threshold' then
        (select array_agg(k order by k collate "C") from jsonb_object_keys(p) as k)
          = case p_side when 'source' then array['duration_seconds', 'operator', 'threshold_value', 'unit']
                        when 'canonical' then array['duration_seconds', 'operator', 'unit', 'value'] end
        and jsonb_typeof(p -> 'duration_seconds') = 'number'
        and jsonb_typeof(p -> (case p_side when 'source' then 'threshold_value' else 'value' end)) = 'number'
        and jsonb_typeof(p -> 'unit') = 'string' and training_load.source_metric_unit_token_ok(p ->> 'unit')
        and jsonb_typeof(p -> 'operator') = 'string' and (p ->> 'operator') in ('>=', '>', '<=', '<')
      else false end, false)
  $$;

CREATE FUNCTION training_load.source_metric_require_club_admin(p_user uuid, p_club uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  perform 1 from public.users u where u.id = p_user and u.is_active = true for share;
  perform 1
    from public.user_club_roles r
    join public.users u on u.id = r.user_id
    join public.clubs c on c.id = r.club_id
   where r.user_id = p_user and r.club_id = p_club and r.role = 'club_admin' and r.is_active = true
     and u.is_active = true and coalesce(c.is_active, true)
     for share of r, c;
  if not found then
    raise exception 'source metric mapping: the acting user is not an active admin of the mapping''s club' using errcode = '42501';
  end if;
end;
$$;

CREATE FUNCTION training_load.source_metric_require_platform_admin(p_user uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  perform 1 from public.users u where u.id = p_user and u.is_active = true for share;
  perform 1
    from public.user_global_roles r
    join public.users u on u.id = r.user_id
   where r.user_id = p_user and r.role = 'platform_admin' and r.is_active = true and u.is_active = true
     for share of r;
  if not found then
    raise exception 'source metric mapping: the acting user is not an active platform admin' using errcode = '42501';
  end if;
end;
$$;

CREATE FUNCTION training_load.source_metric_require_seed_window(p_marker text) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  if p_marker is distinct from 'migrations_v2/202610282300_training_load_v42_source_metric_zone_model.sql'
     or exists (select 1 from public.schema_migrations where migration_name = p_marker) then
    raise exception 'source metric mapping: a seed marker is accepted only from the seeding migration' using errcode = '42501';
  end if;
end;
$$;

CREATE FUNCTION training_load.source_metric_revisions_actor_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid;
  unit_act boolean;
  meaning_act boolean;
  state_facts constant text[] := array['state', 'activated_by_user_id', 'activated_at', 'retired_by_user_id', 'retired_at', 'retired_reason'];
begin
  if tg_op = 'INSERT' then
    -- O9: a seeding migration's own row, inside v34's seed window (v34's
    -- guard ran first and checked the marker against that window).
    if new.seed_migration is not null and new.created_by_user_id is null then
      return new;
    end if;
    actor := training_load.source_metric_context_actor();
    if training_load.source_metric_actor_basis(actor, null) is distinct from 'platform_admin' then
      raise exception 'source metric revision: the acting user may not change a source revision' using errcode = '42501';
    end if;
    if new.seed_migration is not null then
      raise exception 'source metric revision: a seed marker is written only by a seeding migration, without an acting user' using errcode = '42501';
    end if;
    if new.created_by_user_id is distinct from actor then
      raise exception 'source metric revision: the row names another user than the acting user' using errcode = '42501';
    end if;
    if new.state is distinct from 'draft' then
      raise exception 'source_metric_definition_versions: a revision is created as draft' using errcode = '23514';
    end if;
    return new;
  end if;

  if new.state is distinct from old.state then
    -- A state change writes only the state and its own facts.
    if (to_jsonb(new) - state_facts) is distinct from (to_jsonb(old) - state_facts) then
      raise exception 'source_metric_definition_versions: a state change writes only the state and its own facts' using errcode = '23514';
    end if;
    if not ((old.state = 'draft' and new.state = 'active')
            or (old.state in ('draft', 'active') and new.state = 'retired')) then
      raise exception 'source_metric_definition_versions: this revision state transition is not allowed' using errcode = '23514';
    end if;
    actor := training_load.source_metric_context_actor();
    if training_load.source_metric_actor_basis(actor, null) is distinct from 'platform_admin' then
      raise exception 'source metric revision: the acting user may not change a source revision' using errcode = '42501';
    end if;
    if (new.state = 'active' and new.activated_by_user_id is distinct from actor)
       or (new.state = 'retired' and new.retired_by_user_id is distinct from actor) then
      raise exception 'source metric revision: the row names another user than the acting user' using errcode = '42501';
    end if;
    return new;
  end if;

  -- v37, unchanged: no state change, so exactly one verification act.
  unit_act := old.unit_verified_at is null and new.unit_verified_at is not null;
  meaning_act := old.meaning_verified_at is null and new.meaning_verified_at is not null;
  if unit_act = meaning_act
     or (new.evidence_status is distinct from old.evidence_status and new.evidence_status <> 'verified') then
    raise exception 'source_metric_definition_versions: a revision is changed only by one unit or meaning verification' using errcode = '23514';
  end if;
  actor := training_load.source_metric_context_actor();
  if training_load.source_metric_actor_basis(actor, null) is distinct from 'platform_admin' then
    raise exception 'source metric verification: the acting user may not verify a source metric' using errcode = '42501';
  end if;
  if (unit_act and new.unit_verified_by_user_id is distinct from actor)
     or (meaning_act and new.meaning_verified_by_user_id is distinct from actor) then
    raise exception 'source metric verification: the row names another user than the acting user' using errcode = '42501';
  end if;
  -- v42 (Z3): a zone's meaning act confirms the operator of its shape -
  -- between for the closed zones, >= for the open top zone.
  if meaning_act and new.parameter_kind = 'zone_bounds'
     and (new.bound_operator is null or new.bound_operator not in ('between', '>=')) then
    raise exception 'source_metric_definition_versions: a zone takes the operator between or >=' using errcode = '23514';
  end if;
  if meaning_act and new.parameter_kind = 'event_threshold'
     and (new.bound_operator is null or new.bound_operator not in ('>=', '>', '<=', '<')) then
    raise exception 'source_metric_definition_versions: an event threshold takes a one-sided operator' using errcode = '23514';
  end if;
  if old.evidence_ref is null and new.evidence_ref is not null
     and new.evidence_ref is distinct from (case when unit_act then new.unit_evidence_ref else new.meaning_evidence_ref end) then
    raise exception 'source_metric_definition_versions: the first evidence reference is the completing act''s own' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_revisions_audit_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.unit_verified_at is null and new.unit_verified_at is not null
     and not exists (select 1 from training_load.source_metric_audit
                      where action = 'source_metric_unit_verified' and source_metric_version_id = new.id) then
    raise exception 'source_metric_definition_versions: a unit verification is written with its source_metric_unit_verified audit row' using errcode = '23514';
  end if;
  if old.meaning_verified_at is null and new.meaning_verified_at is not null
     and not exists (select 1 from training_load.source_metric_audit
                      where action = 'source_metric_meaning_verified' and source_metric_version_id = new.id) then
    raise exception 'source_metric_definition_versions: a meaning verification is written with its source_metric_meaning_verified audit row' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.source_metric_revisions_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  ranks constant text[] := array['unproven', 'documented', 'observed', 'verified'];
  unit_act boolean;
  meaning_act boolean;
begin
  if tg_op = 'DELETE' then
    raise exception 'source_metric_definition_versions: a revision is never deleted; retire it' using errcode = '23514';
  end if;
  if tg_op = 'INSERT' then
    -- C42: a new revision only for an active source metric (T2a -> T2b).
    perform 1 from training_load.source_metric_definitions
     where id = new.source_metric_definition_id and state = 'active' for share;
    if not found then
      raise exception 'source_metric_definition_versions: a revision is created only for an active source metric' using errcode = '23514';
    end if;
    if not (new.state = 'draft' or (new.state = 'active' and new.seed_migration is not null)) then
      raise exception 'source_metric_definition_versions: a revision is created as draft; only a seed migration creates it active' using errcode = '23514';
    end if;
    if new.source_unit is not null or new.source_bound_unit is not null or new.unit_verified_by_user_id is not null
       or new.unit_verified_at is not null or new.unit_evidence_ref is not null or new.meaning_verified_by_user_id is not null
       or new.meaning_verified_at is not null or new.meaning_evidence_ref is not null or new.bound_operator is not null
       or new.activated_by_user_id is not null then
      raise exception 'source_metric_definition_versions: a revision is created without proof; unit and meaning are verified afterwards' using errcode = '23514';
    end if;
    if new.seed_migration is not null then
      perform training_load.source_metric_require_seed_window(new.seed_migration);
    end if;
    return new;
  end if;

  if old.state = 'retired' then
    if new is distinct from old then
      raise exception 'source_metric_definition_versions: a retired revision is immutable' using errcode = '23514';
    end if;
    return new;
  end if;
  -- C42: identity, hypothesis, shape, parameter kind and levels are immutable.
  if new.id is distinct from old.id or new.source_metric_definition_id is distinct from old.source_metric_definition_id
     or new.revision_number is distinct from old.revision_number or new.value_shape is distinct from old.value_shape
     or new.parameter_kind is distinct from old.parameter_kind or new.supports_session is distinct from old.supports_session
     or new.supports_drill is distinct from old.supports_drill or new.expected_source_unit is distinct from old.expected_source_unit
     or new.expected_source_bound_unit is distinct from old.expected_source_bound_unit or new.unit_note is distinct from old.unit_note
     or new.created_by_user_id is distinct from old.created_by_user_id or new.created_at is distinct from old.created_at
     or new.seed_migration is distinct from old.seed_migration then
    raise exception 'source_metric_definition_versions: the contract of a revision is immutable; correct it with a new revision' using errcode = '23514';
  end if;
  -- Proof is written once, from NULL, by its own act, never overwritten or cleared.
  if old.unit_verified_at is not null
     and (new.source_unit, new.source_bound_unit, new.unit_verified_by_user_id, new.unit_verified_at, new.unit_evidence_ref)
         is distinct from (old.source_unit, old.source_bound_unit, old.unit_verified_by_user_id, old.unit_verified_at, old.unit_evidence_ref) then
    raise exception 'source_metric_definition_versions: a unit proof is written once' using errcode = '23514';
  end if;
  if old.meaning_verified_at is not null
     and (new.bound_operator, new.meaning_verified_by_user_id, new.meaning_verified_at, new.meaning_evidence_ref)
         is distinct from (old.bound_operator, old.meaning_verified_by_user_id, old.meaning_verified_at, old.meaning_evidence_ref) then
    raise exception 'source_metric_definition_versions: a meaning proof is written once' using errcode = '23514';
  end if;
  if array_position(ranks, new.evidence_status) < array_position(ranks, old.evidence_status) then
    raise exception 'source_metric_definition_versions: the evidence status only rises' using errcode = '23514';
  end if;
  if old.evidence_ref is not null and new.evidence_ref is distinct from old.evidence_ref then
    raise exception 'source_metric_definition_versions: the evidence reference is written once' using errcode = '23514';
  end if;
  unit_act := old.unit_verified_at is null and new.unit_verified_at is not null;
  meaning_act := old.meaning_verified_at is null and new.meaning_verified_at is not null;
  if (unit_act or meaning_act) and new.state is distinct from old.state then
    raise exception 'source_metric_definition_versions: a verification is its own act, apart from a state change' using errcode = '23514';
  end if;

  if new.state is not distinct from old.state then
    if (new.activated_by_user_id, new.activated_at, new.retired_by_user_id, new.retired_at, new.retired_reason)
       is distinct from (old.activated_by_user_id, old.activated_at, old.retired_by_user_id, old.retired_at, old.retired_reason) then
      raise exception 'source_metric_definition_versions: the state facts are written by their transition' using errcode = '23514';
    end if;
  elsif old.state = 'draft' and new.state = 'active' then
    -- C42: activation needs an active source metric (a committed draft already
    -- blocks retirement, so this plain read is a backstop) and no other
    -- active revision (the partial unique index is the physical guard).
    if not exists (select 1 from training_load.source_metric_definitions
                    where id = new.source_metric_definition_id and state = 'active') then
      raise exception 'source_metric_definition_versions: a revision of a retired source metric is not activated' using errcode = '23514';
    end if;
    if exists (select 1 from training_load.source_metric_definition_versions
                where source_metric_definition_id = new.source_metric_definition_id and id <> new.id and state = 'active') then
      raise exception 'source_metric_definition_versions: another revision of this source metric is active; retire it first' using errcode = '23514';
    end if;
  elsif new.state = 'retired' then
    if (new.activated_by_user_id, new.activated_at) is distinct from (old.activated_by_user_id, old.activated_at) then
      raise exception 'source_metric_definition_versions: the state facts are written by their transition' using errcode = '23514';
    end if;
    if exists (select 1 from training_load.source_metric_mapping_versions
                where source_metric_version_id = old.id and status in ('needs_review', 'active')) then
      raise exception 'source_metric_definition_versions: a revision pinned by a submitted or active mapping version is not retired' using errcode = '23514';
    end if;
  else
    raise exception 'source_metric_definition_versions: this revision state transition is not allowed' using errcode = '23514';
  end if;

  -- The acting users the contract names (D intro), after every registry row.
  if unit_act then
    perform training_load.source_metric_require_platform_admin(new.unit_verified_by_user_id);
  end if;
  if meaning_act then
    perform training_load.source_metric_require_platform_admin(new.meaning_verified_by_user_id);
  end if;
  if old.state = 'draft' and new.state = 'active' then
    perform training_load.source_metric_require_platform_admin(new.activated_by_user_id);
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_metric_revisions_lifecycle_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if not exists (select 1 from training_load.source_metric_audit
                    where action = 'source_metric_revision_create' and source_metric_version_id = new.id) then
      raise exception 'source_metric_definition_versions: a revision is written with its source_metric_revision_create audit row' using errcode = '23514';
    end if;
  elsif not exists (select 1 from training_load.source_metric_audit
                     where action = case new.state when 'active' then 'source_metric_revision_activate' else 'source_metric_revision_retire' end
                       and source_metric_version_id = new.id and from_status = old.state and to_status = new.state) then
    raise exception 'source_metric_definition_versions: a state change is written with its source_metric_revision_activate or _retire audit row' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.source_metric_text_ok(v text, max_len integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
    select coalesce(char_length(v) between 1 and max_len
       and v !~ '^[\u0020\u00a0\u1680\u2000-\u200a\u202f\u205f\u3000]|[\u0020\u00a0\u1680\u2000-\u200a\u202f\u205f\u3000]$'
       and v !~ '[\u0001-\u001f\u007f-\u009f\u00ad\u034f\u061c\u115f\u1160\u17b4\u17b5\u180b-\u180f\u200b-\u200f\u2028-\u202e\u2060-\u206f\u2800\u3164\ufe00-\ufe0f\ufeff\uffa0\ufff0-\ufffb\U0001bca0-\U0001bca3\U0001d173-\U0001d17a\U000e0000-\U000e0fff]', false)
  $_$;

CREATE FUNCTION training_load.source_metric_unit_token_ok(v text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    select coalesce(char_length(v) between 1 and 30
       and v !~ '[\u0020|=\u0001-\u001f\u007f-\u009f\u00a0\u00ad\u034f\u061c\u115f\u1160\u1680\u17b4\u17b5\u180b-\u180f\u2000-\u200f\u2028-\u202f\u205f-\u206f\u2800\u3000\u3164\ufe00-\ufe0f\ufeff\uffa0\ufff0-\ufffb\U0001bca0-\U0001bca3\U0001d173-\U0001d17a\U000e0000-\U000e0fff]', false)
  $$;

CREATE FUNCTION training_load.source_metric_value_matches(p_source numeric, p_value numeric, p_scale numeric, p_div numeric, p_off numeric) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    select coalesce(scale(trim_scale(p_value)) <= 9 and (
      abs(p_value * p_div - (p_source * p_scale + p_off * p_div)) < p_div * 0.0000000005
      or (abs(p_value * p_div - (p_source * p_scale + p_off * p_div)) = p_div * 0.0000000005
          and sign(p_value * p_div - (p_source * p_scale + p_off * p_div)) = sign(p_source * p_scale + p_off * p_div))), false)
  $$;

CREATE FUNCTION training_load.source_team_binding_check_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  conn record;
  team_club uuid;
  host_state text;
begin
  perform training_load.hold_gpexe_team_lock(new.team_id, 'binding');
  select source_system, owner_scope, owner_club_id, owner_team_id, host_key
    into conn from training_load.source_credential_connections where id = new.connection_id for share;
  if not found then
    raise exception 'source_team_bindings: connection % does not exist', new.connection_id using errcode = 'foreign_key_violation';
  end if;
  -- A connection whose host key has been retired takes no new binding. The
  -- catalog row is read FOR SHARE, so a retirement committing meanwhile
  -- waits for this binding (and the next binding then sees it retired).
  select state into host_state from training_load.source_host_catalog
   where source_system = conn.source_system and host_key = conn.host_key for share;
  if host_state is distinct from 'approved' then
    raise exception 'source_team_bindings: connection % uses host key % of %, which is retired; no new binding', new.connection_id, conn.host_key, conn.source_system
      using errcode = 'check_violation';
  end if;
  if new.source_system is distinct from conn.source_system then
    raise exception 'source_team_bindings: the binding must carry its connection''s source (% <> %)', new.source_system, conn.source_system
      using errcode = 'check_violation';
  end if;
  select club_id into team_club from public.teams where id = new.team_id for share;
  if conn.owner_scope = 'club' and team_club is distinct from conn.owner_club_id then
    raise exception 'source_team_bindings: team % is not in the club that owns connection %', new.team_id, new.connection_id
      using errcode = 'check_violation';
  end if;
  if conn.owner_scope = 'team' and new.team_id is distinct from conn.owner_team_id then
    raise exception 'source_team_bindings: team % is not the team that owns connection %', new.team_id, new.connection_id
      using errcode = 'check_violation';
  end if;
  if new.legacy_gpexe_settings_team_id is not null and new.legacy_gpexe_settings_team_id is distinct from new.team_id then
    raise exception 'source_team_bindings: the legacy GPEXE settings pointer must be the binding''s own team' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_team_binding_guard_team_move() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  conn_id uuid;
begin
  if new.club_id is not distinct from old.club_id then
    return new;
  end if;
  perform training_load.hold_gpexe_team_lock(old.id, 'moving the team to another club');
  select b.connection_id into conn_id
    from training_load.source_team_bindings b
    join training_load.source_credential_connections c on c.id = b.connection_id
   where b.team_id = old.id and b.state = 'active'
     and c.owner_scope = 'club' and c.owner_club_id is distinct from new.club_id
   limit 1;
  if conn_id is not null then
    raise exception 'teams: team % is bound through connection % of its current club; end that binding before moving the team', old.id, conn_id
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.source_team_binding_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'source_team_bindings keeps history: DELETE refused (end the binding instead)';
  end if;
  if old.state = 'ended' then
    raise exception 'source_team_bindings: binding % has ended and is immutable', old.id;
  end if;
  -- Ending a binding is a change of the team's source set-up: same lock as
  -- creating it.
  perform training_load.hold_gpexe_team_lock(old.team_id, 'ending a binding');
  if new.id is distinct from old.id or new.team_id is distinct from old.team_id or new.connection_id is distinct from old.connection_id
     or new.source_system is distinct from old.source_system or new.source_team_id is distinct from old.source_team_id
     or new.bound_by_user_id is distinct from old.bound_by_user_id or new.bound_at is distinct from old.bound_at
     or new.bind_reason is distinct from old.bind_reason
     or new.legacy_gpexe_settings_team_id is distinct from old.legacy_gpexe_settings_team_id then
    raise exception 'source_team_bindings: binding % is immutable except for ending it', old.id;
  end if;
  if new.state <> 'ended' then
    raise exception 'source_team_bindings: the only change to binding % is ending it', old.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.team_import_actor_basis(p_actor uuid, p_team uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
  v_club uuid;
begin
  perform 1 from public.users u where u.id = p_actor and u.is_active = true for share;
  if not found then
    raise exception 'user % may not switch imports for team %', p_actor, p_team using errcode = '42501';
  end if;
  perform 1 from public.user_global_roles r where r.user_id = p_actor and r.role = 'platform_admin' and r.is_active = true for share;
  if found then
    return 'platform_admin';
  end if;
  select t.club_id into v_club from public.teams t where t.id = p_team;
  perform 1 from public.user_club_roles cr
   where cr.user_id = p_actor and cr.club_id = v_club and cr.role = 'club_admin' and cr.is_active = true for share;
  if found then
    return 'club_admin';
  end if;
  raise exception 'user % may not switch imports for team %', p_actor, p_team using errcode = '42501';
end;
$$;

CREATE FUNCTION training_load.team_import_write_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op in ('DELETE', 'TRUNCATE') then
    raise exception '% is never deleted (% refused)', tg_table_name, tg_op using errcode = '23514';
  end if;
  if tg_table_name <> 'gpexe_team_import_switch' and tg_op = 'UPDATE' then
    raise exception '% is append-only (% refused)', tg_table_name, tg_op using errcode = '23514';
  end if;
  if current_setting('optimove.team_import_tx', true) is distinct from txid_current()::text then
    raise exception '% is written only by its sanctioned function', tg_table_name using errcode = '42501';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.undo_imported_session(p_actor uuid, p_team uuid, p_candidate uuid, p_request_key uuid, p_reason text, p_expected_event uuid DEFAULT NULL::uuid) RETURNS TABLE(replayed boolean, event_id uuid, deletion_log_id uuid, removed_counts jsonb, removed_total integer, new_candidate_id uuid, undone_candidate_ids uuid[])
    LANGUAGE plpgsql
    AS $$
declare
  v_reason text := btrim(coalesce(p_reason, ''));
  v_hash text;
  v_req record;
  v_cand record;
  v_offer record;
  v_ids uuid[];
  v_event_id uuid;
  v_event record;
  v_scope jsonb;
  v_act uuid[];
  v_part uuid[];
  v_occ uuid[];
  v_seg uuid[];
  v_ident uuid[];
  v_batch uuid[];
  v_obs uuid[];
  v_work jsonb;
  v_removed jsonb := '{}'::jsonb;
  v_total integer;
  v_n integer;
  v_log uuid;
  v_req_id uuid := gen_random_uuid();
  v_new uuid;
  v_last_status text;
  v_constraint text;
  v_status text;
  v_pass integer := 0;
  v_act_before uuid[];
begin
  if p_actor is null or p_team is null or p_candidate is null or p_request_key is null then
    raise exception 'undo_imported_session: actor, team, candidate and request key are required' using errcode = '22023';
  end if;
  if length(v_reason) not between 1 and 500 or v_reason ~ '[[:cntrl:]]' then
    perform training_load.session_undo_refuse('invalid_reason');
  end if;
  v_hash := encode(sha256(convert_to(p_candidate::text || '|' || v_reason || '|' || coalesce(p_expected_event::text, ''), 'UTF8')), 'hex');

  -- 1. The right: the acting user, then the platform-admin role row (the revocations' order).
  perform 1 from public.users u where u.id = p_actor and u.is_active = true for share;
  if not found then
    raise exception 'user % may not undo an imported session', p_actor using errcode = '42501';
  end if;
  perform 1 from public.user_global_roles r where r.user_id = p_actor and r.role = 'platform_admin' and r.is_active = true for share;
  if not found then
    raise exception 'user % may not undo an imported session', p_actor using errcode = '42501';
  end if;

  -- 1b. An unlocked look at the candidate BEFORE the team lock. The approval locks a candidate row and only then waits for
  --     the team lock, the undo the other way round; an undo aimed at a candidate that is not imported (an approval may hold
  --     it) is therefore refused here, before it can wait for that row while holding the team lock. An imported row can be
  --     locked by an approval that refuses it before waiting for the team lock, and by a check's finalization, which then
  --     only TRY-locks the team (never waits), so the later FOR UPDATE cannot close a cycle. An undone row passes on
  --     purpose: its replay is answered below.
  select c.status into v_status from training_load.gpexe_import_candidates c where c.id = p_candidate and c.owner_team_id = p_team;
  if not found then
    perform training_load.session_undo_refuse('candidate_not_found');
  end if;
  if v_status <> 'imported' then
    perform training_load.session_undo_refuse('candidate_not_imported');
  end if;

  -- 2. The team's import lock: the importer's own key, so an import and an undo of the same team wait for each other.
  perform pg_advisory_xact_lock(hashtextextended('gpexe-import-team:' || lower(p_team::text), 21));

  -- 3. A replay answers the saved outcome before any further lock.
  select * into v_req from training_load.gpexe_session_undo_requests q
   where q.requested_by_user_id = p_actor and q.request_key = p_request_key and q.owner_team_id = p_team;
  if found then
    if v_req.request_hash <> v_hash then
      perform training_load.session_undo_refuse('request_key_reused');
    end if;
    return query select true, v_req.event_id, v_req.deletion_log_id, v_req.removed_counts, v_req.removed_total, v_req.new_candidate_id, v_req.undone_candidate_ids;
    return;
  end if;

  -- 4. The event the requested candidate's approval wrote, and every approved version of the session that wrote into it. A
  --    session changed in GPEXE and approved again (acceptChanges) goes into the SAME event (one event per session, v20), so
  --    removing the event undoes all of them: they are locked by id, and the undo marks every one of them.
  select a.metric_event_id into v_event_id from training_load.gpexe_import_approvals a where a.candidate_id = p_candidate;
  if not found then
    perform training_load.session_undo_refuse('approval_missing');
  end if;
  perform 1 from training_load.gpexe_import_candidates c
   where c.owner_team_id = p_team
     and c.id in (select a.candidate_id from training_load.gpexe_import_approvals a where a.metric_event_id = v_event_id)
   order by c.id for update;
  select * into v_cand from training_load.gpexe_import_candidates c where c.id = p_candidate and c.owner_team_id = p_team;
  if not found then
    perform training_load.session_undo_refuse('candidate_not_found');
  end if;
  if v_cand.status <> 'imported' then
    perform training_load.session_undo_refuse('candidate_not_imported');
  end if;
  if v_cand.import_undone_at is not null then
    perform training_load.session_undo_refuse('already_undone');
  end if;
  v_ids := coalesce(array(
    select c.id from training_load.gpexe_import_candidates c
      join training_load.gpexe_import_approvals a on a.candidate_id = c.id
     where a.metric_event_id = v_event_id and c.owner_team_id = p_team and c.status = 'imported' and c.import_undone_at is null
     order by c.id), '{}');

  -- 5. The event, locked, and the identity of what is about to be removed.
  if p_expected_event is not null and p_expected_event <> v_event_id then
    perform training_load.session_undo_refuse('event_mismatch');
  end if;
  select e.id, e.owner_team_id, e.source_external_id into v_event
    from training_load.metric_events e where e.id = v_event_id for update;
  if not found then
    perform training_load.session_undo_refuse('event_missing');
  end if;
  if v_event.owner_team_id is distinct from p_team then
    perform training_load.session_undo_refuse('event_team_mismatch');
  end if;
  if v_event.source_external_id is distinct from 'team_session:' || v_cand.gpexe_team_session_id then
    perform training_load.session_undo_refuse('event_session_mismatch');
  end if;
  if (select count(*) from training_load.metric_events e2
       join training_load.metric_source_connections c2 on c2.id = e2.source_connection_id
      where c2.source_system = 'gpexe' and e2.owner_team_id = p_team and e2.source_external_id = v_event.source_external_id) > 1 then
    perform training_load.session_undo_refuse('two_events_for_session');
  end if;

  -- 6. The scope, collected again after the activities are locked (a link added meanwhile is seen here or waits).
  v_scope := training_load.session_undo_scope(v_event_id);
  v_act := coalesce(array(select jsonb_array_elements_text(v_scope -> 'activityIds')::uuid), '{}');
  -- Lock the activities, look again, and repeat until the set no longer grows (a link added while a lock was waited for is
  -- seen by the next look; three rounds are far more than the importer's own creation under the team lock can need).
  loop
    exit when cardinality(v_act) = 0;
    perform 1 from training.activities a where a.id = any(v_act) order by a.id for update;
    v_act_before := v_act;
    v_scope := training_load.session_undo_scope(v_event_id);
    v_act := coalesce(array(select jsonb_array_elements_text(v_scope -> 'activityIds')::uuid), '{}');
    exit when v_act <@ v_act_before;
    v_pass := v_pass + 1;
    if v_pass >= 3 then
      raise exception 'undo_imported_session: the activities of the event keep changing' using errcode = '55P03';
    end if;
  end loop;
  if (v_scope ->> 'manualOccasionCount')::int > 0 then
    perform training_load.session_undo_refuse('manual_occasion');
  end if;
  if (v_scope ->> 'sharedActivityCount')::int > 0 then
    perform training_load.session_undo_refuse('shared_activity');
  end if;
  if (v_scope ->> 'otherEventLinkCount')::int > 0 then
    perform training_load.session_undo_refuse('other_event_link');
  end if;
  v_work := v_scope -> 'rosterWork';
  if (v_work ->> 'decisions')::int + (v_work ->> 'requests')::int + (v_work ->> 'completions')::int + (v_work ->> 'completionLog')::int > 0 then
    perform training_load.session_undo_refuse('roster_decisions_exist', v_work::text);
  end if;
  if (v_scope ->> 'entangledActivityCount')::int > 0 then
    perform training_load.session_undo_refuse('entangled_activity');
  end if;
  if (v_scope ->> 'calendarLinkCount')::int > 0 then
    perform training_load.session_undo_refuse('calendar_link_exists', v_scope ->> 'calendarLinkCount');
  end if;
  if (v_scope ->> 'manualWriteRequestCount')::int > 0 then
    perform training_load.session_undo_refuse('manual_write_request_exists');
  end if;
  v_part := coalesce(array(select jsonb_array_elements_text(v_scope -> 'participantIds')::uuid), '{}');
  v_occ := coalesce(array(select jsonb_array_elements_text(v_scope -> 'occasionIds')::uuid), '{}');
  v_seg := coalesce(array(select jsonb_array_elements_text(v_scope -> 'segmentIds')::uuid), '{}');
  v_ident := coalesce(array(select jsonb_array_elements_text(v_scope -> 'identityIds')::uuid), '{}');
  v_batch := coalesce(array(select jsonb_array_elements_text(v_scope -> 'batchIds')::uuid), '{}');
  v_obs := coalesce(array(select jsonb_array_elements_text(v_scope -> 'observationIds')::uuid), '{}');

  -- 7. The removal, in the CLI's order, under the marker.
  perform set_config('optimove.session_undo_tx', txid_current()::text, true);
  begin
    if cardinality(v_obs) > 0 then
      delete from training.activity_source_observations where id = any(v_obs);
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'activity_source_observations', v_n);
    end if;
    if cardinality(v_act) > 0 then
      delete from training.activity_component_metric_segment_links l using training.activity_components c
       where c.id = l.activity_component_id and c.activity_id = any(v_act);
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'activity_component_metric_segment_links', v_n);
      delete from training.activity_components where activity_id = any(v_act);
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'activity_components', v_n);
      -- Only this event's links: a foreign one left behind makes the activity delete fail and the whole call roll back.
      delete from training.activity_participant_metric_participant_links l using training_load.metric_event_participants p
       where p.id = l.metric_event_participant_id and p.event_id = v_event_id;
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'activity_participant_metric_participant_links', v_n);
      delete from training.activity_participants where activity_id = any(v_act);
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'activity_participants', v_n);
      delete from training.activity_metric_event_links where metric_event_id = v_event_id;
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'activity_metric_event_links', v_n);
      delete from training.activities where id = any(v_act);
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'activities', v_n);
    end if;
    if cardinality(v_occ) > 0 then
      delete from training_load.metric_value_source_provenance p using training_load.metric_values v
       where v.id = p.metric_value_id and v.occasion_id = any(v_occ);
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'metric_value_source_provenance', v_n);
      delete from training_load.metric_values where occasion_id = any(v_occ);
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'metric_values', v_n);
      update training_load.metric_source_identities set current_occasion_id = null where current_occasion_id = any(v_occ);
      -- One statement for the whole chain: occasions point at each other and the checks run at the end of the statement.
      delete from training_load.metric_measurement_occasions where id = any(v_occ);
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'metric_measurement_occasions', v_n);
    end if;
    if cardinality(v_ident) > 0 then
      delete from training_load.metric_source_identities where id = any(v_ident);
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'metric_source_identities', v_n);
    end if;
    if cardinality(v_part) > 0 then
      delete from training_load.metric_event_participants where id = any(v_part);
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'metric_event_participants', v_n);
    end if;
    if cardinality(v_seg) > 0 then
      delete from training_load.metric_event_segments where id = any(v_seg);
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'metric_event_segments', v_n);
    end if;
    if (v_scope ->> 'hasBinding')::boolean then
      delete from training_load.metric_event_source_bindings b where b.event_id = v_event_id;
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'metric_event_source_bindings', v_n);
    end if;
    delete from training_load.metric_events where id = v_event_id;
    get diagnostics v_n = row_count;
    v_removed := training_load.session_undo_add(v_removed, 'metric_events', v_n);
    if cardinality(v_batch) > 0 then
      delete from training_load.metric_import_batches b
       where b.id = any(v_batch)
         and not exists (select 1 from training_load.metric_measurement_occasions o where o.import_batch_id = b.id);
      get diagnostics v_n = row_count;
      v_removed := training_load.session_undo_add(v_removed, 'metric_import_batches', v_n);
    end if;
  exception when foreign_key_violation then
    get stacked diagnostics v_constraint = constraint_name;
    perform training_load.session_undo_refuse('referenced_elsewhere', v_constraint);
  end;
  select coalesce(sum(value::int), 0)::int into v_total from jsonb_each_text(v_removed);

  -- 8. The deletion log (v21): one row, in this transaction, after the event is gone.
  insert into training_load.import_deletion_log
    (deleted_by_user_id, authorized_via, reason, event_id, source_system, source_connection_id, source_external_id,
     owner_team_id, occurred_date, reference_set_external_id, removed_counts, removed_total)
  values (p_actor, 'platform_admin', v_reason, v_event_id, v_scope ->> 'sourceSystem', (v_scope ->> 'connectionId')::uuid,
          v_scope ->> 'externalId', (v_scope ->> 'ownerTeamId')::uuid, (v_scope ->> 'occurredDate')::date,
          v_scope ->> 'referenceSetExternalId', v_removed, v_total)
  returning id into v_log;

  -- 9. Every candidate of the event is marked undone (their request is checked at the end of this call). Then, for the NEWEST
  --    approved content among them, when its raw snapshot is still available, the check that last saw it succeeded and the
  --    team has no live candidate of the session with other content, a fresh pending candidate of that content is written.
  update training_load.gpexe_import_candidates
     set import_undone_at = clock_timestamp(), import_undone_request_id = v_req_id
   where id = any(v_ids);
  select c.* into v_offer
    from training_load.gpexe_import_candidates c
    join training_load.gpexe_import_approvals a on a.candidate_id = c.id
   where c.id = any(v_ids)
   order by a.approved_at desc, c.id desc limit 1;
  select k.status into v_last_status from training_load.gpexe_import_checks k
   where k.id = v_offer.last_seen_check_id and k.owner_team_id = p_team;
  if v_offer.raw_bundle is not null and v_offer.raw_purged_at is null and v_offer.raw_expires_at > now()
     and v_last_status = 'succeeded'
     -- Never offer content older than what the team already has: a live candidate of the same session with other content
     -- (newer data a search published) means the old snapshot would be approvable over it.
     and not exists (select 1 from training_load.gpexe_import_candidates o
                      where o.owner_team_id = p_team and o.gpexe_team_session_id = v_offer.gpexe_team_session_id
                        and o.import_undone_at is null and o.bundle_hash <> v_offer.bundle_hash
                        and o.status in ('pending', 'blocked', 'imported')) then
    v_new := gen_random_uuid();
    insert into training_load.gpexe_import_candidates
      (id, owner_team_id, gpexe_team_session_id, session_started_at, session_label, bundle_hash, raw_bundle, raw_expires_at,
       status, first_seen_check_id, last_seen_check_id, first_seen_at, last_seen_at, drill_parameter_effect)
    values (v_new, p_team, v_offer.gpexe_team_session_id, v_offer.session_started_at, v_offer.session_label, v_offer.bundle_hash,
            v_offer.raw_bundle, least(v_offer.raw_expires_at, now() + interval '30 days'), 'pending',
            v_offer.first_seen_check_id, v_offer.last_seen_check_id, v_offer.first_seen_at, now(), v_offer.drill_parameter_effect);
  end if;

  -- 10. The request record, then the deferred link is checked here, not at the COMMIT.
  insert into training_load.gpexe_session_undo_requests
    (id, requested_by_user_id, request_key, request_hash, owner_team_id, candidate_id, undone_candidate_ids, event_id,
     deletion_log_id, reason, removed_counts, removed_total, new_candidate_id)
  values (v_req_id, p_actor, p_request_key, v_hash, p_team, p_candidate, v_ids, v_event_id, v_log, v_reason, v_removed, v_total, v_new);
  set constraints training_load.gpexe_import_candidates_import_undone_request_fkey immediate;
  -- The marker covers this call only.
  perform set_config('optimove.session_undo_tx', '', true);
  return query select false, v_event_id, v_log, v_removed, v_total, v_new, v_ids;
end;
$$;

CREATE FUNCTION training_load.unit_conversions_actor_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  actor uuid;
begin
  if tg_op = 'INSERT' then
    if new.created_by_user_id is null then
      -- A seed row: v34's guard decides (its seed window).
      return new;
    end if;
    actor := training_load.source_metric_context_actor();
    if new.created_by_user_id is distinct from actor
       or training_load.source_metric_actor_basis(actor, null) is distinct from 'platform_admin' then
      raise exception 'unit conversion: the acting user may not write this conversion' using errcode = '42501';
    end if;
    return new;
  end if;
  if old.state = 'active' and new.state = 'retired' then
    actor := training_load.source_metric_context_actor();
    if new.retired_by_user_id is distinct from actor
       or training_load.source_metric_actor_basis(actor, null) is distinct from 'platform_admin' then
      raise exception 'unit conversion: the acting user may not write this conversion' using errcode = '42501';
    end if;
    if new.retired_at is distinct from now() then
      raise exception 'unit conversion: a retirement carries the time of its own transaction' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.unit_conversions_create_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from training_load.source_metric_audit
                  where action = 'unit_conversion_create' and unit_conversion_id = new.id) then
    raise exception 'unit_conversions: a conversion is written with its unit_conversion_create audit row' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.unit_conversions_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'unit_conversions: a conversion is never deleted; retire it' using errcode = '23514';
  end if;
  if tg_op = 'INSERT' then
    if new.state is distinct from 'active' then
      raise exception 'unit_conversions: a conversion is created active' using errcode = '23514';
    end if;
    if new.created_by_user_id is not null then
      perform training_load.source_metric_require_platform_admin(new.created_by_user_id);
    elsif new.seed_migration is not null then
      perform training_load.source_metric_require_seed_window(new.seed_migration);
    end if;
    return new;
  end if;
  if old.state = 'retired' or new.state is not distinct from old.state
     or new.id is distinct from old.id or new.from_unit is distinct from old.from_unit or new.to_unit is distinct from old.to_unit
     or new.scale::text is distinct from old.scale::text or new.scale_divisor::text is distinct from old.scale_divisor::text
     or new."offset"::text is distinct from old."offset"::text or new.evidence_ref is distinct from old.evidence_ref
     or new.created_by_user_id is distinct from old.created_by_user_id or new.created_at is distinct from old.created_at
     or new.seed_migration is distinct from old.seed_migration then
    raise exception 'unit_conversions: a conversion is immutable; the only change is its retirement' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.unit_conversions_retire_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from training_load.source_metric_audit
                  where action = 'unit_conversion_retire' and unit_conversion_id = new.id
                    and from_status = 'active' and to_status = 'retired') then
    raise exception 'unit_conversions: a retirement is written with its unit_conversion_retire audit row' using errcode = '23514';
  end if;
  return null;
end;
$$;

CREATE FUNCTION training_load.update_dashboard_metadata(p_dashboard_id uuid, p_expected_revision integer, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_clear_description boolean DEFAULT false, p_default_filter jsonb DEFAULT NULL::jsonb, p_clear_default_filter boolean DEFAULT false, p_is_template boolean DEFAULT NULL::boolean) RETURNS SETOF training_load.dashboards
    LANGUAGE plpgsql
    AS $$
declare
  v_current_revision integer;
begin
  select d.revision into v_current_revision from training_load.dashboards d where d.id = p_dashboard_id for update;
  if not found then
    raise exception 'update_dashboard_metadata: dashboard % not found', p_dashboard_id;
  end if;
  perform training_load.assert_dashboard_writable(p_dashboard_id);
  if v_current_revision <> p_expected_revision then
    raise exception 'update_dashboard_metadata: stale revision (expected %, dashboard is at %) — reload and retry', p_expected_revision, v_current_revision using errcode = '40001';
  end if;
  update training_load.dashboards d set
    name = coalesce(p_name, d.name),
    description = case when p_clear_description then null else coalesce(p_description, d.description) end,
    default_filter = case when p_clear_default_filter then null else coalesce(p_default_filter, d.default_filter) end,
    is_template = coalesce(p_is_template, d.is_template)
  where d.id = p_dashboard_id and d.revision = p_expected_revision;
  if not found then
    raise exception 'update_dashboard_metadata: stale revision (expected %) — reload and retry', p_expected_revision using errcode = '40001';
  end if;
  return query select * from training_load.dashboards where id = p_dashboard_id;
end;
$$;

CREATE FUNCTION training_load.update_series(p_series_id uuid, p_widget_id uuid, p_expected_widget_revision integer, p_axis character varying DEFAULT NULL::character varying, p_color text DEFAULT NULL::text, p_clear_color boolean DEFAULT false, p_display_label text DEFAULT NULL::text, p_clear_display_label boolean DEFAULT false, p_source_policy character varying DEFAULT NULL::character varying, p_source_connection_id uuid DEFAULT NULL::uuid, p_data_scope_level character varying DEFAULT NULL::character varying, p_analytical_aggregation character varying DEFAULT NULL::character varying, p_aggregation_role_policy character varying DEFAULT NULL::character varying, p_coverage_policy character varying DEFAULT NULL::character varying, p_comparison_period character varying DEFAULT NULL::character varying, p_clear_comparison_period boolean DEFAULT false) RETURNS TABLE(series_id uuid, widget_revision integer)
    LANGUAGE plpgsql
    AS $$
declare
  v_dashboard_id uuid;
  v_current_widget_revision integer;
begin
  select w.dashboard_id into v_dashboard_id from training_load.dashboard_widgets w where w.id = p_widget_id;
  if not found then
    raise exception 'update_series: widget % not found', p_widget_id;
  end if;
  perform 1 from training_load.dashboards d where d.id = v_dashboard_id for update;
  perform training_load.assert_dashboard_writable(v_dashboard_id);
  select w.revision into v_current_widget_revision from training_load.dashboard_widgets w where w.id = p_widget_id for update;
  if v_current_widget_revision <> p_expected_widget_revision then
    raise exception 'update_series: stale widget revision (expected %, widget is at %) — reload and retry', p_expected_widget_revision, v_current_widget_revision using errcode = '40001';
  end if;
  -- Whenever the CALLER explicitly changes source_policy to anything
  -- other than 'source_connection', the connection pin is cleared
  -- automatically — no separate p_clear flag needed, since a non-
  -- 'source_connection' policy can never legally carry a connection id
  -- (the table's own CHECK constraint would otherwise reject the
  -- transition outright, since the OLD connection id would survive a
  -- naive coalesce).
  update training_load.dashboard_widget_series s set
    axis = coalesce(p_axis, s.axis),
    color = case when p_clear_color then null else coalesce(p_color, s.color) end,
    display_label = case when p_clear_display_label then null else coalesce(p_display_label, s.display_label) end,
    source_policy = coalesce(p_source_policy, s.source_policy),
    source_connection_id = case
      when p_source_policy is not null and p_source_policy <> 'source_connection' then null
      else coalesce(p_source_connection_id, s.source_connection_id)
    end,
    data_scope_level = coalesce(p_data_scope_level, s.data_scope_level),
    analytical_aggregation = coalesce(p_analytical_aggregation, s.analytical_aggregation),
    aggregation_role_policy = coalesce(p_aggregation_role_policy, s.aggregation_role_policy),
    coverage_policy = coalesce(p_coverage_policy, s.coverage_policy),
    comparison_period = case when p_clear_comparison_period then null else coalesce(p_comparison_period, s.comparison_period) end
  where s.id = p_series_id and s.widget_id = p_widget_id;
  if not found then
    raise exception 'update_series: series % not found under widget %', p_series_id, p_widget_id;
  end if;
  return query select p_series_id, w.revision from training_load.dashboard_widgets w where w.id = p_widget_id;
end;
$$;

CREATE FUNCTION training_load.update_widget_content(p_widget_id uuid, p_expected_widget_revision integer, p_widget_type text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_group_by character varying DEFAULT NULL::character varying, p_state character varying DEFAULT NULL::character varying, p_display_config jsonb DEFAULT NULL::jsonb, p_local_filter_override jsonb DEFAULT NULL::jsonb, p_clear_local_filter_override boolean DEFAULT false) RETURNS TABLE(widget_id uuid, widget_revision integer, dashboard_id uuid)
    LANGUAGE plpgsql
    AS $$
declare
  v_dashboard_id uuid;
  v_current_widget_revision integer;
begin
  select w.dashboard_id into v_dashboard_id from training_load.dashboard_widgets w where w.id = p_widget_id;
  if not found then
    raise exception 'update_widget_content: widget % not found', p_widget_id;
  end if;
  perform 1 from training_load.dashboards d where d.id = v_dashboard_id for update;
  perform training_load.assert_dashboard_writable(v_dashboard_id);
  select w.revision into v_current_widget_revision from training_load.dashboard_widgets w where w.id = p_widget_id for update;
  if not found then
    raise exception 'update_widget_content: widget % disappeared concurrently', p_widget_id;
  end if;
  if v_current_widget_revision <> p_expected_widget_revision then
    raise exception 'update_widget_content: stale widget revision (expected %, widget is at %) — reload and retry', p_expected_widget_revision, v_current_widget_revision using errcode = '40001';
  end if;
  update training_load.dashboard_widgets w set
    widget_type = coalesce(p_widget_type, w.widget_type),
    title = coalesce(p_title, w.title),
    group_by = coalesce(p_group_by, w.group_by),
    state = coalesce(p_state, w.state),
    display_config = coalesce(p_display_config, w.display_config),
    local_filter_override = case when p_clear_local_filter_override then null else coalesce(p_local_filter_override, w.local_filter_override) end
  where w.id = p_widget_id and w.revision = p_expected_widget_revision;
  if not found then
    raise exception 'update_widget_content: stale widget revision (expected %) — reload and retry', p_expected_widget_revision using errcode = '40001';
  end if;
  return query select w.id, w.revision, w.dashboard_id from training_load.dashboard_widgets w where w.id = p_widget_id;
end;
$$;

CREATE FUNCTION training_load.update_widget_layout(p_widget_id uuid, p_expected_widget_revision integer, p_x smallint DEFAULT NULL::smallint, p_y smallint DEFAULT NULL::smallint, p_width smallint DEFAULT NULL::smallint, p_height smallint DEFAULT NULL::smallint, p_mobile_order integer DEFAULT NULL::integer) RETURNS TABLE(widget_id uuid, dashboard_id uuid, x smallint, y smallint, width smallint, height smallint, mobile_order integer, widget_revision integer, dashboard_revision integer)
    LANGUAGE plpgsql
    AS $$
declare
  v_dashboard_id uuid;
  v_current_widget_revision integer;
  v_locked_dashboard_id uuid;
  v_current_x smallint;
  v_current_y smallint;
  v_current_width smallint;
  v_current_height smallint;
  v_current_mobile_order integer;
begin
  -- 1. An UNLOCKED read used ONLY to find dashboard_id (never trusted for
  --    anything else — it exists purely to know which dashboard row to
  --    lock first, since dashboard_id is immutable so this can never
  --    itself go stale in a way that matters).
  select w.dashboard_id into v_dashboard_id from training_load.dashboard_widgets w where w.id = p_widget_id;
  if not found then
    raise exception 'update_widget_layout: widget % not found', p_widget_id;
  end if;

  -- 2. Lock the DASHBOARD row first — genuinely first, before this
  --    function has touched dashboard_widgets at all.
  perform 1 from training_load.dashboards d where d.id = v_dashboard_id for update;
  perform training_load.assert_dashboard_writable(v_dashboard_id);

  -- 3. NOW lock and RE-READ the widget row — this is the fresh,
  --    trustworthy revision AND current position/size, taken only after
  --    the dashboard lock is held, so nothing can have raced it
  --    undetected in between, and an omitted field's COALESCE fallback
  --    (step 6) is never a stale pre-lock value.
  select w.dashboard_id, w.revision, w.x, w.y, w.width, w.height, w.mobile_order
    into v_locked_dashboard_id, v_current_widget_revision, v_current_x, v_current_y, v_current_width, v_current_height, v_current_mobile_order
    from training_load.dashboard_widgets w where w.id = p_widget_id for update;
  if not found then
    raise exception 'update_widget_layout: widget % disappeared concurrently (deleted between lookup and lock)', p_widget_id;
  end if;

  -- 4. Confirm the widget still belongs to the SAME dashboard we locked
  --    (defense-in-depth — dashboard_id is immutable by trigger).
  if v_locked_dashboard_id is distinct from v_dashboard_id then
    raise exception 'update_widget_layout: widget % dashboard_id changed between lookup and lock (% -> %)', p_widget_id, v_dashboard_id, v_locked_dashboard_id;
  end if;

  -- 5. ONLY NOW check the caller's expected revision, against the FRESH,
  --    locked value from step 3 — never the stale step-1 read.
  if v_current_widget_revision <> p_expected_widget_revision then
    raise exception 'update_widget_layout: stale widget revision (expected %, widget is at %) — reload and retry', p_expected_widget_revision, v_current_widget_revision using errcode = '40001';
  end if;

  -- 6. The UPDATE itself — every field COALESCEs against the widget's
  --    OWN locked current value when the caller omitted it — with an
  --    EXTRA revision guard in the WHERE clause on top of the row lock
  --    already held.
  update training_load.dashboard_widgets w
    set x = coalesce(p_x, v_current_x), y = coalesce(p_y, v_current_y),
        width = coalesce(p_width, v_current_width), height = coalesce(p_height, v_current_height),
        mobile_order = coalesce(p_mobile_order, v_current_mobile_order)
    where w.id = p_widget_id and w.revision = p_expected_widget_revision;
  if not found then
    raise exception 'update_widget_layout: stale widget revision (expected %) — reload and retry', p_expected_widget_revision using errcode = '40001';
  end if;

  set constraints training_load.dashboard_widgets_check_no_overlap, training_load.dashboard_widgets_order_unique, training_load.dashboard_widgets_mobile_order_unique immediate;

  -- 7. Return the REAL, fresh widget AND dashboard revision tokens.
  return query
    select w.id, w.dashboard_id, w.x, w.y, w.width, w.height, w.mobile_order, w.revision, d.revision
    from training_load.dashboard_widgets w
    join training_load.dashboards d on d.id = w.dashboard_id
    where w.id = p_widget_id;
end;
$$;

CREATE FUNCTION training_load.validate_event_source_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  ev record;
begin
  select source_connection_id, source_external_id into ev
    from training_load.metric_events where id = new.event_id for update;
  if not found then
    raise exception 'metric_event_source_bindings: event (id=%) does not exist', new.event_id;
  end if;
  if ev.source_connection_id is distinct from new.source_connection_id
     or ev.source_external_id is distinct from new.source_external_id then
    raise exception 'metric_event_source_bindings: binding (connection=%, external_id=%) does not match event (id=%, connection=%, external_id=%)',
      new.source_connection_id, new.source_external_id, new.event_id, ev.source_connection_id, ev.source_external_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_external_schedule_timezone_and_recurrence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_version jsonb;
begin
  if not exists (select 1 from pg_timezone_names where name = NEW.timezone) then
    raise exception 'timezone % is not a recognized IANA timezone name', NEW.timezone;
  end if;
  if NEW.recurrence_rule is not null then
    v_version := NEW.recurrence_rule -> 'version';
    if v_version is null or jsonb_typeof(v_version) is distinct from 'number' then
      raise exception 'recurrence_rule.version must be a JSON number';
    end if;
    if (v_version #>> '{}')::numeric <> NEW.recurrence_rule_version then
      raise exception 'recurrence_rule.version (%) must match recurrence_rule_version column (%)', v_version, NEW.recurrence_rule_version;
    end if;
  end if;
  return NEW;
end $$;

CREATE FUNCTION training_load.validate_gpexe_athlete_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'gpexe_athlete_links rows are never deleted; unlink instead';
  end if;
  if tg_op = 'UPDATE' then
    if old.unlinked_at is not null then
      raise exception 'gpexe_athlete_links: link % is already unlinked', old.id;
    end if;
    if new.id is distinct from old.id or new.owner_team_id is distinct from old.owner_team_id
       or new.gpexe_athlete_id is distinct from old.gpexe_athlete_id or new.athlete_id is distinct from old.athlete_id
       or new.linked_by_user_id is distinct from old.linked_by_user_id or new.linked_at is distinct from old.linked_at
       or new.unlinked_at is null then
      raise exception 'gpexe_athlete_links: only unlinking is allowed';
    end if;
    return new;
  end if;
  -- Same membership rule the importer applies (assertAthletesInTeam).
  if not exists (
    select 1 from public.athlete_memberships m
     where m.athlete_id = new.athlete_id and m.team_id = new.owner_team_id
       and m.membership_type = 'team' and m.status = 'active'
  ) then
    raise exception 'gpexe_athlete_links: athlete % has no active membership in team %', new.athlete_id, new.owner_team_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_gpexe_import_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  right_row record;
  cand record;
  seen_status text;
begin
  if tg_op <> 'INSERT' then
    raise exception 'gpexe_import_approvals is append-only (% refused)', tg_op;
  end if;
  -- Roles before the candidate: the lock order above.
  select * into right_row from training_load.lock_gpexe_import_approver(new.approved_by_user_id, new.owner_team_id);
  if right_row.basis is distinct from new.approval_basis or right_row.grant_id is distinct from new.approver_grant_id then
    raise exception 'gpexe_import_approvals: the recorded basis does not match the approver''s current right'
      using errcode = 'insufficient_privilege';
  end if;
  select owner_team_id, gpexe_team_session_id, bundle_hash, preview_hash, status, raw_bundle is not null as has_snapshot, raw_expires_at,
         coalesce(jsonb_array_length(preview -> 'changesToImported'), 0) as changes_to_imported,
         last_seen_check_id, drill_parameter_effect
    into cand
    from training_load.gpexe_import_candidates
   where id = new.candidate_id
   for update;
  if not found or cand.owner_team_id is distinct from new.owner_team_id then
    raise exception 'gpexe_import_approvals: candidate % does not belong to team %', new.candidate_id, new.owner_team_id;
  end if;
  if cand.status <> 'pending' then
    raise exception 'gpexe_import_approvals: candidate % is %, not pending', new.candidate_id, cand.status;
  end if;
  if not cand.has_snapshot or cand.raw_expires_at <= now() then
    raise exception 'gpexe_import_approvals: the snapshot of candidate % has expired', new.candidate_id;
  end if;
  if cand.gpexe_team_session_id is distinct from new.gpexe_team_session_id
     or cand.bundle_hash is distinct from new.bundle_hash
     or cand.preview_hash is distinct from new.preview_hash then
    raise exception 'gpexe_import_approvals: the approval does not match the candidate''s content and preview';
  end if;
  -- The accepted changes are the ones the preview lists, not a number the
  -- writer chose (the CHECK then requires them accepted when there are any).
  if new.changes_to_imported is distinct from cand.changes_to_imported then
    raise exception 'gpexe_import_approvals: changes_to_imported does not match the candidate''s preview';
  end if;
  -- v33: only a candidate whose last sighting is a check of its team that
  -- atomically succeeded is actionable, and a session with two or more drills
  -- only with a confirmed drill-parameter effect.
  select status into seen_status from training_load.gpexe_import_checks where id = cand.last_seen_check_id and owner_team_id = cand.owner_team_id;
  if seen_status is distinct from 'succeeded' then
    raise exception 'gpexe_import_approvals: candidate % is not confirmed by a succeeded check', new.candidate_id;
  end if;
  if cand.drill_parameter_effect is null or cand.drill_parameter_effect not in ('not_required', 'confirmed') then
    raise exception 'gpexe_import_approvals: candidate % has no confirmed drill-parameter effect', new.candidate_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_gpexe_import_approver() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'gpexe_import_approvers rows are never deleted; revoke instead';
  end if;
  if tg_op = 'UPDATE' then
    if old.revoked_at is not null then
      raise exception 'gpexe_import_approvers: grant % is already revoked', old.id;
    end if;
    if new.id is distinct from old.id or new.owner_team_id is distinct from old.owner_team_id
       or new.user_id is distinct from old.user_id or new.granted_by_user_id is distinct from old.granted_by_user_id
       or new.granted_at is distinct from old.granted_at or new.grant_reason is distinct from old.grant_reason
       or new.revoked_at is null then
      raise exception 'gpexe_import_approvers: only revoking is allowed';
    end if;
    perform training_load.assert_active_platform_admin(new.revoked_by_user_id, 'gpexe_import_approvers revoke');
    return new;
  end if;
  perform training_load.assert_active_platform_admin(new.granted_by_user_id, 'gpexe_import_approvers grant');
  -- The grantee must be an active user who coaches this team right now.
  perform 1
    from public.user_team_roles tr
    join public.users u on u.id = tr.user_id
   where tr.user_id = new.user_id and tr.team_id = new.owner_team_id
     and tr.role = 'team_coach' and tr.is_active = true and u.is_active = true
   for share of tr;
  if not found then
    raise exception 'gpexe_import_approvers: user % is not an active coach of team %', new.user_id, new.owner_team_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_import_deletion_log() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform 1
    from public.user_global_roles r
    join public.users u on u.id = r.user_id
   where r.user_id = new.deleted_by_user_id
     and r.role = 'platform_admin'
     and r.is_active = true
     and u.is_active = true
   for share of r;
  if not found then
    raise exception 'import_deletion_log: user % is not an active platform admin — only a platform admin may undo an imported session', new.deleted_by_user_id
      using errcode = 'insufficient_privilege';
  end if;
  if exists (select 1 from training_load.metric_events where id = new.event_id) then
    raise exception 'import_deletion_log: event % still exists — a log row records a removal made in the same transaction, not a plan', new.event_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_measurement_occasion_segment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  participant_event uuid;
  segment_event uuid;
begin
  if new.segment_id is null then
    return new;
  end if;
  select event_id into participant_event from training_load.metric_event_participants where id = new.event_participant_id;
  select event_id into segment_event from training_load.metric_event_segments where id = new.segment_id;
  if participant_event is distinct from segment_event then
    raise exception 'segment % does not belong to the same event as participant %', new.segment_id, new.event_participant_id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_metric_value() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_type varchar;
  v_min numeric;
  v_max numeric;
begin
  select value_type, min_value, max_value into v_type, v_min, v_max
    from training_load.metric_definition_versions where id = new.metric_definition_version_id;
  if v_type = 'numeric' then
    if new.value_numeric is null or new.value_boolean is not null or new.value_text is not null then
      raise exception 'value_type=numeric requires value_numeric only (occasion=%, definition=%)', new.occasion_id, new.metric_definition_id;
    end if;
    if (v_min is not null and new.value_numeric < v_min) or (v_max is not null and new.value_numeric > v_max) then
      raise exception 'value_numeric % out of bounds [%, %] for definition %', new.value_numeric, v_min, v_max, new.metric_definition_id;
    end if;
  elsif v_type = 'boolean' then
    if new.value_boolean is null or new.value_numeric is not null or new.value_text is not null then
      raise exception 'value_type=boolean requires value_boolean only (occasion=%, definition=%)', new.occasion_id, new.metric_definition_id;
    end if;
  elsif v_type = 'text' then
    if new.value_text is null or new.value_numeric is not null or new.value_boolean is not null then
      raise exception 'value_type=text requires value_text only (occasion=%, definition=%)', new.occasion_id, new.metric_definition_id;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_no_identity_points_at_flagged() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if exists (select 1 from training_load.metric_source_identities where current_occasion_id = new.id) then
    raise exception 'occasion (id=%) was marked import_conflict_status=% but a source identity still points at it as current', new.id, new.import_conflict_status;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_no_identity_points_at_superseded() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if exists (select 1 from training_load.metric_source_identities where current_occasion_id = new.id) then
    raise exception 'occasion (id=%) was marked superseded but a source identity still points at it as current', new.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_occasion_source_owner_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  event_scope varchar;
  event_club uuid;
  event_team uuid;
  event_user uuid;
  ref_scope varchar;
  ref_club uuid;
  ref_team uuid;
  ref_user uuid;
begin
  if new.source_identity_id is null and new.import_batch_id is null then
    return new;
  end if;
  select e.owner_scope, e.owner_club_id, e.owner_team_id, e.owner_user_id into event_scope, event_club, event_team, event_user
    from training_load.metric_event_participants p
    join training_load.metric_events e on e.id = p.event_id
    where p.id = new.event_participant_id;

  if new.source_identity_id is not null then
    select c.owner_scope, c.owner_club_id, c.owner_team_id, c.owner_user_id into ref_scope, ref_club, ref_team, ref_user
      from training_load.metric_source_identities si
      join training_load.metric_source_connections c on c.id = si.source_connection_id
      where si.id = new.source_identity_id;
    if event_scope is distinct from ref_scope or event_club is distinct from ref_club
       or event_team is distinct from ref_team or event_user is distinct from ref_user then
      raise exception 'occasion''s root event owner_scope does not match its source connection''s owner_scope (event=%/%/%/% connection=%/%/%/%)',
        event_scope, event_club, event_team, event_user, ref_scope, ref_club, ref_team, ref_user;
    end if;
  end if;

  if new.import_batch_id is not null then
    select b.owner_scope, b.owner_club_id, b.owner_team_id, b.owner_user_id into ref_scope, ref_club, ref_team, ref_user
      from training_load.metric_import_batches b where b.id = new.import_batch_id;
    if event_scope is distinct from ref_scope or event_club is distinct from ref_club
       or event_team is distinct from ref_team or event_user is distinct from ref_user then
      raise exception 'occasion''s root event owner_scope does not match its import batch''s owner_scope (event=%/%/%/% batch=%/%/%/%)',
        event_scope, event_club, event_team, event_user, ref_scope, ref_club, ref_team, ref_user;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_source_identity_current_occasion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  occ_superseded uuid;
  occ_conflict varchar;
begin
  if new.current_occasion_id is null or new.current_occasion_id is not distinct from old.current_occasion_id then
    return new;
  end if;
  select superseded_by_occasion_id, import_conflict_status into occ_superseded, occ_conflict
    from training_load.metric_measurement_occasions where id = new.current_occasion_id;
  if occ_superseded is not null then
    raise exception 'metric_source_identities.current_occasion_id (id=%) cannot point at an already-superseded occasion', new.current_occasion_id;
  end if;
  if occ_conflict is not null then
    raise exception 'metric_source_identities.current_occasion_id (id=%) cannot point at an import-conflict-flagged occasion (status=%)', new.current_occasion_id, occ_conflict;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_structure_link_scope_breadth() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  target_scope varchar;
  target_club uuid;
  target_team uuid;
  target_user uuid;
begin
  if new.domain_id is not null then
    select owner_scope, owner_club_id, owner_team_id, owner_user_id into target_scope, target_club, target_team, target_user
      from training_load.metric_domains where id = new.domain_id;
    if not training_load.link_scope_within_target(new.owner_scope, new.owner_club_id, new.owner_team_id, new.owner_user_id, target_scope, target_club, target_team, target_user) then
      raise exception 'structure link owner_scope=% exceeds visibility of target domain %', new.owner_scope, new.domain_id;
    end if;
  end if;
  if new.category_id is not null then
    select owner_scope, owner_club_id, owner_team_id, owner_user_id into target_scope, target_club, target_team, target_user
      from training_load.metric_categories where id = new.category_id;
    if not training_load.link_scope_within_target(new.owner_scope, new.owner_club_id, new.owner_team_id, new.owner_user_id, target_scope, target_club, target_team, target_user) then
      raise exception 'structure link owner_scope=% exceeds visibility of target category %', new.owner_scope, new.category_id;
    end if;
  end if;
  if new.metric_definition_id is not null then
    select owner_scope, owner_club_id, owner_team_id, owner_user_id into target_scope, target_club, target_team, target_user
      from training_load.metric_definitions where id = new.metric_definition_id;
    if not training_load.link_scope_within_target(new.owner_scope, new.owner_club_id, new.owner_team_id, new.owner_user_id, target_scope, target_club, target_team, target_user) then
      raise exception 'structure link owner_scope=% exceeds visibility of target definition %', new.owner_scope, new.metric_definition_id;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_template_metric_key_hints_shape() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_elem jsonb;
begin
  if new.template_metric_key_hints is null then
    return new;
  end if;
  if jsonb_typeof(new.template_metric_key_hints) <> 'array' then
    raise exception 'dashboard_widget_series: template_metric_key_hints must be a JSON array of objects (widget %)', new.widget_id;
  end if;
  for v_elem in select * from jsonb_array_elements(new.template_metric_key_hints) loop
    if jsonb_typeof(v_elem) <> 'object' then
      raise exception 'dashboard_widget_series: template_metric_key_hints elements must be objects, not a bare string/scalar (got %, widget %) — every hint must carry at least {"key": "..."}', v_elem, new.widget_id;
    end if;
    if not (v_elem ? 'key') or jsonb_typeof(v_elem -> 'key') <> 'string' or length(v_elem ->> 'key') = 0 then
      raise exception 'dashboard_widget_series: each template_metric_key_hints element requires a non-empty string "key" (got %, widget %)', v_elem, new.widget_id;
    end if;
    if (v_elem ? 'valueType') and v_elem -> 'valueType' is not null and (v_elem ->> 'valueType') not in ('numeric', 'boolean', 'text') then
      raise exception 'dashboard_widget_series: template_metric_key_hints "valueType" must be numeric/boolean/text (got %, widget %)', v_elem -> 'valueType', new.widget_id;
    end if;
    if (v_elem ? 'scopeLevel') and v_elem -> 'scopeLevel' is not null and (v_elem ->> 'scopeLevel') not in ('day', 'session', 'component') then
      raise exception 'dashboard_widget_series: template_metric_key_hints "scopeLevel" must be day/session/component (got %, widget %)', v_elem -> 'scopeLevel', new.widget_id;
    end if;
    if (v_elem ? 'unit') and v_elem -> 'unit' is not null and jsonb_typeof(v_elem -> 'unit') <> 'string' then
      raise exception 'dashboard_widget_series: template_metric_key_hints "unit" must be a string or explicit null (got %, widget %)', v_elem -> 'unit', new.widget_id;
    end if;
  end loop;
  return new;
end;
$$;

CREATE FUNCTION training_load.validate_template_resolution_candidates_shape() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_elem jsonb;
  v_count integer := 0;
  v_seen text[] := '{}';
  v_text text;
begin
  if new.template_resolution_candidates is null then
    return new;
  end if;
  if jsonb_typeof(new.template_resolution_candidates) <> 'array' then
    raise exception 'dashboard_widget_series: template_resolution_candidates must be a JSON array of UUID strings (widget %)', new.widget_id;
  end if;
  for v_elem in select * from jsonb_array_elements(new.template_resolution_candidates) loop
    if jsonb_typeof(v_elem) <> 'string' then
      raise exception 'dashboard_widget_series: template_resolution_candidates elements must be UUID strings (got %, widget %)', v_elem, new.widget_id;
    end if;
    v_text := v_elem #>> '{}';
    begin
      perform v_text::uuid;
    exception when invalid_text_representation then
      raise exception 'dashboard_widget_series: template_resolution_candidates element % is not a valid UUID (widget %)', v_text, new.widget_id;
    end;
    if v_text = any(v_seen) then
      raise exception 'dashboard_widget_series: template_resolution_candidates contains a duplicate id % (widget %)', v_text, new.widget_id;
    end if;
    v_seen := v_seen || v_text;
    v_count := v_count + 1;
  end loop;
  if v_count < 2 then
    raise exception 'dashboard_widget_series: template_resolution_candidates must have at least 2 DISTINCT candidates for resolution_status=ambiguous (got %, widget %)', v_count, new.widget_id;
  end if;
  return new;
end;
$$;

CREATE TABLE calendar.event_activity_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    activity_id uuid NOT NULL,
    link_method character varying(10) DEFAULT 'manual'::character varying NOT NULL,
    linked_by_user_id uuid NOT NULL,
    linked_at timestamp with time zone DEFAULT now() NOT NULL,
    ended_at timestamp with time zone,
    ended_by_user_id uuid,
    CONSTRAINT event_activity_links_end_shape CHECK (((ended_at IS NULL) = (ended_by_user_id IS NULL))),
    CONSTRAINT event_activity_links_method_check CHECK (((link_method)::text = ANY ((ARRAY['manual'::character varying, 'automatic'::character varying])::text[])))
);

CREATE TABLE calendar.event_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    kind character varying(20) NOT NULL,
    basis character varying(20) NOT NULL,
    performed_by_user_id uuid NOT NULL,
    performed_at timestamp with time zone DEFAULT now() NOT NULL,
    reason text,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    request_id uuid NOT NULL,
    revision integer NOT NULL,
    CONSTRAINT event_changes_basis_check CHECK (((basis)::text = ANY ((ARRAY['platform_admin'::character varying, 'club_admin'::character varying, 'team_coach'::character varying, 'private_coach'::character varying])::text[]))),
    CONSTRAINT event_changes_details_check CHECK (calendar.details_ok(details)),
    CONSTRAINT event_changes_kind_check CHECK (((kind)::text = ANY ((ARRAY['create'::character varying, 'update'::character varying, 'cancel'::character varying, 'attach_sessions'::character varying, 'detach_sessions'::character varying, 'attach_activity'::character varying, 'detach_activity'::character varying, 'set_schedule'::character varying, 'clear_schedule'::character varying, 'set_fields'::character varying, 'align_sessions'::character varying])::text[]))),
    CONSTRAINT event_changes_reason_check CHECK (((reason IS NULL) OR calendar.multiline_text_ok(reason, 500))),
    CONSTRAINT event_changes_revision_check CHECK ((revision >= 1))
);

CREATE TABLE calendar.event_field_options (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    field_id uuid NOT NULL,
    label text NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    seed_key text,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT event_field_options_label_check CHECK (training_load.source_metric_text_ok(label, 40)),
    CONSTRAINT event_field_options_seed_key_check CHECK (((seed_key IS NULL) OR (seed_key ~ '^[a-z][a-z0-9_]{1,40}$'::text)))
);

CREATE TABLE calendar.event_field_values (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    field_id uuid NOT NULL,
    option_id uuid,
    number_value numeric,
    scale_value smallint,
    bool_value boolean,
    text_value text,
    updated_by_user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT event_field_values_number_check CHECK (calendar.detail_number_ok(number_value)),
    CONSTRAINT event_field_values_one_value CHECK ((num_nonnulls(option_id, number_value, scale_value, bool_value, text_value) <= 1)),
    CONSTRAINT event_field_values_scale_check CHECK (((scale_value IS NULL) OR ((scale_value >= 1) AND (scale_value <= 5)))),
    CONSTRAINT event_field_values_text_check CHECK (((text_value IS NULL) OR training_load.source_metric_text_ok(text_value, 200)))
);

CREATE TABLE calendar.event_fields (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_scope character varying(20) NOT NULL,
    owner_club_id uuid,
    key text NOT NULL,
    label text NOT NULL,
    description text,
    filled_by character varying(10) DEFAULT 'coach'::character varying NOT NULL,
    value_kind character varying(12) NOT NULL,
    unit text,
    min_value numeric,
    max_value numeric,
    required boolean DEFAULT false NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    seed_key text,
    archived_at timestamp with time zone,
    archived_by_user_id uuid,
    created_by_user_id uuid,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT event_fields_archive_shape CHECK (((archived_at IS NULL) = (archived_by_user_id IS NULL))),
    CONSTRAINT event_fields_bounds_check CHECK (((min_value IS NULL) OR (max_value IS NULL) OR (min_value <= max_value))),
    CONSTRAINT event_fields_description_check CHECK (((description IS NULL) OR training_load.source_metric_text_ok(description, 200))),
    CONSTRAINT event_fields_filled_by_check CHECK (((filled_by)::text = 'coach'::text)),
    CONSTRAINT event_fields_key_check CHECK ((key ~ '^[a-z][a-z0-9_]{1,40}$'::text)),
    CONSTRAINT event_fields_label_check CHECK (training_load.source_metric_text_ok(label, 60)),
    CONSTRAINT event_fields_max_check CHECK (calendar.detail_number_ok(max_value)),
    CONSTRAINT event_fields_min_check CHECK (calendar.detail_number_ok(min_value)),
    CONSTRAINT event_fields_number_shape CHECK ((((value_kind)::text = 'number'::text) OR ((unit IS NULL) AND (min_value IS NULL) AND (max_value IS NULL)))),
    CONSTRAINT event_fields_owner_scope_check CHECK (((owner_scope)::text = ANY ((ARRAY['system'::character varying, 'club'::character varying])::text[]))),
    CONSTRAINT event_fields_owner_shape CHECK (((((owner_scope)::text = 'system'::text) AND (owner_club_id IS NULL)) OR (((owner_scope)::text = 'club'::text) AND (owner_club_id IS NOT NULL)))),
    CONSTRAINT event_fields_revision_check CHECK ((revision >= 1)),
    CONSTRAINT event_fields_seed_key_check CHECK (((seed_key IS NULL) OR (seed_key ~ '^[a-z][a-z0-9_]{1,40}$'::text))),
    CONSTRAINT event_fields_unit_check CHECK (((unit IS NULL) OR training_load.source_metric_unit_token_ok(unit))),
    CONSTRAINT event_fields_value_kind_check CHECK (((value_kind)::text = ANY ((ARRAY['choice'::character varying, 'number'::character varying, 'scale_1_5'::character varying, 'yes_no'::character varying, 'short_text'::character varying])::text[])))
);

CREATE TABLE calendar.event_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_key uuid NOT NULL,
    request_hash text NOT NULL,
    operation character varying(20) NOT NULL,
    performed_by_user_id uuid NOT NULL,
    event_id uuid NOT NULL,
    result jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT event_requests_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT event_requests_operation_check CHECK (((operation)::text = ANY ((ARRAY['create'::character varying, 'update'::character varying, 'cancel'::character varying, 'attach_sessions'::character varying, 'detach_sessions'::character varying, 'attach_activity'::character varying, 'detach_activity'::character varying, 'set_schedule'::character varying, 'clear_schedule'::character varying, 'set_fields'::character varying, 'align_sessions'::character varying])::text[]))),
    CONSTRAINT event_requests_result_check CHECK ((jsonb_typeof(result) = 'object'::text))
);

CREATE TABLE calendar.event_selected_fields (
    event_id uuid NOT NULL,
    field_id uuid NOT NULL,
    "position" integer NOT NULL,
    CONSTRAINT event_selected_fields_position_check CHECK (("position" >= 0))
);

CREATE TABLE calendar.event_session_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    plan_id uuid,
    day date NOT NULL,
    am_pm text,
    bta text,
    session_order integer DEFAULT 0 NOT NULL,
    logical_session_id_at_link uuid,
    session_name_at_link text,
    linked_by_user_id uuid NOT NULL,
    linked_at timestamp with time zone DEFAULT now() NOT NULL,
    ended_at timestamp with time zone,
    ended_by_user_id uuid,
    CONSTRAINT event_session_links_end_shape CHECK (((ended_at IS NULL) = (ended_by_user_id IS NULL))),
    CONSTRAINT event_session_links_name_check CHECK (((session_name_at_link IS NULL) OR training_load.source_metric_text_ok(session_name_at_link, 120))),
