    event_type_id uuid NOT NULL,
    title text NOT NULL,
    day date NOT NULL,
    end_day date,
    start_time time without time zone,
    end_time time without time zone,
    timezone character varying(64) NOT NULL,
    location text,
    status character varying(10) DEFAULT 'planned'::character varying NOT NULL,
    cancelled_at timestamp with time zone,
    cancelled_by_user_id uuid,
    cancel_reason text,
    expects text[] DEFAULT '{}'::text[] NOT NULL,
    notes text,
    external_schedule_id uuid,
    test_schedule_id uuid,
    revision integer DEFAULT 1 NOT NULL,
    created_by_user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    location_id uuid,
    CONSTRAINT events_cancel_reason_check CHECK (((cancel_reason IS NULL) OR calendar.multiline_text_ok(cancel_reason, 500))),
    CONSTRAINT events_cancel_shape CHECK (((((status)::text = 'planned'::text) AND (cancelled_at IS NULL) AND (cancelled_by_user_id IS NULL) AND (cancel_reason IS NULL)) OR (((status)::text = 'cancelled'::text) AND (cancelled_at IS NOT NULL) AND (cancelled_by_user_id IS NOT NULL)))),
    CONSTRAINT events_end_day_check CHECK (((end_day IS NULL) OR (end_day >= day))),
    CONSTRAINT events_expects_check CHECK (calendar.expects_ok(expects)),
    CONSTRAINT events_location_check CHECK (((location IS NULL) OR training_load.source_metric_text_ok(location, 120))),
    CONSTRAINT events_location_one CHECK (((location_id IS NULL) OR (location IS NULL))),
    CONSTRAINT events_notes_check CHECK (((notes IS NULL) OR calendar.multiline_text_ok(notes, 2000))),
    CONSTRAINT events_owner_scope_check CHECK (((owner_scope)::text = ANY ((ARRAY['club'::character varying, 'team'::character varying, 'user'::character varying])::text[]))),
    CONSTRAINT events_owner_shape CHECK (((((owner_scope)::text = 'user'::text) AND (owner_user_id IS NOT NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'club'::text) AND (owner_club_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'team'::text) AND (owner_team_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL)))),
    CONSTRAINT events_revision_check CHECK ((revision >= 1)),
    CONSTRAINT events_span_check CHECK (((end_day IS NULL) OR (end_day <= (day + 366)))),
    CONSTRAINT events_status_check CHECK (((status)::text = ANY ((ARRAY['planned'::character varying, 'cancelled'::character varying])::text[]))),
    CONSTRAINT events_time_shape CHECK (((end_time IS NULL) OR ((start_time IS NOT NULL) AND (((end_day IS NOT NULL) AND (end_day > day)) OR (end_time > start_time))))),
    CONSTRAINT events_title_check CHECK (training_load.source_metric_text_ok(title, 120))
);

