    CONSTRAINT assets_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT assets_object_key_check CHECK (((length(object_key) >= 1) AND (length(object_key) <= 1024))),
    CONSTRAINT assets_provider_check CHECK ((provider = 'r2'::text)),
    CONSTRAINT assets_size_bytes_check CHECK ((size_bytes > 0)),
    CONSTRAINT assets_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'verifying'::text, 'ready'::text, 'failed'::text, 'deleting'::text, 'deleted'::text])))
);

