    CONSTRAINT plan_items_target_check CHECK (((((item_type)::text = 'exercise'::text) AND ((exercise_id IS NOT NULL) OR (title IS NOT NULL))) OR (((item_type)::text = 'domain'::text) AND ((domain_id IS NOT NULL) OR (domain_name IS NOT NULL) OR (title IS NOT NULL))) OR (((item_type)::text = 'category'::text) AND ((category_id IS NOT NULL) OR (category_name IS NOT NULL) OR (title IS NOT NULL))) OR (((item_type)::text = 'section'::text) AND ((section_id IS NOT NULL) OR (section_name IS NOT NULL) OR (title IS NOT NULL))) OR (((item_type)::text = ANY (ARRAY[('custom'::character varying)::text, ('note'::character varying)::text, ('recovery'::character varying)::text])) AND (title IS NOT NULL)))),
    CONSTRAINT plan_items_type_check CHECK (((item_type)::text = ANY (ARRAY[('exercise'::character varying)::text, ('domain'::character varying)::text, ('category'::character varying)::text, ('section'::character varying)::text, ('custom'::character varying)::text, ('note'::character varying)::text, ('recovery'::character varying)::text]))),
    CONSTRAINT plan_items_video_asset_selection CHECK (((video_source = 'asset'::text) = (video_asset_id IS NOT NULL))),
    CONSTRAINT plan_items_video_source_check CHECK ((video_source = ANY (ARRAY['legacy'::text, 'asset'::text, 'none'::text])))
);

CREATE VIEW media.l1_item_assets WITH (security_invoker='true') AS
 SELECT i.id,
    i.plan_session_id,
        CASE
            WHEN (i.video_source = 'asset'::text) THEN i.video_asset_id
            WHEN (i.video_source = 'legacy'::text) THEN video.asset_id
            ELSE NULL::uuid
        END AS video_asset_id,
        CASE
            WHEN (i.image_source = 'asset'::text) THEN i.image_asset_id
            WHEN (i.image_source = 'legacy'::text) THEN image.asset_id
            ELSE NULL::uuid
        END AS image_asset_id
   FROM ((plans.plan_items i
     LEFT JOIN media.drive_copies video ON (((i.video_source = 'legacy'::text) AND (video.kind = 'video'::text) AND (video.drive_file_id = media.l1_drive_file_id(i.video_url)))))
     LEFT JOIN media.drive_copies image ON (((i.image_source = 'legacy'::text) AND (image.kind = 'image'::text) AND (image.drive_file_id = media.l1_drive_file_id(i.image_url)))));

