    CONSTRAINT uploads_purpose_check CHECK ((purpose = ANY (ARRAY['exercise_video'::text, 'exercise_image'::text, 'video_frame'::text, 'automatic_thumbnail'::text, 'drive_import_video'::text, 'drive_import_image'::text]))),
