CREATE VIEW media.asset_reference_matrix WITH (security_invoker='true') AS
 SELECT e.video_asset_id AS asset_id,
    'exercise'::text AS reference_type,
    e.id AS reference_id,
    'video'::text AS slot,
    e.id AS exercise_id,
    NULL::uuid AS plan_item_id,
    NULL::uuid AS plan_id,
    NULL::uuid AS hold_id,
    true AS protects_retention
   FROM library.exercises e
  WHERE (e.video_asset_id IS NOT NULL)
UNION ALL
 SELECT e.image_asset_id AS asset_id,
    'exercise'::text AS reference_type,
    e.id AS reference_id,
    'image'::text AS slot,
    e.id AS exercise_id,
    NULL::uuid AS plan_item_id,
    NULL::uuid AS plan_id,
    NULL::uuid AS hold_id,
    true AS protects_retention
   FROM library.exercises e
  WHERE (e.image_asset_id IS NOT NULL)
UNION ALL
 SELECT p.video_asset_id AS asset_id,
    'plan_item'::text AS reference_type,
    p.id AS reference_id,
    'video'::text AS slot,
    p.exercise_id,
    p.id AS plan_item_id,
    d.plan_id,
    NULL::uuid AS hold_id,
    true AS protects_retention
   FROM ((plans.plan_items p
     JOIN plans.plan_sessions s ON ((s.id = p.plan_session_id)))
     JOIN plans.plan_days d ON ((d.id = s.plan_day_id)))
  WHERE (p.video_asset_id IS NOT NULL)
UNION ALL
 SELECT p.image_asset_id AS asset_id,
    'plan_item'::text AS reference_type,
    p.id AS reference_id,
    'image'::text AS slot,
    p.exercise_id,
    p.id AS plan_item_id,
    d.plan_id,
    NULL::uuid AS hold_id,
    true AS protects_retention
   FROM ((plans.plan_items p
     JOIN plans.plan_sessions s ON ((s.id = p.plan_session_id)))
     JOIN plans.plan_days d ON ((d.id = s.plan_day_id)))
  WHERE (p.image_asset_id IS NOT NULL)
UNION ALL
 SELECT h.asset_id,
    'retention_hold'::text AS reference_type,
    h.id AS reference_id,
    h.slot,
    NULL::uuid AS exercise_id,
    h.plan_item_id,
    r.source_plan_id AS plan_id,
    h.hold_id,
    true AS protects_retention
   FROM (media.hold_assets h
     JOIN media.retention_holds r ON ((r.id = h.hold_id)))
UNION ALL
 SELECT a.source_video_asset_id AS asset_id,
    'derived_image'::text AS reference_type,
    a.id AS reference_id,
    'source_video'::text AS slot,
    NULL::uuid AS exercise_id,
    NULL::uuid AS plan_item_id,
    NULL::uuid AS plan_id,
    NULL::uuid AS hold_id,
    true AS protects_retention
   FROM media.assets a
  WHERE (a.source_video_asset_id IS NOT NULL)
UNION ALL
 SELECT u.asset_id,
    'upload'::text AS reference_type,
    u.id AS reference_id,
    NULL::text AS slot,
    NULL::uuid AS exercise_id,
    NULL::uuid AS plan_item_id,
    NULL::uuid AS plan_id,
    NULL::uuid AS hold_id,
    (u.status = ANY (ARRAY['reserved'::text, 'verifying'::text, 'cancelling'::text])) AS protects_retention
   FROM media.uploads u
UNION ALL
 SELECT c.asset_id,
    'drive_copy'::text AS reference_type,
    c.asset_id AS reference_id,
    c.kind AS slot,
    NULL::uuid AS exercise_id,
    NULL::uuid AS plan_item_id,
    NULL::uuid AS plan_id,
    NULL::uuid AS hold_id,
    true AS protects_retention
   FROM media.drive_copies c
UNION ALL
 SELECT i.video_asset_id AS asset_id,
    'drive_plan_item'::text AS reference_type,
    i.id AS reference_id,
    'video'::text AS slot,
    p.exercise_id,
    i.id AS plan_item_id,
    d.plan_id,
    NULL::uuid AS hold_id,
    true AS protects_retention
   FROM (((media.l1_item_assets i
     JOIN plans.plan_items p ON ((p.id = i.id)))
     JOIN plans.plan_sessions s ON ((s.id = i.plan_session_id)))
     JOIN plans.plan_days d ON ((d.id = s.plan_day_id)))
  WHERE ((p.video_asset_id IS NULL) AND (i.video_asset_id IS NOT NULL))
UNION ALL
 SELECT i.image_asset_id AS asset_id,
    'drive_plan_item'::text AS reference_type,
    i.id AS reference_id,
    'image'::text AS slot,
    p.exercise_id,
    i.id AS plan_item_id,
    d.plan_id,
    NULL::uuid AS hold_id,
    true AS protects_retention
   FROM (((media.l1_item_assets i
     JOIN plans.plan_items p ON ((p.id = i.id)))
     JOIN plans.plan_sessions s ON ((s.id = i.plan_session_id)))
     JOIN plans.plan_days d ON ((d.id = s.plan_day_id)))
  WHERE ((p.image_asset_id IS NULL) AND (i.image_asset_id IS NOT NULL));

CREATE TABLE media.drive_copy_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    drive_file_id text NOT NULL,
    kind text NOT NULL,
    asset_id uuid NOT NULL,
    event text NOT NULL,
    performed_by_user_id uuid NOT NULL,
    reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT drive_copy_events_check CHECK (((event = 'created'::text) OR (reason IS NOT NULL))),
    CONSTRAINT drive_copy_events_event_check CHECK ((event = ANY (ARRAY['created'::text, 'removed'::text]))),
    CONSTRAINT drive_copy_events_kind_check CHECK ((kind = ANY (ARRAY['video'::text, 'image'::text]))),
    CONSTRAINT drive_copy_events_reason_check CHECK (((reason IS NULL) OR ((length(reason) >= 1) AND (length(reason) <= 1000))))
);

CREATE TABLE media.retention_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    asset_id uuid,
    hold_id uuid,
    event text NOT NULL,
    source_table text NOT NULL,
    source_id uuid,
    reason text NOT NULL,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    database_role text DEFAULT CURRENT_USER NOT NULL,
    transaction_id bigint DEFAULT txid_current() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE media.storage_accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_user_id uuid,
    owner_club_id uuid,
    used_bytes bigint DEFAULT 0 NOT NULL,
    reserved_bytes bigint DEFAULT 0 NOT NULL,
    override_limit_bytes bigint,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    owner_platform boolean,
    CONSTRAINT storage_accounts_one_owner CHECK ((num_nonnulls(owner_user_id, owner_club_id, owner_platform) = 1)),
    CONSTRAINT storage_accounts_override_limit_bytes_check CHECK ((override_limit_bytes >= 0)),
    CONSTRAINT storage_accounts_owner_platform_check CHECK (owner_platform),
    CONSTRAINT storage_accounts_reserved_bytes_check CHECK ((reserved_bytes >= 0)),
    CONSTRAINT storage_accounts_revision_check CHECK ((revision > 0)),
    CONSTRAINT storage_accounts_used_bytes_check CHECK ((used_bytes >= 0))
);

CREATE TABLE media.storage_limit_audit (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    storage_account_id uuid,
    performed_by_user_id uuid NOT NULL,
    old_values jsonb NOT NULL,
    new_values jsonb NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT storage_limit_audit_reason_check CHECK (((length(reason) >= 1) AND (length(reason) <= 1000)))
);

CREATE TABLE media.storage_policy (
    id boolean DEFAULT true NOT NULL,
    default_limit_bytes bigint DEFAULT 0 NOT NULL,
    max_video_bytes bigint DEFAULT 209715200 NOT NULL,
    max_image_bytes bigint DEFAULT 10485760 NOT NULL,
    max_parallel_uploads integer DEFAULT 2 NOT NULL,
    allowed_mime_types text[] DEFAULT ARRAY['video/mp4'::text, 'video/webm'::text, 'image/jpeg'::text, 'image/png'::text, 'image/webp'::text] NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT storage_policy_allowed_mime_types_check CHECK (((cardinality(allowed_mime_types) > 0) AND (allowed_mime_types <@ ARRAY['video/mp4'::text, 'video/webm'::text, 'image/jpeg'::text, 'image/png'::text, 'image/webp'::text]))),
    CONSTRAINT storage_policy_default_limit_bytes_check CHECK ((default_limit_bytes >= 0)),
    CONSTRAINT storage_policy_id_check CHECK (id),
    CONSTRAINT storage_policy_max_image_bytes_check CHECK ((max_image_bytes > 0)),
    CONSTRAINT storage_policy_max_parallel_uploads_check CHECK (((max_parallel_uploads >= 1) AND (max_parallel_uploads <= 20))),
    CONSTRAINT storage_policy_max_video_bytes_check CHECK ((max_video_bytes > 0)),
    CONSTRAINT storage_policy_revision_check CHECK ((revision > 0))
);

CREATE TABLE media.upload_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    upload_id uuid,
    performed_by_user_id uuid NOT NULL,
    event text NOT NULL,
    error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT upload_events_event_check CHECK ((event = ANY (ARRAY['requested'::text, 'issued'::text, 'renewed'::text, 'verifying'::text, 'completed'::text, 'cancelling'::text, 'cancelled'::text, 'failed'::text])))
);

CREATE TABLE plans.plan_nodes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_session_id uuid NOT NULL,
    parent_id uuid,
    node_type character varying(20) NOT NULL,
    name character varying(255) NOT NULL,
    color character varying(32),
    icon_url text,
    short_note text,
    note text,
    node_order numeric DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT plan_nodes_node_type_check CHECK (((node_type)::text = ANY ((ARRAY['domain'::character varying, 'category'::character varying, 'section'::character varying])::text[])))
);

CREATE TABLE plans.plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_type character varying(20) NOT NULL,
    created_by_user_id uuid NOT NULL,
    club_id uuid,
    team_id uuid,
    athlete_id uuid,
    name character varying(255),
    note text,
    icon_url text,
    week_start date,
    start_date date,
    duration_days integer,
    program_order numeric,
    status character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    source_type character varying(40),
    source_ref text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_external_id character varying,
    is_template boolean DEFAULT false NOT NULL,
    color character varying(32),
    visibility character varying(32) DEFAULT 'private'::character varying NOT NULL,
    edit_source_plan_id uuid,
    is_edit_draft boolean DEFAULT false NOT NULL,
    library_scope character varying(32) DEFAULT 'my'::character varying NOT NULL,
    library_category character varying(80),
    cover_image_url text,
    is_free boolean DEFAULT true NOT NULL,
    price_cents integer,
    available_until date,
    owner_type character varying(32) DEFAULT 'coach'::character varying NOT NULL,
    access_model character varying(32) DEFAULT 'free_forever'::character varying NOT NULL,
    access_duration_days integer,
    subscription_period character varying(16),
    can_copy boolean DEFAULT true NOT NULL,
    can_edit_copy boolean DEFAULT true NOT NULL,
    can_assign_to_athlete boolean DEFAULT true NOT NULL,
    athlete_can_view_directly boolean DEFAULT false NOT NULL,
    requires_approval boolean DEFAULT false NOT NULL,
    builder_batch_id uuid,
    legacy_pre_migration_draft boolean DEFAULT false NOT NULL,
    track_training_load_default boolean DEFAULT false NOT NULL,
    request_rpe_default boolean DEFAULT false NOT NULL,
    CONSTRAINT plans_access_duration_days_check CHECK (((access_duration_days IS NULL) OR (access_duration_days > 0))),
    CONSTRAINT plans_access_model_check CHECK (((access_model)::text = ANY ((ARRAY['free_forever'::character varying, 'one_time_forever'::character varying, 'time_limited'::character varying, 'subscription'::character varying, 'assigned'::character varying, 'trial'::character varying])::text[]))),
    CONSTRAINT plans_duration_positive_check CHECK (((duration_days IS NULL) OR (duration_days > 0))),
    CONSTRAINT plans_library_scope_check CHECK (((library_scope)::text = ANY ((ARRAY['workspace'::character varying, 'my'::character varying, 'team'::character varying, 'club'::character varying, 'optimove'::character varying, 'marketplace'::character varying])::text[]))),
    CONSTRAINT plans_owner_type_check CHECK (((owner_type)::text = ANY ((ARRAY['coach'::character varying, 'team'::character varying, 'club'::character varying, 'optimove'::character varying, 'marketplace'::character varying])::text[]))),
    CONSTRAINT plans_plan_type_check CHECK (((plan_type)::text = ANY (ARRAY[('weekly'::character varying)::text, ('program'::character varying)::text]))),
    CONSTRAINT plans_request_rpe_default_requires_track_training_load CHECK (((request_rpe_default = false) OR (track_training_load_default = true))),
    CONSTRAINT plans_status_check CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'active'::character varying, 'archived'::character varying])::text[]))),
    CONSTRAINT plans_subscription_period_check CHECK (((subscription_period IS NULL) OR ((subscription_period)::text = ANY ((ARRAY['month'::character varying, 'year'::character varying])::text[])))),
    CONSTRAINT plans_type_shape_check CHECK (((((plan_type)::text = 'weekly'::text) AND (athlete_id IS NOT NULL) AND (is_template = false) AND (week_start IS NOT NULL) AND (start_date IS NULL) AND (duration_days IS NULL)) OR (((plan_type)::text = 'program'::text) AND (week_start IS NULL) AND (((is_template = true) AND (athlete_id IS NULL)) OR ((is_template = false) AND (athlete_id IS NOT NULL)))))),
    CONSTRAINT plans_visibility_check CHECK (((visibility)::text = ANY ((ARRAY['private'::character varying, 'team'::character varying, 'club'::character varying, 'public'::character varying])::text[])))
);

CREATE VIEW plans.v_plan_item_node_ancestry AS
 WITH RECURSIVE node_chain AS (
         SELECT plan_nodes.id,
            plan_nodes.parent_id,
            plan_nodes.node_type,
            plan_nodes.id AS leaf_id
           FROM plans.plan_nodes
        UNION ALL
         SELECT pn.id,
            pn.parent_id,
            pn.node_type,
            nc.leaf_id
           FROM (plans.plan_nodes pn
             JOIN node_chain nc ON ((pn.id = nc.parent_id)))
        )
 SELECT leaf_id AS plan_node_id,
    (max(
        CASE
            WHEN ((node_type)::text = 'domain'::text) THEN (id)::text
            ELSE NULL::text
        END))::uuid AS domain_node_id,
    (max(
        CASE
            WHEN ((node_type)::text = 'category'::text) THEN (id)::text
            ELSE NULL::text
        END))::uuid AS category_node_id,
    (max(
        CASE
            WHEN ((node_type)::text = 'section'::text) THEN (id)::text
            ELSE NULL::text
        END))::uuid AS section_node_id
   FROM node_chain
  GROUP BY leaf_id;

CREATE VIEW plans.v_plan_node_ancestry_detail AS
 WITH RECURSIVE node_chain AS (
         SELECT plan_nodes.id,
            plan_nodes.parent_id,
            plan_nodes.node_type,
            plan_nodes.name,
            plan_nodes.color,
            plan_nodes.icon_url,
            plan_nodes.short_note,
            plan_nodes.note,
            plan_nodes.node_order,
            plan_nodes.plan_session_id,
            plan_nodes.id AS leaf_id
           FROM plans.plan_nodes
        UNION ALL
         SELECT pn.id,
            pn.parent_id,
            pn.node_type,
            pn.name,
            pn.color,
            pn.icon_url,
            pn.short_note,
            pn.note,
            pn.node_order,
            pn.plan_session_id,
            nc.leaf_id
           FROM (plans.plan_nodes pn
             JOIN node_chain nc ON ((pn.id = nc.parent_id)))
        )
 SELECT leaf_id AS plan_node_id,
    (array_agg(plan_session_id))[1] AS plan_session_id,
    (max(
        CASE
            WHEN ((node_type)::text = 'domain'::text) THEN (id)::text
            ELSE NULL::text
        END))::uuid AS domain_node_id,
    (max((
        CASE
            WHEN ((node_type)::text = 'domain'::text) THEN name
            ELSE NULL::character varying
        END)::text))::character varying(255) AS domain_name,
    (max((
        CASE
            WHEN ((node_type)::text = 'domain'::text) THEN color
            ELSE NULL::character varying
        END)::text))::character varying(40) AS domain_color,
    max(
        CASE
            WHEN ((node_type)::text = 'domain'::text) THEN icon_url
            ELSE NULL::text
        END) AS domain_icon_url,
    max(
        CASE
            WHEN ((node_type)::text = 'domain'::text) THEN short_note
            ELSE NULL::text
        END) AS domain_short_note,
    max(
        CASE
            WHEN ((node_type)::text = 'domain'::text) THEN note
            ELSE NULL::text
        END) AS domain_note,
    max(
        CASE
            WHEN ((node_type)::text = 'domain'::text) THEN node_order
            ELSE NULL::numeric
        END) AS domain_order,
    (max(
        CASE
            WHEN ((node_type)::text = 'category'::text) THEN (id)::text
            ELSE NULL::text
        END))::uuid AS category_node_id,
    (max((
        CASE
            WHEN ((node_type)::text = 'category'::text) THEN name
            ELSE NULL::character varying
        END)::text))::character varying(255) AS category_name,
    (max((
        CASE
            WHEN ((node_type)::text = 'category'::text) THEN color
            ELSE NULL::character varying
        END)::text))::character varying(40) AS category_color,
    max(
        CASE
            WHEN ((node_type)::text = 'category'::text) THEN icon_url
            ELSE NULL::text
        END) AS category_icon_url,
    max(
        CASE
            WHEN ((node_type)::text = 'category'::text) THEN short_note
            ELSE NULL::text
        END) AS category_short_note,
    max(
        CASE
            WHEN ((node_type)::text = 'category'::text) THEN note
            ELSE NULL::text
        END) AS category_note,
    max(
        CASE
            WHEN ((node_type)::text = 'category'::text) THEN node_order
            ELSE NULL::numeric
        END) AS category_order,
    (max(
        CASE
            WHEN ((node_type)::text = 'section'::text) THEN (id)::text
            ELSE NULL::text
        END))::uuid AS section_node_id,
    (max((
        CASE
            WHEN ((node_type)::text = 'section'::text) THEN name
            ELSE NULL::character varying
        END)::text))::character varying(255) AS section_name,
    (max((
        CASE
            WHEN ((node_type)::text = 'section'::text) THEN color
            ELSE NULL::character varying
        END)::text))::character varying(40) AS section_color,
    max(
        CASE
            WHEN ((node_type)::text = 'section'::text) THEN icon_url
            ELSE NULL::text
        END) AS section_icon_url,
    max(
        CASE
            WHEN ((node_type)::text = 'section'::text) THEN short_note
            ELSE NULL::text
        END) AS section_short_note,
    max(
        CASE
            WHEN ((node_type)::text = 'section'::text) THEN note
            ELSE NULL::text
        END) AS section_note,
    max(
        CASE
            WHEN ((node_type)::text = 'section'::text) THEN node_order
            ELSE NULL::numeric
        END) AS section_order
   FROM node_chain
  GROUP BY leaf_id;

CREATE VIEW plans.v_plan_node_sort_path AS
 WITH RECURSIVE node_chain AS (
         SELECT plan_nodes.id,
            ARRAY[COALESCE(plan_nodes.node_order, (0)::numeric)] AS sort_path
           FROM plans.plan_nodes
          WHERE (plan_nodes.parent_id IS NULL)
        UNION ALL
         SELECT pn.id,
            (nc.sort_path || COALESCE(pn.node_order, (0)::numeric))
           FROM (plans.plan_nodes pn
             JOIN node_chain nc ON ((pn.parent_id = nc.id)))
        )
 SELECT id AS plan_node_id,
    sort_path
   FROM node_chain;

CREATE VIEW plans.v_plan_summary AS
SELECT
    NULL::uuid AS plan_id,
    NULL::character varying(20) AS plan_type,
    NULL::boolean AS is_template,
    NULL::character varying(255) AS plan_name,
    NULL::character varying(20) AS status,
    NULL::character varying(40) AS source_type,
    NULL::character varying AS source_external_id,
    NULL::date AS week_start,
    NULL::date AS week_end,
    NULL::date AS start_date,
    NULL::date AS valid_until,
    NULL::integer AS duration_days,
    NULL::numeric AS program_order,
    NULL::uuid AS athlete_uuid,
    NULL::character varying(100) AS athlete_id,
    NULL::character varying AS athlete_source_external_id,
    NULL::character varying(220) AS athlete_name,
    NULL::text AS athlete_image_url,
    NULL::bigint AS block_or_day_count,
    NULL::bigint AS session_count,
    NULL::bigint AS item_count,
    NULL::bigint AS matched_exercise_count,
    NULL::bigint AS item_without_exercise_id_count,
    NULL::character varying(32) AS library_scope,
    NULL::character varying(80) AS library_category,
    NULL::text AS cover_image_url,
    NULL::boolean AS is_free,
    NULL::integer AS price_cents,
    NULL::date AS available_until,
    NULL::character varying(32) AS owner_type,
    NULL::character varying(32) AS visibility,
    NULL::character varying(32) AS access_model,
    NULL::integer AS access_duration_days,
    NULL::character varying(16) AS subscription_period,
    NULL::boolean AS can_copy,
    NULL::boolean AS can_edit_copy,
    NULL::boolean AS can_assign_to_athlete,
    NULL::boolean AS athlete_can_view_directly,
    NULL::boolean AS requires_approval;

CREATE TABLE public.athletes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    athlete_id character varying(100) NOT NULL,
    user_id uuid,
    first_name character varying(100) NOT NULL,
    last_name character varying(100) NOT NULL,
    full_name character varying(220) NOT NULL,
    display_name character varying(220),
    gender character varying(30),
    birth_date date,
    country character varying(100),
    city character varying(100),
    address_line character varying(255),
    phone character varying(50),
    email character varying(255),
    image_url text,
    club_id uuid,
    team_id uuid,
    is_active boolean DEFAULT true NOT NULL,
    created_by_user_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_external_id character varying,
    device_timezone character varying(64),
    device_timezone_updated_at timestamp with time zone
);

CREATE VIEW plans.v_program_plan_items AS
 SELECT p.id AS plan_id,
    p.name AS plan_name,
    p.plan_type,
    p.is_template,
    p.program_order,
    p.start_date,
    p.duration_days,
    (
        CASE
            WHEN ((p.start_date IS NOT NULL) AND (p.duration_days IS NOT NULL)) THEN (p.start_date + (((p.duration_days - 1))::double precision * '1 day'::interval))
            ELSE NULL::timestamp without time zone
        END)::date AS valid_until,
    p.source_type,
    p.source_external_id,
    a.id AS athlete_uuid,
    a.athlete_id,
    a.source_external_id AS athlete_source_external_id,
    a.full_name AS athlete_name,
    a.image_url AS athlete_image_url,
    pd.id AS plan_block_id,
    pd.block_index,
    pd.block_name,
    pd.block_type,
    pd.block_order,
    pd.day_note,
    ps.id AS plan_session_id,
    ps.am_pm,
    ps.bta,
    ps.session_order,
    pi.id AS plan_item_id,
    pi.item_type,
    pi.item_order,
    pi.domain_order,
    pi.category_order,
    pi.section_order,
    pi.exercise_order,
    pi.domain_name,
    pi.domain_color,
    pi.domain_icon_url,
    pi.domain_short_note,
    pi.domain_note,
    pi.category_name,
    pi.category_color,
    pi.category_icon_url,
    pi.category_short_note,
    pi.category_note,
    pi.section_name,
    pi.section_color,
    pi.section_icon_url,
    pi.section_short_note,
    pi.section_note,
    pi.title,
    pi.description,
    pi.image_url,
    pi.video_url,
    pi.sets,
    pi.reps,
    pi.load,
    e.id AS exercise_id,
    e.exercise_code,
    e.name AS library_exercise_name,
    pi.source_row_ref,
    ps.session_time,
    pi.plan_node_id,
    na.domain_node_id,
    na.category_node_id,
    na.section_node_id
   FROM ((((((plans.plans p
     LEFT JOIN public.athletes a ON ((a.id = p.athlete_id)))
     JOIN plans.plan_days pd ON ((pd.plan_id = p.id)))
     JOIN plans.plan_sessions ps ON ((ps.plan_day_id = pd.id)))
     JOIN plans.plan_items pi ON ((pi.plan_session_id = ps.id)))
     LEFT JOIN library.exercises e ON ((e.id = pi.exercise_id)))
     LEFT JOIN plans.v_plan_item_node_ancestry na ON ((na.plan_node_id = pi.plan_node_id)))
  WHERE (((p.plan_type)::text = 'program'::text) AND COALESCE(p.is_active, true) AND (NOT COALESCE(p.is_edit_draft, false)))
  ORDER BY p.is_template, COALESCE(a.source_external_id, p.source_external_id), p.program_order, p.name, pd.block_index, ps.session_order, pi.item_order;

CREATE VIEW plans.v_weekly_plan_items AS
 SELECT p.id AS plan_id,
    p.name AS plan_name,
    p.week_start,
    ((p.week_start + '6 days'::interval))::date AS week_end,
    a.id AS athlete_uuid,
    a.athlete_id,
    a.source_external_id AS athlete_source_external_id,
    a.full_name AS athlete_name,
    a.image_url AS athlete_image_url,
    pd.id AS plan_day_id,
    pd.date,
    pd.day_note,
    pd.day_order,
    ps.id AS plan_session_id,
    ps.am_pm,
    ps.bta,
    ps.session_order,
    pi.id AS plan_item_id,
    pi.item_type,
    pi.item_order,
    pi.domain_order,
    pi.category_order,
    pi.section_order,
    pi.exercise_order,
    pi.domain_name,
    pi.domain_color,
    pi.domain_icon_url,
    pi.domain_short_note,
    pi.domain_note,
    pi.category_name,
    pi.category_color,
    pi.category_icon_url,
    pi.category_short_note,
    pi.category_note,
    pi.section_name,
    pi.section_color,
    pi.section_icon_url,
    pi.section_short_note,
    pi.section_note,
    pi.title,
    pi.description,
    pi.image_url,
    pi.video_url,
    pi.sets,
    pi.reps,
    pi.load,
    e.id AS exercise_id,
    e.exercise_code,
    e.name AS library_exercise_name,
    pi.source_row_ref,
    ps.session_time,
    pi.plan_node_id,
    na.domain_node_id,
    na.category_node_id,
    na.section_node_id,
    nsp.sort_path AS hierarchy_sort_path,
    ps.name AS session_name
   FROM (((((((plans.plans p
     JOIN public.athletes a ON ((a.id = p.athlete_id)))
     JOIN plans.plan_days pd ON ((pd.plan_id = p.id)))
     JOIN plans.plan_sessions ps ON ((ps.plan_day_id = pd.id)))
     JOIN plans.plan_items pi ON ((pi.plan_session_id = ps.id)))
     LEFT JOIN library.exercises e ON ((e.id = pi.exercise_id)))
     LEFT JOIN plans.v_plan_item_node_ancestry na ON ((na.plan_node_id = pi.plan_node_id)))
     LEFT JOIN plans.v_plan_node_sort_path nsp ON ((nsp.plan_node_id = pi.plan_node_id)))
  WHERE (((p.plan_type)::text = 'weekly'::text) AND ((p.status)::text = 'active'::text) AND COALESCE(p.is_active, true) AND (NOT COALESCE(p.is_edit_draft, false)))
UNION ALL
 SELECT p.id AS plan_id,
    p.name AS plan_name,
    p.week_start,
    ((p.week_start + '6 days'::interval))::date AS week_end,
    a.id AS athlete_uuid,
    a.athlete_id,
    a.source_external_id AS athlete_source_external_id,
    a.full_name AS athlete_name,
    a.image_url AS athlete_image_url,
    pd.id AS plan_day_id,
    pd.date,
    pd.day_note,
    pd.day_order,
    ps.id AS plan_session_id,
    ps.am_pm,
    ps.bta,
    ps.session_order,
    NULL::uuid AS plan_item_id,
    (pn.node_type)::character varying(30) AS item_type,
    NULL::numeric AS item_order,
    nad.domain_order,
    nad.category_order,
    nad.section_order,
    NULL::numeric AS exercise_order,
    nad.domain_name,
    nad.domain_color,
    nad.domain_icon_url,
    nad.domain_short_note,
    nad.domain_note,
    nad.category_name,
    nad.category_color,
    nad.category_icon_url,
    nad.category_short_note,
    nad.category_note,
    nad.section_name,
    nad.section_color,
    nad.section_icon_url,
    nad.section_short_note,
    nad.section_note,
    NULL::character varying(255) AS title,
    NULL::text AS description,
    NULL::text AS image_url,
    NULL::text AS video_url,
    NULL::character varying(80) AS sets,
    NULL::character varying(80) AS reps,
    NULL::character varying(80) AS load,
    NULL::uuid AS exercise_id,
    NULL::character varying(100) AS exercise_code,
    NULL::character varying(255) AS library_exercise_name,
    NULL::text AS source_row_ref,
    ps.session_time,
    pn.id AS plan_node_id,
    nad.domain_node_id,
    nad.category_node_id,
    nad.section_node_id,
    nsp.sort_path AS hierarchy_sort_path,
    ps.name AS session_name
   FROM ((((((plans.plan_nodes pn
     JOIN plans.v_plan_node_ancestry_detail nad ON ((nad.plan_node_id = pn.id)))
     JOIN plans.plan_sessions ps ON ((ps.id = pn.plan_session_id)))
     JOIN plans.plan_days pd ON ((pd.id = ps.plan_day_id)))
     JOIN plans.plans p ON ((p.id = pd.plan_id)))
     JOIN public.athletes a ON ((a.id = p.athlete_id)))
     LEFT JOIN plans.v_plan_node_sort_path nsp ON ((nsp.plan_node_id = pn.id)))
  WHERE (((p.plan_type)::text = 'weekly'::text) AND ((p.status)::text = 'active'::text) AND COALESCE(p.is_active, true) AND (NOT COALESCE(p.is_edit_draft, false)) AND (NOT (EXISTS ( SELECT 1
           FROM plans.plan_items pi2
          WHERE (pi2.plan_node_id = pn.id)))) AND (NOT (EXISTS ( SELECT 1
           FROM plans.plan_nodes child
          WHERE (child.parent_id = pn.id)))))
  ORDER BY 7, 3, 11, 13, 17, 56, 20, 18, 52;

