    CONSTRAINT athlete_invites_context_type_check CHECK (((context_type)::text = ANY ((ARRAY['platform'::character varying, 'private_coach'::character varying, 'club'::character varying, 'team'::character varying, 'legacy'::character varying])::text[]))),
