CREATE TABLE tests.test_battery_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    test_battery_id uuid NOT NULL,
    version_number integer NOT NULL,
    status character varying(10) NOT NULL,
    previous_version_id uuid,
    previous_version_test_battery_id uuid,
    forked_from_version_id uuid,
    forked_from_battery_id uuid,
    name character varying(200) NOT NULL,
    description text,
    overall_instructions text,
    published_at timestamp with time zone,
    archived_at timestamp with time zone,
    archived_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT test_battery_versions_check CHECK (((previous_version_id IS NULL) = (previous_version_test_battery_id IS NULL))),
    CONSTRAINT test_battery_versions_check1 CHECK (((version_number = 1) = (previous_version_id IS NULL))),
    CONSTRAINT test_battery_versions_check2 CHECK ((((version_number > 1) AND (forked_from_version_id IS NULL) AND (forked_from_battery_id IS NULL)) OR ((version_number = 1) AND (forked_from_battery_id IS NULL) AND (forked_from_version_id IS NULL)) OR ((version_number = 1) AND (forked_from_battery_id IS NOT NULL) AND (forked_from_version_id IS NOT NULL)))),
    CONSTRAINT test_battery_versions_check3 CHECK (((((status)::text = 'draft'::text) AND (published_at IS NULL) AND (archived_at IS NULL) AND (archived_by IS NULL)) OR (((status)::text = 'active'::text) AND (published_at IS NOT NULL) AND (archived_at IS NULL) AND (archived_by IS NULL)) OR (((status)::text = 'archived'::text) AND (published_at IS NOT NULL) AND (archived_at IS NOT NULL)))),
    CONSTRAINT test_battery_versions_status_check CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'active'::character varying, 'archived'::character varying])::text[]))),
    CONSTRAINT test_battery_versions_version_number_check CHECK ((version_number > 0))
);

CREATE TABLE tests.test_category (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_scope character varying(20) NOT NULL,
    owner_user_id uuid,
    owner_club_id uuid,
    owner_team_id uuid,
    created_by_user_id uuid,
    name character varying(200) NOT NULL,
    description text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT test_category_check CHECK (((((owner_scope)::text = 'system'::text) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'user'::text) AND (owner_user_id IS NOT NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'club'::text) AND (owner_club_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'team'::text) AND (owner_team_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL)))),
    CONSTRAINT test_category_owner_scope_check CHECK (((owner_scope)::text = ANY ((ARRAY['system'::character varying, 'club'::character varying, 'team'::character varying, 'user'::character varying])::text[])))
);

CREATE TABLE tests.test_criteria_conditions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    output_id uuid NOT NULL,
    set_version_id uuid NOT NULL,
    battery_version_id uuid,
    condition_group integer DEFAULT 1 NOT NULL,
    parameter_source_kind character varying(40) NOT NULL,
    source_battery_item_parameter_selection_id uuid,
    source_battery_derived_parameter_id uuid,
    source_declaration_id uuid,
    operator character varying(10) NOT NULL,
    reference_type character varying(20) NOT NULL,
    static_value jsonb,
    static_value_upper jsonb,
    reference_value_id uuid,
    baseline_window_days integer,
    threshold_percent numeric,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT test_criteria_conditions_baseline_window_days_check CHECK (((baseline_window_days IS NULL) OR (baseline_window_days > 0))),
    CONSTRAINT test_criteria_conditions_check CHECK (((((parameter_source_kind)::text = 'battery_item_parameter_selection'::text) AND (battery_version_id IS NOT NULL) AND (source_battery_item_parameter_selection_id IS NOT NULL) AND (source_battery_derived_parameter_id IS NULL) AND (source_declaration_id IS NULL)) OR (((parameter_source_kind)::text = 'battery_derived'::text) AND (battery_version_id IS NOT NULL) AND (source_battery_derived_parameter_id IS NOT NULL) AND (source_battery_item_parameter_selection_id IS NULL) AND (source_declaration_id IS NULL)) OR (((parameter_source_kind)::text = 'declared_source'::text) AND (battery_version_id IS NULL) AND (source_declaration_id IS NOT NULL) AND (source_battery_item_parameter_selection_id IS NULL) AND (source_battery_derived_parameter_id IS NULL)))),
    CONSTRAINT test_criteria_conditions_check1 CHECK (((((reference_type)::text = 'static'::text) AND (static_value IS NOT NULL) AND (reference_value_id IS NULL) AND (baseline_window_days IS NULL) AND (threshold_percent IS NULL) AND (((operator)::text <> 'between'::text) OR (static_value_upper IS NOT NULL)) AND (((operator)::text = 'between'::text) OR (static_value_upper IS NULL))) OR (((reference_type)::text = 'predefined_reference'::text) AND (reference_value_id IS NOT NULL) AND (static_value IS NULL) AND (static_value_upper IS NULL) AND (baseline_window_days IS NULL) AND (threshold_percent IS NULL)) OR (((reference_type)::text = ANY ((ARRAY['individual_history'::character varying, 'group_reference'::character varying])::text[])) AND (baseline_window_days IS NOT NULL) AND (threshold_percent IS NOT NULL) AND (static_value IS NULL) AND (static_value_upper IS NULL) AND (reference_value_id IS NULL)) OR (((reference_type)::text = 'session_reference'::text) AND (static_value IS NULL) AND (static_value_upper IS NULL) AND (reference_value_id IS NULL) AND (baseline_window_days IS NULL) AND (threshold_percent IS NULL)))),
    CONSTRAINT test_criteria_conditions_check2 CHECK ((((operator)::text <> 'between'::text) OR ((reference_type)::text = 'static'::text))),
    CONSTRAINT test_criteria_conditions_condition_group_check CHECK ((condition_group > 0)),
    CONSTRAINT test_criteria_conditions_operator_check CHECK (((operator)::text = ANY ((ARRAY['lt'::character varying, 'lte'::character varying, 'gt'::character varying, 'gte'::character varying, 'eq'::character varying, 'neq'::character varying, 'between'::character varying])::text[]))),
    CONSTRAINT test_criteria_conditions_parameter_source_kind_check CHECK (((parameter_source_kind)::text = ANY ((ARRAY['battery_item_parameter_selection'::character varying, 'battery_derived'::character varying, 'declared_source'::character varying])::text[]))),
    CONSTRAINT test_criteria_conditions_reference_type_check CHECK (((reference_type)::text = ANY ((ARRAY['static'::character varying, 'predefined_reference'::character varying, 'individual_history'::character varying, 'group_reference'::character varying, 'session_reference'::character varying])::text[])))
);

CREATE TABLE tests.test_criteria_outputs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    set_version_id uuid NOT NULL,
    rule_id uuid NOT NULL,
    evaluation_order integer NOT NULL,
    label text NOT NULL,
    label_short character varying(50),
    color_code character varying(20),
    severity_level smallint DEFAULT 0 NOT NULL,
    alert_required boolean DEFAULT false NOT NULL,
    recommendation_text text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT test_criteria_outputs_evaluation_order_check CHECK ((evaluation_order > 0)),
    CONSTRAINT test_criteria_outputs_severity_level_check CHECK (((severity_level >= 0) AND (severity_level <= 5)))
);

