    CONSTRAINT test_criteria_set_version_sources_check CHECK (((((source_kind)::text = 'native'::text) AND (test_parameter_id IS NOT NULL) AND (test_derived_parameter_id IS NULL)) OR (((source_kind)::text = 'test_derived'::text) AND (test_derived_parameter_id IS NOT NULL) AND (test_parameter_id IS NULL)))),
    CONSTRAINT test_criteria_set_version_sources_source_kind_check CHECK (((source_kind)::text = ANY ((ARRAY['native'::character varying, 'test_derived'::character varying])::text[])))
