    name character varying(200) NOT NULL,
    description text,
    battery_version_id uuid,
    minimum_age_years numeric,
    maximum_age_years numeric,
    gender character varying(20),
    sport_id uuid,
    sport_position_id uuid,
    athlete_id uuid,
    published_at timestamp with time zone,
    archived_at timestamp with time zone,
    archived_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT test_criteria_set_versions_check CHECK (((previous_version_id IS NULL) = (previous_version_criteria_set_id IS NULL))),
    CONSTRAINT test_criteria_set_versions_check1 CHECK (((version_number = 1) = (previous_version_id IS NULL))),
    CONSTRAINT test_criteria_set_versions_check2 CHECK ((((version_number > 1) AND (forked_from_version_id IS NULL) AND (forked_from_criteria_set_id IS NULL)) OR ((version_number = 1) AND (forked_from_criteria_set_id IS NULL) AND (forked_from_version_id IS NULL)) OR ((version_number = 1) AND (forked_from_criteria_set_id IS NOT NULL) AND (forked_from_version_id IS NOT NULL)))),
    CONSTRAINT test_criteria_set_versions_check3 CHECK (((((status)::text = 'draft'::text) AND (published_at IS NULL) AND (archived_at IS NULL) AND (archived_by IS NULL)) OR (((status)::text = 'active'::text) AND (published_at IS NOT NULL) AND (archived_at IS NULL) AND (archived_by IS NULL)) OR (((status)::text = 'archived'::text) AND (published_at IS NOT NULL) AND (archived_at IS NOT NULL)))),
    CONSTRAINT test_criteria_set_versions_check4 CHECK (((minimum_age_years IS NULL) OR (maximum_age_years IS NULL) OR (minimum_age_years <= maximum_age_years))),
    CONSTRAINT test_criteria_set_versions_check5 CHECK (((sport_position_id IS NULL) OR (sport_id IS NOT NULL))),
    CONSTRAINT test_criteria_set_versions_gender_check CHECK (((gender IS NULL) OR ((gender)::text = ANY ((ARRAY['male'::character varying, 'female'::character varying, 'any'::character varying])::text[])))),
    CONSTRAINT test_criteria_set_versions_maximum_age_years_check CHECK (((maximum_age_years IS NULL) OR (maximum_age_years >= (0)::numeric))),
    CONSTRAINT test_criteria_set_versions_minimum_age_years_check CHECK (((minimum_age_years IS NULL) OR (minimum_age_years >= (0)::numeric))),
    CONSTRAINT test_criteria_set_versions_status_check CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'active'::character varying, 'archived'::character varying])::text[]))),
    CONSTRAINT test_criteria_set_versions_version_number_check CHECK ((version_number > 0))
);

