    CONSTRAINT test_parameter_reference_values_check1 CHECK (((sport_position_id IS NULL) OR (sport_id IS NOT NULL))),
    CONSTRAINT test_parameter_reference_values_gender_check CHECK (((gender)::text = ANY ((ARRAY['male'::character varying, 'female'::character varying, 'any'::character varying])::text[]))),
    CONSTRAINT test_parameter_reference_values_max_age_years_check CHECK (((max_age_years IS NULL) OR (max_age_years >= (0)::numeric))),
