    CONSTRAINT test_parameter_reference_values_reference_type_check CHECK (((reference_type)::text = ANY ((ARRAY['cv'::character varying, 'sem'::character varying, 'swc'::character varying, 'mdc'::character varying])::text[]))),
    CONSTRAINT test_parameter_reference_values_source_type_check CHECK (((source_type)::text = ANY ((ARRAY['literature'::character varying, 'club_measured'::character varying, 'vendor_provided'::character varying, 'expert_estimate'::character varying])::text[]))),
    CONSTRAINT test_parameter_reference_values_value_check CHECK ((value >= (0)::numeric))
);

CREATE TABLE tests.test_parameters (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
