    value_type character varying(20) DEFAULT 'numeric'::character varying NOT NULL,
    minimum_value numeric,
    maximum_value numeric,
    decimal_places integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT test_parameters_check CHECK (((minimum_value IS NULL) OR (maximum_value IS NULL) OR (minimum_value <= maximum_value))),
    CONSTRAINT test_parameters_check1 CHECK ((((value_type)::text <> ALL ((ARRAY['boolean'::character varying, 'text'::character varying])::text[])) OR ((minimum_value IS NULL) AND (maximum_value IS NULL)))),
    CONSTRAINT test_parameters_check2 CHECK ((((value_type)::text = 'numeric'::text) OR (((value_type)::text = ANY ((ARRAY['integer'::character varying, 'ordinal'::character varying])::text[])) AND ((decimal_places IS NULL) OR (decimal_places = 0))) OR (((value_type)::text = ANY ((ARRAY['boolean'::character varying, 'text'::character varying])::text[])) AND (decimal_places IS NULL)))),
    CONSTRAINT test_parameters_decimal_places_check CHECK (((decimal_places IS NULL) OR (decimal_places >= 0))),
    CONSTRAINT test_parameters_value_type_check CHECK (((value_type)::text = ANY ((ARRAY['numeric'::character varying, 'integer'::character varying, 'boolean'::character varying, 'ordinal'::character varying, 'text'::character varying])::text[])))
);

CREATE TABLE tests.test_schedule_notification_dispatches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    occurrence_id uuid NOT NULL,
    assignment_id uuid,
    notification_kind character varying(20) NOT NULL,
    recipient_user_id uuid NOT NULL,
    dedupe_key character varying(300) NOT NULL,
    status character varying(10) DEFAULT 'pending'::character varying NOT NULL,
    completed_count integer,
    total_count integer,
    last_computed_at timestamp with time zone,
    sent_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    app_notification_id uuid,
    CONSTRAINT test_schedule_notification_dispatches_check CHECK ((((notification_kind)::text <> ALL ((ARRAY['athlete_invitation'::character varying, 'athlete_reminder'::character varying])::text[])) OR (assignment_id IS NOT NULL))),
    CONSTRAINT test_schedule_notification_dispatches_check1 CHECK ((((notification_kind)::text <> ALL ((ARRAY['coach_digest'::character varying, 'final_digest'::character varying])::text[])) OR (assignment_id IS NULL))),
    CONSTRAINT test_schedule_notification_dispatches_check2 CHECK ((((status)::text <> 'sent'::text) OR (sent_at IS NOT NULL))),
    CONSTRAINT test_schedule_notification_dispatches_check3 CHECK (((completed_count IS NULL) OR (total_count IS NULL) OR (completed_count <= total_count))),
    CONSTRAINT test_schedule_notification_dispatches_completed_count_check CHECK (((completed_count IS NULL) OR (completed_count >= 0))),
    CONSTRAINT test_schedule_notification_dispatches_notification_kind_check CHECK (((notification_kind)::text = ANY ((ARRAY['athlete_invitation'::character varying, 'athlete_reminder'::character varying, 'coach_digest'::character varying, 'final_digest'::character varying])::text[]))),
    CONSTRAINT test_schedule_notification_dispatches_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'sent'::character varying, 'skipped'::character varying])::text[]))),
    CONSTRAINT test_schedule_notification_dispatches_total_count_check CHECK (((total_count IS NULL) OR (total_count >= 0)))
);

CREATE TABLE tests.test_schedule_notification_rules (
