    CONSTRAINT test_schedule_notification_rules_check1 CHECK ((((notification_kind)::text <> ALL ((ARRAY['coach_digest'::character varying, 'final_digest'::character varying])::text[])) OR (digest_trigger IS NOT NULL))),
    CONSTRAINT test_schedule_notification_rules_check2 CHECK ((((notification_kind)::text <> ALL ((ARRAY['athlete_invitation'::character varying, 'athlete_reminder'::character varying])::text[])) OR (digest_trigger IS NULL))),
    CONSTRAINT test_schedule_notification_rules_check3 CHECK ((((notification_kind)::text <> ALL ((ARRAY['coach_digest'::character varying, 'final_digest'::character varying])::text[])) OR (reminder_offset_minutes IS NULL))),
    CONSTRAINT test_schedule_notification_rules_digest_trigger_check CHECK (((digest_trigger IS NULL) OR ((digest_trigger)::text = ANY ((ARRAY['on_open'::character varying, 'on_close'::character varying, 'periodic'::character varying])::text[])))),
    CONSTRAINT test_schedule_notification_rules_notification_kind_check CHECK (((notification_kind)::text = ANY ((ARRAY['athlete_invitation'::character varying, 'athlete_reminder'::character varying, 'coach_digest'::character varying, 'final_digest'::character varying])::text[]))),
    CONSTRAINT test_schedule_notification_rules_reminder_offset_minutes_check CHECK (((reminder_offset_minutes IS NULL) OR (reminder_offset_minutes > 0)))
);

CREATE TABLE tests.test_schedule_occurrences (
