    CONSTRAINT test_schedule_occurrences_check CHECK ((num_nonnulls(snapshot_test_version_id, snapshot_test_battery_version_id) = 1)),
    CONSTRAINT test_schedule_occurrences_check1 CHECK ((opens_at <= closes_at)),
    CONSTRAINT test_schedule_occurrences_check2 CHECK (((due_at IS NULL) OR ((due_at >= opens_at) AND (due_at <= closes_at)))),
    CONSTRAINT test_schedule_occurrences_status_check CHECK (((status)::text = ANY ((ARRAY['scheduled'::character varying, 'open'::character varying, 'closed'::character varying, 'cancelled'::character varying])::text[])))
);

