    CONSTRAINT test_schedule_targets_target_kind_check CHECK (((target_kind)::text = ANY ((ARRAY['athlete'::character varying, 'team'::character varying, 'club'::character varying])::text[])))
);

CREATE TABLE tests.test_schedules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    test_version_id uuid,
    test_battery_version_id uuid,
    schedule_kind character varying(10) NOT NULL,
    timezone character varying(64) NOT NULL,
    start_date date NOT NULL,
    end_date date,
    recurrence_rule jsonb,
    recurrence_rule_version integer DEFAULT 1 NOT NULL,
    opens_time time without time zone NOT NULL,
    due_time time without time zone,
    closes_time time without time zone NOT NULL,
    status character varying(10) NOT NULL,
    created_by_user_id uuid NOT NULL,
    owner_scope character varying(20) NOT NULL,
    owner_user_id uuid,
    owner_club_id uuid,
    owner_team_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
