    CONSTRAINT gpexe_athlete_identities_source_team_format CHECK ((source_team_id ~ '^(0|[1-9][0-9]{0,11})$'::text)),
    CONSTRAINT gpexe_athlete_identities_ttl CHECK ((expires_at = (observed_at + '336:00:00'::interval)))
);

