    owner_club_id uuid,
    owner_team_id uuid,
    is_active boolean DEFAULT true NOT NULL,
    created_by_user_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    key text,
    description text,
    icon_url text,
    CONSTRAINT metric_categories_canonical_key CHECK ((((owner_scope)::text <> ALL (ARRAY['system'::text, 'club'::text])) OR (key IS NOT NULL))),
    CONSTRAINT metric_categories_check CHECK (((((owner_scope)::text = 'system'::text) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'user'::text) AND (owner_user_id IS NOT NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'club'::text) AND (owner_club_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'team'::text) AND (owner_team_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL)))),
    CONSTRAINT metric_categories_icon_rule CHECK (((icon_url IS NULL) OR ((icon_url ~ '^icon:[a-z0-9]+(-[a-z0-9]+)*$'::text) AND (char_length(icon_url) <= 69)))),
    CONSTRAINT metric_categories_key_rule CHECK (((key IS NULL) OR (key ~ '^[a-z][a-z0-9_]{0,62}$'::text))),
    CONSTRAINT metric_categories_owner_scope_check CHECK (((owner_scope)::text = ANY ((ARRAY['system'::character varying, 'club'::character varying, 'team'::character varying, 'user'::character varying])::text[])))
);

CREATE TABLE training_load.metric_classification_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seq bigint NOT NULL,
    object_kind text NOT NULL,
    kind text NOT NULL,
    domain_id uuid,
    category_id uuid,
    metric_definition_id uuid,
    link_id uuid,
    owner_scope text NOT NULL,
    owner_club_id uuid,
    old_name text,
    new_name text,
    old_description text,
    new_description text,
    old_active boolean,
    new_active boolean,
    changed_by_user_id uuid NOT NULL,
    xact_id xid8 NOT NULL,
    changed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    old_icon_url text,
    new_icon_url text,
    CONSTRAINT metric_classification_changes_kind_check CHECK ((kind = ANY (ARRAY['create'::text, 'rename'::text, 'archive'::text, 'restore'::text, 'link'::text, 'remove'::text, 'icon'::text]))),
    CONSTRAINT metric_classification_changes_kind_shape CHECK (((object_kind = 'link'::text) OR ((kind = 'create'::text) AND (old_name IS NULL) AND (new_name IS NOT NULL) AND (old_active IS NULL) AND (new_active = true) AND (old_icon_url IS NULL) AND ((new_icon_url IS NULL) OR ((new_icon_url ~ '^icon:[a-z0-9]+(-[a-z0-9]+)*$'::text) AND (char_length(new_icon_url) <= 69)))) OR ((kind = 'rename'::text) AND (old_name IS NOT NULL) AND (new_name IS NOT NULL) AND (old_active = true) AND (new_active = true) AND (NOT (old_icon_url IS DISTINCT FROM new_icon_url))) OR ((kind = 'archive'::text) AND (old_active = true) AND (new_active = false) AND (NOT (old_name IS DISTINCT FROM new_name)) AND (NOT (old_description IS DISTINCT FROM new_description)) AND (NOT (old_icon_url IS DISTINCT FROM new_icon_url))) OR ((kind = 'restore'::text) AND (old_active = false) AND (new_active = true) AND (NOT (old_name IS DISTINCT FROM new_name)) AND (NOT (old_description IS DISTINCT FROM new_description)) AND (NOT (old_icon_url IS DISTINCT FROM new_icon_url))) OR ((kind = 'icon'::text) AND (old_name IS NOT NULL) AND (old_active = true) AND (new_active = true) AND (NOT (old_name IS DISTINCT FROM new_name)) AND (NOT (old_description IS DISTINCT FROM new_description)) AND (old_icon_url IS DISTINCT FROM new_icon_url) AND ((new_icon_url IS NULL) OR ((new_icon_url ~ '^icon:[a-z0-9]+(-[a-z0-9]+)*$'::text) AND (char_length(new_icon_url) <= 69)))))),
    CONSTRAINT metric_classification_changes_object_check CHECK ((object_kind = ANY (ARRAY['domain'::text, 'category'::text, 'link'::text]))),
    CONSTRAINT metric_classification_changes_owner_scope_check CHECK ((owner_scope = ANY (ARRAY['system'::text, 'club'::text]))),
    CONSTRAINT metric_classification_changes_owner_shape CHECK (((owner_scope = 'system'::text) = (owner_club_id IS NULL))),
    CONSTRAINT metric_classification_changes_shape CHECK ((((object_kind = 'domain'::text) AND (domain_id IS NOT NULL) AND (category_id IS NULL) AND (metric_definition_id IS NULL) AND (link_id IS NULL) AND (kind = ANY (ARRAY['create'::text, 'rename'::text, 'archive'::text, 'restore'::text, 'icon'::text]))) OR ((object_kind = 'category'::text) AND (category_id IS NOT NULL) AND (domain_id IS NULL) AND (metric_definition_id IS NULL) AND (link_id IS NULL) AND (kind = ANY (ARRAY['create'::text, 'rename'::text, 'archive'::text, 'restore'::text, 'icon'::text]))) OR ((object_kind = 'link'::text) AND (link_id IS NOT NULL) AND (kind = ANY (ARRAY['link'::text, 'remove'::text])) AND (num_nonnulls(domain_id, category_id, metric_definition_id) = 2) AND (old_name IS NULL) AND (new_name IS NULL) AND (old_description IS NULL) AND (new_description IS NULL) AND (old_active IS NULL) AND (new_active IS NULL) AND (old_icon_url IS NULL) AND (new_icon_url IS NULL))))
);

ALTER TABLE training_load.metric_classification_changes ALTER COLUMN seq ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME training_load.metric_classification_changes_seq_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

