CREATE TABLE training_load.metric_variable_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seq bigint NOT NULL,
    metric_definition_id uuid NOT NULL,
    owner_scope text NOT NULL,
    owner_club_id uuid,
    kind text NOT NULL,
    old_label text NOT NULL,
    new_label text NOT NULL,
    old_short_label text,
    new_short_label text,
    old_description text,
    new_description text,
    old_state text NOT NULL,
    new_state text NOT NULL,
    changed_by_user_id uuid NOT NULL,
    xact_id xid8 NOT NULL,
    changed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    old_icon_url text,
    new_icon_url text,
    CONSTRAINT metric_variable_changes_kind_check CHECK ((kind = ANY (ARRAY['rename'::text, 'archive'::text, 'restore'::text, 'icon'::text]))),
    CONSTRAINT metric_variable_changes_kind_shape CHECK ((((kind = 'rename'::text) AND (old_state = 'active'::text) AND (new_state = 'active'::text) AND (NOT (old_icon_url IS DISTINCT FROM new_icon_url))) OR ((kind = 'archive'::text) AND (old_state = 'active'::text) AND (new_state = 'archived'::text) AND (NOT (old_icon_url IS DISTINCT FROM new_icon_url))) OR ((kind = 'restore'::text) AND (old_state = 'archived'::text) AND (new_state = 'active'::text) AND (NOT (old_icon_url IS DISTINCT FROM new_icon_url))) OR ((kind = 'icon'::text) AND (old_state = 'active'::text) AND (new_state = 'active'::text) AND (old_label = new_label) AND (NOT (old_short_label IS DISTINCT FROM new_short_label)) AND (NOT (old_description IS DISTINCT FROM new_description)) AND (old_icon_url IS DISTINCT FROM new_icon_url) AND ((new_icon_url IS NULL) OR ((new_icon_url ~ '^icon:[a-z0-9]+(-[a-z0-9]+)*$'::text) AND (char_length(new_icon_url) <= 69)))))),
    CONSTRAINT metric_variable_changes_new_state_check CHECK ((new_state = ANY (ARRAY['active'::text, 'archived'::text]))),
    CONSTRAINT metric_variable_changes_old_state_check CHECK ((old_state = ANY (ARRAY['active'::text, 'archived'::text]))),
    CONSTRAINT metric_variable_changes_owner_scope_check CHECK ((owner_scope = ANY (ARRAY['system'::text, 'club'::text]))),
    CONSTRAINT metric_variable_changes_owner_shape CHECK (((owner_scope = 'system'::text) = (owner_club_id IS NULL)))
);

ALTER TABLE training_load.metric_variable_changes ALTER COLUMN seq ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME training_load.metric_variable_changes_seq_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

