    CONSTRAINT metric_variable_requests_operation_id_iff CHECK (((operation_id IS NOT NULL) = (operation = 'variable_copy'::text))),
    CONSTRAINT metric_variable_requests_owner_scope_check CHECK ((owner_scope = ANY (ARRAY['system'::text, 'club'::text]))),
    CONSTRAINT metric_variable_requests_owner_shape CHECK (((owner_scope = 'system'::text) = (owner_club_id IS NULL))),
    CONSTRAINT metric_variable_requests_reason_check CHECK (((reason IS NULL) OR ((operation = ANY (ARRAY['variable_rename'::text, 'variable_archive'::text, 'variable_restore'::text])) AND training_load.source_metric_text_ok(reason, 500)))),
    CONSTRAINT metric_variable_requests_team_coach_shape CHECK (((basis <> 'team_coach'::text) OR ((owner_scope = 'club'::text) AND (operation = ANY (ARRAY['variable_rename'::text, 'variable_archive'::text, 'variable_restore'::text, 'variable_icon'::text]))))),
