    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_key text NOT NULL,
    requested_by_user_id uuid NOT NULL,
    operation_kind character varying(30) NOT NULL,
    owner_scope character varying(20) NOT NULL,
    owner_user_id uuid,
    owner_club_id uuid,
    owner_team_id uuid,
    request_content_hash text NOT NULL,
    status character varying(20) DEFAULT 'completed'::character varying NOT NULL,
    result_event_id uuid,
    result_occasion_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT metric_write_requests_check CHECK (((((owner_scope)::text = 'system'::text) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'user'::text) AND (owner_user_id IS NOT NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'club'::text) AND (owner_club_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'team'::text) AND (owner_team_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL)))),
    CONSTRAINT metric_write_requests_operation_kind_check CHECK (((operation_kind)::text = ANY ((ARRAY['create_manual_occasion'::character varying, 'create_group_event'::character varying, 'correct_occasion'::character varying])::text[]))),
    CONSTRAINT metric_write_requests_owner_scope_check CHECK (((owner_scope)::text = ANY ((ARRAY['system'::character varying, 'club'::character varying, 'team'::character varying, 'user'::character varying])::text[]))),
    CONSTRAINT metric_write_requests_status_check CHECK (((status)::text = 'completed'::text))
);

CREATE TABLE training_load.plan_workspace_ownership (
    plan_id uuid NOT NULL,
    owner_scope character varying(20) NOT NULL,
    owner_user_id uuid,
    owner_club_id uuid,
    owner_team_id uuid,
