    CONSTRAINT plan_workspace_ownership_check CHECK (((((owner_scope)::text = 'system'::text) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'user'::text) AND (owner_user_id IS NOT NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'club'::text) AND (owner_club_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'team'::text) AND (owner_team_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL)) OR (((owner_scope)::text = 'unresolved'::text) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)))),
    CONSTRAINT plan_workspace_ownership_owner_scope_check CHECK (((owner_scope)::text = ANY ((ARRAY['system'::character varying, 'club'::character varying, 'team'::character varying, 'user'::character varying, 'unresolved'::character varying])::text[])))
);

CREATE TABLE training_load.planned_rpe_workspace_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
