    owner_team_id uuid,
    enabled boolean DEFAULT false NOT NULL,
    enabled_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_user_id uuid,
    CONSTRAINT planned_rpe_workspace_settings_check CHECK (((((owner_scope)::text = 'system'::text) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'user'::text) AND (owner_user_id IS NOT NULL) AND (owner_club_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'club'::text) AND (owner_club_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_team_id IS NULL)) OR (((owner_scope)::text = 'team'::text) AND (owner_team_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_club_id IS NULL)))),
    CONSTRAINT planned_rpe_workspace_settings_check1 CHECK (((enabled = false) OR (enabled_at IS NOT NULL))),
    CONSTRAINT planned_rpe_workspace_settings_owner_scope_check CHECK (((owner_scope)::text = ANY ((ARRAY['system'::character varying, 'club'::character varying, 'team'::character varying, 'user'::character varying])::text[])))
);

CREATE TABLE training_load.session_feedback (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    athlete_id uuid NOT NULL,
    plan_session_id uuid,
    session_date date NOT NULL,
    plan_name text,
    plan_week_start date,
    session_name text,
    session_time time without time zone,
    session_am_pm character varying(10),
    session_bta character varying(10),
    rpe smallint NOT NULL,
    duration_minutes smallint NOT NULL,
    srpe integer GENERATED ALWAYS AS ((rpe * duration_minutes)) STORED,
    athlete_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    logical_session_id uuid,
    source character varying(20) DEFAULT 'planned'::character varying NOT NULL,
    external_assignment_id uuid,
    event_name text,
    CONSTRAINT session_feedback_athlete_note_check CHECK (((athlete_note IS NULL) OR (char_length(athlete_note) <= 500))),
    CONSTRAINT session_feedback_duration_minutes_check CHECK (((duration_minutes >= 1) AND (duration_minutes <= 600))),
    CONSTRAINT session_feedback_rpe_check CHECK (((rpe >= 0) AND (rpe <= 10))),
    CONSTRAINT session_feedback_source_check CHECK (((source)::text = ANY ((ARRAY['planned'::character varying, 'scheduled_external'::character varying])::text[]))),
    CONSTRAINT session_feedback_source_identity_xor CHECK (((((source)::text = 'planned'::text) AND (logical_session_id IS NOT NULL) AND (external_assignment_id IS NULL)) OR (((source)::text = 'scheduled_external'::text) AND (external_assignment_id IS NOT NULL) AND (logical_session_id IS NULL) AND (plan_session_id IS NULL) AND (event_name IS NOT NULL))))
);

CREATE TABLE training_load.source_connection_audit (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    connection_id uuid NOT NULL,
    team_id uuid,
    action text NOT NULL,
    outcome text NOT NULL,
    error_code text,
    reason text,
    performed_by_user_id uuid,
    basis text,
    performed_at timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT source_connection_audit_action_check CHECK ((action = ANY (ARRAY['create'::text, 'connect'::text, 'reconnect'::text, 'test'::text, 'disconnect'::text, 'auto_invalidate'::text, 'bind'::text, 'unbind'::text, 'rotate_key'::text]))),
    CONSTRAINT source_connection_audit_actor CHECK ((((action = 'auto_invalidate'::text) AND (performed_by_user_id IS NULL) AND (basis = 'system'::text)) OR ((action <> 'auto_invalidate'::text) AND (performed_by_user_id IS NOT NULL) AND (basis = ANY (ARRAY['platform_admin'::text, 'club_admin'::text]))))),
    CONSTRAINT source_connection_audit_basis_check CHECK (((basis IS NULL) OR (basis = ANY (ARRAY['platform_admin'::text, 'club_admin'::text, 'system'::text])))),
    CONSTRAINT source_connection_audit_bind_names_team CHECK (((action <> ALL (ARRAY['bind'::text, 'unbind'::text])) OR (team_id IS NOT NULL))),
    CONSTRAINT source_connection_audit_error_code_format CHECK (((error_code IS NULL) OR (error_code ~ '^[a-z][a-z0-9_]{1,60}$'::text))),
    CONSTRAINT source_connection_audit_failed_has_code CHECK (((outcome <> ALL (ARRAY['refused'::text, 'failed'::text])) OR (error_code IS NOT NULL))),
    CONSTRAINT source_connection_audit_metadata_is_object CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT source_connection_audit_metadata_no_secret_keys CHECK ((NOT training_load.jsonb_names_a_secret(metadata))),
    CONSTRAINT source_connection_audit_outcome_check CHECK ((outcome = ANY (ARRAY['ok'::text, 'refused'::text, 'failed'::text, 'unknown'::text]))),
    CONSTRAINT source_connection_audit_reason_check CHECK (((reason IS NULL) OR ((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 500))))
);

CREATE TABLE training_load.source_credential_connections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_system text NOT NULL,
    owner_scope text NOT NULL,
    owner_club_id uuid,
    owner_team_id uuid,
    host_key text NOT NULL,
    account_label text NOT NULL,
    credential_kind text NOT NULL,
    credential_ciphertext bytea,
    credential_nonce bytea,
    credential_auth_tag bytea,
    credential_key_version integer,
    state text DEFAULT 'not_connected'::text NOT NULL,
    last_verified_at timestamp with time zone,
    last_error_code text,
    last_error_at timestamp with time zone,
    created_by_user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_user_id uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT source_credential_connections_account_label_check CHECK (((length(btrim(account_label)) >= 1) AND (length(btrim(account_label)) <= 120))),
    CONSTRAINT source_credential_connections_credential_complete CHECK ((((credential_ciphertext IS NULL) AND (credential_nonce IS NULL) AND (credential_auth_tag IS NULL) AND (credential_key_version IS NULL)) OR ((credential_ciphertext IS NOT NULL) AND (credential_nonce IS NOT NULL) AND (credential_auth_tag IS NOT NULL) AND (credential_key_version IS NOT NULL) AND (octet_length(credential_nonce) = 12) AND (octet_length(credential_auth_tag) = 16) AND (octet_length(credential_ciphertext) >= 1) AND (credential_key_version >= 1)))),
    CONSTRAINT source_credential_connections_credential_kind_format CHECK ((credential_kind ~ '^[a-z][a-z0-9_]{1,30}$'::text)),
    CONSTRAINT source_credential_connections_host_key_format CHECK ((host_key ~ '^[a-z0-9][a-z0-9_-]{0,30}$'::text)),
    CONSTRAINT source_credential_connections_last_error_code_format CHECK (((last_error_code IS NULL) OR (last_error_code ~ '^[a-z][a-z0-9_]{1,60}$'::text))),
    CONSTRAINT source_credential_connections_owner_check CHECK ((((owner_scope = 'club'::text) AND (owner_club_id IS NOT NULL) AND (owner_team_id IS NULL)) OR ((owner_scope = 'team'::text) AND (owner_team_id IS NOT NULL) AND (owner_club_id IS NULL)))),
    CONSTRAINT source_credential_connections_owner_scope_check CHECK ((owner_scope = ANY (ARRAY['club'::text, 'team'::text]))),
    CONSTRAINT source_credential_connections_source_system_format CHECK ((source_system ~ '^[a-z][a-z0-9_]{1,30}$'::text)),
    CONSTRAINT source_credential_connections_state_check CHECK ((state = ANY (ARRAY['not_connected'::text, 'linked_untested'::text, 'verified'::text, 'needs_reconnect'::text, 'source_unavailable'::text]))),
    CONSTRAINT source_credential_connections_state_has_credential CHECK (((state = 'not_connected'::text) OR (credential_ciphertext IS NOT NULL))),
    CONSTRAINT source_credential_connections_state_linked_untested_facts CHECK (((state <> 'linked_untested'::text) OR ((last_error_code IS NOT NULL) AND (last_error_at IS NOT NULL)))),
    CONSTRAINT source_credential_connections_state_needs_reconnect_facts CHECK (((state <> 'needs_reconnect'::text) OR (last_error_code IS NOT NULL))),
    CONSTRAINT source_credential_connections_state_not_connected_no_credential CHECK (((state <> 'not_connected'::text) OR (credential_ciphertext IS NULL))),
    CONSTRAINT source_credential_connections_state_unavailable_facts CHECK (((state <> 'source_unavailable'::text) OR (last_error_at IS NOT NULL))),
    CONSTRAINT source_credential_connections_state_verified_facts CHECK (((state <> 'verified'::text) OR (last_verified_at IS NOT NULL))),
    CONSTRAINT source_credential_connections_state_verified_has_credential CHECK (((state <> 'verified'::text) OR (credential_ciphertext IS NOT NULL)))
);

CREATE TABLE training_load.source_host_catalog (
    source_system text NOT NULL,
    host_key text NOT NULL,
    label text NOT NULL,
    state text DEFAULT 'approved'::text NOT NULL,
    approved_at timestamp with time zone DEFAULT now() NOT NULL,
    note text,
    api_family text NOT NULL,
    CONSTRAINT source_host_catalog_api_family_check CHECK ((api_family = ANY (ARRAY['api'::text, 'rest_v1'::text]))),
    CONSTRAINT source_host_catalog_host_key_format CHECK ((host_key ~ '^[a-z0-9][a-z0-9_-]{0,30}$'::text)),
    CONSTRAINT source_host_catalog_label_check CHECK (((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 80))),
    CONSTRAINT source_host_catalog_note_check CHECK (((note IS NULL) OR ((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 500)))),
    CONSTRAINT source_host_catalog_source_system_format CHECK ((source_system ~ '^[a-z][a-z0-9_]{1,30}$'::text)),
    CONSTRAINT source_host_catalog_state_check CHECK ((state = ANY (ARRAY['approved'::text, 'retired'::text])))
);

CREATE TABLE training_load.source_metric_audit (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    action text NOT NULL,
    source_metric_definition_id uuid,
    source_metric_version_id uuid,
    mapping_id uuid,
    mapping_version_id uuid,
    activation_id uuid,
    unit_conversion_id uuid,
    metric_source_connection_id uuid,
    team_id uuid,
    from_status text,
    to_status text,
    reason text,
    evidence_ref text,
    performed_by_user_id uuid NOT NULL,
    basis text NOT NULL,
    performed_at timestamp with time zone DEFAULT now() NOT NULL,
    operation_id uuid NOT NULL,
    request_key uuid,
    request_hash text,
    CONSTRAINT source_metric_audit_action_check CHECK ((action = ANY (ARRAY['source_metric_create'::text, 'source_metric_revision_create'::text, 'source_metric_unit_verified'::text, 'source_metric_meaning_verified'::text, 'source_metric_revision_activate'::text, 'source_metric_revision_retire'::text, 'source_metric_retire'::text, 'mapping_create'::text, 'mapping_version_create'::text, 'mapping_status'::text, 'mapping_version_replaced'::text, 'activation_start'::text, 'activation_end'::text, 'unit_conversion_create'::text, 'unit_conversion_retire'::text, 'source_instance_end'::text]))),
    CONSTRAINT source_metric_audit_action_shape CHECK (training_load.source_metric_audit_row_ok(action, (((((((
CASE
    WHEN (source_metric_definition_id IS NULL) THEN '0'::text
    ELSE '1'::text
END ||
CASE
    WHEN (source_metric_version_id IS NULL) THEN '0'::text
    ELSE '1'::text
END) ||
CASE
    WHEN (mapping_id IS NULL) THEN '0'::text
    ELSE '1'::text
END) ||
CASE
    WHEN (mapping_version_id IS NULL) THEN '0'::text
    ELSE '1'::text
END) ||
CASE
    WHEN (activation_id IS NULL) THEN '0'::text
    ELSE '1'::text
END) ||
CASE
    WHEN (unit_conversion_id IS NULL) THEN '0'::text
    ELSE '1'::text
END) ||
CASE
    WHEN (metric_source_connection_id IS NULL) THEN '0'::text
    ELSE '1'::text
END) ||
CASE
    WHEN (team_id IS NULL) THEN '0'::text
    ELSE '1'::text
END), from_status, to_status, reason, evidence_ref, basis)),
    CONSTRAINT source_metric_audit_basis_check CHECK ((basis = ANY (ARRAY['platform_admin'::text, 'club_admin'::text]))),
    CONSTRAINT source_metric_audit_evidence_ref_check CHECK (((evidence_ref IS NULL) OR training_load.source_metric_evidence_ref_ok(evidence_ref))),
    CONSTRAINT source_metric_audit_from_status_check CHECK (((from_status IS NULL) OR (from_status = ANY (ARRAY['draft'::text, 'needs_review'::text, 'active'::text, 'disabled'::text, 'retired'::text, 'inactive'::text])))),
    CONSTRAINT source_metric_audit_reason_check CHECK (((reason IS NULL) OR training_load.source_metric_text_ok(reason, 500))),
    CONSTRAINT source_metric_audit_request_hash_format CHECK (((request_hash IS NULL) OR (request_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT source_metric_audit_request_pair CHECK (((request_key IS NULL) = (request_hash IS NULL))),
    CONSTRAINT source_metric_audit_to_status_check CHECK (((to_status IS NULL) OR (to_status = ANY (ARRAY['draft'::text, 'needs_review'::text, 'active'::text, 'disabled'::text, 'retired'::text, 'inactive'::text]))))
);

CREATE TABLE training_load.source_metric_definition_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_metric_definition_id uuid NOT NULL,
    revision_number integer NOT NULL,
    value_shape text NOT NULL,
    parameter_kind text NOT NULL,
    supports_session boolean NOT NULL,
    supports_drill boolean NOT NULL,
    expected_source_unit text,
    unit_note text,
    source_unit text,
    expected_source_bound_unit text,
    source_bound_unit text,
    bound_operator text,
    unit_verified_by_user_id uuid,
    unit_verified_at timestamp with time zone,
    unit_evidence_ref text,
    meaning_verified_by_user_id uuid,
    meaning_verified_at timestamp with time zone,
    meaning_evidence_ref text,
    evidence_status text NOT NULL,
    evidence_ref text,
    state text DEFAULT 'draft'::text NOT NULL,
    activated_by_user_id uuid,
    activated_at timestamp with time zone,
    retired_by_user_id uuid,
    retired_at timestamp with time zone,
    retired_reason text,
    created_by_user_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    seed_migration text,
    CONSTRAINT source_metric_revisions_activation_actor_or_seed CHECK ((((activated_by_user_id IS NULL) OR (activated_at IS NOT NULL)) AND ((activated_at IS NULL) OR ((activated_by_user_id IS NULL) <> (seed_migration IS NULL))))),
    CONSTRAINT source_metric_revisions_actor_or_seed CHECK (((created_by_user_id IS NULL) <> (seed_migration IS NULL))),
    CONSTRAINT source_metric_revisions_bound_only_parameterized CHECK (((parameter_kind <> 'none'::text) OR ((expected_source_bound_unit IS NULL) AND (source_bound_unit IS NULL) AND (bound_operator IS NULL)))),
    CONSTRAINT source_metric_revisions_bound_operator_check CHECK (((bound_operator IS NULL) OR (bound_operator = ANY (ARRAY['between'::text, '>='::text, '>'::text, '<='::text, '<'::text])))),
    CONSTRAINT source_metric_revisions_bound_unit_with_unit_proof CHECK (((source_bound_unit IS NULL) OR (unit_verified_at IS NOT NULL))),
    CONSTRAINT source_metric_revisions_evidence_ref_check CHECK (((evidence_ref IS NULL) OR training_load.source_metric_evidence_ref_ok(evidence_ref))),
    CONSTRAINT source_metric_revisions_evidence_ref_iff_proven CHECK (((evidence_status = 'unproven'::text) = (evidence_ref IS NULL))),
    CONSTRAINT source_metric_revisions_evidence_status_check CHECK ((evidence_status = ANY (ARRAY['unproven'::text, 'documented'::text, 'observed'::text, 'verified'::text]))),
    CONSTRAINT source_metric_revisions_expected_bound_unit_token CHECK (((expected_source_bound_unit IS NULL) OR training_load.source_metric_unit_token_ok(expected_source_bound_unit))),
    CONSTRAINT source_metric_revisions_expected_unit_token CHECK (((expected_source_unit IS NULL) OR training_load.source_metric_unit_token_ok(expected_source_unit))),
    CONSTRAINT source_metric_revisions_levels_check CHECK ((supports_session OR supports_drill)),
    CONSTRAINT source_metric_revisions_meaning_evidence_ref_check CHECK (((meaning_evidence_ref IS NULL) OR training_load.source_metric_evidence_ref_ok(meaning_evidence_ref))),
    CONSTRAINT source_metric_revisions_meaning_proof_together CHECK ((((meaning_verified_by_user_id IS NULL) = (meaning_verified_at IS NULL)) AND ((meaning_verified_at IS NULL) = (meaning_evidence_ref IS NULL)))),
    CONSTRAINT source_metric_revisions_number_check CHECK ((revision_number > 0)),
    CONSTRAINT source_metric_revisions_operator_with_meaning CHECK (((parameter_kind = 'none'::text) OR ((meaning_verified_at IS NULL) = (bound_operator IS NULL)))),
    CONSTRAINT source_metric_revisions_parameter_kind_check CHECK ((parameter_kind = ANY (ARRAY['none'::text, 'zone_bounds'::text, 'event_threshold'::text]))),
    CONSTRAINT source_metric_revisions_proven_bound_unit CHECK (((parameter_kind = 'none'::text) OR (source_unit IS NULL) OR (source_bound_unit IS NOT NULL))),
    CONSTRAINT source_metric_revisions_retired_reason_check CHECK (((retired_reason IS NULL) OR training_load.source_metric_text_ok(retired_reason, 500))),
    CONSTRAINT source_metric_revisions_seed_migration_format CHECK (((seed_migration IS NULL) OR (seed_migration ~ '^migrations_v2/[0-9]{12}_[a-z0-9_]+\.sql$'::text))),
    CONSTRAINT source_metric_revisions_shape_kind CHECK ((((value_shape = 'zone_distance'::text) = (parameter_kind = 'zone_bounds'::text)) AND ((value_shape = 'event_count'::text) = (parameter_kind = 'event_threshold'::text)))),
    CONSTRAINT source_metric_revisions_source_bound_unit_token CHECK (((source_bound_unit IS NULL) OR training_load.source_metric_unit_token_ok(source_bound_unit))),
    CONSTRAINT source_metric_revisions_source_unit_token CHECK (((source_unit IS NULL) OR training_load.source_metric_unit_token_ok(source_unit))),
    CONSTRAINT source_metric_revisions_state_check CHECK ((state = ANY (ARRAY['draft'::text, 'active'::text, 'retired'::text]))),
    CONSTRAINT source_metric_revisions_state_facts CHECK ((((state = 'draft'::text) AND (activated_by_user_id IS NULL) AND (activated_at IS NULL) AND (retired_by_user_id IS NULL) AND (retired_at IS NULL) AND (retired_reason IS NULL)) OR ((state = 'active'::text) AND (activated_at IS NOT NULL) AND (retired_by_user_id IS NULL) AND (retired_at IS NULL) AND (retired_reason IS NULL)) OR ((state = 'retired'::text) AND (retired_by_user_id IS NOT NULL) AND (retired_at IS NOT NULL) AND (retired_reason IS NOT NULL)))),
    CONSTRAINT source_metric_revisions_unit_evidence_ref_check CHECK (((unit_evidence_ref IS NULL) OR training_load.source_metric_evidence_ref_ok(unit_evidence_ref))),
    CONSTRAINT source_metric_revisions_unit_note_check CHECK (((unit_note IS NULL) OR training_load.source_metric_text_ok(unit_note, 500))),
    CONSTRAINT source_metric_revisions_unit_proof_together CHECK ((((unit_verified_by_user_id IS NULL) = (unit_verified_at IS NULL)) AND ((unit_verified_at IS NULL) = (unit_evidence_ref IS NULL)))),
    CONSTRAINT source_metric_revisions_unit_proven_iff_verified CHECK (((source_unit IS NULL) = (unit_verified_at IS NULL))),
    CONSTRAINT source_metric_revisions_value_shape_check CHECK ((value_shape = ANY (ARRAY['number'::text, 'numeric_text'::text, 'unit_value_object'::text, 'zone_distance'::text, 'event_count'::text]))),
    CONSTRAINT source_metric_revisions_verified_iff_proven CHECK (((evidence_status = 'verified'::text) = ((source_unit IS NOT NULL) AND (meaning_verified_at IS NOT NULL) AND ((parameter_kind = 'none'::text) OR (bound_operator IS NOT NULL)))))
);

CREATE TABLE training_load.source_metric_definitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_system text NOT NULL,
    api_family text NOT NULL,
    source_metric_key text NOT NULL,
    source_label text NOT NULL,
    state text DEFAULT 'active'::text NOT NULL,
    retired_by_user_id uuid,
    retired_at timestamp with time zone,
    retired_reason text,
    created_by_user_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    seed_migration text,
    CONSTRAINT source_metric_definitions_actor_or_seed CHECK (((created_by_user_id IS NULL) <> (seed_migration IS NULL))),
    CONSTRAINT source_metric_definitions_api_family_check CHECK ((api_family = ANY (ARRAY['api'::text, 'rest_v1'::text]))),
    CONSTRAINT source_metric_definitions_key_format CHECK ((source_metric_key ~ '^[a-z][a-z0-9_.]{1,120}$'::text)),
    CONSTRAINT source_metric_definitions_label_check CHECK (training_load.source_metric_text_ok(source_label, 80)),
    CONSTRAINT source_metric_definitions_retired_facts CHECK ((((state = 'active'::text) AND (retired_by_user_id IS NULL) AND (retired_at IS NULL) AND (retired_reason IS NULL)) OR ((state = 'retired'::text) AND (retired_by_user_id IS NOT NULL) AND (retired_at IS NOT NULL) AND (retired_reason IS NOT NULL)))),
    CONSTRAINT source_metric_definitions_retired_reason_check CHECK (((retired_reason IS NULL) OR training_load.source_metric_text_ok(retired_reason, 500))),
    CONSTRAINT source_metric_definitions_seed_migration_format CHECK (((seed_migration IS NULL) OR (seed_migration ~ '^migrations_v2/[0-9]{12}_[a-z0-9_]+\.sql$'::text))),
    CONSTRAINT source_metric_definitions_source_system_format CHECK ((source_system ~ '^[a-z][a-z0-9_]{1,30}$'::text)),
    CONSTRAINT source_metric_definitions_state_check CHECK ((state = ANY (ARRAY['active'::text, 'retired'::text])))
);

CREATE TABLE training_load.source_metric_mapping_activations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    mapping_version_id uuid NOT NULL,
    mapping_id uuid NOT NULL,
    source_metric_definition_id uuid NOT NULL,
    metric_definition_id uuid NOT NULL,
    parameter_fingerprint text NOT NULL,
    source_team_binding_id uuid NOT NULL,
    team_id uuid NOT NULL,
    applies_to_session boolean NOT NULL,
    applies_to_drill boolean NOT NULL,
    requirement text NOT NULL,
    activated_by_user_id uuid NOT NULL,
    activated_basis text NOT NULL,
    activated_at timestamp with time zone DEFAULT now() NOT NULL,
    reason text NOT NULL,
    ended_at timestamp with time zone,
    ended_by_user_id uuid,
    ended_basis text,
    end_reason text,
    CONSTRAINT source_metric_activations_activated_basis_check CHECK ((activated_basis = ANY (ARRAY['platform_admin'::text, 'club_admin'::text]))),
    CONSTRAINT source_metric_activations_end_reason_check CHECK (((end_reason IS NULL) OR (end_reason = ANY (ARRAY['admin_ended'::text, 'mapping_version_replaced'::text, 'mapping_version_disabled'::text])))),
    CONSTRAINT source_metric_activations_ended_basis_check CHECK (((ended_basis IS NULL) OR (ended_basis = ANY (ARRAY['platform_admin'::text, 'club_admin'::text])))),
    CONSTRAINT source_metric_activations_ended_facts CHECK ((((ended_at IS NULL) = (ended_by_user_id IS NULL)) AND ((ended_at IS NULL) = (ended_basis IS NULL)) AND ((ended_at IS NULL) = (end_reason IS NULL)))),
    CONSTRAINT source_metric_activations_levels_check CHECK ((applies_to_session OR applies_to_drill)),
    CONSTRAINT source_metric_activations_reason_check CHECK (training_load.source_metric_text_ok(reason, 500)),
    CONSTRAINT source_metric_activations_requirement_check CHECK ((requirement = ANY (ARRAY['required'::text, 'optional'::text])))
);

CREATE TABLE training_load.source_metric_mapping_version_copies (
    club_version_id uuid NOT NULL,
    system_version_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT source_metric_mapping_version_copies_not_itself CHECK ((club_version_id <> system_version_id))
);

CREATE TABLE training_load.source_metric_mapping_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    mapping_id uuid NOT NULL,
    source_metric_definition_id uuid NOT NULL,
    metric_definition_id uuid NOT NULL,
    owner_key text NOT NULL,
    source_metric_version_id uuid NOT NULL,
    version_number integer NOT NULL,
    metric_definition_version_id uuid NOT NULL,
    conversion_kind text NOT NULL,
    scale numeric NOT NULL,
    scale_divisor numeric NOT NULL,
    "offset" numeric NOT NULL,
    rounding_decimals integer,
    source_unit text NOT NULL,
    target_unit text NOT NULL,
    conversion_note text,
    parameter_kind text NOT NULL,
    source_parameters jsonb NOT NULL,
    canonical_parameters jsonb NOT NULL,
    parameter_fingerprint text NOT NULL,
    parameter_scale numeric NOT NULL,
    parameter_scale_divisor numeric NOT NULL,
    parameter_offset numeric NOT NULL,
    applies_to_session boolean NOT NULL,
    applies_to_drill boolean NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    submitted_by_user_id uuid,
    submitted_at timestamp with time zone,
    submitted_basis text,
    activated_by_user_id uuid,
    activated_at timestamp with time zone,
    activated_basis text,
    disabled_by_user_id uuid,
    disabled_at timestamp with time zone,
    disabled_basis text,
    disable_reason text,
    created_by_user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT source_metric_mapping_versions_activated_basis_check CHECK (((activated_basis IS NULL) OR (activated_basis = ANY (ARRAY['platform_admin'::text, 'club_admin'::text])))),
    CONSTRAINT source_metric_mapping_versions_activated_facts CHECK ((((activated_by_user_id IS NULL) = (activated_at IS NULL)) AND ((activated_at IS NULL) = (activated_basis IS NULL)))),
    CONSTRAINT source_metric_mapping_versions_canonical_parameters_shape CHECK (training_load.source_metric_parameters_shape_ok(parameter_kind, 'canonical'::text, canonical_parameters)),
    CONSTRAINT source_metric_mapping_versions_conversion_kind_check CHECK ((conversion_kind = 'numeric_linear'::text)),
    CONSTRAINT source_metric_mapping_versions_conversion_note_check CHECK (((conversion_note IS NULL) OR training_load.source_metric_text_ok(conversion_note, 500))),
    CONSTRAINT source_metric_mapping_versions_disable_reason_check CHECK (((disable_reason IS NULL) OR training_load.source_metric_text_ok(disable_reason, 500))),
    CONSTRAINT source_metric_mapping_versions_disabled_basis_check CHECK (((disabled_basis IS NULL) OR (disabled_basis = ANY (ARRAY['platform_admin'::text, 'club_admin'::text])))),
    CONSTRAINT source_metric_mapping_versions_disabled_facts CHECK ((((disabled_by_user_id IS NULL) = (disabled_at IS NULL)) AND ((disabled_at IS NULL) = (disabled_basis IS NULL)) AND ((disabled_at IS NULL) = (disable_reason IS NULL)))),
    CONSTRAINT source_metric_mapping_versions_divisor_positive CHECK ((scale_divisor > (0)::numeric)),
    CONSTRAINT source_metric_mapping_versions_factors_finite CHECK ((training_load.source_metric_numeric_finite(scale) AND training_load.source_metric_numeric_finite(scale_divisor) AND training_load.source_metric_numeric_finite("offset"))),
    CONSTRAINT source_metric_mapping_versions_factors_normal CHECK (((scale = (1)::numeric) OR (scale_divisor = (1)::numeric))),
    CONSTRAINT source_metric_mapping_versions_fingerprint_shape CHECK ((((parameter_kind = 'none'::text) = (parameter_fingerprint = ''::text)) AND ((parameter_fingerprint = ''::text) OR (parameter_fingerprint ~ '^v[0-9]+:[0-9a-f]{64}$'::text)))),
    CONSTRAINT source_metric_mapping_versions_levels_check CHECK ((applies_to_session OR applies_to_drill)),
    CONSTRAINT source_metric_mapping_versions_no_parameters_identity CHECK (((parameter_kind <> 'none'::text) OR ((parameter_scale = (1)::numeric) AND (parameter_scale_divisor = (1)::numeric) AND (parameter_offset = (0)::numeric)))),
    CONSTRAINT source_metric_mapping_versions_note_when_units_differ CHECK (((source_unit = target_unit) OR (conversion_note IS NOT NULL))),
    CONSTRAINT source_metric_mapping_versions_number_check CHECK ((version_number > 0)),
    CONSTRAINT source_metric_mapping_versions_parameter_divisor_positive CHECK ((parameter_scale_divisor > (0)::numeric)),
    CONSTRAINT source_metric_mapping_versions_parameter_factors_finite CHECK ((training_load.source_metric_numeric_finite(parameter_scale) AND training_load.source_metric_numeric_finite(parameter_scale_divisor) AND training_load.source_metric_numeric_finite(parameter_offset))),
    CONSTRAINT source_metric_mapping_versions_parameter_factors_normal CHECK (((parameter_scale = (1)::numeric) OR (parameter_scale_divisor = (1)::numeric))),
    CONSTRAINT source_metric_mapping_versions_parameter_kind_check CHECK ((parameter_kind = ANY (ARRAY['none'::text, 'zone_bounds'::text, 'event_threshold'::text]))),
    CONSTRAINT source_metric_mapping_versions_parameter_scale_positive CHECK ((parameter_scale > (0)::numeric)),
    CONSTRAINT source_metric_mapping_versions_rounding_decimals_check CHECK (((rounding_decimals IS NULL) OR ((rounding_decimals >= 0) AND (rounding_decimals <= 6)))),
    CONSTRAINT source_metric_mapping_versions_scale_positive CHECK ((scale > (0)::numeric)),
    CONSTRAINT source_metric_mapping_versions_source_parameters_shape CHECK (training_load.source_metric_parameters_shape_ok(parameter_kind, 'source'::text, source_parameters)),
    CONSTRAINT source_metric_mapping_versions_source_unit_token CHECK (training_load.source_metric_unit_token_ok(source_unit)),
    CONSTRAINT source_metric_mapping_versions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'needs_review'::text, 'active'::text, 'disabled'::text]))),
    CONSTRAINT source_metric_mapping_versions_status_facts CHECK ((((status = 'draft'::text) AND (submitted_at IS NULL) AND (activated_at IS NULL) AND (disabled_at IS NULL)) OR ((status = 'needs_review'::text) AND (submitted_at IS NOT NULL) AND (activated_at IS NULL) AND (disabled_at IS NULL)) OR ((status = 'active'::text) AND (submitted_at IS NOT NULL) AND (activated_at IS NOT NULL) AND (disabled_at IS NULL)) OR ((status = 'disabled'::text) AND (disabled_at IS NOT NULL) AND ((activated_at IS NULL) OR (submitted_at IS NOT NULL))))),
    CONSTRAINT source_metric_mapping_versions_submitted_basis_check CHECK (((submitted_basis IS NULL) OR (submitted_basis = ANY (ARRAY['platform_admin'::text, 'club_admin'::text])))),
    CONSTRAINT source_metric_mapping_versions_submitted_facts CHECK ((((submitted_by_user_id IS NULL) = (submitted_at IS NULL)) AND ((submitted_at IS NULL) = (submitted_basis IS NULL)))),
    CONSTRAINT source_metric_mapping_versions_target_unit_token CHECK (training_load.source_metric_unit_token_ok(target_unit))
);

CREATE TABLE training_load.source_metric_mappings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_metric_definition_id uuid NOT NULL,
    source_system text NOT NULL,
    api_family text NOT NULL,
    metric_definition_id uuid NOT NULL,
    owner_scope text NOT NULL,
    owner_club_id uuid,
    owner_key text GENERATED ALWAYS AS (COALESCE((owner_club_id)::text, 'system'::text)) STORED NOT NULL,
    created_by_user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT source_metric_mappings_owner_check CHECK ((((owner_scope = 'system'::text) AND (owner_club_id IS NULL)) OR ((owner_scope = 'club'::text) AND (owner_club_id IS NOT NULL)))),
    CONSTRAINT source_metric_mappings_owner_scope_check CHECK ((owner_scope = ANY (ARRAY['system'::text, 'club'::text])))
);

CREATE TABLE training_load.source_team_bindings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    team_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    source_system text NOT NULL,
    source_team_id text NOT NULL,
    state text DEFAULT 'active'::text NOT NULL,
    bound_by_user_id uuid NOT NULL,
    bound_at timestamp with time zone DEFAULT now() NOT NULL,
    bind_reason text,
    ended_at timestamp with time zone,
    ended_by_user_id uuid,
    end_reason text,
    legacy_gpexe_settings_team_id uuid,
    CONSTRAINT source_team_bindings_bind_reason_check CHECK (((bind_reason IS NULL) OR ((length(btrim(bind_reason)) >= 1) AND (length(btrim(bind_reason)) <= 500)))),
    CONSTRAINT source_team_bindings_end_reason_check CHECK (((end_reason IS NULL) OR ((length(btrim(end_reason)) >= 1) AND (length(btrim(end_reason)) <= 500)))),
    CONSTRAINT source_team_bindings_ended_facts CHECK ((((state = 'active'::text) AND (ended_at IS NULL) AND (ended_by_user_id IS NULL) AND (end_reason IS NULL)) OR ((state = 'ended'::text) AND (ended_at IS NOT NULL) AND (ended_by_user_id IS NOT NULL) AND (end_reason IS NOT NULL)))),
    CONSTRAINT source_team_bindings_gpexe_team_id_canonical CHECK (((source_system <> 'gpexe'::text) OR (source_team_id ~ '^(0|[1-9][0-9]{0,11})$'::text))),
    CONSTRAINT source_team_bindings_legacy_pointer_is_gpexe CHECK (((legacy_gpexe_settings_team_id IS NULL) OR (source_system = 'gpexe'::text))),
    CONSTRAINT source_team_bindings_source_system_format CHECK ((source_system ~ '^[a-z][a-z0-9_]{1,30}$'::text)),
    CONSTRAINT source_team_bindings_source_team_id_format CHECK ((source_team_id ~ '^[A-Za-z0-9._:-]{1,64}$'::text)),
    CONSTRAINT source_team_bindings_state_check CHECK ((state = ANY (ARRAY['active'::text, 'ended'::text])))
);

CREATE TABLE training_load.unit_conversions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    from_unit text NOT NULL,
    to_unit text NOT NULL,
    scale numeric NOT NULL,
    scale_divisor numeric NOT NULL,
    "offset" numeric NOT NULL,
    state text DEFAULT 'active'::text NOT NULL,
    retired_by_user_id uuid,
    retired_at timestamp with time zone,
    retired_reason text,
    evidence_ref text NOT NULL,
    created_by_user_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    seed_migration text,
    CONSTRAINT unit_conversions_actor_or_seed CHECK (((created_by_user_id IS NULL) <> (seed_migration IS NULL))),
    CONSTRAINT unit_conversions_divisor_positive CHECK ((scale_divisor > (0)::numeric)),
    CONSTRAINT unit_conversions_evidence_ref_check CHECK (training_load.source_metric_evidence_ref_ok(evidence_ref)),
    CONSTRAINT unit_conversions_factors_finite CHECK ((training_load.source_metric_numeric_finite(scale) AND training_load.source_metric_numeric_finite(scale_divisor) AND training_load.source_metric_numeric_finite("offset"))),
    CONSTRAINT unit_conversions_factors_normal CHECK (((scale = (1)::numeric) OR (scale_divisor = (1)::numeric))),
    CONSTRAINT unit_conversions_factors_normal_form CHECK (training_load.source_metric_factor_pair_normal(scale, scale_divisor)),
    CONSTRAINT unit_conversions_from_unit_check CHECK (training_load.source_metric_text_ok(from_unit, 30)),
    CONSTRAINT unit_conversions_retired_facts CHECK ((((state = 'active'::text) AND (retired_by_user_id IS NULL) AND (retired_at IS NULL) AND (retired_reason IS NULL)) OR ((state = 'retired'::text) AND (retired_by_user_id IS NOT NULL) AND (retired_at IS NOT NULL) AND (retired_reason IS NOT NULL)))),
    CONSTRAINT unit_conversions_retired_reason_check CHECK (((retired_reason IS NULL) OR training_load.source_metric_text_ok(retired_reason, 500))),
    CONSTRAINT unit_conversions_scale_positive CHECK ((scale > (0)::numeric)),
    CONSTRAINT unit_conversions_seed_migration_format CHECK (((seed_migration IS NULL) OR (seed_migration ~ '^migrations_v2/[0-9]{12}_[a-z0-9_]+\.sql$'::text))),
    CONSTRAINT unit_conversions_state_check CHECK ((state = ANY (ARRAY['active'::text, 'retired'::text]))),
    CONSTRAINT unit_conversions_to_unit_check CHECK (training_load.source_metric_text_ok(to_unit, 30)),
    CONSTRAINT unit_conversions_units_are_tokens CHECK ((training_load.source_metric_unit_token_ok(from_unit) AND training_load.source_metric_unit_token_ok(to_unit))),
    CONSTRAINT unit_conversions_units_differ CHECK ((from_unit <> to_unit))
);

